insert into public.treatments (slug, category, care_kind, include_keys, seo, cost_page, name, menu_name, alternate_name, summary, procedure, national_range, cost_factors, desk_work, card_blurb, icon, related, read_slugs, video_slugs, reviewer_id, content, display, images, published) values
  ('gynecomastia-surgery', 'surgery', null, null, null, null, 'Gynecomastia surgery', 'Gynecomastia surgery', 'Male breast reduction', 'Surgery for enlarged chest tissue in men: fat removed by liposuction, gland cut out, or both.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Chest","howPerformed":"Fat is removed by liposuction, breast gland tissue is cut out through a small cut at the edge of the areola or the side of the chest, or both; extra skin is removed or tightened in large cases.","preparation":"Examination by a surgeon, review of medicines, blood tests and an anaesthesia fitness check.","followup":"Compression garment, review visits, and a gradual return to exercise as the surgeon advises."}'::jsonb, '{"minInr":58000,"maxInr":98000,"fromInr":42000,"validAsOf":"2026-11","isSample":true}'::jsonb, '[{"factor":"Grade and method","why":"Liposuction alone takes less theatre time than gland removal with skin removal."},{"factor":"Anaesthesia","why":"General anaesthesia costs more than local with sedation."},{"factor":"Hospital type","why":"A day-care centre and a multi-specialty hospital price rooms and theatre differently."},{"factor":"City","why":"Rents and wages differ between cities, and so do facility fees."},{"factor":"Stay","why":"Day care at the lower end, one night in a room at the upper."},{"factor":"Garment and medicines","why":"Brand and number of garments, and the medicines prescribed."},{"factor":"Follow-up visits","why":"Some quotes include them, some charge per visit."},{"factor":"A second operation","why":"Some hospitals include a touch-up for a period, some charge in full."}]'::jsonb, 'About 1 week', 'The full procedure guide: who it suits, how it is done, recovery.', 3, '["liposuction","tummy-tuck"]'::jsonb, '["gynecomastia-grades","gynecomastia-fat-or-gland","pseudogynecomastia"]'::jsonb, '["gynecomastia-explained","gynecomastia-recovery-weeks"]'::jsonb, null, '{"dek":"Surgery removes extra chest gland, fat or both, and a surgeon decides which after an examination. Here is what [gynecomastia surgery](/gynecomastia-surgery) involves, when you can work, drive and train, and how we check a surgeon. The [national cost factors](/cost/gynecomastia-surgery) are on their own page.","shortAnswers":[{"q":"Do I even need surgery?","a":"It depends on whether the enlargement is gland, fat or both. Only an examination can tell. Many teenagers settle without surgery.","href":"#fat-or-gland","linkText":"Gland or fat"},{"q":"What will it cost?","a":"One bill with the surgeon, anaesthesia and facility fees in it, and a few items to ask for in writing. The range shown is to be confirmed.","href":"#cost","linkText":"The lines"},{"q":"How long until I can work and drive?","a":"Desk work after about a week, driving after about two, chest training after six or more.","href":"#recovery","linkText":"The calendar"},{"q":"Who operates, and who checks them?","a":"No surgeon is listed yet. We list one only after registration and accreditation are checked.","href":"#choose","linkText":"The checks"}],"operation":{"lead":"Gynecomastia is growth of the breast gland in boys and men, on one side or both. Surgery takes out fat, gland or both, and the plan depends on what an examination finds.","body":"Your surgeon may suggest [liposuction only or gland removal](/learn/gynecomastia-liposuction-vs-gland-removal), or the two together. [Liposuction](/liposuction) reaches the fat through tiny cuts, and some surgeons use ultrasound- or power-assisted tools for it. Gland tissue is firm and has to be cut out, usually through a small cut at the edge of the areola or the side of the chest. Larger cases also need skin removal or tightening. The [grades of gynecomastia](/learn/gynecomastia-grades) help the surgeon choose.","caption":"Two common approaches, drawn side by side.","ask":"Is mine gland, fat or both, and what would you do about each part?","how":["**Liposuction:** fat is suctioned out through tiny cuts. A few very small marks.","**Gland removal:** the gland is cut out through a small cut at the edge of the areola or the side of the chest. One small line.","**Skin removal or tightening:** extra skin is cut away, or tightened with radiofrequency energy in some cases. Longer scars if skin is cut away.","Smaller operations may use local anaesthesia with sedation, larger ones general anaesthesia. Many are day care; some need one night. A thin drain is sometimes placed for a day or two."],"whoItSuits":[{"term":"Health","text":"Good general health, a weight that has been steady for some months, and no smoking if you can manage it."},{"term":"Expectations","text":"A clear idea of what surgery can change. Scars remain and the result depends on your body."},{"term":"Reason","text":"The chest bothers you in daily life: clothes, the gym, swimming, or how you feel about it."},{"term":"Who asks","text":"Teenagers and their parents, bodybuilders, men in desk jobs, and older men with loose skin. Each group has a different first question, and the surgeon''s answer differs too."}]},"fatOrGland":{"lead":"The two look alike in a mirror and feel different to the hand. Only a doctor can tell after an examination, and may ask for an ultrasound or blood tests.","body":"Hormone balance, some medicines and recent weight change can all cause chest enlargement, so see a doctor before you plan surgery. Read about [fat or gland](/learn/gynecomastia-fat-or-gland) and [chest fat without gland](/learn/pseudogynecomastia). Many teenagers settle without an operation, and some [possible causes](/learn/gynecomastia-causes) can be treated first. For [what exercise can change](/learn/male-chest-exercise-and-fat), see our short guide.","term":"**Pseudogynecomastia** is chest fat that looks like gland. Many men have a mix of the two.","tissueTable":[{"feature":"Feel","gland":"Firm, rubbery disc","fat":"Soft, spread across the chest"},{"feature":"Where","gland":"Behind the nipple","fat":"All over the chest, often the sides too"},{"feature":"Tenderness","gland":"Often tender to touch","fat":"Usually not tender"},{"feature":"Weight loss","gland":"Changes little","fat":"Often reduces"}],"seeDoctor":"A hard lump, one side only, pain or nipple discharge. Do this before you plan surgery.","causes":["Hormone balance: relatively more oestrogen than testosterone, as in puberty, later life or some illnesses.","Some medicines, for example certain antibiotics, anxiety medicines and treatments for the prostate or the stomach.","Alcohol, anabolic steroids and some drugs.","Medical conditions such as kidney, liver or thyroid problems."],"symptoms":["A lump or firm disc behind the nipple, on one or both sides.","Swelling that is uneven between the two sides.","Tenderness, or a wider areola.","Fluid from the nipple. This needs a doctor''s check soon."],"myths":["Creams, oils, homeopathy and fat-burner supplements: there is no good evidence that any of them removes gland tissue.","Chest exercise: it builds muscle under the tissue and can make a gland look more prominent, not smaller.","\"It is always just fat\": not so. Many men have gland, and gland does not shrink with diet."],"gradesCaption":"Grades of gynecomastia, and the usual approach. Scales differ between surgeons, so yours will explain theirs.","grades":[{"grade":"I","looks":"Small mound around the nipple, no loose skin","approach":"Liposuction, or gland removal if firm"},{"grade":"II","looks":"Larger, with more fat around it, no loose skin","approach":"Gland removal with liposuction"},{"grade":"III","looks":"Moderate, with loose skin","approach":"As II, and sometimes skin removal"},{"grade":"IV","looks":"Large, with loose skin","approach":"Skin removal, often in two stages"}]},"recovery":{"lead":"Typical timing for an uncomplicated operation. Your surgeon sets yours. {pending}","body":"A compression vest is worn for the first weeks, under clothes, as the surgeon advises. Summers here are hot, so ask for a breathable garment and a spare. The [full recovery guide](/gynecomastia-surgery#recovery) has the detail.","highlights":[{"pre":"about","big":"1 week","text":"Desk work, with some soreness"},{"pre":"about","big":"2 weeks","text":"Driving, if the surgeon agrees"},{"big":"6 weeks","post":"or more","text":"Chest and arm training, if the surgeon agrees"}],"timeline":[{"when":"Day 0","notice":"Drowsy after anaesthesia, chest wrapped","doThis":"Home the same day or after one night. An attendant stays with you. Garment on."},{"when":"Day 1 to 2","notice":"Soreness and tightness, some swelling","doThis":"Rest, with light movement indoors. Pain medicine as prescribed. WhatsApp check-in from us on day 1."},{"when":"Day 3 to 7","notice":"Bruising and swelling at their most, then easing","doThis":"Short walks. Desk work from home from about day 5 to 7 if you feel ready. Drain out, if one was placed."},{"when":"Week 2","notice":"Bruising fading, chest feels tight","doThis":"Office, and driving if the surgeon agrees. Brisk walking or cycling if comfortable. Review visit. Stitches checked."},{"when":"Week 4","notice":"Swelling lessening, numb patches common","doThis":"Light leg gym. Garment continues as advised."},{"when":"Week 6","notice":"Chest feels more normal","doThis":"Heavy lifting, chest press and swimming only if the surgeon agrees."},{"when":"Week 12","notice":"Most swelling settled, scars still pink","doThis":"Review visit. Flights and long drives as the surgeon advises."}],"grid":{"cols":["Day 1","Wk 1","Wk 2","Wk 4","Wk 6+"],"rows":[{"label":"Desk work","cells":[{"state":"n","text":"No"},{"state":"m","text":"Some"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Driving","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Walking","cells":[{"state":"m","text":"Short"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Leg gym","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Light"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Chest, arms","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"If ok"}]}]},"closing":"Ask before booking a flight in the first weeks. Some soreness and swelling are expected, and swelling takes months to settle."},"risks":{"lead":"Every operation has risks. These are the ones to ask about, in plain words. No frequencies are shown here, because we show a figure only when a named source backs it.","rows":[{"risk":"Bleeding","means":"Blood collects under the skin and may need draining","ask":"Whether a drain is used, and what to watch for at home"},{"risk":"Fluid or infection","means":"Fluid collects (a seroma), or the wound gets infected","ask":"Which signs mean a same-day call, and whose number to use"},{"risk":"Uneven chest","means":"Dents, lumps, or one side that differs from the other","ask":"How the surgeon checks both sides before you leave theatre"},{"risk":"Nipple feeling","means":"Numbness or extra sensitivity, usually easing over months","ask":"How long it can last in your case"},{"risk":"Scars and loose skin","means":"Scars fade over a year or more; loose skin may remain","ask":"To see where the cuts will be marked"},{"risk":"Slow healing","means":"A wound heals late, and in rare cases some tissue is lost","ask":"What raises the chance, such as smoking, and what to stop beforehand"},{"risk":"Anaesthesia and medicines","means":"Allergic reactions and, rarely, a blood clot","ask":"Who gives the anaesthesia, and what the fitness check covers"},{"risk":"Coming back","means":"Weight gain, some medicines and steroids can bring new enlargement","ask":"What to avoid, and what to do if it returns"},{"risk":"A second operation","means":"A touch-up may be needed after the first","ask":"Whether it is charged, and for how long after the first"}],"alert":"**Call the hospital the same day** for fever, spreading redness, fast swelling on one side, bleeding through the dressing or severe pain. Chest pain or breathlessness: call 112.","wait":["Your chest is still changing, or it started recently.","You use steroids or testosterone products. Stopping may help.","A liver, kidney or thyroid problem has not been looked at.","You plan to lose a lot of weight soon, or you smoke."],"tell":["Every medicine and supplement, including gym supplements.","Alcohol and cannabis use.","When the enlargement began, and whether it changed in the last year."]},"patientQuestions":[{"q":"Will anyone at work come to know I had this done?","href":"#getting-there","linkText":"Read: getting there and staying"},{"q":"I am 19. Is it too early to think about surgery?","href":"#fat-or-gland","linkText":"Read: is it fat or gland"},{"q":"Do I need to stop my gym routine before and after?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Can I take a flight or a long drive a few days later?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Is one side done first, or both together?","href":"#surgery","linkText":"Read: the operation"},{"q":"How do I know if it is fat, or a gland?","href":"#fat-or-gland","linkText":"Read: is it fat or gland"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"In person, by WhatsApp or by phone, whichever you choose. No pressure to book."},{"title":"A surgeon examines you","text":"Gland or fat, and the grade, are decided in person, not on the phone."},{"title":"The hospital writes the cost","text":"Surgeon, anaesthesia and facility fees, plus the items it adds, listed one by one."},{"title":"You pick the anaesthesia and the date","text":"The surgeon and the anaesthetist advise. Most operations are day care."},{"title":"After the operation","text":"A check-in from us on day 1, a compression vest, review visits, and a staged return to work and training."}],"quoteChecks":["list the surgeon, anaesthesia and facility fees separately?","say whether a second operation is included, and for how long?","name the same room, day care or overnight?","write down the number of follow-up visits?"],"extras":["Tests before surgery","Compression garment","Medicines for the first days","Follow-up visits","Treating a complication","A second operation","Loose skin, if added later","Your attendant''s stay and travel"],"insurance":"**Insurance.** Gynecomastia surgery is usually treated as cosmetic, and most policies do not pay for cosmetic surgery. A policy may consider it when a doctor records a medical need. Read your policy, ask your insurer in writing before you book, and keep the estimate and the diagnosis. We do not promise cashless approval.","payment":"**Payment.** Cash, cards and instalments through a lender may be possible. Terms and fees depend on the hospital and the lender and are not shown here. {tbc}","sources":[{"label":"NHS: Gynaecomastia","href":"https://www.nhs.uk/conditions/gynaecomastia/"},{"label":"Mayo Clinic: Gynecomastia","href":"https://www.mayoclinic.org/diseases-conditions/gynecomastia/symptoms-causes/syc-20351793"},{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date shown are sample data and will be replaced by the real ones.","The range is a working figure from the partner side. It still has to be confirmed in writing for Bestdoctorsin and the partner hospital, and it will carry a date.","Typical timings for an uncomplicated operation, to be confirmed by the reviewer. Your surgeon''s advice overrides this page.","Insurance wording is general and is to be confirmed by the reviewer. Your policy document decides.","Several grading scales are in use and they do not match exactly. The four grades here are a plain summary, not a quotation of one scale. Studies on technique and recovery will be read and cited here after the reviewer checks each one."]}'::jsonb, null, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('liposuction', 'surgery', null, null, null, null, 'Liposuction', 'Liposuction', 'Body contouring', 'Removes stubborn pockets of fat from areas such as the abdomen, flanks, thighs, arms, chest and chin. Not a weight-loss treatment.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Abdomen, waist, thighs, hips, arms, back, chest, chin and neck","howPerformed":"Fat is loosened and drawn out through tiny cuts with a thin tube, sometimes with ultrasound, power or laser assistance; a solution is often put into the fat first.","preparation":"Examination by a surgeon, review of medicines, blood tests and an anaesthesia fitness check.","followup":"Compression garment, a first review about three to five days later, more review visits, and a gradual return to exercise as the surgeon advises."}'::jsonb, '{"minInr":60000,"maxInr":80000,"validAsOf":"2026-11","isSample":true}'::jsonb, '[{"factor":"Areas treated","why":"The abdomen, flanks, thighs, arms, back, chest and chin differ in size, depth of fat and skin."},{"factor":"Number of areas","why":"Two or more areas take longer, need a bigger anaesthetic plan and usually cost more."},{"factor":"Technique","why":"Ultrasound-assisted and other equipment-based methods are priced differently from standard suction."},{"factor":"Amount of fat removed","why":"More fat means more time, and may mean a night in hospital."},{"factor":"Hospital charges","why":"A day-care centre and a multi-specialty hospital price theatre and rooms differently."},{"factor":"Anaesthesia","why":"General anaesthesia costs more than local with sedation."},{"factor":"Garments and follow-up","why":"Number of garments, and whether review visits are included or charged one by one."},{"factor":"A second operation","why":"Some quotes include a touch-up for a period, some charge in full."}]'::jsonb, 'About 1 to 2 weeks', 'Removes stubborn fat from chosen areas. Not for weight loss.', 1, '["gynecomastia-surgery","tummy-tuck"]'::jsonb, '["liposuction-vs-weight-loss","liposuction-recovery-timeline","liposuction-body-areas"]'::jsonb, '[]'::jsonb, null, '{"dek":"Liposuction removes pockets of fat that diet and exercise did not shift, from areas such as the abdomen, flanks, thighs, arms or chin. It is not weight loss. Here is what [liposuction](/liposuction) involves, what changes the price area by area, how recovery runs, and how we check a surgeon. The [national cost factors](/cost/liposuction) are on their own page.","shortAnswers":[{"q":"Is liposuction a way to lose weight?","a":"No. It reshapes stubborn pockets of fat in one or more areas. It is not a treatment for obesity, and the surgeon will ask you to be near a steady weight first.","href":"#surgery","linkText":"What it does"},{"q":"What will it cost?","a":"It depends on the area, the number of areas and the technique, so the price is shown area by area, not as one headline figure. The ranges are to be confirmed.","href":"#cost","linkText":"The price table"},{"q":"How long until I am back to normal?","a":"Most people rest for a few days, return to desk work within one to two weeks and build up exercise over four to six weeks. The contour keeps settling for months.","href":"#recovery","linkText":"The calendar"},{"q":"Who operates, and who checks them?","a":"No surgeon is listed yet. We list one only after registration and accreditation are checked.","href":"#choose","linkText":"The checks"}],"operation":{"lead":"Liposuction takes out localised fat through tiny cuts, using a thin tube. It shapes the body. It does not treat weight, and fat cells left in untreated areas can still grow if weight is gained.","body":"The surgeon marks the areas while you stand, then you have anaesthesia, which may be local with sedation or general depending on how much is being treated. A salt-water solution with a numbing medicine is often put into the fat first, so there is less bleeding and discomfort. Fat is then loosened and drawn out, the shape is checked from several sides, and the cuts are closed. You wear a compression garment afterwards. [Chest fat in men](/learn/liposuction-for-men) can be treated this way too, and when the cause is gland tissue rather than fat, the plan is different: see [gynecomastia surgery](/gynecomastia-surgery).","caption":"Fat removed through tiny cuts with a thin tube.","ask":"Which areas will you treat, which technique and why, how much fat do you expect to remove, and what is the plan if one side needs touching up later?","how":["Consultation: history, medicines, examination, and tests the surgeon asks for. An anaesthesia fitness check follows.","Planning: the surgeon marks the areas standing up and agrees the goal with you, including what liposuction cannot do.","Anaesthesia: local with sedation for a small area, general for larger or several areas. The surgeon and the anaesthetist decide.","The operation: tiny cuts, a solution into the fat, loosening and removal of fat, then a check of the contour and closure.","Straight after: a compression garment, a short stay in recovery, and written instructions. Some people go home the same day and some stay a night, depending on the areas and the anaesthesia.","Follow-up: a first review in the first week, usually around day 3 to 5, then more visits as the surgeon plans."],"whoItSuits":[{"term":"Often suits","text":"Adults in good general health, near a steady weight, with firm skin and a pocket of fat that has not moved with diet and exercise."},{"term":"Needs a different plan","text":"Loose skin or a stretched abdominal wall is not fixed by liposuction. See [liposuction or tummy tuck](/learn/liposuction-vs-tummy-tuck)."},{"term":"Often asked to wait","text":"A recent big change in weight, smoking, pregnancy or plans for it, and some health conditions. The surgeon decides after an examination."},{"term":"Not a substitute for","text":"Weight loss, or a treatment for obesity. See [liposuction is not weight loss](/learn/liposuction-vs-weight-loss)."}]},"areas":{"lead":"Surgeons commonly treat the abdomen, waist and flanks, thighs and hips, buttocks, the bra-strap area of the back, the upper arms, the chest, and the chin and neck. Each area behaves differently, and that is why the price depends on the area.","body":"How many areas are treated, how much fat sits in each, and how elastic the skin is all change the plan. A small, firm-skinned area may need one short session. Several areas at once take longer, need a larger anaesthetic plan and cost more. Read [which body areas liposuction can treat](/learn/liposuction-body-areas) for a closer look at each one.","rows":[{"area":"Abdomen","usual":"Often the largest single area","depends":"How far the fat extends, and whether loose skin or weak muscle is the real issue"},{"area":"Waist and flanks","usual":"Often paired with the abdomen","depends":"Number of zones treated, front to back"},{"area":"Thighs and hips","usual":"Inner, outer or both","depends":"Volume of fat, and skin tone after the fat is removed"},{"area":"Upper arms","usual":"Usually a smaller area","depends":"Skin elasticity: loose skin may need more than liposuction"},{"area":"Back, bra-strap area","usual":"Treated in zones","depends":"Number of zones and the depth of fat"},{"area":"Chest in men","usual":"Fat only, or with gland removal","depends":"Whether it is fat or gland: see [gynecomastia surgery](/gynecomastia-surgery)"},{"area":"Chin and neck","usual":"Small area, short operation","depends":"Technique, and whether skin or muscle under the chin is also a cause"}],"note":"Which areas, how many and in what order is a surgeon''s decision after an examination. A photo or a phone call cannot settle it."},"techniques":{"lead":"Several techniques exist, and a surgeon may combine them. The choice depends on the area, the amount of fat, the skin, earlier procedures and what you want. No technique suits everyone, and this page does not rank them.","rows":[{"name":"Tumescent","how":"A salt-water solution with a numbing medicine and a medicine that narrows blood vessels is put into the fat, then the fat is drawn out.","often":"The base of most plans; used with the others","ask":"How much solution and what limit do you keep for one session?"},{"name":"Ultrasound-assisted","how":"Sound energy loosens fat before it is drawn out. A surgeon may choose it for denser fat or for finer shaping.","often":"Denser areas such as the back or the male chest","ask":"Why this technique for my area, and does it change the price?"},{"name":"Power-assisted","how":"The tube moves with a small motor, so the surgeon makes shorter strokes.","often":"Larger volumes, or repeat work","ask":"Does it change the time under anaesthesia?"},{"name":"Laser-assisted","how":"Laser energy warms and loosens fat before removal, and some surgeons use it to tighten skin slightly.","often":"Small areas and some neck or chin plans","ask":"What does it add over the standard approach in my case?"},{"name":"Traditional suction","how":"The surgeon moves a thin tube by hand to break up and draw out fat.","often":"Many routine cases","ask":"Is this enough for the areas I have chosen?"}],"note":"Newer does not mean better for you. Ask the surgeon to explain the choice and what it does to the quote. See [types of liposuction](/learn/types-of-liposuction)."},"compare":{"tummyTuckLead":"Liposuction and a tummy tuck solve different problems. Liposuction removes fat. A tummy tuck removes loose skin and tightens the abdominal muscle wall. Some people need one, some need both, and a surgeon decides after an examination.","tummyTuck":[{"feature":"What it changes","lipo":"Fat in a chosen area","tuck":"Loose skin and a stretched muscle wall"},{"feature":"Cuts","lipo":"Tiny cuts, a few millimetres","tuck":"A long cut low on the abdomen, and one around the navel"},{"feature":"Skin","lipo":"Does not remove loose skin","tuck":"Removes extra skin"},{"feature":"Recovery","lipo":"Usually shorter","tuck":"Usually longer, with more restriction early on"},{"feature":"Often chosen when","lipo":"Skin is firm and fat is the main issue","tuck":"Skin is loose or muscles have parted, for example after pregnancy or a large weight change"}],"nonSurgicalLead":"Several non-surgical options are described for small pockets of fat. They are different from surgery, and this page has no comparison data on how much each changes in how many sessions.","nonSurgical":[{"name":"Fat freezing","text":"A device cools the skin over a pocket of fat. It is done in sessions and no cuts are made."},{"name":"Radiofrequency","text":"A device warms the tissue in sessions, and is also used for skin tightening."},{"name":"Laser and ultrasound devices","text":"Energy devices used over the skin in sessions."},{"name":"Fat-dissolving injections","text":"Injections into a small pocket, such as under the chin, usually in more than one session."},{"name":"Muscle stimulation","text":"A device that makes muscles contract, sometimes combined with other tools."}],"nonSurgicalNote":"Each usually changes less per session than surgery, and results vary between people. Ask any provider for written details of what was done for people like you, how many sessions are planned and what each costs. See [fat freezing, laser, RF or liposuction](/learn/liposuction-vs-non-surgical-fat-reduction).","whoShouldWait":["Your weight is still changing","You are pregnant or planning a pregnancy soon","You smoke and have not been able to stop","A health condition is not under control","You expect liposuction to replace weight loss"]},"recovery":{"lead":"Recovery runs in stages, and the contour keeps improving for months. These are typical timings for an uncomplicated operation, {pending} and your surgeon''s advice overrides this page.","body":"Swelling and bruising are normal at first and hide the final shape. The compression garment helps the skin settle against the new contour. You will usually have a review in the first week, and more visits afterwards. Plan leave and travel around the first review, not around the operation date. The [week by week recovery guide](/learn/liposuction-recovery-timeline) goes into more detail.","highlights":[{"pre":"Rest for","big":"2 to 3","post":"days","text":"Swelling, soreness and bruising are usual"},{"pre":"Review at","big":"day 3 to 5","text":"The first check, and a garment fit"},{"pre":"Back to routine in","big":"2 to 4","post":"weeks","text":"Desk work often sooner, if the surgeon agrees"},{"pre":"Shape settles by","big":"6 to 12","post":"months","text":"Swelling fades slowly, and skin adjusts"}],"timeline":[{"when":"Day 0 to 3","notice":"Soreness, swelling, bruising, fluid leaking from the cuts, tiredness","doThis":"Rest, short walks in the house, garment on, medicines as advised, plenty of fluids"},{"when":"Week 1","notice":"Swelling peaks and bruises change colour; the first review","doThis":"Light movement; the surgeon may allow a shower and desk work soon after"},{"when":"Weeks 2 to 4","notice":"Less soreness, uneven swelling, numb or tight skin","doThis":"Gradual return to routine; light massage only if the surgeon advises it"},{"when":"Weeks 4 to 6","notice":"Comfort improves, firmness may remain","doThis":"Step up activity as the surgeon allows; heavy lifting and hard training after approval"},{"when":"Months 2 to 3","notice":"The contour is clearer; some swelling remains","doThis":"Normal exercise if approved; garment as the surgeon sets"},{"when":"Months 6 to 12","notice":"Final shape; scars fade and soften","doThis":"Keep a steady weight; ask about any area that looks uneven before deciding on touch-ups"}],"grid":{"cols":["Day 1 to 3","Week 1","Week 2","Weeks 4 to 6"],"rows":[{"label":"Desk work","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Often"},{"state":"y","text":"Yes"}]},{"label":"Driving","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"}]},{"label":"Walking","cells":[{"state":"y","text":"Short"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Gym","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"}]},{"label":"Flying","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Often"}]}]},"closing":"Bring up any pain that is getting worse, a fever, a hot or red area, a swollen calf or breathlessness with your doctor straight away. Do not wait for the next visit."},"risks":{"lead":"Every operation carries risk. These are the ones people most often ask about, in plain words, and what you can do or ask. This is not a complete list, and the surgeon will go through yours.","rows":[{"risk":"Bruising and swelling","means":"Common, and expected for weeks. They hide the final shape.","ask":"How long should I expect it, and what is normal for my areas?"},{"risk":"Numbness or changed feeling","means":"Often temporary. A patch can stay different for longer.","ask":"How long can this last in my area?"},{"risk":"Uneven contour or lumps","means":"The surface can look uneven, and one side can differ from the other.","ask":"How do you check the shape during the operation, and when is a touch-up considered?"},{"risk":"Fluid collection (seroma)","means":"Fluid can gather under the skin and may need draining.","ask":"How will it be checked, and who drains it?"},{"risk":"Bleeding or a blood collection (haematoma)","means":"Uncommon. May need treatment.","ask":"What is your plan if it happens?"},{"risk":"Infection","means":"Possible after any cut. Early treatment matters.","ask":"Which signs should make me call, and who do I call?"},{"risk":"Loose skin","means":"Skin may not tighten fully after fat is removed, especially with low elasticity.","ask":"Will my skin tighten, and what is the plan if it does not?"},{"risk":"Scars and marks","means":"Tiny scars remain. Colour changes can occur.","ask":"Where will the cuts be, and how do you place them?"},{"risk":"Clots and anaesthesia risks","means":"Rare, but serious when they happen. Larger operations raise the risk.","ask":"What do you do to lower the risk of clots, and what are my own risk factors?"},{"risk":"A second operation","means":"Sometimes needed to improve the shape.","ask":"Is a second operation charged, and for how long after the first?"}],"alert":"Call your doctor straight away for a fever, spreading redness or heat, a swollen painful calf, chest pain, breathlessness, heavy bleeding or pain that keeps getting worse. If you cannot reach the doctor, go to the nearest emergency department. See [liposuction risks](/learn/liposuction-risks).","wait":["Your weight is still changing","You smoke and have not stopped","A health condition or a medicine needs adjusting first","You are pregnant, or planning a pregnancy soon","You have had a recent illness or infection"],"tell":["All your medicines and supplements, including blood thinners","Earlier operations and any problems with anaesthesia","Any history of blood clots, in you or your family","Allergies, especially to medicines or dressings","Smoking, alcohol, and any steroid or supplement use"]},"patientQuestions":[{"q":"I have tried gym and diet for years. Is this the next step?","href":"#surgery","linkText":"Read: the operation"},{"q":"Will I be able to work from home the next day?","href":"#recovery","linkText":"Read: recovery calendar"},{"q":"Can two or three areas be done together?","href":"#areas","linkText":"Read: areas and techniques"},{"q":"Will the fat come back?","href":"#faq","linkText":"Read: questions"},{"q":"Is it better to have a tummy tuck?","href":"#compare","linkText":"Read: tummy tuck and other options"},{"q":"Does a men''s chest or love-handle plan differ?","href":"#areas","linkText":"Read: areas and techniques"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"In person, by WhatsApp or by phone, whichever you choose. Tell us which areas bother you. No pressure to book."},{"title":"A surgeon examines you","text":"Areas, technique and anaesthesia are decided in person, not by phone or from a photo."},{"title":"The hospital writes the cost","text":"The surgeon, anaesthesia and facility fees, plus garments, tests and follow-up visits, listed one by one."},{"title":"You pick the date","text":"The surgeon and the anaesthetist advise on day care or a night''s stay."},{"title":"After the operation","text":"A check-in from us on day 1, a compression garment, review visits and a staged return to routine."}],"quoteChecks":["list the areas treated and the technique?","list the surgeon, anaesthesia and facility fees separately?","say whether the compression garment is included?","write down the number of follow-up visits?","say whether a second operation is included, and for how long?"],"extras":["Tests before surgery","Compression garments (and a spare)","Medicines for the first days","Follow-up visits","Treating a complication","A second operation or touch-up","An overnight stay, if the surgeon asks","Your attendant''s stay and travel"],"insurance":"**Insurance.** Liposuction is usually treated as cosmetic, and most policies do not pay for cosmetic surgery. Read your policy, ask your insurer in writing before you book, and keep the estimate. We do not promise cashless approval.","payment":"**Payment.** Cash, cards and instalments through a lender may be possible. Terms and fees depend on the hospital and the lender and are not shown here. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date shown are sample data and will be replaced by the real ones.","The ranges are working figures from one source. They still have to be confirmed in writing for Bestdoctorsin and the partner hospital, and each will carry a date.","Typical timings for an uncomplicated operation, to be confirmed by the reviewer. Your surgeon''s advice overrides this page.","Insurance wording is general and is to be confirmed by the reviewer. Your policy document decides.","Published studies on technique, risk and recovery will be read and cited here after the reviewer opens and checks each one. None is cited yet."]}'::jsonb, '{"titleEm":"(body contouring)","heroPlate":"areas","heroPlateCaption":"Areas where liposuction is commonly planned. A surgeon marks the exact zones on you.","operationHeading":"What the operation involves: tiny cuts, a thin tube and a plan","operationPlate":"cannula","operationCaptions":[{"title":"Before","text":"Fat sits in layers under the skin"},{"title":"During","text":"A thin tube removes it through tiny cuts"}],"recoveryHeading":"Recovery calendar: day 0 to month 12","riskGuideHref":"/liposuction#risks","priceLabel":"One area, usual total bill","priceLinkText":"Other areas and techniques","costMode":"options","costHeading":"What it costs, area by area","costCaption":"Price table by area and technique. Each row is a separate case, so the rows are not added together.","tocLabels":{"surgery":"The operation","choices":"Areas and techniques"}}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('tummy-tuck', 'surgery', null, null, null, null, 'Tummy tuck', 'Tummy tuck', 'Abdominoplasty', 'For loose skin and weak abdominal muscle after weight change.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Abdomen","howPerformed":"Extra skin is removed and the abdominal muscle is tightened.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Compression garment and review visits."}'::jsonb, null, '[]'::jsonb, '2 to 3 weeks', 'For loose skin and weak abdominal muscle after weight change.', 2, '["liposuction","gynecomastia-surgery"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('rhinoplasty', 'surgery', null, null, null, null, 'Rhinoplasty', 'Rhinoplasty', 'Nose surgery', 'Surgery to change the shape or the breathing function of the nose.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Nose","howPerformed":"The bone and cartilage of the nose are reshaped.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Splint, review visits and a staged return to activity."}'::jsonb, null, '[]'::jsonb, 'To be confirmed', 'Surgery to change the shape or the breathing function of the nose.', 1, '["liposuction"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('breast-augmentation', 'surgery', null, null, null, null, 'Breast augmentation', 'Breast augmentation', null, 'Surgery to increase breast size with implants or fat.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Breast","howPerformed":"An implant is placed through a small cut, or fat is moved from another area.","preparation":"Examination, medicine review and an anaesthesia fitness check.","followup":"Support garment and review visits."}'::jsonb, null, '[]'::jsonb, 'To be confirmed', 'Surgery to increase breast size with implants or fat.', 3, '["tummy-tuck"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, null, null, false),
  ('acne-treatment', 'skin', null, '[{"key":"consultation","label":"First consultation","ask":"Is the first visit charged, and is it credited if you start a plan?"},{"key":"prescriber","label":"Prescriber is a dermatologist","ask":"Who writes the prescription, and are they registered with a medical council?"},{"key":"medicines","label":"Creams, gels and tablets","ask":"Are medicines in the quote, or bought separately each month?"},{"key":"tests","label":"Tests if tablets need checks","ask":"Which blood tests are planned, and who pays for them?"},{"key":"consumables","label":"Peel or light session supplies","ask":"Is each session priced with its solutions and consumables?"},{"key":"followups","label":"Follow-up visits","ask":"How many reviews does the plan include, and what does an extra one cost?"},{"key":"aftercare","label":"Aftercare products","ask":"Which products are advised, and are they in the price?"}]'::jsonb, '{"title":"Acne Treatment: Options, Timeline, Side Effects, Cost","description":"What acne treatment involves, how long it takes, the risks, who should wait, and what a course costs. Reviewed by a registered doctor.","cityTitle":"Acne Treatment in {city}: Cost, Timeline, Risks"}'::jsonb, '{"seoTitle":"Acne Treatment Cost in India: What Changes the Price","metaDescription":"What an acne course costs in India: consultation, medicines, peels and light sessions, follow-ups, and what to ask in writing.","h1":"Acne treatment cost in India","answer":"An acne plan is priced as a series: a consultation, follow-up visits, medicines each month, and sometimes procedures. The total depends on how many months you need and what is added. The ranges on this page are {sample} until confirmed quotes are collected, and each one will show its source and date.","unit":"course","rangeHeading":"Sample lines for a course","rangeCaption":"Each line is a separate case with its own range. Your total is built from the lines that apply to you, not from one headline figure.","planner":{"heading":"A six-month planner","formula":"Total = consultation + (follow-up visits x months) + (medicines x months) + (procedure sessions x price per session) + tests","steps":["Ask the doctor how many months and how many visits to plan for.","Fill each line from the written quote, not from a verbal estimate.","Add tests and aftercare products if they are not in the quote.","Leave the lines that do not apply to your plan blank. The formula gives your own range, not an average."]},"factors":[{"factor":"Severity and type","why":"Mild acne may need a cream and few reviews. Severe acne can need tablets, tests and more visits."},{"factor":"Number of months","why":"The total grows with the length of the plan, so ask for the expected number of months."},{"factor":"Who treats you","why":"A dermatologist, a general physician and a cosmetology clinic price visits differently."},{"factor":"Tablets and monitoring","why":"Some tablets need blood tests and closer review, which adds visits and fees."},{"factor":"Procedures","why":"Each peel or light session is priced separately, and sessions repeat."},{"factor":"Clinic type","why":"A hospital outpatient department and a standalone clinic structure fees differently."},{"factor":"City","why":"Visit fees differ between cities. Ranges by city appear only where local quotes exist."}],"notIncluded":["Medicines bought at a pharmacy each month","Blood tests done at an outside lab","Sunscreen and moisturiser","Treatment of a reaction","Extra visits beyond the plan","Your travel and time off for repeat visits"],"compareQuotes":["Ask each clinic for the same lines in writing: consultation, each review, medicines, tests and procedures.","Compare the number of months and visits each plan assumes, not only the price of one visit.","Check who prescribes and examines you, and ask for the registration number to be shown on the quote.","Be careful of a plan that asks you to prepay for many sessions before an examination.","A promise of a set number of days to a result is a reason to ask more questions."],"insurance":"Acne treatment is usually treated as cosmetic or routine skin care, and many policies do not pay for it. Some may consider severe acne when a doctor records a medical need. Ask your insurer in writing before you start.","payment":"Visits and procedures are usually paid per visit. Instalments may be available through a lender, and terms are not shown here. {tbc}","method":"No figure is shown yet. When quotes arrive each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used.","faqs":[{"q":"How much does acne treatment cost in India?","a":"It depends on the plan. A course is the sum of a consultation, reviews, medicines, and any procedures, over several months. Ranges on this page are sample data until confirmed. Ask each clinic for the same lines in writing so you can compare."},{"q":"Why do two clinics quote different totals?","a":"They may assume different numbers of months and visits, include different medicines, or count procedures differently. Compare line by line."},{"q":"Are peels and light sessions included in a course?","a":"Not always. Many quotes price them per session on top of visits and medicines. Ask how many sessions the doctor expects."},{"q":"Do tablets add to the cost?","a":"They can. Some need blood tests and extra reviews, which add fees. Ask for tests and review dates in the written plan."},{"q":"Is there a lower-cost way to treat acne?","a":"A simple plan with fewer procedures costs less than a plan with many sessions. What suits you is a doctor''s decision after an examination. Price is one factor to weigh against the plan''s length and checks."},{"q":"Does insurance pay for acne treatment?","a":"Usually not, because policies often treat it as cosmetic. Ask your insurer in writing."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'Acne treatment', 'Acne treatment', null, 'Medicines, peels and light-based sessions a doctor can use for acne, chosen by the type and grade of acne and by skin type.', '{"procedureType":"https://schema.org/NoninvasiveProcedure","bodyLocation":"Face, chest and back","howPerformed":"A doctor examines the skin, then chooses creams, tablets, peels, light or laser sessions, or a mix, and reviews progress over weeks.","preparation":"Skin examination, a review of current creams and medicines, and a pregnancy check where it applies.","followup":"Review visits every few weeks, sun protection, and changes to the plan as the skin responds."}'::jsonb, null, '[{"factor":"Type and grade of acne","why":"Mild acne may need a cream only, while deeper or widespread acne may need tablets, tests and more visits."},{"factor":"Who treats","why":"A dermatologist and a general clinic price consultations differently."},{"factor":"Medicines","why":"The prescription decides the monthly cost, and some tablets need blood tests."},{"factor":"Sessions","why":"Peels, light and laser are priced per session, and a plan often needs several."},{"factor":"Follow-up visits","why":"Some clinics include review visits in the plan, some charge for each."},{"factor":"Aftercare products","why":"Cleansers, moisturisers and sun protection are bought separately in most plans."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do clinic fees."}]'::jsonb, 'Most people go on with normal days', 'Types and grades of acne, treatment options, what the first three months look like.', 2, '["hydrafacial","anti-aging-treatment"]'::jsonb, '["acne-grades-when-to-see-doctor","acne-medicines-doctors-prescribe","how-long-acne-treatment-takes"]'::jsonb, '[]'::jsonb, null, '{"dek":"Acne treatment usually means creams, sometimes tablets, and sometimes a procedure such as a peel or a light session, chosen after a doctor looks at your skin. Most plans run for months, and a first change often takes 6 to 8 weeks to show. Results vary and acne can return. The [cost of a course](/cost/acne-treatment) depends on the plan, so ask for each line in writing.","shortAnswers":[{"q":"Can a pharmacy cream do the job?","a":"For a few mild spots, sometimes. If spots are many, painful, deep or leave marks, a dermatologist can choose stronger options and watch for side effects.","href":"#surgery","linkText":"What treatment involves"},{"q":"How long will it take?","a":"Plan for months. A first change often shows at about 6 to 8 weeks, and the plan is reviewed every few weeks.","href":"#recovery","linkText":"The first three months"},{"q":"What will it cost?","a":"A consultation, then follow-up visits, medicines and sometimes procedures. The ranges shown are to be confirmed.","href":"#cost","linkText":"The cost lines"},{"q":"Who should I see?","a":"A registered dermatologist for anything beyond a few mild spots. Check the registration before the first visit.","href":"#choose","linkText":"The checks"}],"operation":{"lead":"Acne starts when pores block and the oil glands under the skin become inflamed. Treatment aims to reduce new spots, calm the ones you have and lower the chance of marks. The doctor looks at the type of spots, how many there are, where they sit and what you have already tried.","body":"Your plan may be one cream, a mix of creams, a course of tablets, a procedure, or a combination. Read about [acne grades](/learn/acne-grades-when-to-see-doctor) before the visit, and about the [medicines doctors prescribe](/learn/acne-medicines-doctors-prescribe) to know what to ask. If you are asked about [isotretinoin](/learn/isotretinoin-acne-questions), read that guide first. Some spots that look like acne are caused by yeast, and the plan is different, see [fungal and bacterial acne](/learn/fungal-acne-vs-bacterial-acne). A [hydrafacial](/hydrafacial) is a skin-care session and does not treat acne.","caption":"How a plan is built: examine, choose, review, adjust.","ask":"Which type and grade is mine, and what do you expect to change in the first 8 weeks?","how":["First visit: the doctor examines your skin and asks about creams you have used, medicines, periods and pregnancy plans if they apply, and family history. Photos taken in the clinic stay with the clinic.","Creams and gels: used on the skin every day. Dryness, stinging or peeling are common in the first weeks.","Tablets: some people with moderate or severe acne, or acne that leaves marks, are prescribed tablets. These need a doctor''s checks. Never take another person''s tablets.","Procedures: a chemical peel, a light session or clearing of blocked pores may be added. Sessions are spaced weeks apart, and the doctor sets the number.","Follow-up: visits every few weeks at first, so the doctor can change the plan. Skipping reviews is a common reason plans stall."],"whoItSuits":[{"term":"Who asks","text":"Teenagers and their parents, adults whose acne started after 25, and women with spots along the jaw. The first question differs for each group, and so does the plan."},{"term":"Expectations","text":"Acne is managed over time. Treatment can help reduce spots and marks, results vary, and acne can return after a plan ends."},{"term":"Commitment","text":"Daily use of creams for months, and review visits. If travel makes visits hard, plan that before you start."},{"term":"Under 18","text":"A parent or guardian takes part in decisions about tablets and procedures. The doctor explains the plan to both."}]},"areas":{"lead":"Doctors describe acne by grade. Scales differ between doctors, so yours will explain theirs. This table shows the usual idea, not a diagnosis.","body":"Only an examination can say which grade you have. Grade changes over time, and the plan changes with it.","rows":[{"area":"Mild","usual":"Blackheads and whiteheads, a few small red spots","depends":"How long it has lasted and whether products are making it worse"},{"area":"Moderate","usual":"More red spots with pus, on the face and sometimes the back or chest","depends":"Marks left behind, skin type, and whether creams alone have been tried properly"},{"area":"Severe","usual":"Many large, painful lumps and deep spots, often with marks","depends":"Whether tablets are suitable, pregnancy plans, and checks needed before they start"},{"area":"Sudden or unusual","usual":"A rapid flare, uniform itchy bumps, or acne after a new medicine or supplement","depends":"The cause. It needs a doctor early, not a stronger cream"}],"note":"A grade helps a doctor choose a plan. It does not decide the outcome."},"techniques":{"lead":"These are the usual options. A doctor may use one or combine several. Medicine names and doses are decided at the visit and are not listed here.","rows":[{"name":"Creams and gels","how":"Applied to the skin, usually daily","often":"Mild to moderate acne, and as the base of most plans","ask":"How do I build up use, and what dryness is normal?"},{"name":"Antibiotic tablets","how":"Taken by mouth for a limited period, often with a cream","often":"Moderate acne with many inflamed spots","ask":"How long will I take them, and what stops me from staying on them?"},{"name":"Hormonal approaches","how":"Prescribed by a doctor for some women after assessment","often":"Women whose acne follows a cycle pattern","ask":"Which tests are needed first, and what if I plan a pregnancy?"},{"name":"Isotretinoin tablets","how":"A prescription course with regular checks","often":"Severe acne, or acne that leaves marks, after a specialist''s assessment","ask":"What are the pregnancy rules, blood tests and review dates?"},{"name":"Chemical peel","how":"A solution applied to the skin in clinic, then washed off","often":"Some people with mild to moderate acne or marks, as an add-on","ask":"How many sessions, how long is flaking, and what is the pigment risk for my skin?"},{"name":"Light or laser session","how":"A device used on the skin in clinic","often":"Selected cases, as an add-on to a plan","ask":"What is the aim, how many sessions, and what are the burn and pigment risks?"},{"name":"Clearing blocked pores","how":"A clinician gently removes blackheads and whiteheads","often":"Many blackheads and whiteheads, alongside creams","ask":"Who does it, and how are tools cleaned?"}],"note":"A procedure is usually an add-on to a plan. It does not replace one. See [peels, light and laser for acne](/learn/acne-peels-light-laser)."},"recovery":{"lead":"There is no recovery period for a cream. This is what the first three months commonly look like, and your doctor sets yours. {pending}","body":"Dryness and peeling in the first weeks do not mean the plan is failing. Some people see a flare before things settle. Tell the doctor if skin burns, swells or breaks out in a rash. See [how long acne treatment takes](/learn/how-long-acne-treatment-takes).","highlights":[{"pre":"about","big":"6 to 8 weeks","text":"Before a first visible change is usual, per the reviewer"},{"pre":"every","big":"4 to 6 weeks","text":"Typical gap between early reviews, set by the doctor"},{"pre":"about","big":"3 months","text":"Point where many doctors judge whether the plan is working"}],"timeline":[{"when":"Day 0","notice":"Plan written, creams started","doThis":"Start slowly as advised. Use sunscreen if the doctor says so. Do not pick spots."},{"when":"Week 1 to 2","notice":"Dryness, stinging or peeling from creams","doThis":"Use a gentle moisturiser if advised. Do not add scrubs or extra products."},{"when":"Week 4","notice":"Some people see a flare before it settles","doThis":"First review. Tell the doctor about irritation, missed doses and new products."},{"when":"Week 6 to 8","notice":"A first change often becomes visible","doThis":"Keep the routine. Photos at home on the same day each month help the review."},{"when":"Month 3","notice":"Doctor decides whether to continue, change or add","doThis":"Review visit. Procedures, if planned, are timed around this visit."},{"when":"Month 6 and after","notice":"Maintenance, or a break from some medicines","doThis":"Ask what to do if spots return, and who to see locally."}],"grid":{"cols":["Wk 1","Wk 2","Wk 4","Wk 8","Mo 3"],"rows":[{"label":"Daily creams","cells":[{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Sun cover","cells":[{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Peel or light","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"},{"state":"m","text":"If planned"}]},{"label":"Review visit","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"y","text":"Yes"},{"state":"m","text":"Often"},{"state":"y","text":"Yes"}]},{"label":"Planning a pregnancy","cells":[{"state":"m","text":"Tell doctor"},{"state":"m","text":"Tell doctor"},{"state":"m","text":"Tell doctor"},{"state":"m","text":"Tell doctor"},{"state":"m","text":"Tell doctor"}]}]},"closing":"Tell your doctor at once about swelling of the lips or face, a spreading rash, severe mood change, or burning after a peel. If you cannot reach the doctor, go to the nearest emergency department."},"risks":{"lead":"Every treatment has risks. These are the ones people most often ask about, in plain words, with what to ask. This is not a complete list, and your doctor will go through yours.","rows":[{"risk":"Dryness and irritation","means":"Common with creams and tablets in the first weeks. Skin can sting, redden or peel.","ask":"How do I build up use, and when should I stop and call?"},{"risk":"Sun sensitivity","means":"Some creams and tablets make skin burn more easily, and sun can darken marks.","ask":"Which sun protection do you advise for my skin?"},{"risk":"A flare in the first weeks","means":"Some people see more spots before improvement.","ask":"How long is a flare expected, and when is it a reason to call?"},{"risk":"Birth defects with some tablets","means":"Some acne tablets can seriously harm an unborn baby. Pregnancy rules and tests apply.","ask":"What do I need to do about pregnancy before, during and after the course?"},{"risk":"Mood or liver changes","means":"Some tablets need blood tests and a doctor''s attention to mood.","ask":"Which tests, how often, and what signs should I report?"},{"risk":"Peel burns and colour change","means":"A peel or light session can leave darker or lighter patches, more often in darker skin.","ask":"What is my risk, and can you do a small test area first?"},{"risk":"Scarring from picking","means":"Picking and squeezing can leave marks that last longer than the spot.","ask":"What can I do instead of picking, and when do marks need treatment?"},{"risk":"Acne returning","means":"Acne can return after a plan ends, so maintenance matters.","ask":"What is the plan after the course, and when should I come back?"}],"alert":"Call your doctor straight away for swelling of the face or lips, a spreading rash, blistering, severe stomach pain, yellow skin or eyes, or a low mood that worries you or the people around you. If you cannot reach the doctor, go to the nearest emergency department.","wait":["You are pregnant or planning a pregnancy (ask before any tablet or peel)","Acne started suddenly, is very painful or is spreading fast","Acne began after a new medicine or supplement","The skin shows signs of infection: heat, pus that spreads, fever","You took isotretinoin in recent months and a peel or laser is being planned"],"tell":["Every cream, tablet, supplement and home remedy you use","Pregnancy, breastfeeding or plans to conceive","Previous reactions to medicines or skin products","A tendency to dark marks or thick scars after skin injuries","Low mood, liver or kidney conditions, and family history of acne scars"]},"patientQuestions":[{"q":"Do I need a doctor, or will a pharmacy cream do?","href":"#surgery","linkText":"Read: what treatment involves"},{"q":"How many months before I see a change?","href":"#recovery","linkText":"Read: the first three months"},{"q":"Which grade of acne do I have?","href":"#areas","linkText":"Read: grades"},{"q":"Are tablets always needed?","href":"#compare","linkText":"Read: the options"},{"q":"Why did my acne return?","href":"#faq","linkText":"Read: questions"},{"q":"What will a course cost in total?","href":"#cost","linkText":"Read: the cost lines"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp, in the language you prefer. Say how long the acne has lasted and what you have tried. No pressure to book."},{"title":"A dermatologist examines your skin","text":"The plan is made in person after looking at your skin, not from a photo or a phone call."},{"title":"You receive a written plan","text":"Visits, medicines, procedures and expected months, each on its own line."},{"title":"You start slowly","text":"The first weeks are for building up creams and watching for irritation."},{"title":"You return for reviews","text":"A coordinator check-in after the first week, then reviews at the interval the doctor sets."}],"quoteChecks":["name the doctor who prescribes and examines you?","list the consultation and each follow-up visit separately?","say which medicines are included and which you buy yourself?","list any blood tests that tablets need?","price each peel or light session, with its number of sessions?"],"extras":["Follow-up visits beyond those in the plan","Creams and gels each month","Tablets, if prescribed","Blood tests if tablets need monitoring","Peels, light sessions and pore clearing","Sunscreen and moisturiser","Treatment of a reaction","Travel and time off for repeat visits"],"insurance":"Insurance. Acne treatment is usually treated as cosmetic or routine skin care, and many policies do not pay for it. Some policies may consider severe acne when a doctor records a medical need. Ask your insurer in writing before you start and keep the plan.","payment":"Payment. Pay per visit or per procedure session. Instalment plans through a lender may exist, but terms depend on the clinic and the lender and are not shown here. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"},{"label":"American Academy of Dermatology: acne overview for patients","href":"https://www.aad.org/public/diseases/acne"},{"label":"NHS: acne overview","href":"https://www.nhs.uk/conditions/acne/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered dermatologist signs off.","Timings such as 6 to 8 weeks and the review gaps are general ranges to be confirmed or replaced by the reviewer.","Prescription medicines are named by class only here. Doses and brands are for the treating doctor.","Insurance and payment wording is general and to be confirmed. Your policy document decides.","Studies cited here will be read and checked by the reviewer first. None is cited yet."]}'::jsonb, '{"costMode":"options","priceLabel":"A course of acne treatment, usual total","priceLinkText":"The lines inside it","costHeading":"What an acne plan costs","costCaption":"Each line is a separate case with its own range. Sample data / To be confirmed.","operationHeading":"What acne treatment involves","recoveryHeading":"What the first three months look like","recoveryTocLabel":"First three months","timelineCaption":"What most people notice and do, by time since starting.","risksHeading":"Side effects and risks","riskGuideHref":"/acne-treatment#risks","heroPlate":"none","operationPlate":"none","labels":{"areasHeading":"Which kind of acne is it","areasCaption":"Grades of acne and what a doctor checks. Scales differ between doctors.","areasNoPlate":true,"techniquesHeading":"Treatment options","techniquesCaption":"The usual options, who they suit and what to ask.","tocTechniques":"Options"},"tocLabels":{"surgery":"What it involves","choices":"Types and grades"},"costUnit":"course"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('hydrafacial', 'skin', null, '[{"key":"consultation","label":"Skin check before the session","ask":"Is a skin check charged, and who does it?"},{"key":"performer","label":"Who performs it","ask":"Is it a doctor, a nurse or a trained technician, and can I see their training?"},{"key":"device","label":"Device tips and single-use parts","ask":"Are the tips new or single-use for me, and how are reusable parts cleaned?"},{"key":"serums","label":"Serums and boosters","ask":"Which serums are in the base price, and which boosters are extra?"},{"key":"numbing","label":"Cooling or comfort measures","ask":"Is anything used for comfort, and is it in the price?"},{"key":"aftercare","label":"Aftercare products","ask":"Which products are advised, and are they in the price?"},{"key":"review","label":"Review visit if the skin reacts","ask":"What happens, and what do I pay, if my skin reacts?"}]'::jsonb, '{"title":"Hydrafacial: Steps, Downtime, Risks and Cost Factors","description":"What a hydrafacial involves, what it cannot do, aftercare, who should skip it, and what changes the price. Doctor reviewed.","cityTitle":"Hydrafacial in {city}: Cost, Downtime, Risks"}'::jsonb, '{"seoTitle":"Hydrafacial Cost in India: What Changes the Price","metaDescription":"What a hydrafacial costs per session, why quotes differ (serums, add-ons, packs), and what to ask in writing.","h1":"Hydrafacial cost in India","answer":"A hydrafacial is priced per session, and the base price is only the start. Serums, boosters, extra steps and packs change the total, which is why quotes for the same session differ. The ranges on this page are {sample} until confirmed quotes are collected, and each will show its source and date.","unit":"session","rangeHeading":"Sample lines for one session","rangeCaption":"Each line is a separate case with its own range. Your total is built from the lines in your quote, not from one headline figure.","factors":[{"factor":"Base session or add-ons","why":"Boosters, extra steps and add-on serums are usually priced on top of the base session."},{"factor":"Packs","why":"A pack has a total and a per-session figure. Read both, and try one session before paying for a pack."},{"factor":"Who performs it","why":"A doctor-led clinic and a salon price the same session differently."},{"factor":"Device parts and serums","why":"Single-use tips and the serum choice change the bill."},{"factor":"Aftercare products","why":"Some clinics include them, some sell them separately."},{"factor":"Skin check","why":"Some places charge for it and credit it to the session, some do not charge."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}],"notIncluded":["Booster serums beyond the base session","Extra steps such as LED, where provided","Aftercare products","A skin check, if charged separately","Treatment of a reaction","Your travel and time off"],"compareQuotes":["Ask each place for the same lines in writing: the base session, each serum, each booster and any pack.","Compare totals for the same steps, not the headline price.","Ask who performs the session and whether tips are single-use.","Pay for one session before a pack, and keep the written quote.","A promise of a result for every skin type is a reason to ask more questions."],"insurance":"A hydrafacial is skin care, and most health policies do not pay for it. Ask your insurer in writing if you think a medical reason applies.","payment":"Sessions are usually paid for one at a time. Instalments may exist for packs, and terms are not shown here. {tbc}","method":"No figure is shown yet. When quotes arrive, each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used.","faqs":[{"q":"How much does a hydrafacial cost per session?","a":"It depends on the base session, serums, boosters and extra steps. The range on this page is sample data until confirmed. Ask each place for the same lines in writing, so you can compare totals."},{"q":"Why do quotes for the same session differ?","a":"Places count different things. One includes a serum and a booster in the base price, another adds them. Compare the total for the same steps."},{"q":"Is a pack cheaper than single sessions?","a":"A pack total divided by sessions can be lower per session, but you commit before you know how your skin reacts. Try one session first."},{"q":"Are boosters worth paying for?","a":"That depends on your skin and your goal, and it is a question for the person who performs it. Ask what is in a booster and what it is meant to do."},{"q":"Does insurance pay for a hydrafacial?","a":"Usually not, because it is skin care. Ask your insurer in writing."},{"q":"What should the quote list?","a":"The base session, each serum and booster, any extra steps, the pack total and per-session price, aftercare products, and what happens if your skin reacts."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'Hydrafacial', 'Hydrafacial', null, 'A skin-care session with a device that cleanses, exfoliates and applies serums. It is not a treatment for acne, scars or ageing.', '{"procedureType":"https://schema.org/NoninvasiveProcedure","bodyLocation":"Face","howPerformed":"A handheld device cleanses the skin, loosens dead skin with a mild acid, draws out debris by suction and applies serums, in steps over about half an hour.","preparation":"A short skin check, including recent medicines, pregnancy, active infection and sunburn.","followup":"Gentle skin care and sun protection for a few days, and a review visit if the skin reacts."}'::jsonb, null, '[{"factor":"Base session or add-ons","why":"Boosters, extra steps and add-on serums are usually priced on top of the base session."},{"factor":"Packs","why":"A pack of sessions has a total and a per-session figure, and the two should be read together."},{"factor":"Who performs it","why":"A doctor-led clinic and a salon price the same session differently."},{"factor":"Device parts and serums","why":"Single-use tips and the serum choice change the bill."},{"factor":"Aftercare products","why":"Some clinics include them, some sell them separately."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}]'::jsonb, 'Most people go back to routine the same day', 'What the steps are, who should skip it, downtime and aftercare.', 1, '["acne-treatment","anti-aging-treatment"]'::jsonb, '["hydrafacial-vs-regular-facial","hydrafacial-side-effects-who-should-skip","read-hydrafacial-quote"]'::jsonb, '[]'::jsonb, null, '{"dek":"A hydrafacial is a clinic facial that cleans and exfoliates the skin and loosens blocked pores with a handheld device, then applies a serum. A session takes about 30 to 45 minutes. Skin can look pink for a few hours. It is a skin-care session and not a treatment for acne or scars. The [cost per session](/cost/hydrafacial) changes with the serums, add-ons and packs in the quote.","shortAnswers":[{"q":"What does it do?","a":"It cleans the skin surface, removes dead skin and loosens debris from pores. The effect is on the surface and is short-lived.","href":"#surgery","linkText":"The steps"},{"q":"Who should skip it?","a":"Anyone with sunburn, open sores, a cold sore or infection, or a recent peel, laser or isotretinoin course. Ask first if you are pregnant.","href":"#risks","linkText":"Who should wait"},{"q":"What is the downtime?","a":"Most people go back to routine the same day. Pink skin can last a few hours and sensitivity a day or two.","href":"#recovery","linkText":"Hours and days"},{"q":"Why do quotes differ?","a":"Serums, boosters, extra steps and packs are priced on top of a base session. The ranges shown are to be confirmed.","href":"#cost","linkText":"The cost lines"}],"operation":{"lead":"A hydrafacial uses one handheld device to cleanse, exfoliate, loosen debris from pores with gentle suction, and apply serums. It looks and feels like a facial, and it is done in a clinic or salon.","body":"It does not treat acne, remove scars or change pigment. If you have active acne, a doctor may suggest another plan first, see [acne treatment](/acne-treatment) and [hydrafacial for acne-prone skin](/learn/hydrafacial-acne-prone-skin). For lines and ageing skin, see [anti-aging treatment](/anti-aging-treatment). Read [how a hydrafacial differs from a regular facial](/learn/hydrafacial-vs-regular-facial) before you compare quotes.","caption":"The steps run in order on a clean, dry face.","ask":"Who will perform my session, what is in the serum, and which of my skin conditions would make you advise against it?","how":["Skin check: a short look at your skin and a few questions about medicines, pregnancy, sunburn, cold sores and recent treatments.","Cleanse and exfoliate: the surface is cleaned and dead skin is loosened with a mild solution.","Loosen pores: a gentle suction removes debris from pores. Some people feel a tugging or stinging.","Serum: a serum is applied, and a booster may be added at extra cost.","Finish: sun protection is advised and aftercare is explained."],"whoItSuits":[{"term":"Who asks","text":"Adults who want a cleaning session before an event, people who like a facial with some exfoliation, and people curious about a clinic option rather than a salon facial."},{"term":"Expectations","text":"A fresh surface feel that settles over days. It is not a treatment for any skin condition, and results vary between people."},{"term":"Skin type","text":"Not every skin tolerates it. People with very sensitive skin, active eczema or a tendency to dark marks need a doctor''s advice first."},{"term":"Under 18","text":"A parent or guardian should take part in the decision, and a doctor should check the skin first."}]},"extraSections":[{"id":"steps","heading":"The steps in order","tocLabel":"Steps","lead":"Clinics order the steps slightly differently. This is the usual pattern, and your clinic will explain its own.","table":{"caption":"What happens, and what to ask at each step.","head":["Step","What happens","What to ask"],"rows":[["Skin check","Questions and a look at your skin","Will anyone examine my skin before starting?"],["Cleanse and exfoliate","A solution removes dead skin from the surface","Which solution, and for how long?"],["Pore cleaning","Gentle suction lifts debris out of pores","Is the tip new or cleaned between clients?"],["Serum","A serum is applied, sometimes with a booster","What is in it, and is it in the base price?"],["Finish","Sun protection and aftercare advice","What should I avoid in the next two days?"]]}},{"id":"limits","heading":"What a hydrafacial cannot do","tocLabel":"Limits","paragraphs":["A hydrafacial works on the skin surface. It does not remove acne scars, treat melasma or shrink pores in a lasting way, and it does not stop skin ageing. A doctor can say which of those concerns need a different approach.","Some people notice that skin looks fresher for a few days. That is a short-term effect on the surface, and results vary. Ask the clinic to say plainly what it expects for your skin and for how long."],"note":{"label":"If you have acne scars or pigment","text":"See a dermatologist before you pay for a pack of sessions. Irritating skin that is already marked can make marks darker."}},{"id":"how-often","heading":"How often people go","tocLabel":"How often","paragraphs":["Clinics suggest different gaps between sessions, and the suggestion often depends on skin type and on whether you use acids or retinoids at home. Our reviewer will give a general range once review is complete. {pending}","A pack of several sessions has a total price and a per-session price. Read both, and do not prepay for a pack before you have tried one session and seen how your skin reacts. See [how often can you get a hydrafacial](/learn/how-often-hydrafacial)."]}],"techniques":{"lead":"People compare a hydrafacial with other skin-care options. This table lists the plain differences, with no ranking.","rows":[{"name":"Regular facial","how":"Cleansing, steam or massage, extractions and a mask, usually by hand","often":"People who want a relaxing facial with lower cost","ask":"What steps are included, and who performs them?"},{"name":"Hydrafacial","how":"A handheld device cleanses, exfoliates, suctions debris and applies serums","often":"People who want a device-based clean with some exfoliation","ask":"Which serums, and what are the extra charges?"},{"name":"Chemical peel","how":"A stronger solution removes layers of skin, with flaking or redness for days","often":"Some people with marks or rough texture, on a doctor''s advice","ask":"How long is the redness, and what is my pigment risk?"},{"name":"Microdermabrasion","how":"A device rubs away the top layer of dead skin","often":"People who want surface exfoliation","ask":"How does it differ from this for my skin type?"}],"note":"See [hydrafacial vs chemical peel vs microdermabrasion](/learn/hydrafacial-vs-peel-vs-microdermabrasion) for more."},"recovery":{"lead":"There is no recovery period for most people. This is what the first hours and days commonly look like, and your clinic sets yours. {pending}","body":"Tell the clinic if skin burns, swells or blisters, or if you get a cold sore. Skin that is irritated needs rest, not extra products. See [side effects and who should skip it](/learn/hydrafacial-side-effects-who-should-skip).","highlights":[{"pre":"about","big":"30 to 45 min","text":"A usual session, per the reviewer"},{"pre":"for","big":"a few hours","text":"Pink skin is common straight after"},{"pre":"for","big":"1 to 2 days","text":"Skin can feel sensitive, so keep to gentle care"}],"timeline":[{"when":"First hours","notice":"Pink or flushed skin, slight stinging","doThis":"Apply the sun protection the clinic advises. Do not scrub or use strong acids."},{"when":"Day 1","notice":"Skin may feel tight or sensitive","doThis":"Gentle cleanser and moisturiser. Avoid sun, heat and heavy makeup if you can."},{"when":"Day 2 to 3","notice":"Sensitivity settles, a few people see small breakouts","doThis":"Do not pick. Tell the clinic if breakouts grow or the skin burns."},{"when":"Week 1","notice":"Skin back to usual","doThis":"Resume your usual routine, as advised. Check whether a repeat session is needed at all."}],"grid":{"cols":["Hours","Day 1","Day 3","Wk 1"],"rows":[{"label":"Normal day","cells":[{"state":"y","text":"Most"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Makeup","cells":[{"state":"m","text":"Light"},{"state":"m","text":"Light"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Strong acids","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"}]},{"label":"Strong sun","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Cover"},{"state":"m","text":"Cover"}]},{"label":"Peel or laser","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"}]}]},"closing":"Never assume there is no downtime. Skin reacts differently from one person to the next. If you have an event, book a trial session at least a few weeks before it."},"risks":{"lead":"A hydrafacial is gentle for many people, and it still has risks. These are the ones people most often ask about, with what to ask. This is not a complete list.","rows":[{"risk":"Redness and stinging","means":"Common straight after, and usually short-lived.","ask":"How long should it last for my skin, and when should I call?"},{"risk":"Breakouts afterwards","means":"Some people see small spots in the days after.","ask":"Is a breakout likely for me, and what should I do about it?"},{"risk":"Allergic reaction to a serum","means":"Rash, itch or swelling after a serum or booster.","ask":"What is in the serum, and can I patch test first?"},{"risk":"Cold sore flare","means":"Skin treatments can bring on a cold sore in people who get them.","ask":"I get cold sores. What should I do before and after?"},{"risk":"Infection from tools","means":"Tips and tools that are not clean or single-use can spread infection.","ask":"Are the tips new or cleaned, and how?"},{"risk":"Colour change on irritated skin","means":"Skin that is irritated can darken afterwards, more often in darker skin.","ask":"Is my skin at risk, and should I wait or try a small area?"},{"risk":"Burns or injury","means":"Misuse of the device, or too many passes, can injure the skin.","ask":"Who performs it, and what training do they have?"}],"alert":"Call the clinic or a doctor straight away for blistering, swelling of the face or lips, spreading redness or heat, fever, or pain that keeps getting worse. If you cannot reach them, go to the nearest emergency department.","wait":["You have sunburn or skin that is raw from the sun","You have open sores, a cold sore, an infection or active eczema on the face","You started a new acid or retinoid and your skin is irritated","You took isotretinoin in recent months (the reviewer will set the interval)","You are pregnant, or you are unsure (ask your doctor first)","You had a peel or laser recently"],"tell":["All creams, acids, retinoids and tablets you use, including recent ones","Pregnancy, breastfeeding or plans to conceive","A history of cold sores, eczema, dark marks or keloid scars","Allergies to products or ingredients","Any peel, laser or other facial treatment in recent weeks"]},"patientQuestions":[{"q":"Is a hydrafacial the same as a regular facial?","href":"#compare","linkText":"Read: how it compares"},{"q":"Can I have one with active acne?","href":"#risks","linkText":"Read: who should wait"},{"q":"How many sessions and how often?","href":"#how-often","linkText":"Read: how often"},{"q":"What will it cost, and why do quotes differ?","href":"#cost","linkText":"Read: the cost lines"},{"q":"How long will my skin look pink?","href":"#recovery","linkText":"Read: hours and days"},{"q":"How do I check who is performing it?","href":"#choose","linkText":"Read: the checks"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp. Say what you hope for and what products you use. No pressure to book."},{"title":"A skin check comes first","text":"The person doing the session looks at your skin and asks about medicines, pregnancy and recent treatments."},{"title":"You see the quote line by line","text":"The base session, serums, boosters, extra steps and any pack, each on its own line."},{"title":"You try one session","text":"Pay for one session before a pack, and see how your skin reacts."},{"title":"You get aftercare advice","text":"Written advice for the first days, and who to call if the skin reacts."}],"quoteChecks":["say who performs the session and what their training is?","list the base session and each serum or booster separately?","give a pack total and the per-session figure side by side?","say how tips and tools are cleaned or whether they are single-use?","state what happens, and what you pay, if your skin reacts?"],"extras":["Booster serums beyond the base session","Extra steps such as LED, where provided","Packs of several sessions","Aftercare products","A skin check, if charged separately","A review visit if the skin reacts","Treatment of a reaction","Travel and time off"],"insurance":"Insurance. A hydrafacial is skin care and most health policies do not pay for it. Ask your insurer in writing if you think a medical reason applies, and keep the quote.","payment":"Payment. Pay per session or per pack. Instalment plans may exist for packs, and terms are not shown here. Pay for one session before a pack. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"},{"label":"American Academy of Dermatology: skin care basics for patients","href":"https://www.aad.org/public/everyday-care"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered dermatologist signs off.","Session length, how long pinkness lasts and the interval after isotretinoin are general ranges to be confirmed by the reviewer.","Hydrafacial is the name people search for. Other clinics use similar machines under other names. The trademark and wording position is with the founder''s lawyer.","Insurance and payment wording is general and to be confirmed. Your policy document decides.","Studies cited here will be read and checked by the reviewer first. None is cited yet."]}'::jsonb, '{"costMode":"options","priceLabel":"One hydrafacial session, usual cost","priceLinkText":"The lines inside it","costHeading":"What a session costs","costCaption":"Each line is a separate case with its own range. Sample data / To be confirmed.","operationHeading":"What a hydrafacial is and is not","recoveryHeading":"Downtime and aftercare","recoveryTocLabel":"Downtime","timelineCaption":"What most people notice and do, by time since the session.","risksHeading":"Side effects and risks","riskGuideHref":"/hydrafacial#risks","heroPlate":"none","operationPlate":"none","labels":{"techniquesHeading":"How it compares","techniquesCaption":"Plain differences between options people compare. No ranking.","tocTechniques":"How it compares"},"tocLabels":{"surgery":"What it is","choices":"Steps"},"costUnit":"session"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('botulinum-toxin-injections', 'injectables', null, '[{"key":"consultation","label":"Consultation and face assessment","ask":"Is the first visit charged, and is it credited if you go ahead?"},{"key":"prescriber","label":"Doctor who assesses and prescribes","ask":"Who decides the plan, and are they registered with a medical council?"},{"key":"performer","label":"Who injects","ask":"Is the person who injects a doctor, and can I see their registration?"},{"key":"product","label":"The medicine, from a sealed pack","ask":"Will the sealed pack and batch label be shown to me before use?"},{"key":"review","label":"Review visit","ask":"Is a review at about two weeks included, and what does a touch-up cost?"},{"key":"aftercare","label":"Aftercare advice","ask":"Do I get written advice for the first day, and who do I call if I am worried?"}]'::jsonb, '{"title":"Botulinum Toxin Injections: Cost, Risks and Downtime","description":"Botulinum toxin (often called Botox) relaxes facial muscles to soften frown lines. See cost factors, downtime, risks and how to choose a doctor.","cityTitle":"Botulinum Toxin Injections in {city}: Cost and Risks"}'::jsonb, '{"seoTitle":"Botulinum Toxin Injection Cost in India: What Changes It","metaDescription":"Why prices differ for wrinkle injections: areas treated, doctor, product and follow-up. Sample ranges by area, never a per-unit price.","h1":"Botulinum toxin injection cost in India","answer":"Prices for wrinkle injections in India vary widely because they depend on how many areas are treated, the doctor''s training, the product prescribed and whether follow-up is included. The ranges below are {sample} pending confirmed quotes, each with a date and the number of data points.","unit":"area","rangeHeading":"Sample lines by area","rangeCaption":"Each line is a separate case with its own range. There is no per-unit figure, because units are not comparable between products or doctors.","factors":[{"factor":"Areas treated","why":"Each area needs a different plan, and the total grows with the number of areas."},{"factor":"Doctor and facility","why":"A dermatologist, a general doctor and the clinic type price the consultation differently."},{"factor":"The product prescribed","why":"Different medicines are prescribed, and the dose is set by the doctor, so the figure is not comparable between quotes."},{"factor":"Follow-up and touch-up policy","why":"Some clinics include a review and an adjustment, some charge for each."},{"factor":"Repeat visits","why":"The effect fades over months, so the yearly cost depends on how often you return."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}],"notIncluded":["A review visit, if not included","A touch-up, if the result needs adjusting","Other treatments suggested on the day","Treatment of a complication","Your travel and time off"],"compareQuotes":["Ask each clinic for the total for the same plan in writing, with the areas listed.","Do not compare a per-unit figure with a total. Ask what the total covers.","Check who assesses and injects, and ask for the registration.","Ask to see the sealed pack and the batch label before use.","Be careful of any price given before a doctor has seen you, and of any bundle to prepay."],"insurance":"Use for wrinkles is cosmetic, and most health policies do not pay for it. Ask your insurer in writing before you book.","payment":"Pay at the visit or by card. Instalments depend on the clinic and the lender, and terms are not shown here. {tbc}","method":"No figure is shown yet. When quotes arrive, each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used. If the founder''s lawyer decides that ranges for a prescription medicine count as promotion, the range column is removed and the factor table and the quote checklist remain.","faqs":[{"q":"How much do wrinkle injections cost in India?","a":"It depends on the areas treated, the doctor, the product prescribed and follow-up. The ranges on this page are sample data until confirmed. Ask each clinic for the total for the same plan in writing."},{"q":"Why is there no price per unit?","a":"Units are not comparable between products or doctors, and a low per-unit figure can sit beside a high total. A written total for your plan is what to compare."},{"q":"Is a follow-up visit included?","a":"Sometimes. Ask whether a review at about two weeks and a touch-up are in the quote, and what each costs if not."},{"q":"Why do prices differ between clinics?","a":"Doctors, products, areas and follow-up policies differ. Compare the same plan line by line."},{"q":"Does insurance cover it?","a":"Usually not, because use for wrinkles is cosmetic. Ask your insurer in writing."},{"q":"What should the quote list?","a":"The areas treated, the total, who assesses and injects, the review visit, the touch-up policy and what happens if you have a problem."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'Botulinum toxin injections', 'Botulinum toxin injections', null, 'Small injections of a prescription medicine into facial muscles to soften lines such as frown lines. A doctor decides if it suits you.', '{"procedureType":"https://schema.org/NoninvasiveProcedure","bodyLocation":"Face","howPerformed":"A doctor injects a diluted prescription medicine into chosen facial muscles with a fine needle, at several points, in a short visit.","preparation":"A doctor''s examination, a medical history, a check of current medicines, and a pregnancy check where it applies.","followup":"Staying upright and avoiding rubbing the area for the hours the doctor names, and a review visit if needed."}'::jsonb, null, '[{"factor":"Areas treated","why":"Each area needs a different amount of medicine and a different plan."},{"factor":"Who injects","why":"A trained doctor and the clinic''s seniority change the consultation fee."},{"factor":"Repeat visits","why":"The effect fades over months, so the yearly cost depends on how often you return."},{"factor":"Review visit","why":"Some clinics include a check visit, some charge for it."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}]'::jsonb, 'Most people go back to routine the same day', 'What it is, who it suits, side effects, aftercare, and how to check what is used.', 3, '["anti-aging-treatment","prp-treatment"]'::jsonb, '["how-long-wrinkle-injections-last","botulinum-toxin-side-effects","check-wrinkle-injection-product"]'::jsonb, '[]'::jsonb, null, '{"dek":"Botulinum toxin injections (often called Botox) relax small facial muscles so that lines made by frowning or squinting look softer. A doctor decides after a consultation whether they suit you. The effect is temporary and fades over months. [Cost](/cost/botulinum-toxin-injections) depends mostly on the areas treated, the doctor and the product prescribed.","shortAnswers":[{"q":"What does it do?","a":"It softens lines caused by muscle movement, such as frown lines. It does not change sun damage, sagging skin or lost volume.","href":"#surgery","linkText":"What it does and does not do"},{"q":"How long does it last?","a":"The effect is temporary and fades over months. The reviewer will give a general range. Results vary.","href":"#recovery","linkText":"Onset and duration"},{"q":"What will it cost?","a":"Cost depends on the areas treated, the doctor and follow-up. There is no per-unit price here, because units differ and a total plan is what matters.","href":"#cost","linkText":"The cost lines"},{"q":"Who should wait?","a":"Pregnancy, breastfeeding, some nerve and muscle conditions, an infection at the site and some medicines need a doctor''s view first.","href":"#risks","linkText":"Who should wait"}],"operation":{"lead":"Botulinum toxin is a prescription medicine. A doctor injects a small amount into chosen muscles with a fine needle. The muscle relaxes, and the skin over it creases less. It acts on movement lines. It does not add volume or tighten skin.","body":"Only a registered doctor can prescribe and decide the plan, and the dose is set by the doctor for your face. Other medical uses exist, and they are decided by a doctor and not covered here. If volume loss or loose skin bothers you more than lines, read [botulinum toxin vs fillers](/learn/botulinum-toxin-vs-fillers) and our [anti-aging treatment guide](/anti-aging-treatment). Before you book, read [how to check the product](/learn/check-wrinkle-injection-product).","caption":"Areas commonly discussed for movement lines. The doctor decides yours.","ask":"Which lines are you treating, what result should I expect, and what is the plan if it is uneven?","how":["Consultation: the doctor asks about your health, medicines, pregnancy plans and what bothers you. You are asked to frown, raise your brows and squint so the doctor can see how the muscles move.","Plan and consent: the doctor explains the areas, the risks and what to expect, and asks for your consent. You see the sealed pack and batch label.","Injections: tiny injections are given at several points. Most people describe pinprick discomfort, and it varies.","Short observation: you may be asked to wait a short time, and the doctor explains the first-day advice.","Review: many doctors ask you to return at about two weeks to check the result and decide whether anything needs adjusting. {pending}"],"whoItSuits":[{"term":"Who asks","text":"Adults who are bothered by lines between the brows, across the forehead or at the corners of the eyes, and want to talk to a doctor about options."},{"term":"Expectations","text":"A softer look to movement lines for a time, not a different face. The effect is temporary and results vary. Some people prefer to keep some movement, and the doctor can plan for that."},{"term":"Age","text":"No set age. The doctor decides after assessing your face. See [what age doctors consider](/learn/age-for-wrinkle-injections)."},{"term":"Men and women","text":"Both. Muscle strength and brow shape differ, and the plan differs with them. See [wrinkle injections for men](/learn/wrinkle-injections-for-men)."}]},"areas":{"lead":"These are the areas most often discussed for wrinkles. A doctor decides which, if any, suit your face.","body":"Each area is treated for a different line, and the plan differs. Treating several areas together raises the total, and a doctor may suggest treating fewer.","rows":[{"area":"Between the brows","usual":"Frown lines, sometimes called the elevens","depends":"How strongly the muscles pull, and your brow position"},{"area":"Forehead","usual":"Horizontal lines across the forehead","depends":"Brow height and eyelid position. Over-treating can leave the brow heavy"},{"area":"Outer corners of the eyes","usual":"Lines from squinting or smiling","depends":"How the lines look at rest, and your smile"}],"note":"A face diagram will be added to this page. Image slot: no photos of patients, no syringes, no vials or packaging."},"techniques":{"lead":"People often compare botulinum toxin with other options for ageing skin. This table lists plain differences, with no ranking.","rows":[{"name":"Botulinum toxin","how":"A medicine injected into muscles that relaxes them","often":"Lines caused by movement, such as frown lines","ask":"Which lines will it soften, and what will it not change?"},{"name":"A filler","how":"A gel injected under the skin to add volume or smooth a fold","often":"Folds and lost volume","ask":"Which type is used, how long is it expected to last, and what are the rare blood vessel risks?"},{"name":"Skin boosters","how":"Small injections meant to improve skin hydration and texture","often":"Dull or dry-looking skin, with mixed evidence","ask":"What does the evidence say, and how many sessions?"},{"name":"Peels and lasers","how":"A solution or a light device acts on the skin surface","often":"Texture and tone, with some days of redness","ask":"What is the downtime, and what is my risk of dark marks?"}],"note":"See the [anti-aging treatment guide](/anti-aging-treatment) for a longer comparison."},"extraSections":[{"id":"product","heading":"Checking the product and who injects","tocLabel":"Check the product","lead":"This is a prescription medicine, and the checks below are your right as a patient. A good clinic will welcome them.","bullets":["The person who assesses you and injects is a registered doctor. Ask for the registration and check it on the state medical council or National Medical Commission register.","The medicine comes from a licensed supplier in a sealed vial. Ask to see the sealed pack and the batch label before anything is prepared.","You receive a written plan with the areas and the follow-up, and you sign a consent form after the risks are explained.","Nobody pressures you to decide on the day, to add areas, or to pay for a bundle in advance.","You know who to call if something worries you, and what a follow-up visit costs."],"note":{"label":"A note on wording","text":"We do not name products, give units or promote a price. The dose is set by your doctor."}}],"recovery":{"lead":"There is little recovery for most people, and the effect takes days to show. This is what the first hours, days and weeks commonly look like, and your doctor sets yours. {pending}","body":"Small bumps or redness at the injection sites are common and short-lived. Follow the doctor''s advice about touching the area, lying down, exercise and heat on the first day. See [what to do after wrinkle injections](/learn/aftercare-after-wrinkle-injections).","highlights":[{"pre":"within","big":"minutes","text":"Small bumps or redness may appear and then settle"},{"pre":"after","big":"days","text":"The effect starts to show, per the reviewer"},{"pre":"over","big":"months","text":"The effect fades, which is why repeat visits happen"}],"timeline":[{"when":"First hours","notice":"Small bumps, redness or tenderness at the sites","doThis":"Follow the doctor''s advice on touching, rubbing and lying down. Avoid heat and hard exercise if told to."},{"when":"Day 1","notice":"Possible small bruises","doThis":"Normal activity as the doctor allows. Do not massage the area unless advised."},{"when":"Day 3 to 7","notice":"The effect begins to show","doThis":"Watch for droopiness or unevenness and note it for the review."},{"when":"About week 2","notice":"The effect is usually fully visible","doThis":"Review visit. The doctor checks the result and decides whether anything needs adjusting."},{"when":"Month 2 to 3 and after","notice":"The effect gradually fades","doThis":"Decide with the doctor whether and when to return. There is no need to rush."}],"grid":{"cols":["Day 0","Day 1","Day 3","Wk 2"],"rows":[{"label":"Return to work","cells":[{"state":"y","text":"Often"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Gym","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Heat, sauna","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"}]},{"label":"Lying flat","cells":[{"state":"n","text":"Ask"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Facial, massage","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"}]}]},"closing":"Do not assume there is no downtime. Bruising can show for a few days. If you have an event, plan the injections a few weeks ahead, so the effect and any adjustment are done in time."},"risks":{"lead":"Every injection carries risk. These are the ones people most often ask about, in plain words, and what to ask. This is not a complete list, and the product leaflet and your doctor will go through yours.","rows":[{"risk":"Bruising and soreness","means":"Common at the injection sites and usually short-lived.","ask":"How long should it last, and what can I do to reduce it?"},{"risk":"Headache","means":"Some people have a headache in the first days.","ask":"What can I take, and when should I call?"},{"risk":"An uneven or unwanted result","means":"One side can look different from the other, or the effect can be stronger or weaker than planned.","ask":"How is it adjusted, and is a touch-up in the plan?"},{"risk":"Drooping eyelid or brow","means":"The medicine can spread to a nearby muscle. It is temporary and settles as the effect wears off.","ask":"How do you lower the chance, and what do you do if it happens?"},{"risk":"Allergic reaction","means":"Rash, itching or swelling. Rarely it is severe.","ask":"Do I have any allergy that matters, and what is the plan if I react?"},{"risk":"Spread of the effect","means":"Rarely the effect can spread beyond the area treated, with weakness, trouble swallowing or breathing. It needs urgent care.","ask":"What signs should send me to an emergency department?"},{"risk":"A product that is not genuine","means":"Counterfeit or diluted medicine is a known risk where checks are skipped.","ask":"Can I see the sealed pack and the batch label before use?"}],"alert":"Go to an emergency department straight away for difficulty breathing, swallowing or speaking, a spreading rash with swelling of the face or lips, or severe weakness. Tell them you had botulinum toxin. Call your doctor for a drooping eyelid, double vision or pain that keeps getting worse.","wait":["You are pregnant, breastfeeding or planning a pregnancy","You have a nerve or muscle condition, or take medicines that affect nerves or muscles (ask the doctor)","You have an infection or skin disease at the injection site","You are allergic to an ingredient or reacted to it before","You have unrealistic expectations, such as changing the shape of your face","You are being pushed to decide on the day"],"tell":["All medicines, supplements and blood thinners you take","Any nerve or muscle condition, and any past reaction to injections","Pregnancy, breastfeeding or plans to conceive","Previous cosmetic treatments, including fillers and lasers","Allergies to medicines, ingredients or dressings"]},"patientQuestions":[{"q":"How long do wrinkle injections last?","href":"#recovery","linkText":"Read: onset and duration"},{"q":"Will my face look stiff?","href":"#areas","linkText":"Read: areas"},{"q":"How much does it cost, and why no per-unit price?","href":"#cost","linkText":"Read: the cost lines"},{"q":"What are the side effects?","href":"#risks","linkText":"Read: risks"},{"q":"How do I check the product and the doctor?","href":"#product","linkText":"Read: the checks"},{"q":"Is it better than fillers?","href":"#compare","linkText":"Read: other options"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp. Say what bothers you. The coordinator does not name a product or quote a price before you see a doctor."},{"title":"A doctor assesses your face","text":"The doctor looks at how your face moves, asks about your health and explains the options, including not treating."},{"title":"You receive a written plan","text":"The areas, the total, the review visit and what a touch-up costs, each on its own line."},{"title":"You consent and check the product","text":"You sign after the risks are explained, and you see the sealed pack and batch label."},{"title":"After the visit","text":"Written advice for the first day, a check-in from us the next day, and a review visit at the interval the doctor sets."}],"quoteChecks":["list the areas treated and the total for the whole plan?","say who assesses and injects, with their registration?","say whether a review visit is included, and what a touch-up costs?","tell you the medicine will be shown to you sealed before use?","state what happens if the result is uneven or you have a problem?"],"extras":["A review visit, if not included","A touch-up, if the result needs adjusting","Treatment of a complication","A second visit as the effect fades","Other treatments suggested on the day","Aftercare products","Your travel and time off"],"insurance":"Insurance. Use for wrinkles is cosmetic, and most health policies do not pay for it. Ask your insurer in writing before you book, and keep the plan. We do not promise cashless approval.","payment":"Payment. Pay at the visit, or by card. Terms for instalments depend on the clinic and the lender and are not shown here. Do not prepay for a bundle of visits before you have seen a doctor. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"},{"label":"Central Drugs Standard Control Organisation: regulator of medicines in India","href":"https://cdsco.gov.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered dermatologist signs off.","Onset, duration and review timing are general ranges to be confirmed by the reviewer against the product leaflet.","Botulinum toxin is a prescription medicine. This page is general information. It names no product, gives no dose and makes no price promotion.","The wording and the slug of this page are with the founder''s lawyer. Insurance and payment wording is general and to be confirmed.","Studies cited here will be read and checked by the reviewer first. None is cited yet."]}'::jsonb, '{"costMode":"options","priceLabel":"Usual cost for one area","priceLinkText":"The lines by area","costHeading":"What the injections cost, by area","costCaption":"Each line is a separate case. There is no per-unit price. Sample data / To be confirmed.","compareGuideHref":"/cost/botulinum-toxin-injections","operationHeading":"What the injection does and does not do","recoveryHeading":"Downtime and the first day","recoveryTocLabel":"Downtime","timelineCaption":"What most people notice and do, by time since the injections.","risksHeading":"Risks and side effects","riskGuideHref":"/botulinum-toxin-injections#risks","heroPlate":"none","operationPlate":"none","labels":{"areasHeading":"Areas treated for wrinkles","areasCaption":"Areas commonly discussed. The doctor decides yours.","areasNoPlate":true,"techniquesHeading":"Other options","techniquesCaption":"Plain differences between options people compare. No ranking.","tocTechniques":"Other options"},"tocLabels":{"surgery":"What it does","choices":"Areas"},"costUnit":"area"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('anti-aging-treatment', 'skin', null, '[{"key":"consultation","label":"Consultation and skin assessment","ask":"Is the first visit charged, and is it credited if you go ahead?"},{"key":"prescriber","label":"Doctor who assesses and plans","ask":"Who decides the plan, and are they registered with a medical council?"},{"key":"performer","label":"Who performs each treatment","ask":"Is it a doctor, a nurse or a technician, and what is their training?"},{"key":"procedure","label":"The session itself","ask":"What exactly is done in one session, and how many sessions are planned?"},{"key":"numbing","label":"Numbing or cooling","ask":"Is anything used for comfort, and is it in the price?"},{"key":"aftercare","label":"Aftercare products","ask":"Which products are advised, and are they in the price?"},{"key":"review","label":"Review visit","ask":"Is a review included, and what does an extra visit cost?"}]'::jsonb, '{"title":"Anti-Aging Treatment: Options, Cost Factors, Risks","description":"Non-surgical anti-aging options: injectables, skin boosters, PRP, peels and lasers. Cost factors, downtime, risks and who should wait.","cityTitle":"Anti-Aging Treatment in {city}: Cost, Downtime, Risks"}'::jsonb, '{"seoTitle":"Anti-Aging Treatment Cost in India: What Changes It","metaDescription":"What anti-aging treatment costs in India by method: sessions, maintenance, clinic and doctor. Sample ranges, labelled, and what to ask in writing.","h1":"Anti-aging treatment cost in India","answer":"Anti-aging treatment is priced per method and per session, and most plans need several sessions and repeat visits. So the cost for a year matters more than the price of one session. The ranges on this page are {sample} until confirmed quotes are collected, and each will show its source and date.","unit":"session","rangeHeading":"Sample lines by method","rangeCaption":"Each line is a separate case with its own range, one row per method. Your total is built from the methods and sessions in your plan.","planner":{"heading":"A year planner","formula":"Yearly cost = consultation + (sessions x price per session, for each method) + repeat visits + aftercare products","steps":["Ask the doctor for each method in the plan, the number of sessions and the gap between them.","Add the repeat visits that the plan expects in the year.","Add aftercare products and any review visits that are not in the quote.","Leave blank the methods that are not in your plan. The formula gives your own range, not an average."]},"factors":[{"factor":"Which methods are combined","why":"Each method has its own price, and a plan often joins two or more."},{"factor":"Number of sessions","why":"Peels, lasers and tightening devices are priced per session, and a course needs several."},{"factor":"Area treated","why":"Face only, or face and neck, changes the plan and the time."},{"factor":"Who treats","why":"A dermatologist and a general clinic price consultations differently."},{"factor":"Maintenance","why":"Most methods need repeats, so the yearly cost matters more than one session."},{"factor":"Device or product used","why":"Different devices and products carry different fees. We name none here."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}],"notIncluded":["Repeat and maintenance visits","Prescription creams and aftercare products","Review and touch-up visits","Numbing cream or cooling, if charged","Treatment of a reaction","Your travel and time off for repeat visits"],"compareQuotes":["Ask each clinic for the same lines in writing, one row per method with its sessions.","Break any package into lines, so you can compare it with single sessions.","Ask for the yearly cost with repeats, and not only the first session.","Check who assesses and performs each treatment, and ask for the registration.","Be careful of a package to prepay on the first day."],"insurance":"Anti-aging treatments are cosmetic, and most health policies do not pay for them. Ask your insurer in writing before you start.","payment":"Sessions are usually paid for as you go. Package plans and instalments depend on the clinic and the lender, and terms are not shown here. {tbc}","method":"No figure is shown yet. When quotes arrive, each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used.","faqs":[{"q":"How much does anti-aging treatment cost in India?","a":"It depends on the methods, the number of sessions and the repeats. The ranges on this page are sample data until confirmed. Ask each clinic for the plan line by line, so you can compare."},{"q":"Why is the price per method and not one price?","a":"The methods are different treatments with different equipment, time and risks. A single headline figure would hide that."},{"q":"Are packages cheaper?","a":"A package can lower the price per session, and it commits you before you know the result. Ask for each part as a separate line, and try one session first."},{"q":"How much will I spend in a year?","a":"Add the sessions for each method and the repeat visits. Ask the doctor for the plan for twelve months, and not only the first course."},{"q":"Does insurance cover it?","a":"Usually not, because the treatments are cosmetic. Ask your insurer in writing."},{"q":"What should the quote list?","a":"Each method, the sessions, the price of each, who performs it, aftercare products, and what happens if you have a problem."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'Anti-aging treatment', 'Anti-aging treatment', 'Anti-ageing skin care', 'The non-surgical options people compare for ageing skin: injections, peels, light and energy devices, and daily skin care. A doctor matches them to your skin.', '{"procedureType":"https://schema.org/NoninvasiveProcedure","bodyLocation":"Face and neck","howPerformed":"A doctor looks at skin type, the signs that bother you and your health, then plans one or more options such as injections, peels, light or energy devices and a home routine.","preparation":"A skin and medical history, a review of current products and medicines, and sun exposure habits.","followup":"Review visits, sun protection, and changes to the plan as the skin responds."}'::jsonb, null, '[{"factor":"Which options are combined","why":"Each option has its own price, and a plan often joins two or more."},{"factor":"Number of sessions","why":"Peels, light and energy devices are priced per session, and a course needs several."},{"factor":"Area treated","why":"Face only, or face and neck, changes the plan and the time."},{"factor":"Who treats","why":"A dermatologist and a general clinic price consultations differently."},{"factor":"Maintenance","why":"Most options need repeat visits, so the yearly cost matters more than one session."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}]'::jsonb, 'Depends on the option, from none to a few days', 'A plain map of the options, what each can and cannot do, and what to ask.', 2, '["botulinum-toxin-injections","prp-treatment","hydrafacial"]'::jsonb, '["skin-boosters-vs-fillers-vs-toxin","chemical-peels-for-ageing-skin","anti-aging-care-by-decade"]'::jsonb, '[]'::jsonb, null, '{"dek":"Non-surgical anti-aging treatments aim to soften lines, improve skin texture or tone, or add a little firmness. They do not stop ageing and cannot do what surgery does. A dermatologist picks the options after looking at your skin. Cost and downtime depend on the method, how many sessions you need and your skin type. The [cost factors](/cost/anti-aging-treatment) are on their own page.","shortAnswers":[{"q":"What can these treatments do?","a":"They can soften some lines, change skin texture or tone, or add firmness or volume for a time. They do not stop ageing, and each method targets something different.","href":"#surgery","linkText":"What they can and cannot do"},{"q":"Which one suits me?","a":"That depends on what bothers you and on your skin. A dermatologist matches the concern to the method, and sometimes advises daily care first.","href":"#compare","linkText":"The options at a glance"},{"q":"What is the downtime?","a":"It runs from none to several days of redness or flaking, depending on the method. Some leave bruises.","href":"#recovery","linkText":"Downtime by method"},{"q":"What will it cost?","a":"Each method has its own price per session, and plans often need several sessions and repeats. The ranges shown are to be confirmed.","href":"#cost","linkText":"The cost lines"}],"operation":{"lead":"People use the term anti-aging for a group of non-surgical options that act on lines, skin texture, tone and firmness. A dermatologist looks at your skin, asks what bothers you and what you have tried, and then plans one or more options. Some people need only a better daily routine.","body":"No option stops the skin from ageing. Each has limits, and some suit one concern better than another. Read [skin boosters, fillers and toxin compared](/learn/skin-boosters-vs-fillers-vs-toxin) to see the differences. Daily sun protection matters more than any procedure, see [sunscreen and retinoids](/learn/sunscreen-retinoids-skin-ageing). If you are looking for [botulinum toxin injections](/botulinum-toxin-injections) or [PRP treatment](/prp-treatment), each has its own page.","caption":"The usual path: assess, start with daily care, add one option at a time, review.","ask":"Which of my concerns can each option help with, which can it not, and what do you suggest I try first?","how":["Assessment: the doctor looks at your skin in good light and asks about sun exposure, smoking, medicines, pregnancy plans, past treatments and what you want to change.","Daily care first: for many people the first step is sun protection and a gentle routine. The doctor may add a prescription cream.","One option at a time: a plan may begin with one method and add another later, so that you can see what each does.","Sessions: peels, light and energy devices are given in a course, spaced weeks apart. Injections are given in short visits.","Review and maintenance: most options need repeat visits, so the yearly cost matters more than one session."],"whoItSuits":[{"term":"Who asks","text":"Adults from their thirties onwards who notice lines, rough texture, uneven tone or lost volume, and who want to understand options before they decide."},{"term":"Expectations","text":"A change to some features for a time. Results vary, and nothing here makes skin look as it did years ago. Some people see little change."},{"term":"Commitment","text":"Several sessions for some methods, repeat visits for most, and daily sun protection for all."},{"term":"Time","text":"Downtime ranges from none to several days. Plan around work and events, and avoid new treatments in the final week before one."}]},"techniques":{"lead":"These are the options people compare. Each row says what the option is, what it targets, and what to ask. There is no ranking, and no price in this table.","rows":[{"name":"Botulinum toxin","how":"A prescription medicine injected into facial muscles","often":"Lines caused by movement, such as frown lines. Effect fades over months. See [botulinum toxin injections](/botulinum-toxin-injections)","ask":"Which lines will it soften, and what will it not change?"},{"name":"Fillers","how":"A gel injected under the skin","often":"Folds and lost volume. Duration depends on the type","ask":"Which type, and what are the lump, bruise and rare blood vessel risks?"},{"name":"Skin boosters","how":"Small injections meant to improve hydration and texture","often":"Dull or dry-looking skin. Evidence is limited or mixed, pending the reviewer","ask":"What do studies show, how many sessions, and what is the downtime?"},{"name":"PRP for the face","how":"Platelet-rich plasma from your own blood, injected or applied after needling","often":"Texture and tone, with limited evidence. See [PRP treatment](/prp-treatment)","ask":"What does the evidence say, and how many sessions?"},{"name":"Chemical peels","how":"A solution removes layers of skin, with flaking for days","often":"Texture, tone and fine lines. Depth changes the downtime","ask":"Which depth, how long is the redness, and what is my pigment risk?"},{"name":"Lasers and light devices","how":"Light energy acts on the skin surface or deeper","often":"Texture, tone, marks and some lines. Several sessions","ask":"What is the aim, what is the downtime, and what is my risk of dark marks?"},{"name":"Ultrasound or radiofrequency tightening","how":"Heat energy delivered below the surface","often":"Mild firmness in selected areas. Results vary, and it is not a surgical lift","ask":"How many sittings, what does it feel like, and what are the burn risks?"}],"note":"A [hydrafacial](/hydrafacial) is a skin-care session and is not an anti-aging treatment. Each method has its own page or guide, and a combination is a doctor''s decision."},"extraSections":[{"id":"downtime-by-method","heading":"Downtime and sessions by method","tocLabel":"Downtime by method","lead":"General ranges for the reviewer to confirm. Your doctor sets yours, and individual skin varies.","table":{"caption":"What most people notice, by method. Ranges are to be confirmed.","head":["Method","Usual downtime","Sessions","Main risks"],"rows":[["Botulinum toxin","Small bumps for hours, bruises for a few days","A short visit, repeated as the effect fades","Bruising, uneven result, drooping eyelid or brow"],["Fillers","Swelling and bruising for several days","Short visits, repeated by the type","Lumps, bruises, rare blood vessel blockage"],["Skin boosters","Small bumps and redness for a day or two","A short course, set by the doctor","Bruising, lumps, infection"],["PRP for the face","Redness and swelling for a day or two","A short course, set by the doctor","Bruising, infection, no visible benefit"],["Chemical peels","Redness and flaking for days, by depth","A course for light peels","Burns, dark or light patches, scarring"],["Lasers and light devices","Redness for days, longer for stronger devices","A course spaced weeks apart","Burns, dark marks, scarring"],["Tightening devices","Mild redness or tenderness","One or several sittings","Burns, nerve irritation, uneven result"]]}},{"id":"pigment-risk","heading":"Dark marks and Indian skin","tocLabel":"Pigment risk","paragraphs":["Skin with more natural pigment can darken after irritation, and some peels and lasers carry a higher chance of dark marks. The reviewer will confirm which options need extra care. A good plan starts gently, may test a small area, and puts sun protection first.","If you already have melasma or marks, tell the doctor before any session. A treatment that irritates the skin can make them darker. {pending}"]},{"id":"daily-care","heading":"Daily care that matters more than any procedure","tocLabel":"Daily care","bullets":["Sun protection every day. UV light is a major cause of skin ageing, and it also darkens marks after treatments.","Not smoking. Smoking is linked to earlier ageing of the skin.","Sleep, a varied diet and exercise support general health. No food or home remedy is proven to stop skin ageing.","A gentle cleanser and a moisturiser. A doctor may add a prescription cream, and will tell you what to stop before a peel or laser."],"note":{"label":"No products named","text":"We do not name products or brands. Ask the doctor which type of sunscreen and moisturiser fits your skin."}}],"recovery":{"lead":"Downtime depends on the method. This is what the first days commonly look like across options, and your doctor sets yours. {pending}","body":"Gentle care, sun protection and not picking at flaking skin help most. Tell the doctor about burning, blistering or swelling that spreads. See [chemical peels](/learn/chemical-peels-for-ageing-skin) and [laser on Indian skin](/learn/laser-for-ageing-skin-indian-skin) for more.","highlights":[{"pre":"from","big":"none","post":"to days","text":"Downtime depends on the method"},{"pre":"up to","big":"a week","text":"Redness or flaking after some peels and lasers, per the reviewer"},{"big":"months","text":"Many options need repeat visits, so plan the year and not one session"}],"timeline":[{"when":"Day 0","notice":"Redness, bumps or tenderness, by method","doThis":"Follow the written advice. Use the sun protection the doctor names."},{"when":"Day 1 to 3","notice":"Swelling, bruises or peeling can show","doThis":"Gentle cleanser and moisturiser. Do not pick. Keep out of strong sun."},{"when":"Day 4 to 7","notice":"Flaking after peels and some lasers settles","doThis":"Resume your routine as the doctor says. Report burning or a spreading rash."},{"when":"Week 2 to 4","notice":"Most visible effects of a session have settled","doThis":"Review visit. The doctor decides whether to continue, change or stop."},{"when":"Month 3 and after","notice":"Effects of some methods begin to fade","doThis":"Decide on maintenance. There is no need to rush."}],"grid":{"cols":["Toxin","Filler","Peel","Laser","Tighten"],"rows":[{"label":"Back to work","cells":[{"state":"y","text":"Often"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"},{"state":"y","text":"Often"}]},{"label":"Visible redness","cells":[{"state":"m","text":"Hours"},{"state":"m","text":"Days"},{"state":"m","text":"Days"},{"state":"m","text":"Days"},{"state":"m","text":"Hours"}]},{"label":"Bruising possible","cells":[{"state":"m","text":"Yes"},{"state":"m","text":"Yes"},{"state":"y","text":"Rare"},{"state":"y","text":"Rare"},{"state":"y","text":"Rare"}]},{"label":"Strict sun cover","cells":[{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"n","text":"Strict"},{"state":"n","text":"Strict"},{"state":"y","text":"Yes"}]}]},"closing":"Do not assume that any option has no downtime. If you have an event, start several weeks ahead, so that any redness, swelling or adjustment is done in time."},"risks":{"lead":"Every treatment has risks. These are the ones people most often ask about, in plain words, and what to ask. The full list for each method belongs to the doctor, and the product leaflet where there is one.","rows":[{"risk":"Redness, swelling and bruising","means":"Common and usually short-lived after injections, peels and lasers.","ask":"How long should it last for this method, and when should I call?"},{"risk":"Dark or light patches","means":"Irritation can change the colour of the skin, more often with some peels and lasers and in darker skin.","ask":"What is my risk, and can you test a small area first?"},{"risk":"Burns and scarring","means":"Peels, lasers and heat devices can injure the skin if used wrongly or too strongly.","ask":"Who performs it, and what do you do if it blisters?"},{"risk":"Lumps and uneven result","means":"Fillers and injections can leave lumps or an uneven look.","ask":"How is it corrected, and what does a correction cost?"},{"risk":"Rare blood vessel blockage","means":"A filler can rarely block a blood vessel, which needs urgent care.","ask":"What signs should send me to an emergency department?"},{"risk":"Infection","means":"Any break in the skin can become infected.","ask":"What are the signs, and who do I call?"},{"risk":"Allergic reaction","means":"Rash, itch or swelling after a product or a numbing cream.","ask":"Do I have any allergy that matters?"},{"risk":"No visible benefit","means":"Results vary, and some people see little change from some methods.","ask":"What do you expect for my skin, and what is the plan if there is no change?"}],"alert":"Call the clinic or a doctor straight away for blistering, spreading redness or heat, fever, severe or worsening pain, a pale or dusky patch of skin, or any change in vision. If you cannot reach them, go to the nearest emergency department.","wait":["You are pregnant, breastfeeding or planning a pregnancy (ask before any treatment)","You have an infection or an acne flare on the area","You are sun-tanned or recently sunburned","You took isotretinoin in recent months and a peel or laser is planned (the reviewer will set the interval)","You tend to form keloid or thick scars","You expect to look as you did years ago"],"tell":["All creams, retinoids, medicines and supplements, including blood thinners","Pregnancy, breastfeeding or plans to conceive","Past reactions to cosmetic treatments, peels or fillers","A tendency to dark marks, cold sores or thick scars","Allergies to medicines, products and numbing creams"]},"patientQuestions":[{"q":"Which treatment suits my concern?","href":"#compare","linkText":"Read: the options at a glance"},{"q":"Do these treatments stop ageing?","href":"#surgery","linkText":"Read: what they can and cannot do"},{"q":"How much downtime should I plan?","href":"#downtime-by-method","linkText":"Read: downtime by method"},{"q":"Are some options riskier for darker skin?","href":"#pigment-risk","linkText":"Read: dark marks"},{"q":"What will it cost over a year?","href":"#cost","linkText":"Read: the cost lines"},{"q":"Should I try daily care first?","href":"#daily-care","linkText":"Read: daily care"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp. Say what bothers you and what you have tried. The coordinator does not name a product or quote a price before you see a doctor."},{"title":"A dermatologist assesses your skin","text":"The plan is made in person after looking at your skin in good light, not from a photo."},{"title":"You receive a written plan","text":"Each method, the sessions planned and a total, each on its own line, and what happens if you stop."},{"title":"You start with one thing","text":"A plan may begin with daily care or one method, so that you can see what it does before you add more."},{"title":"You return for reviews","text":"A coordinator check-in the next day, then reviews at the interval the doctor sets."}],"quoteChecks":["list each method, the number of sessions and the price of each?","say who performs each treatment and their training?","tell you what the yearly cost looks like with repeat visits?","name the downtime and risks of each method in writing?","break any package into lines, so you can compare it with a single session?"],"extras":["Repeat visits and maintenance sessions","Prescription creams and aftercare products","Review and touch-up visits","Treatment of a reaction","Numbing cream or cooling, if charged","Other treatments suggested on the day","Your travel and time off for repeat visits"],"insurance":"Insurance. Anti-aging treatments are cosmetic, and most health policies do not pay for them. Ask your insurer in writing before you start, and keep the plan. We do not promise cashless approval.","payment":"Payment. Pay per session or per treatment. Package plans and instalments depend on the clinic and the lender and are not shown here. Ask for a line-by-line breakdown of any package before you pay. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"},{"label":"American Academy of Dermatology: skin care and sun protection for patients","href":"https://www.aad.org/public/everyday-care"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered dermatologist signs off.","Downtime, session counts and how long effects last are general statements to be confirmed or replaced by the reviewer.","Evidence for skin boosters and for PRP on the face is described as limited or mixed, pending the reviewer.","Botulinum toxin is a prescription medicine. This page names no product, gives no dose and makes no price promotion.","Insurance and payment wording is general and to be confirmed. Studies cited here will be read and checked by the reviewer first. None is cited yet."]}'::jsonb, '{"costMode":"options","priceLabel":"One session of one method, usual cost","priceLinkText":"The lines by method","costHeading":"What each method costs per session","costCaption":"One row per method. Each line is a separate case with its own range. Sample data / To be confirmed.","operationHeading":"What anti-aging treatment can and cannot do","recoveryHeading":"Downtime by method","recoveryTocLabel":"Downtime","timelineCaption":"What most people notice and do, by time since a session.","risksHeading":"Risks and side effects","riskGuideHref":"/anti-aging-treatment#risks","heroPlate":"none","operationPlate":"none","labels":{"techniquesHeading":"The options at a glance","techniquesCaption":"What each option is, what it targets and what to ask. No ranking and no price.","tocTechniques":"The options"},"tocLabels":{"surgery":"What it can do","choices":"Options"},"costUnit":"session"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('prp-treatment', 'hair', null, '[{"key":"consultation","label":"Consultation and scalp or skin check","ask":"Is the first visit charged, and is it credited if you start a course?"},{"key":"performer","label":"Who draws the blood and injects","ask":"Is it a doctor, a nurse or a technician, and what is their training?"},{"key":"kit","label":"Blood draw and PRP kit","ask":"Is the kit single-use and sealed, and is it in the price?"},{"key":"procedure","label":"The session itself","ask":"What is done in one session, and how many sessions are planned?"},{"key":"numbing","label":"Numbing cream or cooling","ask":"Is numbing cream used, and is it in the price?"},{"key":"aftercare","label":"Aftercare products","ask":"Which products are advised, and are they in the price?"},{"key":"review","label":"Review visit","ask":"How many reviews are in the plan, and what does an extra one cost?"}]'::jsonb, '{"title":"PRP Treatment for Hair and Skin: Cost, Sessions, Risks","description":"What PRP is, how many sessions doctors usually plan, what changes the price, recovery, side effects and who should wait. Results vary. Doctor reviewed.","cityTitle":"PRP Treatment in {city}: Cost, Sessions, Risks"}'::jsonb, '{"seoTitle":"PRP Treatment Cost in India: What Changes the Price","metaDescription":"What drives the cost of PRP for hair and skin: sessions, clinic type, kit, add-ons and follow-up. Labelled sample ranges and what a quote should list.","h1":"PRP treatment cost in India","answer":"PRP is priced per session and usually needs several, so the course total matters more than one session fee. The sample ranges below show a single session and the formula for a course, with source and date shown once quotes arrive. Then comes what changes the number.","unit":"session","rangeHeading":"Sample lines per session and per course","rangeCaption":"Per-session lines, then the course as a formula. Each line is a separate case with its own range.","planner":{"heading":"From one session to a course total","formula":"Course total = consultation + (sessions x price per session) + add-ons + reviews, medicines and tests","steps":["Ask the doctor how many sessions and what gap between them.","Multiply the number of sessions by the price of one session in the written quote.","Add any microneedling or other add-on, and reviews, medicines and tests that are not in the quote.","Compare the total for the same number of sessions between clinics, not the price of one session."]},"factors":[{"factor":"Area treated","why":"Scalp, face and under-eye need different amounts of work and time."},{"factor":"Number of sessions","why":"A plan usually has several sessions spaced weeks apart, so the course total matters."},{"factor":"Kit and method","why":"The blood-draw kit and the method used to spin the sample are priced differently."},{"factor":"Who performs it","why":"A doctor-led clinic and other settings price it differently."},{"factor":"Add-ons","why":"Microneedling or other add-ons are priced on top of the base session."},{"factor":"Clinic type","why":"A day-care clinic and a hospital outpatient department structure fees differently."},{"factor":"City","why":"Rents and wages differ between cities, and so do fees."}],"notIncluded":["Sessions beyond the course in the plan","Microneedling or other add-ons","Medicines for hair, if prescribed","Blood tests for medical causes","Review visits and aftercare products","Treatment of a reaction","Your travel and time off for repeat visits"],"compareQuotes":["Ask each clinic for the number of sessions, the gap between them and the course total in writing.","Compare totals for the same number of sessions, and not the price of one session.","Ask who draws the blood and injects, and whether the kit is single-use and sealed.","Ask what happens, and what you pay, if you see no change.","Pay for one session before a package, and be careful of any package to prepay."],"insurance":"PRP for hair or skin is usually treated as cosmetic, and most health policies do not pay for it. Ask your insurer in writing before you start.","payment":"Sessions are usually paid for one at a time. Package plans and instalments depend on the clinic and the lender, and terms are not shown here. {tbc}","method":"No figure is shown yet. When quotes arrive, each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used, and one city''s range is not used for another.","faqs":[{"q":"How much does PRP cost per session in India?","a":"It depends on the area, the kit, the clinic and the add-ons. The range on this page is sample data until confirmed. Ask each clinic for the number of sessions and the course total in writing."},{"q":"How many sessions will I need, and what does that do to the cost?","a":"Plans usually have several sessions, and the doctor sets the number. Multiply by the price of one session, then add add-ons, reviews and tests."},{"q":"Why do quotes differ so much?","a":"Clinics use different kits, methods and numbers of sessions, and some include reviews and tests while others do not. Compare totals for the same plan."},{"q":"Is a package cheaper?","a":"A package can lower the price per session, and it commits you before you know how you respond. Pay for one session first."},{"q":"Does insurance cover PRP?","a":"Usually not, because it is treated as cosmetic. Ask your insurer in writing."},{"q":"What should the quote list?","a":"The number of sessions, the gap, the price of each, the total, who draws the blood and injects, the kit, reviews, medicines, tests and what happens if there is no change."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'PRP treatment', 'PRP treatment', 'Platelet-rich plasma', 'A small blood sample is spun to concentrate platelets, which are then injected into the scalp or face skin. Results vary and it is not a transplant.', '{"procedureType":"https://schema.org/PercutaneousProcedure","bodyLocation":"Scalp, face","howPerformed":"Blood is drawn from your arm and spun in a machine to separate the platelet-rich part, which is injected into the skin of the scalp or face with a fine needle.","preparation":"A doctor''s examination, a medical history, a review of blood-thinning medicines, and a plan for the number of sessions.","followup":"Gentle care of the area for a day or two, and review visits as the doctor plans."}'::jsonb, null, '[{"factor":"Area treated","why":"Scalp and face need different amounts of work."},{"factor":"Number of sessions","why":"A plan usually has several sessions spaced weeks apart, so the course total matters."},{"factor":"Kit and method","why":"The blood-draw kit and the method used for spinning the sample are priced differently."},{"factor":"Who performs it","why":"A doctor-led clinic and other settings price it differently."},{"factor":"Add-ons","why":"Needling or other add-ons are priced on top of the base session."},{"factor":"City and clinic type","why":"Rents and wages differ between cities, and so do fees."}]'::jsonb, 'Same day to 2 days, as the scalp or face settles', 'How it is made, what the evidence says, sessions, side effects, and who should wait.', 1, '["hair-transplant","anti-aging-treatment"]'::jsonb, '["prp-how-it-is-made","prp-hair-sessions-and-spacing","prp-cost-why-quotes-differ"]'::jsonb, '[]'::jsonb, null, '{"dek":"PRP means platelet-rich plasma, made from a small sample of your own blood and injected into the scalp or skin. Doctors use it as an add-on for hair thinning and for skin texture. Evidence is mixed and results vary. A usual plan is several sessions, so the [total bill](/cost/prp-treatment) matters more than one session fee.","shortAnswers":[{"q":"What is PRP?","a":"Blood is drawn from your arm and spun to concentrate platelets. The platelet-rich part is injected into the scalp or skin.","href":"#surgery","linkText":"How it is made"},{"q":"Does it work?","a":"Evidence is mixed. Some people see a change, and some see none. A doctor should tell you plainly what to expect for you.","href":"#evidence","linkText":"What is known"},{"q":"How many sessions?","a":"Usually several, spaced weeks apart, and the doctor sets the number. Ask for the course total and not only one session.","href":"#cost","linkText":"The cost lines"},{"q":"Who should wait?","a":"Active infection, blood disorders or blood thinners, low platelets, pregnancy or cancer treatment need a doctor''s view first.","href":"#risks","linkText":"Who should wait"}],"operation":{"lead":"PRP is a way of using your own blood. A small sample is taken and spun in a machine, which separates a platelet-rich part. That part is injected into the scalp for hair thinning, or into the skin of the face for texture. A doctor decides whether it suits you.","body":"It is not a transplant, and it is not a medicine that changes the cause of hair loss. Hair thinning can come from medical causes such as thyroid, iron or hormone problems, so a doctor checks first. Read [how PRP is made](/learn/prp-how-it-is-made) and [what the evidence says for hair](/learn/prp-for-hair-loss-evidence). If you are comparing it with a [hair transplant](/hair-transplant), the two are different options with different aims.","caption":"From blood draw to injection: draw, spin, separate, inject.","ask":"What do you expect PRP to do for my hair or skin, how many sessions, and what will we do if I see no change?","how":["Consultation: the doctor examines your scalp or skin, asks about hair loss history, medicines, blood conditions and pregnancy plans, and may suggest tests for medical causes.","Blood draw: a small sample is drawn from a vein in your arm, as for a blood test.","Spinning: the sample is spun in a machine so that the platelet-rich plasma separates from the rest. Methods differ between clinics.","Injection: numbing cream may be used. The PRP is injected with a fine needle into the scalp, or into the skin of the face. It can also be applied after microneedling.","Aftercare: you go home the same day, with advice on washing, sun and what to avoid for the first day or two."],"whoItSuits":[{"term":"Hair","text":"Adults with early or mild thinning whose doctor has checked for medical causes, and who understand that evidence is mixed. It is often an add-on to medical care."},{"term":"Skin","text":"Adults who want to talk about texture or under-eye concerns. Evidence is limited and results vary. See [PRP for the face](/learn/prp-face-evidence)."},{"term":"Expectations","text":"Some people notice a change over months, and some do not. No one can promise a result."},{"term":"Commitment","text":"A course of sessions spaced weeks apart, and review visits. If travel makes visits hard, plan that before you start."}]},"extraSections":[{"id":"evidence","heading":"PRP for hair thinning: what is known and unknown","tocLabel":"Hair: the evidence","paragraphs":["Studies of PRP for hair thinning have used different methods, different numbers of sessions and different ways of measuring change, so results are hard to compare. Some report a change in some people, and others report little or none. For that reason the evidence is described as mixed.","A reviewer will open and check published studies before any is named on this page. None is cited yet. {pending}","Hair thinning has many causes. Some need a medical check, such as thyroid, iron and hormone tests. Treating the cause may matter more than any injection."],"note":{"label":"Ask this","text":"Which kind of hair thinning do I have, what are the other options, and why do you suggest PRP for me?"}},{"id":"skin-prp","heading":"PRP for skin: the face, under the eyes and scars","tocLabel":"Skin: face and under-eye","paragraphs":["For the skin, PRP is used by some doctors for texture, fine lines, under-eye concerns and some marks, often with microneedling. Evidence is limited and results vary, and it does not replace sun protection or other care.","Under-eye skin is thin and sensitive. If a doctor suggests PRP there, ask what the aim is, what the risks are and how many sessions. We make no claim about dark circles, scars or ageing. For the wider set of options, see [anti-aging treatment](/anti-aging-treatment)."]},{"id":"sessions","heading":"Sessions and spacing","tocLabel":"Sessions","paragraphs":["Clinics usually plan a course of several sessions spaced a few weeks apart. Our reviewer will give a general range for the number and the gap once review is complete. {pending}","A doctor judges change after some months and decides whether to continue, space the visits out, or stop. Ask in advance what counts as a change and what the plan is if there is none. Do not prepay for a large package before you have seen how you respond."]}],"techniques":{"lead":"People often ask how PRP compares with other options for thinning hair. This table lists plain differences, with no ranking.","rows":[{"name":"PRP","how":"Your own platelet-rich plasma injected into the scalp","often":"Early or mild thinning, as an add-on. Several sessions","ask":"What is the aim, how many sessions, and what if there is no change?"},{"name":"Medicines for hair","how":"Creams or tablets prescribed by a doctor, such as minoxidil, and for some men finasteride","often":"Many types of thinning, used for months or longer","ask":"Which medicine suits me, what are the side effects, and how long must I use it?"},{"name":"Microneedling","how":"Fine needles create tiny channels in the skin, sometimes with PRP applied","often":"Skin texture, and sometimes as a scalp add-on","ask":"What does it add, and what are the infection and irritation risks?"},{"name":"Hair transplant","how":"A procedure that moves hair follicles from a donor area to a thinning area","often":"Established thinning with enough donor hair. See [hair transplant](/hair-transplant)","ask":"Am I a candidate, how many grafts, and what are the risks?"}],"note":"A doctor decides which of these suits you, and some people use more than one."},"recovery":{"lead":"There is little recovery for most people. This is what the first hours and days commonly look like, and your doctor sets yours. {pending}","body":"Mild tenderness, redness and tiny marks from the needle are common. Follow the doctor''s advice about washing your hair or face, sun and exercise on the first day or two. Tell the doctor about a fever, spreading redness or severe pain.","highlights":[{"pre":"same","big":"day","text":"Home after the session, with redness and mild tenderness"},{"pre":"about","big":"4 to 6 weeks","text":"Gap between sessions in many plans, per the reviewer"},{"pre":"after","big":"months","text":"A doctor judges whether there is any change. Hair changes, if any, are gradual"}],"timeline":[{"when":"Same day","notice":"Redness and mild tenderness at injection sites","doThis":"Follow the washing and sun advice you were given. Do not rub or scratch the area."},{"when":"Day 1 to 2","notice":"Swelling or a tight feeling, skin may look flushed","doThis":"Rest as needed. Avoid hard exercise and heat if the doctor says so."},{"when":"Day 3 to 7","notice":"Most visible marks settle on the face. Scalp tenderness eases","doThis":"Gentle care. Report any pus, fever or spreading redness."},{"when":"Week 2 to 4","notice":"Skin and scalp feel usual","doThis":"Next session or review, at the interval the doctor sets."},{"when":"Month 3 to 6","notice":"A doctor reviews whether there is any change","doThis":"Review visit. Decide whether to continue, space out or stop."}],"grid":{"cols":["Day 0","Day 1","Day 3","Wk 1"],"rows":[{"label":"Return to work","cells":[{"state":"y","text":"Often"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Wash scalp or face","cells":[{"state":"n","text":"Ask"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Hard exercise","cells":[{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Strong sun","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Cover"},{"state":"m","text":"Cover"}]},{"label":"Hair colour or treatments","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"}]}]},"closing":"Never assume there is no downtime. Marks and swelling vary between people. If you have an event, plan sessions weeks ahead."},"risks":{"lead":"Every injection carries risk. These are the ones people most often ask about, in plain words, and what to ask. This is not a complete list, and your doctor will go through yours.","rows":[{"risk":"Pain and bruising at the sites","means":"Common. The scalp can be tender for a day or two.","ask":"What do you use for comfort, and how long does it last?"},{"risk":"Swelling or headache","means":"Some people have swelling of the scalp or forehead, or a headache.","ask":"What can I take, and when should I call?"},{"risk":"Infection","means":"Rare. Any needle can carry a risk, and it needs early treatment.","ask":"Is the kit single-use and sealed, and what signs should I report?"},{"risk":"Allergic reaction to numbing cream","means":"Rash, itch or swelling where the cream was applied.","ask":"Do I have any allergy that matters?"},{"risk":"Scalp tenderness","means":"The scalp can feel sore, especially when combed.","ask":"How long should it last, and what can I use?"},{"risk":"No visible benefit","means":"Results vary, and some people see no change after a course.","ask":"What counts as a change, and what is the plan if there is none?"},{"risk":"Blood-related risks","means":"A needle can bleed more in people with a bleeding tendency or on blood thinners.","ask":"Should I stop any medicine, and who decides that?"}],"alert":"Call your doctor straight away for fever, spreading redness or heat, pus, severe pain or swelling that keeps getting worse. If you cannot reach the doctor, go to the nearest emergency department.","wait":["You have an active scalp or skin infection","You have a blood disorder, a low platelet count or take blood thinners (the doctor decides)","You are pregnant or breastfeeding, unless the doctor agrees","You are having cancer treatment","Your diabetes is not controlled","Your hair loss has a medical cause, such as thyroid, iron or hormone problems, that has not been checked","You expect a promised result"],"tell":["All medicines, supplements and blood thinners you take","Any blood disorder, diabetes, thyroid or hormone condition","Pregnancy, breastfeeding or plans to conceive","Past reactions to numbing creams or injections","Any other hair or skin treatment you use, or plan"]},"patientQuestions":[{"q":"Does PRP help with hair thinning?","href":"#evidence","linkText":"Read: what is known"},{"q":"How many sessions will I need?","href":"#sessions","linkText":"Read: sessions"},{"q":"How much will a course cost?","href":"#cost","linkText":"Read: the cost lines"},{"q":"Is PRP for the face the same?","href":"#skin-prp","linkText":"Read: skin"},{"q":"How does PRP compare with medicines or a transplant?","href":"#compare","linkText":"Read: how it compares"},{"q":"Who should not have PRP?","href":"#risks","linkText":"Read: who should wait"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp. Say what you want to talk about, hair or skin. No pressure to book."},{"title":"A doctor examines you","text":"The doctor examines the scalp or skin, asks about medicines and blood conditions, and may suggest tests for medical causes."},{"title":"You receive a written plan","text":"The number of sessions, the gap between them, the price of each and the total, and what happens if there is no change."},{"title":"You start with one session","text":"Pay for the first session before a package. See how you respond and how the visit goes."},{"title":"You return for reviews","text":"A coordinator check-in the next day, then sessions and reviews at the interval the doctor sets."}],"quoteChecks":["state the number of sessions, the gap between them and the course total?","say who draws the blood and injects, with their training?","say that the kit is single-use and sealed?","list review visits, medicines and tests separately?","say what happens, and what you pay, if there is no change?"],"extras":["Sessions beyond the course in the plan","Microneedling or other add-ons","Medicines for hair, if prescribed","Blood tests for medical causes","Follow-up and review visits","Aftercare products","Treatment of a reaction","Your travel and time off for repeat visits"],"insurance":"Insurance. PRP for hair or skin is usually treated as cosmetic, and most health policies do not pay for it. Ask your insurer in writing before you start, and keep the plan. We do not promise cashless approval.","payment":"Payment. Pay per session. Package plans and instalments depend on the clinic and the lender and are not shown here. Pay for one session before a package. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered doctor signs off.","Evidence for PRP is described as mixed. Studies will be cited only after the reviewer opens and checks each one. None is cited yet.","Session counts, gaps between sessions and how long marks last are general ranges to be confirmed by the reviewer.","Kits and devices have their own regulatory status, which is with the founder''s lawyer. This page makes no approval claim.","Insurance and payment wording is general and to be confirmed."]}'::jsonb, '{"costMode":"options","priceLabel":"One PRP session, usual cost","priceLinkText":"The lines inside it","costHeading":"What PRP costs, per session and per course","costCaption":"Per-session ranges. The course total is sessions x per-session range. Sample data / To be confirmed.","operationHeading":"What PRP is and how it is made","recoveryHeading":"Recovery between sessions","recoveryTocLabel":"Recovery","timelineCaption":"What most people notice and do, by time since a session.","risksHeading":"Risks and side effects","riskGuideHref":"/prp-treatment#risks","heroPlate":"none","operationPlate":"none","labels":{"techniquesHeading":"PRP, medicines, microneedling and transplant compared","techniquesCaption":"Plain differences between options for thinning hair. No ranking.","tocTechniques":"How it compares"},"tocLabels":{"surgery":"What it is","choices":"Hair and skin"},"costUnit":"session"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false),
  ('hair-transplant', 'hair', 'surgical', '[{"key":"surgeon","label":"Who performs each step","ask":"Who extracts the grafts, who makes the sites and who implants, and what is their training?"},{"key":"anaesthesia","label":"Local anaesthesia","ask":"What is used, who gives it, and is it in the price?"},{"key":"theatre","label":"Procedure room and day-care stay","ask":"Is the facility fee in the price, and is an overnight stay needed?"},{"key":"consumables","label":"Blades, tools and dressings","ask":"Are all single-use items in the price?"},{"key":"medicines","label":"Medicines after the procedure","ask":"Which medicines are included, and which do I buy?"},{"key":"followups","label":"Follow-up visits","ask":"How many reviews are in the price, and what does an extra one cost?"}]'::jsonb, '{"title":"Hair Transplant: Techniques, Grafts, Recovery, Risks","description":"How a hair transplant works, FUE vs FUT vs DHI, how grafts are counted, who is a candidate, recovery, risks and what sets the price. Results vary.","cityTitle":"Hair Transplant in {city}: Cost, Recovery, Risks"}'::jsonb, '{"seoTitle":"Hair Transplant Cost in India: Per Graft and Total Bill","metaDescription":"How hair transplant cost is built: grafts x rate, technique, sessions, extras. Labelled sample ranges with source and date. What a quote must list.","h1":"Hair transplant cost in India","answer":"The bill is usually grafts times a per-graft rate plus extras, so ask for the graft number and rate in writing. Sample per-graft and total ranges follow, dated and labelled once quotes arrive, then what raises or lowers the number.","unit":"graft","rangeHeading":"Sample per-graft rates and totals by graft band","rangeCaption":"Per-graft rates by method, then total bills by graft band. Each line is a separate case.","planner":{"heading":"How the price is built","formula":"Total = grafts x rate per graft + medicines, add-ons and follow-up","steps":["Ask the doctor for the graft number and how it was counted.","Multiply the graft number by the rate per graft in the written quote.","Add medicines, PRP or other add-ons, follow-up visits, tests and GST if they are not in the quote.","Compare plans for the same graft number and method, not the headline rate."]},"factors":[{"factor":"Number of grafts","why":"The area to cover and the donor supply decide the count, and the count sets most of the bill."},{"factor":"Method","why":"FUE, FUT and DHI take different time and skill, and clinics price them differently."},{"factor":"Sessions","why":"A large area may need more than one session, and each adds its own cost."},{"factor":"Who performs each step","why":"A doctor-led team and other settings price the same work differently."},{"factor":"What is included","why":"Medicines, reviews and add-ons may or may not be in the rate."},{"factor":"Facility","why":"A day-care facility and a hospital outpatient department structure fees differently."},{"factor":"City","why":"Rents and wages differ between cities, and so do fees."}],"notIncluded":["Medicines for hair, such as minoxidil, if prescribed","PRP or other add-ons","A second session","Follow-up visits beyond those in the plan","Tests before the procedure","GST, if shown separately","A stay near the facility","Your travel and time off"],"compareQuotes":["Ask each clinic for the graft number, how it is counted and the rate per graft, in writing.","Compare totals for the same graft number and method, and not the headline rate.","Ask who performs each step, and where you can check their registration.","Ask what happens, and what you pay, if growth is thin.","Do not pay a package before an in-person exam."],"insurance":"A hair transplant for cosmetic reasons is usually not covered by health policies, and instalment terms depend on the lender. Ask your insurer in writing before you book.","payment":"Payment methods and instalments depend on the clinic and the lender, and terms are not shown here. GST wording is to be confirmed. {tbc}","method":"No figure is shown yet. When quotes arrive, each line will show the source type, the number of data points and the date. A range needs at least three dated points from separate sources before it replaces the pending label. Figures from other websites are not used, and one city''s range is not used for another.","faqs":[{"q":"How is a hair transplant priced?","a":"Usually as the number of grafts times a rate per graft, plus extras such as medicines, add-ons and reviews. Ask for the graft number and the rate in writing."},{"q":"Does the method change the price?","a":"Often. FUE, FUT and DHI take different time and skill, and clinics define DHI in different ways. Compare plans for the same graft number and method."},{"q":"How many grafts will I need?","a":"The doctor estimates it from the area, the pattern of loss and the donor supply, after an in-person exam. It is a plan and not a promise, and it can change."},{"q":"What is usually not in the price?","a":"Medicines, PRP or other add-ons, extra follow-up visits, tests, GST if shown separately, a stay near the facility and a second session."},{"q":"Does insurance cover it?","a":"Usually not, when it is done for cosmetic reasons. Ask your insurer in writing."},{"q":"What should the quote list?","a":"The graft number and how it is counted, the method, who performs each step, the sessions, medicines, add-ons, follow-up, GST and what happens if growth is thin."}],"sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}]}'::jsonb, 'Hair transplant', 'Hair transplant', null, 'Moves hair follicles from a donor area, usually the back of the scalp, to a thinning part. Results vary with donor hair and the plan.', '{"procedureType":"https://schema.org/SurgicalProcedure","bodyLocation":"Scalp","howPerformed":"Hair follicles are taken from a donor area one by one or as a thin strip, and placed in tiny cuts in the thinning area, usually under local anaesthesia.","preparation":"Scalp examination, a review of medicines and health, and a plan for the number of grafts and the hairline.","followup":"A first wash visit, review visits, and care instructions for the scabs and the donor area."}'::jsonb, null, '[{"factor":"Grafts needed","why":"A larger area needs more grafts, and the quote often depends on the graft count."},{"factor":"Technique","why":"The method used to take and place follicles changes time and fees."},{"factor":"Donor limits and sessions","why":"A limited donor area may mean more than one session."},{"factor":"Body hair","why":"Using beard or body hair needs extra planning."},{"factor":"Facility type","why":"A day-care centre and a hospital price theatre and rooms differently."},{"factor":"Surgeon time","why":"Who does the key steps, and how long they take, changes the bill."},{"factor":"Medicines and PRP add-on","why":"Medicines after the procedure and any PRP add-on may be listed separately."},{"factor":"Follow-up visits","why":"Some quotes include them, some charge for each."},{"factor":"Tax","why":"Whether tax is added to the quoted figure should be asked in writing."}]'::jsonb, 'To be confirmed by the reviewer', 'Techniques, who is a candidate, grafts, recovery calendar, shock loss and cost.', 1, '["prp-treatment"]'::jsonb, '["hair-transplant-fue-fut-dhi","hair-transplant-norwood-grade-candidate","hair-transplant-recovery-calendar"]'::jsonb, '[]'::jsonb, null, '{"dek":"A hair transplant moves hair follicles from a donor area, usually the back of the scalp, to thinning areas. It does not stop hair loss in the rest of the scalp, so many people also need medicines. Grafts needed, technique and sessions set the [cost](/cost/hair-transplant). Results vary, and a doctor decides who is a candidate.","shortAnswers":[{"q":"What does it do?","a":"It moves follicles from a donor area to a thinning area. The rest of your hair keeps its own pattern of loss.","href":"#surgery","linkText":"What it does and does not do"},{"q":"Who is a candidate?","a":"Adults with established loss and enough donor hair. A doctor examines the scalp and sets a plan.","href":"#candidacy","linkText":"Candidacy by Norwood grade"},{"q":"How long is recovery?","a":"Scabs settle over about two weeks. Shedding comes after, and growth builds over many months.","href":"#recovery","linkText":"The recovery calendar"},{"q":"What sets the price?","a":"Mostly the number of grafts times a rate per graft, plus extras. Ask for both in writing.","href":"#cost","linkText":"The cost lines"}],"operation":{"lead":"A hair transplant is a procedure under local anaesthesia. Follicles are taken from a donor area, usually the back and sides of the scalp, and placed into small sites made in the thinning area. It is done in a day-care facility, and you go home or to a nearby stay the same day. A doctor decides whether it suits you.","body":"The transplanted hairs are meant to keep growing in their new place. Your other hairs can still thin over the years, which is why many people also use medicines such as minoxidil, or for some men finasteride, as a doctor advises. Read [how grafts are counted](/learn/hair-transplant-grafts-needed) and [the limits of the donor area](/learn/hair-transplant-donor-area-limits). If you are thinking of a milder option first, see [PRP treatment](/prp-treatment), which is a different procedure with a different aim.","caption":"Donor area at the back and sides of the scalp, and the thinning area at the front and top.","ask":"Am I a candidate, how many grafts do you plan, and what is the plan if growth is thin?","how":["Consultation: the doctor examines the scalp, often with a magnified scalp check, asks about the pattern and family history, and checks the donor area. Tests may be advised.","Planning: the doctor draws the hairline and the area to be covered, and gives a graft estimate in writing. The number can change after the exam.","Anaesthesia: local anaesthesia is injected into the donor and recipient areas. You are awake.","Extraction: follicles are taken from the donor area, either one by one or as a strip, by the method planned.","Placement: small sites are made in the thinning area and the grafts are placed in them. This takes several hours, with breaks.","Dressing and discharge: you receive wash instructions, medicines and a review date. A first wash visit may be planned for the next day."],"whoItSuits":[{"term":"Established loss","text":"Adults whose pattern of loss has settled, with enough donor hair for the area to be covered."},{"term":"Realistic aims","text":"A plan that fits the donor supply. A doctor will say if the area you hope to cover is more than the donor can give."},{"term":"Medical care alongside","text":"People who accept that medicines or other care may continue, because hair outside the transplant can keep thinning."},{"term":"Time for recovery","text":"People who can manage a quiet first week, a period without sweat or sports, and several reviews over many months."}]},"techniques":{"lead":"FUE, FUT and DHI are names for ways of taking and placing grafts. Clinics describe them differently, so ask what is meant. This table lists plain differences with no ranking.","rows":[{"name":"FUE (follicular unit extraction)","how":"Follicles are taken one by one with a small punch, leaving tiny dot marks. The donor area is often shaved short, fully or in part","often":"People who want to keep a short haircut and accept shaving. Larger sessions take longer","ask":"How many hours of extraction, who does it, and will I be shaved?"},{"name":"FUT (follicular unit transplantation, strip)","how":"A thin strip of scalp is taken from the donor area and divided into grafts under a microscope. This leaves a line scar that hair can cover","often":"People who plan to wear their hair longer and want many grafts in one session","ask":"Where will the scar be, how long will it be, and who cuts and closes it?"},{"name":"DHI (direct hair implantation)","how":"A name used by some clinics for a method where grafts are loaded into a fine pen-like tool and placed without making the sites first. The wording differs between clinics","often":"Smaller areas, or people who want less shaving in the recipient area","ask":"What exactly is meant by this term at your clinic, and how does it change the price?"}],"note":"A doctor decides which method suits your scalp and your aim. Some clinics combine methods, and some use body hair when donor hair is limited, at the reviewer''s confirmation."},"extraSections":[{"id":"grafts","heading":"How grafts are counted","tocLabel":"Grafts","paragraphs":["A graft is a small piece of scalp that holds one to a few hairs. Clinics count grafts, and sometimes count hairs, so ask which one a quote uses. The reviewer will confirm the usual range of hairs per graft. {pending}","The doctor estimates the number from the size of the area, the pattern of loss and the donor supply. That estimate is a plan and not a promise, and it can change after the exam. Ask how the count was made and who counts the grafts on the day.","A higher number is not better in itself. A donor area has a limit, and taking more than it can give can leave it thin. Ask what the donor limit is for you and how much is kept in reserve."],"note":{"label":"Ask this","text":"Will the quote use grafts or hairs, how will you count them on the day, and what happens to the price if the number changes?"}},{"id":"candidacy","heading":"Who is a candidate, by Norwood grade","tocLabel":"Candidacy by Norwood grade","lead":"The Norwood scale describes patterns of male hair loss from grade 2 to grade 7. General notes for the reviewer to confirm. Only a doctor who examines you can say where you stand.","table":{"caption":"General notes by pattern. A doctor decides for you.","head":["Pattern","Usual donor situation","What a doctor checks","May need to wait because"],"rows":[["Grade 2","Donor usually ample","Whether the loss is early and still changing","The pattern is not settled, and medicines may be tried first"],["Grade 3","Donor usually ample","Hairline recession, crown thinning, and family history","Loss may continue, so the plan must allow for it"],["Grade 4","Donor usually enough for the front","Size of the area against the donor supply","A large area may need more than one session"],["Grade 5","Donor usually limited for full cover","How much can be covered, and the order of areas","Expectations may be higher than the donor allows"],["Grade 6","Donor often limited","Whether partial cover is realistic","Donor supply may not match the area"],["Grade 7","Donor often very limited","Whether a transplant is advised at all","Other options may fit better, and body hair may be discussed"]]}},{"id":"donor","heading":"Donor area limits","tocLabel":"Donor limits","paragraphs":["The donor area is the part of the scalp that supplies the grafts. It holds a limited number of follicles, and it cannot be refilled. A plan that takes too many grafts now can leave nothing for later sessions, and can leave the donor area looking thin.","Ask the doctor how many grafts the donor can give over your lifetime, how many this session uses and what is kept in reserve. If hair loss goes on, the plan should allow for that."]},{"id":"shock-loss","heading":"Shock loss and the growth timeline","tocLabel":"Shock loss and timeline","paragraphs":["In the weeks after a transplant, the transplanted hairs often shed. This is called shock loss when it happens in nearby hairs too, and it is common, though not in every person. New hairs begin later, often thin at first, and the reviewer will confirm the usual months. {pending}","Growth builds over many months, and the final look is usually judged after a year or more. No one can promise a result, and a doctor reviews yours. Call the clinic if you are worried about shedding or if the scalp looks infected."],"note":{"label":"How long do transplanted hairs last","text":"Transplanted follicles are meant to keep growing where they are placed, and hairs around them can still thin with time. A doctor can tell you what to expect for your pattern."}},{"id":"choose","heading":"How to choose a doctor and clinic","tocLabel":"How to choose","bullets":["Check the registration of the doctor who performs the key steps, and not only the name in a brochure.","Ask who extracts grafts, who makes the sites and who places them.","Ask for the graft number, the method and what happens if the number changes, all in writing.","Ask about donor limits and how much is kept in reserve.","Ask what is included in the price, and what the follow-up schedule is.","Be careful of a package sold before an in-person exam, and of any promise of a fixed density or result."]}],"recovery":{"lead":"This is the usual shape of recovery, and your doctor sets yours. Day and month ranges are general and are for the reviewer to confirm. {pending}","body":"Plan a quiet first week. Scabs and redness settle over about two weeks. Hairs often shed after that, and new growth comes later and builds slowly. Follow the wash instructions you are given, and do not rub or scratch the grafts.","highlights":[{"pre":"about","big":"1 to 2 weeks","text":"Scabs and crusts fall and redness settles"},{"pre":"weeks","big":"2 to 6","text":"Transplanted hairs may shed. This is common and not in everyone"},{"pre":"month","big":"12 to 18","text":"The final look is usually judged. Growth builds slowly"}],"timeline":[{"when":"Day 0","notice":"Dressing, tenderness, swelling risk on the forehead","doThis":"Sleep with your head raised, as advised. Do not touch the grafts."},{"when":"Day 1 to 3","notice":"Tight scalp, mild swelling, small scabs","doThis":"First wash as instructed. Do not rub the grafts."},{"when":"Day 7 to 14","notice":"Scabs and crusts fall, redness remains","doThis":"Keep to the wash routine. Attend the review visit."},{"when":"Week 2 to 6","notice":"Transplanted hairs may shed","doThis":"Do not panic. Call the clinic if you are worried."},{"when":"Month 3 to 4","notice":"New growth often begins thin","doThis":"Continue medicines if advised, and attend reviews."},{"when":"Month 6 to 9","notice":"Growth and thickness build","doThis":"Keep to the schedule. Do not judge yet."},{"when":"Month 12 to 18","notice":"The final look is usually judged","doThis":"Final review. Discuss whether another session is advised."}],"grid":{"cols":["Day 1","Day 3","Day 7","Wk 2"],"rows":[{"label":"Desk work","cells":[{"state":"n","text":"No"},{"state":"m","text":"Cover"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Wash the scalp","cells":[{"state":"m","text":"As told"},{"state":"m","text":"As told"},{"state":"y","text":"Yes"},{"state":"y","text":"Yes"}]},{"label":"Sports or sweating","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"}]},{"label":"Cap or helmet on grafts","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Ask"},{"state":"m","text":"Ask"}]},{"label":"Strong sun","cells":[{"state":"n","text":"No"},{"state":"n","text":"No"},{"state":"m","text":"Cover"},{"state":"m","text":"Cover"}]}]},"closing":"Never assume a fixed recovery. Swelling, scabbing and shedding vary between people. Plan events and travel months ahead."},"risks":{"lead":"Every procedure carries risk. These are the ones people most often ask about, in plain words, and what to ask. This is not a complete list, and your doctor will go through yours.","rows":[{"risk":"Swelling and bruising","means":"Swelling of the forehead, and sometimes around the eyes, in the first days.","ask":"What can I do, and when should I call?"},{"risk":"Scabbing and redness","means":"Small scabs and pink skin for one to a few weeks.","ask":"How should I wash, and when can I go out?"},{"risk":"Numbness","means":"A numb patch in the donor or recipient area, usually temporary.","ask":"How long does it usually last?"},{"risk":"Shedding (shock loss)","means":"Transplanted or nearby hairs shed in the weeks after.","ask":"What is normal, and when should I call?"},{"risk":"Infection","means":"Rare. Pain, pus, fever or spreading redness need early treatment.","ask":"What signs should I report, and who do I call?"},{"risk":"Folliculitis","means":"Small pimples around the grafts.","ask":"How is it treated?"},{"risk":"Thin growth in some grafts","means":"Not every graft grows as hoped, and results vary.","ask":"What is the plan if growth is thin, and does a repeat session cost extra?"},{"risk":"Scarring in the donor area","means":"A line scar after strip removal, and dot marks after punch removal.","ask":"Where will the marks be, and can my hair cover them?"},{"risk":"A poorly planned hairline","means":"A hairline that does not suit the face or age, or looks uneven.","ask":"Who draws the hairline, and will I approve it before you start?"},{"risk":"Loss continuing outside the transplant","means":"Other hairs can keep thinning.","ask":"Which medicines do you advise, and for how long?"},{"risk":"Dissatisfaction with density","means":"The result may be lower or different from what you hoped.","ask":"What should I expect for my donor and my area?"}],"alert":"Call your doctor straight away for fever, spreading redness or heat, pus, severe pain or swelling that keeps getting worse. If you cannot reach the doctor, go to the nearest emergency department.","wait":["You are under about 25 and your pattern is not yet settled","You have a scalp infection or an active inflammatory scalp disease","You have uncontrolled diabetes or a bleeding disorder","Your donor area is thin","You expect a density the donor cannot give","You have recently had a crash diet or illness with shedding","You have active alopecia areata","You smoke or take blood thinners, and have not asked the doctor"],"tell":["All medicines, supplements and blood thinners you take","Diabetes, thyroid, bleeding or skin conditions","Family history of hair loss","Past hair procedures or treatments","Allergies to anaesthetics, dressings or antibiotics","Smoking and alcohol"]},"patientQuestions":[{"q":"Am I a candidate?","href":"#candidacy","linkText":"Read: Norwood grade"},{"q":"How many grafts will I need?","href":"#grafts","linkText":"Read: how grafts are counted"},{"q":"FUE, FUT or DHI?","href":"#surgery","linkText":"Read: the methods"},{"q":"When will hair grow?","href":"#shock-loss","linkText":"Read: the timeline"},{"q":"What will it cost?","href":"#cost","linkText":"Read: the cost lines"},{"q":"How do I choose a doctor?","href":"#choose","linkText":"Read: how to choose"}],"quoteProcess":[{"title":"You talk to a coordinator","text":"By phone or WhatsApp. Say where you live and what you want to ask. No pressure to book."},{"title":"A doctor examines your scalp","text":"In person, or by photos for a first view. A graft number is given only after an in-person exam."},{"title":"You receive a written plan","text":"The method, the graft number and how it is counted, who performs each step, the price, and what is included."},{"title":"You decide in your own time","text":"Compare plans for the same grafts and method. Do not pay a package before the exam."},{"title":"Reviews after the procedure","text":"A coordinator check-in the next day, a first wash visit, a review around day 10, and later reviews."}],"quoteChecks":["state the number of grafts, how they are counted and the rate per graft?","name the method and say who performs each step?","say how many sessions are planned?","list medicines, PRP or other add-ons and follow-up visits separately?","include GST in the total, or show it as a separate line?","say what happens, and what you pay, if growth is thin?"],"extras":["Medicines for hair, such as minoxidil, if prescribed","PRP or other add-ons","A second session, if the area is large","Follow-up visits beyond those in the plan","Tests before the procedure","GST, if shown separately","A stay near the facility","Your travel and time off"],"insurance":"Insurance. A hair transplant for cosmetic reasons is usually not covered by health policies. Ask your insurer in writing before you book, and keep the plan. We do not promise cashless approval.","payment":"Payment. Payment methods and instalments depend on the clinic and the lender and are not shown here. Do not pay a package before an in-person exam. {tbc}","sources":[{"label":"National Medical Commission: public register of doctors","href":"https://www.nmc.org.in/"}],"footnotes":["Medical review is pending. The reviewer, qualification and review date will be shown once a registered doctor signs off.","Norwood grade notes, graft ranges, the recovery calendar and shock loss timing are general and to be confirmed by the reviewer.","No density, graft survival or growth percentage is given, because none has been verified.","Whether a transplant is done by a qualified practitioner is a public-health concern. Check registration and who performs each step.","Insurance and payment wording is general and to be confirmed."]}'::jsonb, '{"costMode":"options","priceLabel":"Typical bill, up to 2,000 grafts","priceLinkText":"The lines inside it","costHeading":"What a hair transplant costs, per graft and in total","costCaption":"Per-graft ranges by method and bills by graft band. Total = grafts x rate + extras. Sample data / To be confirmed.","operationHeading":"What a hair transplant does and does not do","recoveryHeading":"Recovery calendar","recoveryTocLabel":"Recovery","timelineCaption":"What most people notice and do, by time since the procedure.","risksHeading":"Risks and side effects","riskGuideHref":"/hair-transplant#risks","heroPlate":"none","operationPlate":"none","labels":{"techniquesHeading":"FUE, FUT and DHI explained","techniquesCaption":"Plain differences between methods. No ranking.","tocTechniques":"FUE, FUT and DHI"},"tocLabels":{"surgery":"What it does","choices":"Methods and candidacy"},"costUnit":"graft"}'::jsonb, '{"hero":{},"operation":{},"recovery":{},"card":{}}'::jsonb, false)
insert into public.treatment_city_pages (treatment_slug, city_slug, is_placeholder, published, reviewer_id, meta_description, price_min_inr, price_max_inr, price_from_inr, price_valid_as_of, price_collected_on, price_data_points, price_source_type, price_is_sample, price_chip_label, price_basis, includes, facilities, travel, local_context, usefulness, signoffs, lighthouse_ok, before_after, local_copy, images, local_notes, seo_title, h1, intro, sections) values
  ('gynecomastia-surgery', 'gurgaon', false, false, 'sample-reviewer', 'Gynecomastia surgery in Gurgaon: price lines, recovery calendar, risks, getting there and how we check surgeons.', 62000, 94000, 45000, '2026-11', '2026-11-09', 1, 'founder_published', true, 'To be confirmed', 'Working range, dated 09 Nov 2026, from one source. It covers the three fees listed below. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"The operation is done at a partner facility in Gurgaon, also written Gurugram. We do not name it on this page. Whatever the facility, check the same things.","partners":[{"type":"Partner facility (day care or hospital)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Accreditation","why":"Shows an outside body has checked its processes","ask":"Which body, and until when is it valid?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"Most people come from Delhi, Noida, Faridabad or Rewari. Plan for one attendant and a ride home that avoids peak traffic.","airport":"Indira Gandhi International Airport, Delhi (to be verified)","station":"HUDA City Centre (Yellow Line) and Sikandarpur (Rapid Metro)","stayDays":"Day care for most; one night if the surgeon asks","metro":"The Delhi Metro Yellow Line runs into Gurugram as far as HUDA City Centre, and Rapid Metro joins it at Sikandarpur. {sample} Nearest station and drive time to the partner facility are added once the facility is confirmed.","roadTimes":[{"from":"South Delhi","time":"40 to 70 min","tip":"Leave before the morning peak"},{"from":"Noida","time":"70 to 110 min","tip":"Plan a night''s stay if the operation is late in the day"},{"from":"Faridabad","time":"60 to 100 min","tip":"Plan the ride home away from peak hour"},{"from":"Rewari","time":"60 to 90 min","tip":"Highway ride, a seat that reclines helps"}],"privacyNote":"Ask the coordinator which entrance is quietest for drop-off. No building name is printed on any message we send. Staying one night is a surgeon''s decision, and your attendant can stay with you.","mapCaption":"Travel from nearby areas, no building shown."}'::jsonb, '[]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Most people come from Delhi, Noida, Faridabad or Rewari.","The Delhi Metro Yellow Line runs into Gurugram as far as HUDA City Centre, and Rapid Metro joins it at Sikandarpur."]'::jsonb, null, '[{"heading":"Office schedules","text":"Many people who work in Gurgaon offices ask for a Thursday or Friday operation so that a weekend falls in the first days of rest. Whether that suits you is for the surgeon to say. {pending}"},{"heading":"Which entrance","text":"Ask the coordinator which entrance is used on the day. A quiet drop-off matters to many men, and a front-opening shirt makes dressing easier after surgery."},{"heading":"If you live in Delhi","text":"Delhi is close, but traffic is slow. See the [Delhi page](/gynecomastia-surgery-in-delhi) for planning notes from that side."}]'::jsonb, null, null, null, null),
  ('gynecomastia-surgery', 'delhi', false, false, 'sample-reviewer', 'Gynecomastia surgery in Delhi: price lines, recovery, risks, and how a visit from Noida, Ghaziabad or Faridabad is planned.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Delhi yet. Until one is, this page shows how a Delhi plan is made, and the checks to run on any place you are given. If the surgery turns out to be in Gurgaon, the page will say so plainly.","partners":[{"type":"Partner facility in Delhi (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"In Delhi the hard part is not distance but traffic. Plan the consultation day and the operation day for off-peak hours, and bring an attendant who can drive you home.","airport":"Indira Gandhi International Airport (to be verified)","station":"New Delhi, Old Delhi and Hazrat Nizamuddin stations (to be verified against the facility)","stayDays":"Day care for most; one night if the surgeon asks","metro":"Most of Delhi is on the metro, but you should not take it home after the operation. A cab with a reclining seat is easier on the chest. {sample} The nearest station to the facility is added once it is confirmed.","roadTimes":[{"from":"Noida","time":"50 to 90 min","tip":"Cross the river before the evening peak"},{"from":"Ghaziabad","time":"60 to 100 min","tip":"Ask for a late-morning slot to miss the rush"},{"from":"Faridabad","time":"50 to 90 min","tip":"Plan the ride home away from peak hour"},{"from":"Gurgaon","time":"50 to 90 min","tip":"Leave before the morning peak"}],"privacyNote":"Ask which entrance is quietest and whether the clothes you wear in can be loose. No building name is printed on any message we send. A night''s stay is a surgeon''s decision, and your attendant can stay with you.","mapCaption":"Travel into Delhi from nearby towns, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: which Delhi facility, if any, will host the operation","source":"","asOf":""},{"text":"NEEDS REAL DATA: metro station and road access to that facility, with a date","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Delhi pages are written after a partner is confirmed. Until then this page shows how a Delhi plan is made.","Noida, Ghaziabad and Faridabad patients lose most time to traffic, not distance."]'::jsonb, null, '[{"heading":"Where the operation happens","text":"To be confirmed. If it is done in Gurgaon, the [Gurgaon page](/gynecomastia-surgery-in-gurgaon) has the road times and the facility checks. {tbc}"},{"heading":"Choosing a day","text":"Delhi traffic is lightest mid-morning and early afternoon on weekdays. Ask for a morning operation slot so that you are home well before the evening peak."},{"heading":"Air quality and the first week","text":"Winter air in Delhi can be poor. Whether it matters for recovery is a question for the reviewing surgeon. {pending} Until then, plan the first week indoors if you can."},{"heading":"Who comes with you","text":"Bring one adult who can drive. Parking near a hospital can be limited, so ask the coordinator where the attendant can wait."}]'::jsonb, null, null, null, null),
  ('gynecomastia-surgery', 'lucknow', false, false, 'sample-reviewer', 'Gynecomastia surgery in Lucknow: price lines, recovery, risks, and the trip from Barabanki, Unnao or Sitapur.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Lucknow yet. If the operation ends up being in another city, we will say so at the top of this page and not claim a local site. Whatever the place, run the same checks.","partners":[{"type":"Partner facility in Lucknow (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"Many people who ask about this surgery in Lucknow live in a town outside it and come in for the day. The plan is built around one early train or road trip in, and one ride home with a seat that reclines.","airport":"Chaudhary Charan Singh International Airport, Lucknow (to be verified)","station":"Charbagh station and the Lucknow Metro (to be verified against the facility)","stayDays":"Day care for most; one night if the surgeon asks or the road home is long","metro":"The Lucknow Metro runs along the north-south corridor and is useful for the consultation visit. After the operation a cab is easier. {sample} Station names and distances to the facility are added once it is confirmed.","roadTimes":[{"from":"Barabanki","time":"40 to 70 min","tip":"Short enough for a same-day return if the surgeon agrees"},{"from":"Unnao","time":"60 to 100 min","tip":"Consider a night in Lucknow if the operation is late in the day"},{"from":"Sitapur","time":"80 to 120 min","tip":"Ask whether the first review can be on a video call"},{"from":"Hardoi","time":"100 to 150 min","tip":"Plan a night''s stay and book the return by road, not train"}],"privacyNote":"If you come from a smaller town, tell the coordinator early who may know you at the hospital. A cousin or a neighbour at the front desk is a real worry for many men, and a quiet entrance or a different slot can help.","mapCaption":"Travel into Lucknow from nearby districts, no building shown."}'::jsonb, '[{"text":"NEEDS REAL DATA: which Lucknow facility, if any, will host the operation","source":"","asOf":""},{"text":"NEEDS REAL DATA: road times from Barabanki, Unnao, Sitapur and Hardoi, checked on a map with a date","source":"","asOf":""},{"text":"NEEDS REAL DATA: guest-house or hotel options near the facility","source":"","asOf":""}]'::jsonb, '', '{}'::jsonb, false, '[]'::jsonb, '["Many people ask about this surgery in Lucknow from a town outside it, and come in for the day.","A first review on a video call can save a second long trip to the city."]'::jsonb, null, '[{"heading":"Coming in from a smaller town","text":"Decide before you book whether you will go home the same day or stay a night. Roads out of Lucknow in the evening are slow, and an early operation slot makes a same-day return realistic for nearby towns."},{"heading":"Language","text":"Hindi and Hinglish are fine for the first call and for the consultation. Ask for the written estimate in the language you read most easily. {tbc}"},{"heading":"Summer heat and the vest","text":"May and June heat makes the compression vest hard to wear. Ask for a breathable garment and a spare, and plan the first week in a cool room."},{"heading":"If you live in Kanpur","text":"Lucknow is the nearest other city we cover for Kanpur patients. Read the [Kanpur page](/gynecomastia-surgery-in-kanpur) to compare the trip."}]'::jsonb, null, null, null, null),
  ('gynecomastia-surgery', 'kanpur', false, false, 'sample-reviewer', 'Gynecomastia surgery in Kanpur: price lines, recovery, risks, and whether the operation is in Kanpur or a short trip away.', 62000, 94000, 45000, '2026-11', '2026-11-10', 1, 'founder_published', true, 'To be confirmed', 'Working range from one source, dated 10 Nov 2026. It covers the three fees listed below. The same figure is shown for every city until local quotes are collected. Bills from about Rs 45,000 are possible for small cases.', '{"surgeon":"included","anaesthesia":"included","theatre":"included","stay":"varies","consumables":"unknown","followups":"unknown","medicines":"unknown"}'::jsonb, '{"intro":"No partner facility is confirmed in Kanpur yet. It is possible that people from Kanpur will be asked to travel for the operation, and if so this page will say where and how far, before anything else.","partners":[{"type":"Partner facility for Kanpur patients (to be confirmed)","count":null}],"accreditation":null,"checks":[{"check":"Registration","why":"The facility and the surgeon should both be registered","ask":"May I see the facility''s certificate and proof that the surgeon is registered with a medical council?"},{"check":"Day care or beds","why":"Decides whether you can stay a night if needed","ask":"Is an overnight bed kept for me if the surgeon asks?"},{"check":"Privacy at the front desk","why":"Many men want a quiet drop-off and discreet paperwork","ask":"Which entrance is used, and what name appears on the billing paper?"},{"check":"Emergency plan","why":"A complication needs a plan, not a phone call","ask":"Where would I be taken if I needed more care?"},{"check":"Billing","why":"Every fee and every extra, before you decide","ask":"Can I have the estimate in writing, with every line?"}]}'::jsonb, '{"intro":"For Kanpur the first question is where the operation is. If it is in Kanpur, plan a local day-care visit. If it is in Lucknow, plan a trip of roughly one and a half to two hours