insert into public.faqs (id, treatment_slug, city_slug, position, question, answer, published) values
  ('faq-what', 'gynecomastia-surgery', null, 1, 'What is gynecomastia?', 'It is growth of breast gland tissue in boys and men, on one side or both. The chest can also look full because of fat alone. Doctors call that pseudogynecomastia, and many men have a mix of the two.', true),
  ('faq-symptoms', 'gynecomastia-surgery', null, 2, 'What are the signs, and which need a doctor soon?', 'A firm disc behind the nipple, uneven swelling, tenderness and a wider areola are the usual signs. A hard lump, change on one side only, pain or fluid from the nipple should be seen by a doctor early, before you think about surgery.', true),
  ('faq-candidate', 'gynecomastia-surgery', null, 3, 'Who is a suitable candidate for surgery?', 'Surgeons look for good general health, a steady weight, a chest that has stopped changing, and a reason that matters to you. Smokers are usually asked to stop. A surgeon decides after an examination, not from a photo.', true),
  ('faq-anaesthesia', 'gynecomastia-surgery', null, 4, 'Is gynecomastia surgery done under general or local anaesthesia?', 'Smaller operations can be done under local anaesthesia with sedation. Larger operations, or gland removal together with liposuction, usually use general anaesthesia. The surgeon and the anaesthetist decide after your examination and a fitness check.', true),
  ('faq-work', 'gynecomastia-surgery', null, 5, 'How many days off work do I need?', 'Many people return to desk work after about a week, and some need longer. Driving is usually after about two weeks and chest training after six weeks or more. These are typical timings, not promises, and your surgeon sets yours. The [recovery guide](/gynecomastia-surgery#recovery) shows the full pattern week by week.', true),
  ('faq-scar', 'gynecomastia-surgery', null, 6, 'Will I have visible scars?', 'Yes, some mark remains. For gland removal the cut is usually small and sits at the edge of the areola, where the skin colour changes, or at the side of the chest. Liposuction leaves tiny marks. Larger cases with loose skin may need longer scars. Scars start red and usually fade over a year or more. Ask the surgeon to mark the planned cuts on your chest.', true),
  ('faq-sameday', 'gynecomastia-surgery', 'gurgaon', 7, 'Can I go home to Delhi, Noida or Faridabad the same day?', 'After a day-care operation many people go home the same day, but you should not drive yourself. Bring an attendant, and plan the ride so you are not stuck in traffic for hours on day one. The surgeon and the anaesthetist decide whether you stay a night.', true),
  ('faq-insurance', 'gynecomastia-surgery', null, 8, 'Does insurance cover gynecomastia surgery?', 'Usually not, because most policies treat it as cosmetic. Some may consider it when a doctor records a medical need. Ask your insurer in writing before you book, and ask the hospital which diagnosis and procedure it will put on the estimate.', true),
  ('faq-name', 'gynecomastia-surgery', 'gurgaon', 9, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Gurgaon and Gurugram are the same city in Haryana, and both spellings are in common use. This page uses Gurgaon because more people search for it.', true),
  ('faq-centre', 'gynecomastia-surgery', 'gurgaon', 10, 'What kind of place is the operation done in?', 'A partner day-care surgical centre or a hospital, depending on the plan. We do not name it on this page. The [checks](#facilities) listed above apply to either.', true),
  ('faq-summer', 'gynecomastia-surgery', 'gurgaon', 11, 'Does the heat of a Gurgaon summer matter for recovery?', 'It can. A compression vest is worn under clothes for weeks, and it is uncomfortable in heat. Ask for a breathable garment and a spare, and plan the first week indoors with air conditioning if you can.', true),
  ('faq-return', 'gynecomastia-surgery', null, 12, 'Can the enlargement come back?', 'It can. Weight gain, anabolic steroids, some medicines, alcohol and some medical conditions can cause new enlargement. Read about the [possible causes](/learn/gynecomastia-causes), and if the cause is still there, tell the surgeon before you decide.', true),
  ('faq-myth', 'gynecomastia-surgery', null, 13, 'Can creams, oils or supplements remove it?', 'There is no good evidence that creams, oils, homeopathy or fat-burner supplements remove gland tissue. Fat may shrink with weight loss, gland usually does not. Chest exercise builds muscle and can make a gland look more prominent.', true),
  ('faq-second', 'gynecomastia-surgery', null, 14, 'What if I need a second operation?', 'It happens. Ask the hospital, in writing, whether a second operation is charged and for how long after the first. You can [compare two quotes](/learn/how-to-compare-surgery-quotes) on exactly this line.', true),
  ('lipo-weight', 'liposuction', null, 1, 'Is liposuction a way to lose weight?', 'No. It removes pockets of fat that have not responded to diet and exercise and reshapes the area. It is not a treatment for obesity, and the number on the scale may change very little. Surgeons usually ask you to be near a steady weight first. Read [liposuction is not weight loss](/learn/liposuction-vs-weight-loss).', true),
  ('lipo-regain', 'liposuction', null, 2, 'What happens if I gain weight afterwards?', 'Fat cells in the treated area are removed, but fat cells elsewhere remain, and weight gain can show up in the treated area and in other places. A steady weight and regular exercise keep the shape you worked for. See [can fat come back after liposuction](/learn/liposuction-fat-return).', true),
  ('lipo-pain', 'liposuction', null, 3, 'How painful is it?', 'Most people describe soreness, tightness and bruising rather than sharp pain, and medicines for pain and swelling are given. Larger plans usually hurt more. Tell the doctor straight away if pain keeps getting worse instead of easing.', true),
  ('lipo-activity', 'liposuction', null, 4, 'When can I return to normal activity?', 'Many people rest for a few days, return to desk work within one to two weeks and build up exercise from about four weeks, as the surgeon allows. These are typical timings, not promises. The [recovery calendar](/liposuction#recovery) shows the full pattern.', true),
  ('lipo-technique', 'liposuction', null, 5, 'How do I choose a technique?', 'You do not choose it alone. The surgeon recommends one after looking at the area, the amount of fat, your skin and any earlier operations. Ask why that technique suits you and whether it changes the quote. See [types of liposuction](/learn/types-of-liposuction).', true),
  ('lipo-consult', 'liposuction', null, 6, 'What happens at a consultation?', 'The surgeon asks about your health, medicines and goals, examines the areas while you stand, explains the plan and the risks, and arranges any tests and an anaesthesia check. Ask for the quote in writing, line by line.', true),
  ('lipo-chin', 'liposuction', null, 7, 'Can a double chin or neck be treated?', 'Often yes, when the cause is fat under the chin. If the cause is loose skin or the shape of the jaw, liposuction alone may not help. It is a small area and a shorter operation. See [double chin liposuction](/learn/double-chin-liposuction).', true),
  ('lipo-men', 'liposuction', null, 8, 'Can liposuction treat a man''s chest or love handles?', 'It can treat chest fat and fat at the waist. If the chest enlargement is gland tissue, liposuction alone does not remove it, and the plan may include gland removal. See [gynecomastia surgery](/gynecomastia-surgery) and [liposuction for men](/learn/liposuction-for-men).', true),
  ('lipo-insurance', 'liposuction', null, 9, 'Does insurance cover liposuction?', 'Usually not, because most policies treat it as cosmetic. Ask your insurer in writing before you book, and ask the hospital which diagnosis and procedure it will put on the estimate.', true),
  ('lipo-scars', 'liposuction', null, 10, 'Will there be scars?', 'Yes, tiny marks remain where the tube went in. The surgeon chooses places that are easy to hide, and the marks fade over months. Ask the surgeon to show you where they are planned.', true),
  ('gyn-delhi-where', 'gynecomastia-surgery', 'delhi', 20, 'Is the operation in Delhi itself?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If the operation is in Gurgaon, we will say so at the top of this page, and the [Gurgaon page](/gynecomastia-surgery-in-gurgaon) has the road times for that route.', true),
  ('gyn-delhi-traffic', 'gynecomastia-surgery', 'delhi', 21, 'How do I plan around Delhi traffic on the day?', 'Ask for a morning slot so that the ride home is before the evening peak, and bring an adult who can drive. Wear a loose, front-opening shirt, because lifting your arms may be hard on the first day.', true),
  ('gyn-delhi-ncr', 'gynecomastia-surgery', 'delhi', 22, 'I live in Noida or Ghaziabad. Is the trip manageable?', 'Most people from there manage a day-care operation with one attendant, but the roads are slow. Ask whether a night nearby makes sense if the operation is late in the day, and whether the first review can be a video call.', true),
  ('gyn-delhi-air', 'gynecomastia-surgery', 'delhi', 23, 'Does Delhi''s winter air matter for recovery?', 'Whether it matters is a question for the reviewing surgeon. Until that review is done, a sensible plan is to stay indoors in the first week when the air is poor, and to keep your follow-up visits.', true),
  ('gyn-lko-small-town', 'gynecomastia-surgery', 'lucknow', 20, 'I live outside Lucknow. Can I do this in a day?', 'For nearby towns such as Barabanki, many people manage a same-day return after a day-care operation if the surgeon agrees. From farther towns, plan a night in the city. Book an early slot so that you travel in daylight.', true),
  ('gyn-lko-where', 'gynecomastia-surgery', 'lucknow', 21, 'Is the operation in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is somewhere else, we will say so at the top of the page, with the distance.', true),
  ('gyn-lko-hindi', 'gynecomastia-surgery', 'lucknow', 22, 'Can the consultation and the paperwork be in Hindi?', 'Yes, the first call and the consultation can be in Hindi or Hinglish. Ask for the written estimate in the language you read most easily, and check every line before you sign.', true),
  ('gyn-lko-heat', 'gynecomastia-surgery', 'lucknow', 23, 'How do I manage the vest in the summer heat?', 'Ask for a breathable garment and a spare, wear it over a thin cotton vest and spend the first week in a cool room. If the skin under the garment is red or sore, tell the surgeon at the review.', true),
  ('gyn-knp-travel', 'gynecomastia-surgery', 'kanpur', 20, 'Do I have to travel to Lucknow or Delhi?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If the operation is there, we will say so at the top of the page, with the trip time.', true),
  ('gyn-knp-train', 'gynecomastia-surgery', 'kanpur', 21, 'Is the train or the road better for the trip home?', 'The road is usually easier after the operation, because you can recline and stop when needed. Ask the coordinator to arrange a cab. Train timings are to be added after they are checked.', true),
  ('gyn-knp-followup', 'gynecomastia-surgery', 'kanpur', 22, 'How are follow-up visits handled after I go home?', 'Ask which visits must be in person and which can be a video call. The first review at about a week is the one most likely to need an in-person visit, and later ones may be remote.', true),
  ('gyn-knp-night', 'gynecomastia-surgery', 'kanpur', 23, 'Should a family member stay with me?', 'One adult can usually stay with you in the facility or nearby. Ask about guest-house options if you need to stay a night away from home, and who looks after the vest and the medicines the first evening.', true),
  ('lipo-ggn-name', 'liposuction', 'gurgaon', 20, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are in common use for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('lipo-ggn-day', 'liposuction', 'gurgaon', 21, 'Is liposuction in Gurgaon day care or an overnight stay?', 'It depends on the number of areas and the anaesthesia. A single small area may be day care. Several areas, or ultrasound-assisted work, may need a night. Ask the surgeon before you choose a facility and a date.', true),
  ('lipo-ggn-office', 'liposuction', 'gurgaon', 22, 'I work in a Gurgaon office. How much leave do I need?', 'Many people take a few days off, and return to desk work within one to two weeks. Larger plans need longer. The surgeon decides after the first review, so keep your leave flexible.', true),
  ('lipo-ggn-summer', 'liposuction', 'gurgaon', 23, 'Is the garment a problem in the heat?', 'It can be, from April to September. Ask for a breathable fabric and a spare, wear a thin cotton layer under it, and keep the first week indoors with air conditioning if you can.', true),
  ('lipo-del-where', 'liposuction', 'delhi', 20, 'Is liposuction available in Delhi itself?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If the work is done in Gurgaon, we will say so at the top of the page, and the [Gurgaon page](/liposuction-in-gurgaon) has the road times for that route.', true),
  ('lipo-del-trips', 'liposuction', 'delhi', 21, 'How many trips across the city will I need?', 'Usually three: the consultation, the operation day and the first review about three to five days later. Ask whether the consultation and a later review can be by video to keep the trips down.', true),
  ('lipo-del-clothes', 'liposuction', 'delhi', 22, 'What should I wear to the operation and home?', 'Loose, dark clothes a size up, a front-opening top, and slip-on shoes. The garment goes under your clothes and it is easier to dress without bending.', true),
  ('lipo-del-parking', 'liposuction', 'delhi', 23, 'Where does my attendant park and wait?', 'Parking near a hospital can be limited. Ask the coordinator which gate to use for drop-off and pick-up, and where an attendant can wait. A cab booked for the return avoids the problem.', true),
  ('lipo-lko-where', 'liposuction', 'lucknow', 20, 'Is liposuction done in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, we will say so at the top of the page, with the distance and the travel plan.', true),
  ('lipo-lko-review', 'liposuction', 'lucknow', 21, 'I live far from the city. Who checks me on day 3 to 5?', 'Ask the coordinator at the start. Options are a video call, or a local doctor who looks at the garment and the cuts and sends a note to the surgeon. The surgeon decides what is acceptable.', true),
  ('lipo-lko-stay', 'liposuction', 'lucknow', 22, 'Do I need to stay a night in Lucknow?', 'From nearby towns a same-day return may work for a small, single-area plan. For several areas, or a trip of more than about an hour and a half, plan a night. The surgeon and the anaesthetist decide.', true),
  ('lipo-lko-season', 'liposuction', 'lucknow', 23, 'Does the time of year matter?', 'Heat from May to June makes the garment harder to wear. Weddings and festivals can fill hotels and roads. Ask the surgeon whether the first weeks of recovery fit around any event you have.', true),
  ('lipo-knp-where', 'liposuction', 'kanpur', 20, 'Do I have to go to Lucknow for liposuction?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If the operation is there, the page will say so, with the trip time.', true),
  ('lipo-knp-ride', 'liposuction', 'kanpur', 21, 'How do I manage the ride home with a garment on?', 'Book a cab with a seat that reclines, bring a pillow, keep the garment on, sip water and stop every hour. Do not drive yourself on the first day.', true),
  ('lipo-knp-standing', 'liposuction', 'kanpur', 22, 'My job keeps me standing for long hours. When can I go back?', 'That is for the surgeon to say after the first review. Many people return to desk work earlier than to standing or lifting work. Tell the coordinator what your work involves before you book.', true),
  ('lipo-knp-video', 'liposuction', 'kanpur', 23, 'Can later reviews be done by video from Kanpur?', 'Often yes, once the first in-person review is done. Ask the coordinator which visits must be in person, and send photos only through the channel the clinic names, never by an unknown chat.', true),
  ('acne-pharmacy', 'acne-treatment', null, 1, 'Can creams from a pharmacy treat acne, and when is a doctor needed?', 'For a few mild spots, a pharmacy cream may help. See a doctor if spots are many, painful, deep, leave marks, or have not improved after a couple of months of use. A doctor can also check whether a product is making things worse. Tablets are never available without a prescription.', true),
  ('acne-how-long', 'acne-treatment', null, 2, 'How long before acne improves?', 'A first change often takes about 6 to 8 weeks, and many plans run for months. Early weeks may bring dryness or a flare. The doctor reviews the plan every few weeks. Results vary, and a plan that works for one person may not for another.', true),
  ('acne-return', 'acne-treatment', null, 3, 'Why did acne return after I stopped treatment?', 'Acne is a long-term skin condition for many people. Stopping early, ending a plan too soon, new triggers or hormone changes can bring it back. Ask your doctor what maintenance looks like and what to do if spots return.', true),
  ('acne-isotretinoin', 'acne-treatment', null, 4, 'What is isotretinoin and what checks does it need?', 'It is a prescription tablet used for severe acne or acne that scars, under a specialist''s care. It needs blood tests, regular review and strict pregnancy rules, because it can seriously harm an unborn baby. Never take it without a prescription. See our [isotretinoin guide](/learn/isotretinoin-acne-questions).', true),
  ('acne-pregnancy', 'acne-treatment', null, 5, 'Can I use acne medicines while pregnant or planning pregnancy?', 'Some cannot be used. Tell the doctor before any treatment starts if you are pregnant, breastfeeding or may become pregnant. The doctor will choose options that fit and tell you what to avoid.', true),
  ('acne-food', 'acne-treatment', null, 6, 'Does food cause acne?', 'Research on food and acne is mixed and no single food is proven to cause it for everyone. If you notice a pattern, mention it to your doctor. Do not drop whole food groups without advice, especially a teenager.', true),
  ('acne-peel-tablets', 'acne-treatment', null, 7, 'Can I have a peel or laser while on tablets?', 'It depends on the tablet and the procedure, and some combinations are not advised. Always tell the person doing a peel or laser which tablets you take or took in recent months. Never agree to a procedure without asking.', true),
  ('acne-marks', 'acne-treatment', null, 8, 'Why do some pimples leave marks, and can they be treated?', 'Marks can be flat dark patches or small dents. Picking raises the chance of both. Many dark patches fade over months with sun protection, and dents need a different approach. Treat active acne first. See [acne scars](/learn/acne-scar-types-treatment).', true),
  ('acne-who', 'acne-treatment', null, 9, 'Dermatologist, general physician or cosmetologist: who should I see?', 'A registered dermatologist is trained in skin conditions and prescribes tablets. A general physician can start simple treatment. Cosmetology clinics vary in who treats you, so ask who examines you and check the registration.', true),
  ('acne-cost', 'acne-treatment', null, 10, 'How much does a course cost?', 'It depends on the months of treatment, visits, medicines and any procedures. Read the [cost page](/cost/acne-treatment) and ask each clinic for line-by-line quotes. Figures here are sample data until confirmed.', true),
  ('acne-delhi-where', 'acne-treatment', 'delhi', 20, 'Is acne treatment available in Delhi itself?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If care is in Gurgaon, the page will say so at the top, and the [Gurgaon page](/acne-treatment-in-gurgaon) has road times.', true),
  ('acne-delhi-pollution', 'acne-treatment', 'delhi', 21, 'Does Delhi''s winter air cause my acne?', 'No page can say that for one person. A dermatologist may discuss cleansing, dryness and sun protection in different seasons. Ask at your review, and bring the list of products you use.', true),
  ('acne-delhi-noida', 'acne-treatment', 'delhi', 22, 'I live in Noida or Ghaziabad. Can reviews be nearer home?', 'Sometimes. Ask for a written plan a local doctor could follow, and which reviews need the Delhi dermatologist. Photos on a video call may cover some reviews.', true),
  ('acne-delhi-wedding', 'acne-treatment', 'delhi', 23, 'How early should I start before a wedding?', 'At least two to three months is a common suggestion, because early weeks can bring dryness or a flare. Tell the doctor the date. Avoid starting a peel in the final weeks.', true),
  ('acne-ggn-name', 'acne-treatment', 'gurgaon', 20, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('acne-ggn-office', 'acne-treatment', 'gurgaon', 21, 'Can I keep my review visits to before or after office hours?', 'Ask the clinic. Some hold early or late slots for follow-ups. Fix the day and hour at the start, because a skipped review can stall a plan.', true),
  ('acne-ggn-ac', 'acne-treatment', 'gurgaon', 22, 'Does air conditioning in my office dry my acne skin?', 'It can add to the dryness from acne creams. Tell the doctor and ask about a moisturiser. Do not stop the cream on your own.', true),
  ('acne-ggn-monsoon', 'acne-treatment', 'gurgaon', 23, 'What if monsoon traffic makes me miss a review?', 'Call the clinic and ask for the next slot. A short delay rarely matters, but do not skip the plan. Leave extra time in July and August.', true),
  ('acne-lko-where', 'acne-treatment', 'lucknow', 20, 'Is acne care provided in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, the page will say so at the top, with the distance.', true),
  ('acne-lko-barabanki', 'acne-treatment', 'lucknow', 21, 'I live in Barabanki or Sitapur. How often must I come?', 'That is for the dermatologist to set. Early reviews are often every few weeks, and some can be by video. Ask which are in person and who can see you locally.', true),
  ('acne-lko-summer', 'acne-treatment', 'lucknow', 22, 'Does Lucknow''s summer change how I use acne creams?', 'Heat and sun can make some creams sting and darken marks. Ask the doctor whether to change the routine in May and June, and which sun protection to use.', true),
  ('acne-lko-hindi', 'acne-treatment', 'lucknow', 23, 'Can the consultation and written plan be in Hindi?', 'Yes, the first call and the consultation can be in Hindi or Hinglish. Ask for the plan in the language you read most easily and check every line before you leave.', true),
  ('acne-knp-lucknow', 'acne-treatment', 'kanpur', 20, 'Do I need to go to Lucknow for acne treatment?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If care is there, the page will say so, with the trip time.', true),
  ('acne-knp-local', 'acne-treatment', 'kanpur', 21, 'Can a Kanpur doctor follow a plan written in Lucknow?', 'Often, for simple reviews, if the plan is written down. Ask the dermatologist which changes a local doctor may make and which need a call back.', true),
  ('acne-knp-dust', 'acne-treatment', 'kanpur', 22, 'Does dust in Kanpur make acne worse?', 'This is a question for your reviewing dermatologist, and we make no claim. Ask how often to wash, which cleanser suits your skin, and whether to cover up outdoors.', true),
  ('acne-knp-fog', 'acne-treatment', 'kanpur', 23, 'Winter fog delays trains to Lucknow. How do I plan a review?', 'Book the earliest slot and allow spare time. If the road is blocked, call the clinic. Avoid a long trip straight after a peel, when skin is red and sensitive.', true),
  ('hydra-same', 'hydrafacial', null, 1, 'Is a hydrafacial the same as a regular facial?', 'No. A regular facial is usually done by hand with steam, massage and a mask. A hydrafacial uses a handheld device to cleanse, exfoliate, suction debris from pores and apply serums. Neither is a treatment for a skin condition. See [hydrafacial vs a regular facial](/learn/hydrafacial-vs-regular-facial).', true),
  ('hydra-acne', 'hydrafacial', null, 2, 'Can I have one with active acne?', 'It depends on the acne. Inflamed or painful acne can be irritated by the steps, and a doctor may advise another plan first. A hydrafacial does not treat acne. Ask a dermatologist before you book. See [hydrafacial for acne-prone skin](/learn/hydrafacial-acne-prone-skin).', true),
  ('hydra-sessions', 'hydrafacial', null, 3, 'How many sessions and how often?', 'There is no single answer. Clinics suggest different gaps, and the reviewer will give a general range after review. Try one session first and see how your skin reacts before you buy a pack. See [how often](/learn/how-often-hydrafacial).', true),
  ('hydra-feel', 'hydrafacial', null, 4, 'What does it feel like?', 'Most people feel a gentle suction, some stinging from the solutions and a cool or tingling serum. Sensation varies, and some people find it uncomfortable. Tell the person if it hurts.', true),
  ('hydra-redness', 'hydrafacial', null, 5, 'How long does redness last?', 'Pink skin commonly lasts a few hours, and sensitivity can last a day or two. Longer redness, swelling or blistering needs a call to the clinic.', true),
  ('hydra-skip', 'hydrafacial', null, 6, 'Who should skip it?', 'Anyone with sunburn, open sores, a cold sore, active infection or irritated skin from new acids, and people who had a recent peel, laser or isotretinoin course. Ask first if you are pregnant. See [who should skip it](/learn/hydrafacial-side-effects-who-should-skip).', true),
  ('hydra-pigment', 'hydrafacial', null, 7, 'Will it help tan, pigmentation or open pores?', 'A hydrafacial works on the surface, so it does not treat pigmentation conditions or change pore size in a lasting way. For melasma or marks, see a dermatologist. See [hydrafacial on Indian skin](/learn/hydrafacial-indian-skin-pigmentation).', true),
  ('hydra-cost', 'hydrafacial', null, 8, 'How much does it cost, and why do quotes differ?', 'The base session, serums, boosters, extra steps and packs all change the total. Read the [cost page](/cost/hydrafacial), and ask each place for the same lines in writing. Figures are sample data until confirmed.', true),
  ('hydra-check', 'hydrafacial', null, 9, 'How do I check the machine and the person performing it?', 'Ask who will perform the session and what their training is. Ask whether tips are single-use or how they are cleaned. A reply that is vague is a reason to ask for a doctor-led clinic.', true),
  ('hydra-event', 'hydrafacial', null, 10, 'How many days before a wedding or event should I book?', 'Book a trial session at least a few weeks before, so you see how your skin reacts. Avoid new serums, boosters or facials in the final week. The reviewer will give a general range. See [before a wedding](/learn/hydrafacial-before-wedding-timing).', true),
  ('hydra-delhi-where', 'hydrafacial', 'delhi', 20, 'Is a hydrafacial available in Delhi itself?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If sessions are in Gurgaon, the page will say so at the top, and the [Gurgaon page](/hydrafacial-in-gurgaon) has road times.', true),
  ('hydra-delhi-compare', 'hydrafacial', 'delhi', 21, 'How do I compare Delhi quotes?', 'Ask for the base session, serums, boosters and pack in writing from each place. Compare the total for the same steps. Treat a very low base price with caution until you see what it leaves out.', true),
  ('hydra-delhi-winter', 'hydrafacial', 'delhi', 22, 'Does Delhi''s winter air change how I should plan a session?', 'Winter air is dry, and exfoliated skin can feel tighter. Ask what moisturiser fits, and avoid strong sun and heat on the first day. We make no claim about pollution and sessions.', true),
  ('hydra-delhi-wedding', 'hydrafacial', 'delhi', 23, 'I have a wedding in Delhi in two months. When should I book?', 'Book a trial session a few weeks before, and avoid new products in the final week. Skin can react, and you will want time for it to settle.', true),
  ('hydra-ggn-name', 'hydrafacial', 'gurgaon', 20, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('hydra-ggn-lunch', 'hydrafacial', 'gurgaon', 21, 'Can I have a session in my lunch hour?', 'The session takes under an hour, but pink skin can last a few hours. If you have a meeting, book the last slot of the day instead.', true),
  ('hydra-ggn-mall', 'hydrafacial', 'gurgaon', 22, 'Is a mall salon the same as a skin clinic?', 'Not always. A clinic can check your skin for infection or sunburn before starting. A salon may follow a fixed menu. Ask who performs the session and what training they have.', true),
  ('hydra-ggn-ac', 'hydrafacial', 'gurgaon', 23, 'Does office air conditioning dry my skin after a session?', 'It can add to dryness. Ask the person performing the session which moisturiser and sun protection suit you, and use them as advised.', true),
  ('hydra-lko-where', 'hydrafacial', 'lucknow', 20, 'Is a hydrafacial provided in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, the page will say so at the top, with the distance.', true),
  ('hydra-lko-summer', 'hydrafacial', 'lucknow', 21, 'Can I have a session in a Lucknow summer?', 'It is possible, but heat, sweat and strong sun can sting exfoliated skin. Book an early slot, avoid the afternoon sun and use the protection the clinic advises.', true),
  ('hydra-lko-trip', 'hydrafacial', 'lucknow', 22, 'I live in Unnao. Is one session worth the trip?', 'That depends on your plans. Combine the visit with other errands, book the earliest slot, and avoid prepaying a pack that commits you to more trips.', true),
  ('hydra-lko-hindi', 'hydrafacial', 'lucknow', 23, 'Can the quote be explained in Hindi?', 'Yes, ask the clinic to explain each line in Hindi or Hinglish. Ask for the written quote in the language you read most easily.', true),
  ('hydra-knp-lucknow', 'hydrafacial', 'kanpur', 20, 'Do I need to go to Lucknow for a hydrafacial?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. For a single session, a trip usually costs more in time than it saves in price.', true),
  ('hydra-knp-quote', 'hydrafacial', 'kanpur', 21, 'How do I get a price when none is published?', 'Message or call and ask for the base session, each serum, each booster and any pack in writing. Ask at two or three places and compare.', true),
  ('hydra-knp-dust', 'hydrafacial', 'kanpur', 22, 'Does dust in Kanpur matter after a session?', 'We make no claim. Ask the person who performs it how to clean your face and what to wear outdoors for the first day.', true),
  ('hydra-knp-winter', 'hydrafacial', 'kanpur', 23, 'How does a Kanpur winter affect my skin after a session?', 'Winters are cold and dry, so exfoliated skin can feel tight. Use a moisturiser as advised and avoid hot water on your face for the first day.', true),
  ('toxin-same', 'botulinum-toxin-injections', null, 1, 'Is botulinum toxin the same as Botox?', 'Botox is a common name that many people use for botulinum toxin injections. Botulinum toxin is the medicine, and different products exist. This page uses the name of the medicine. A doctor decides which one is prescribed.', true),
  ('toxin-lasts', 'botulinum-toxin-injections', null, 2, 'How long does it last?', 'The effect is temporary and fades over months. The reviewer will give a general range after review. How long it lasts varies between people and between areas, so ask your doctor what to expect for you. See [how long wrinkle injections last](/learn/how-long-wrinkle-injections-last).', true),
  ('toxin-hurt', 'botulinum-toxin-injections', null, 3, 'Does it hurt?', 'Most people describe pinprick discomfort at each injection. It varies by person and by area. Tell the doctor if it is hard to bear, and ask what can be done for comfort.', true),
  ('toxin-side', 'botulinum-toxin-injections', null, 4, 'What are the common side effects?', 'Small bumps, redness, bruising and headache are the most common, and they are usually short-lived. An uneven result or a drooping eyelid or brow can happen. Rarely, the effect spreads and needs urgent care. See [side effects and what to do](/learn/botulinum-toxin-side-effects).', true),
  ('toxin-men', 'botulinum-toxin-injections', null, 5, 'Can men have it?', 'Yes, a doctor can plan it for men. Muscle strength and brow shape differ, so the plan differs. See [wrinkle injections for men](/learn/wrinkle-injections-for-men).', true),
  ('toxin-age', 'botulinum-toxin-injections', null, 6, 'At what age do doctors consider it?', 'There is no set age. A doctor decides after looking at your face and asking what bothers you. Starting early to prevent lines is not something this page advises. See [what age doctors consider](/learn/age-for-wrinkle-injections).', true),
  ('toxin-frozen', 'botulinum-toxin-injections', null, 7, 'Will my face look frozen?', 'That depends on the plan. Ask for a conservative plan if you want to keep movement. A doctor can treat fewer areas or use a smaller amount, and adjust at the review.', true),
  ('toxin-after', 'botulinum-toxin-injections', null, 8, 'What should I avoid after the injection?', 'Follow your doctor''s advice for the first hours and the first day. This often includes not rubbing the area, avoiding heat and hard exercise, and staying upright for a time. See [what to do after wrinkle injections](/learn/aftercare-after-wrinkle-injections).', true),
  ('toxin-insurance', 'botulinum-toxin-injections', null, 9, 'Is it covered by insurance?', 'Usually not, because use for wrinkles is cosmetic. Check your policy and ask your insurer in writing. We do not promise cashless approval.', true),
  ('toxin-genuine', 'botulinum-toxin-injections', null, 10, 'How do I check the product is genuine?', 'Ask to see the sealed pack and the batch label before it is prepared, and confirm that the doctor who injects is registered. A clinic that is happy to show you is a good sign. See [checking the product](/learn/check-wrinkle-injection-product).', true),
  ('toxin-delhi-where', 'botulinum-toxin-injections', 'delhi', 20, 'Which part of Delhi is the facility in?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If injections are in Gurgaon, the page will say so at the top, and the [Gurgaon page](/botulinum-toxin-injections-in-gurgaon) has road times.', true),
  ('toxin-delhi-slot', 'botulinum-toxin-injections', 'delhi', 21, 'What time of day suits a visit in Delhi?', 'A mid-morning weekday slot avoids both rush hours and leaves a quiet afternoon for the first-day advice. Avoid booking before a long drive or a hard workout.', true),
  ('toxin-delhi-review', 'botulinum-toxin-injections', 'delhi', 22, 'Can the review visit be a video call from Noida or Ghaziabad?', 'Often, for a simple check. Ask which problems need you in person, and where to go for urgent care near home.', true),
  ('toxin-delhi-winter', 'botulinum-toxin-injections', 'delhi', 23, 'Does Delhi''s winter air change the aftercare?', 'We make no claim. The reviewer will confirm the wording. The usual advice for the first day, such as avoiding heat and rubbing the area, applies in every season.', true),
  ('toxin-ggn-reach', 'botulinum-toxin-injections', 'gurgaon', 20, 'How do I reach the clinic from Golf Course Road or Cyber City?', 'That is to be confirmed once a facility is named. The Rapid Metro and Yellow Line serve the area, and a short cab from the station is easy. Ask for a slot outside the evening rush.', true),
  ('toxin-ggn-office', 'botulinum-toxin-injections', 'gurgaon', 21, 'Can I go back to the office after the visit?', 'Many people can, but small bumps or redness can show for a few hours and bruising for a few days. Ask the doctor about activity limits, and consider a late slot so you can go home.', true),
  ('toxin-ggn-name', 'botulinum-toxin-injections', 'gurgaon', 22, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('toxin-ggn-summer', 'botulinum-toxin-injections', 'gurgaon', 23, 'How do I manage heat in the first day in a Gurgaon summer?', 'Avoid heat and hard exercise if your doctor says so. Plan the visit for a cooler hour, travel in an air-conditioned vehicle and spend the rest of the day indoors.', true),
  ('toxin-lko-sameday', 'botulinum-toxin-injections', 'lucknow', 20, 'Can I return to Barabanki or Sitapur the same day?', 'Many people from nearby towns can, if the doctor agrees and the ride is comfortable. From farther towns, plan the whole day. Ask for an early slot.', true),
  ('toxin-lko-where', 'botulinum-toxin-injections', 'lucknow', 21, 'Is the injection provided in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, the page will say so at the top, with the distance.', true),
  ('toxin-lko-heat', 'botulinum-toxin-injections', 'lucknow', 22, 'How do I manage a hot Lucknow day after the visit?', 'Follow the doctor''s advice on heat for the first day. Choose a cooler hour, use an air-conditioned vehicle and stay indoors for the rest of the day if you can.', true),
  ('toxin-lko-agent', 'botulinum-toxin-injections', 'lucknow', 23, 'A person phoned me with a price before I saw a doctor. Is that normal?', 'No. A registered doctor should assess you first, and then a plan and a total are given. Be careful of prices by phone, and of bundles asked in advance.', true),
  ('toxin-knp-lucknow', 'botulinum-toxin-injections', 'kanpur', 20, 'Do I need to go to Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If the visit is there, the page will say so, with the trip time.', true),
  ('toxin-knp-video', 'botulinum-toxin-injections', 'kanpur', 21, 'Can the review be by video from Kanpur?', 'Often, for a simple check, with photos in daylight. Ask which problems need you in person, and where to go for urgent care near home.', true),
  ('toxin-knp-urgent', 'botulinum-toxin-injections', 'kanpur', 22, 'Where do I go for a problem if I live far from the clinic?', 'Ask the doctor on the day, and write the answer on your phone. For trouble breathing, swallowing or speaking, go to the nearest emergency department and say that you had botulinum toxin.', true),
  ('toxin-knp-fog', 'botulinum-toxin-injections', 'kanpur', 23, 'Winter fog makes travel slow. How do I plan the visit and the review?', 'Book the earliest slot, allow spare time, and ask whether the review can be moved by a day. Avoid scheduling the injections on a day when you must travel far afterwards.', true),
  ('aging-what', 'anti-aging-treatment', null, 1, 'What is anti-aging treatment?', 'It is a group of non-surgical options, such as injections, peels, lasers and tightening devices, that aim to soften lines or improve skin texture, tone or firmness. A dermatologist plans them after looking at your skin. They do not stop ageing.', true),
  ('aging-which', 'anti-aging-treatment', null, 2, 'Which method suits which concern?', 'Injections of botulinum toxin act on movement lines, fillers on folds and lost volume, and peels and lasers on texture and tone. Which suits you is a doctor''s decision after an assessment. Start with the one concern that bothers you most.', true),
  ('aging-stop', 'anti-aging-treatment', null, 3, 'Do these treatments stop ageing?', 'No. They change some features for a time. Skin continues to age, and most effects fade, so repeat visits are common. Sun protection and not smoking matter more than any procedure.', true),
  ('aging-sessions', 'anti-aging-treatment', null, 4, 'How many sessions are needed?', 'It depends on the method. Injections are short visits repeated as the effect fades. Peels, lasers and devices come in courses of several sessions. The doctor sets the number, and the reviewer will give a general range after review.', true),
  ('aging-last', 'anti-aging-treatment', null, 5, 'How long do results last?', 'It varies by method and by person. Most effects fade over months, and some people see little change. Ask the doctor what to expect for your skin, and what maintenance would involve.', true),
  ('aging-combine', 'anti-aging-treatment', null, 6, 'Can I combine methods in one visit?', 'Sometimes. A doctor may combine them, and a plan that starts with one method lets you see what each does. Be careful of a package that adds many treatments on the first day.', true),
  ('aging-downtime', 'anti-aging-treatment', null, 7, 'What is the downtime?', 'From none to several days of redness, flaking or bruising, depending on the method. Ask for the downtime of each method in writing. See [downtime by method](#downtime-by-method).', true),
  ('aging-dark', 'anti-aging-treatment', null, 8, 'Which are less suitable for darker skin?', 'Some peels and lasers carry a higher chance of dark marks in skin with more natural pigment. The reviewer will confirm which need extra care. A doctor may test a small area and start gently.', true),
  ('aging-insurance', 'anti-aging-treatment', null, 9, 'Does insurance cover it?', 'Usually not, because the treatments are cosmetic. Check your policy and ask your insurer in writing.', true),
  ('aging-cost', 'anti-aging-treatment', null, 10, 'How much does it cost, and why do quotes differ?', 'Each method has its own price per session, and plans differ in sessions, repeats and who treats you. Read the [cost page](/cost/anti-aging-treatment), and ask each clinic for line-by-line quotes. Figures are sample data until confirmed.', true),
  ('aging-delhi-where', 'anti-aging-treatment', 'delhi', 20, 'Is anti-aging treatment available in Delhi itself?', 'That is to be confirmed. No partner facility is confirmed in Delhi yet. If care is in Gurgaon, the page will say so at the top, and the [Gurgaon page](/anti-aging-treatment-in-gurgaon) has road times.', true),
  ('aging-delhi-pigment', 'anti-aging-treatment', 'delhi', 21, 'Do Delhi''s air and sun make pigmentation a bigger issue for treatments?', 'We make no claim. Ask the dermatologist about your own skin, about sun protection and about which options carry a risk of dark marks for you.', true),
  ('aging-delhi-season', 'anti-aging-treatment', 'delhi', 22, 'Which season suits a peel or laser in Delhi?', 'Many doctors prefer to plan them away from the strongest sun. The reviewer will confirm the wording for Delhi. Ask what suits your skin and the month you want to start.', true),
  ('aging-delhi-wedding', 'anti-aging-treatment', 'delhi', 23, 'How early should I start before a wedding?', 'Several weeks at least, so that downtime and any adjustment are done in time. Avoid new treatments in the final week. Tell the doctor the date.', true),
  ('aging-ggn-name', 'anti-aging-treatment', 'gurgaon', 20, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('aging-ggn-work', 'anti-aging-treatment', 'gurgaon', 21, 'How do I fit a course of sessions around work?', 'Ask how long each session takes and how much redness to expect. Book at the end of the week and keep the next session on your calendar. Tell the doctor if the schedule is too tight.', true),
  ('aging-ggn-water', 'anti-aging-treatment', 'gurgaon', 22, 'Does hard water in Gurgaon affect my results?', 'We make no claim, and no source is yet attached. If your skin feels tight after washing, tell the doctor, who may suggest a gentler cleanser.', true),
  ('aging-ggn-summer', 'anti-aging-treatment', 'gurgaon', 23, 'How should I handle the sun and heat from April to September?', 'Treated skin is more sensitive to sun. Use the sun protection the doctor names, cover up outdoors and ask whether to plan peels and lasers for cooler months.', true),
  ('aging-lko-where', 'anti-aging-treatment', 'lucknow', 20, 'Is anti-aging treatment provided in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, the page will say so at the top, with the distance.', true),
  ('aging-lko-trips', 'anti-aging-treatment', 'lucknow', 21, 'I live in Sitapur. How many trips will a course need?', 'That depends on the plan. Ask the doctor to count the sessions and reviews, and ask which reviews can be by video. Count each one as a day trip before you pay.', true),
  ('aging-lko-summer', 'anti-aging-treatment', 'lucknow', 22, 'Is May or June a bad time for a peel or laser in Lucknow?', 'Strong sun and heat make treated skin more sensitive, so many doctors prefer cooler months. The reviewer will confirm the wording. Ask what suits your skin.', true),
  ('aging-lko-wedding', 'anti-aging-treatment', 'lucknow', 23, 'I want to start before a family wedding. When should I book?', 'Several weeks ahead, since a course takes time and downtime has to settle. Avoid new treatments in the last week. Tell the doctor the date at the first visit.', true),
  ('aging-knp-lucknow', 'anti-aging-treatment', 'kanpur', 20, 'Do I need to go to Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If care is there, the page will say so, with the trip time.', true),
  ('aging-knp-visits', 'anti-aging-treatment', 'kanpur', 21, 'How do I plan three to six visits from Kanpur?', 'Write each visit on a calendar with the date, place and purpose, and add the travel. Ask which visits can be local or by video, and tell the doctor if the total is more than you can manage.', true),
  ('aging-knp-dust', 'anti-aging-treatment', 'kanpur', 22, 'Does dust and industrial air in Kanpur affect treated skin?', 'We make no claim here. Ask the dermatologist how to protect and clean treated skin, and what to wear outdoors after a peel or laser.', true),
  ('aging-knp-train', 'anti-aging-treatment', 'kanpur', 23, 'How do I plan the train or road trip to Lucknow in winter fog?', 'Book the earliest slot, allow spare time, and avoid a long ride straight after a peel or laser. Ask the clinic what to do if you cannot reach it on the day.', true),
  ('prp-what', 'prp-treatment', null, 1, 'What is PRP?', 'PRP means platelet-rich plasma. A small sample of your own blood is spun to concentrate platelets, and the platelet-rich part is injected into the scalp or skin. It is used as an add-on for hair thinning and for skin texture. A doctor decides whether it suits you.', true),
  ('prp-sessions', 'prp-treatment', null, 2, 'How many sessions are usually planned?', 'Usually several, spaced a few weeks apart. The doctor sets the number, and the reviewer will give a general range after review. Ask for the course total and not only the price of one session.', true),
  ('prp-hair', 'prp-treatment', null, 3, 'Can PRP help with hair thinning?', 'Evidence is mixed. Some people notice a change and some notice none, and no one can promise a result. A doctor should check for medical causes first and tell you plainly what to expect. See [what the evidence says](/learn/prp-for-hair-loss-evidence).', true),
  ('prp-hurt', 'prp-treatment', null, 4, 'Does it hurt?', 'Most people feel pinpricks and tenderness, and numbing cream may be used. The scalp can feel sore for a day or two. Tell the doctor if it is hard to bear.', true),
  ('prp-time', 'prp-treatment', null, 5, 'How long before any change?', 'If there is a change, it is usually gradual and judged after some months. A doctor reviews it and decides whether to continue. Ask in advance what counts as a change.', true),
  ('prp-side', 'prp-treatment', null, 6, 'What are the side effects?', 'Pain, bruising, swelling, a headache and scalp tenderness are the most common. Rarely, infection or an allergic reaction to numbing cream can occur. Some people see no visible benefit.', true),
  ('prp-who', 'prp-treatment', null, 7, 'Who should not have PRP?', 'People with an active infection, a blood disorder, low platelets or blood thinners, pregnancy, cancer treatment or uncontrolled diabetes need a doctor''s view first. So does anyone whose hair loss has a medical cause not yet checked.', true),
  ('prp-vs', 'prp-treatment', null, 8, 'How does PRP compare with minoxidil or finasteride?', 'They are different. Minoxidil and finasteride are medicines a doctor prescribes and a person uses for months or longer. PRP is a procedure given in sessions. Some people use both, and a doctor decides what suits you.', true),
  ('prp-cost', 'prp-treatment', null, 9, 'How much does it cost, and why do quotes differ?', 'Kits, methods, sessions, add-ons and clinic type all change the total. Read the [cost page](/cost/prp-treatment), and ask each clinic for the course total in writing. Figures are sample data until confirmed.', true),
  ('prp-face', 'prp-treatment', null, 10, 'Is PRP for the face the same as for hair?', 'The idea is the same, and the injection site and aim differ. Evidence for skin is limited and results vary. See [PRP for the face](/learn/prp-face-evidence).', true),
  ('prp-delhi-workday', 'prp-treatment', 'delhi', 20, 'Can I do sessions on a work day near a metro line?', 'Many people do. A session is short, and you go home after. Ask which slots are free, and keep the same weekday and time for each session.', true),
  ('prp-delhi-winter', 'prp-treatment', 'delhi', 21, 'Does winter pollution change skin PRP timing?', 'We make no claim. Ask the dermatologist what is known and how to protect treated skin. The reviewer will confirm the wording for Delhi.', true),
  ('prp-delhi-gap', 'prp-treatment', 'delhi', 22, 'How far apart are visits?', 'The doctor sets the gap, and in many plans it is a few weeks. The reviewer will give a general range. Ask for every date at the first visit.', true),
  ('prp-delhi-job', 'prp-treatment', 'delhi', 23, 'Can I fit a course around a full-time job?', 'Often, with a fixed slot and a calendar. Count every session and review as a trip, and tell the doctor if the total is more than you can keep.', true),
  ('prp-ggn-name', 'prp-treatment', 'gurgaon', 20, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('prp-ggn-evening', 'prp-treatment', 'gurgaon', 21, 'Are evening slots available after office?', 'That depends on the clinic. Ask which days and until what time, and whether an evening slot can be fixed for the whole course.', true),
  ('prp-ggn-metro', 'prp-treatment', 'gurgaon', 22, 'Which Rapid Metro route reaches the clinic?', 'That is to be confirmed once a facility is named. Sikandarpur is on the Rapid Metro and HUDA City Centre is on the Yellow Line. Ask the clinic how far it is from either.', true),
  ('prp-ggn-delhi', 'prp-treatment', 'gurgaon', 23, 'Can I come from Delhi each time?', 'Many people do. Count the trips for the whole course, and compare a Delhi plan with a Gurgaon one on the total and the number of trips.', true),
  ('prp-lko-travel', 'prp-treatment', 'lucknow', 20, 'Do I need to travel from a small town for each session?', 'A session needs you at the clinic, and some reviews may be by video. Ask which visits need you in person, and count only those as trips.', true),
  ('prp-lko-holiday', 'prp-treatment', 'lucknow', 21, 'Can sessions be six weeks apart around holidays?', 'Often, if the doctor agrees. Fix the dates for the whole course at the first visit, and keep a spare date in case of a delay.', true),
  ('prp-lko-hindi', 'prp-treatment', 'lucknow', 22, 'Is there a Hindi-speaking coordinator?', 'Ask the clinic. The first call and the consultation can be in Hindi or Hinglish. Ask for the plan and the aftercare written in the language you read most easily.', true),
  ('prp-lko-where', 'prp-treatment', 'lucknow', 23, 'Is PRP provided in Lucknow?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. If it is elsewhere, the page will say so at the top, with the distance.', true),
  ('prp-knp-lucknow', 'prp-treatment', 'kanpur', 20, 'Do I travel to Lucknow for PRP?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If care is there, the page will say so, with the trip time.', true),
  ('prp-knp-rail', 'prp-treatment', 'kanpur', 21, 'Which train timings suit a four to six week visit?', 'That is to be checked against a current timetable and added with a date. Plan a regular trip, keep a spare date for winter fog, and check the return as well.', true),
  ('prp-knp-local', 'prp-treatment', 'kanpur', 22, 'Can reviews be done locally?', 'Often, for a simple check, if the plan is written down for a Kanpur doctor. Ask which changes a local doctor may make and what the planning doctor needs to see.', true),
  ('prp-knp-dust', 'prp-treatment', 'kanpur', 23, 'Does Kanpur''s dust matter after a scalp session?', 'We make no claim. Ask the doctor when you can wash your hair, what to use and what to wear outdoors for the first day.', true),
  ('ht-methods', 'hair-transplant', null, 1, 'FUE, FUT or DHI: which is right?', 'It depends on your scalp, your hair length and your aim. FUE takes follicles one by one, FUT takes a thin strip, and DHI is a name some clinics use for a pen-like placement method. A doctor decides after an exam. See [the methods compared](/learn/hair-transplant-fue-fut-dhi).', true),
  ('ht-candidate', 'hair-transplant', null, 2, 'Am I a candidate at Norwood 3, 5 or 7?', 'A doctor decides, after examining the scalp. Donor supply matters as much as the pattern. At higher grades the donor may not cover the area, and other options may fit. See [candidacy by grade](/learn/hair-transplant-norwood-grade-candidate).', true),
  ('ht-grafts', 'hair-transplant', null, 3, 'How many grafts will I need?', 'The doctor estimates it from the area, the pattern and the donor supply, and it can change after the exam. Ask how grafts are counted. See [how grafts are counted](/learn/hair-transplant-grafts-needed).', true),
  ('ht-bill', 'hair-transplant', null, 4, 'What does the bill cover and what is extra?', 'The rate usually covers the procedure and the team. Medicines, add-ons, extra reviews, tests and GST may be extra. Read the [cost page](/cost/hair-transplant) and ask for a written list.', true),
  ('ht-growth', 'hair-transplant', null, 5, 'When does hair start to grow?', 'New hairs often begin around the third or fourth month, thin at first, and build over many months. The reviewer will confirm the usual months. No one can promise a result.', true),
  ('ht-shock', 'hair-transplant', null, 6, 'What is shock loss?', 'Shedding of transplanted and sometimes nearby hairs in the weeks after the procedure. It is common but not in everyone. Call the doctor if you are worried. See [shock loss](/learn/hair-transplant-shock-loss).', true),
  ('ht-last', 'hair-transplant', null, 7, 'How long do transplanted hairs last?', 'Transplanted follicles are meant to keep growing where they are placed. Hairs around them can still thin with time. A doctor can tell you what to expect for your pattern.', true),
  ('ht-women', 'hair-transplant', null, 8, 'Can women have a hair transplant?', 'Some can. Female hair loss is often spread over the scalp and needs a medical check first. A doctor decides. See [hair transplant for women](/learn/hair-transplant-for-women).', true),
  ('ht-risks', 'hair-transplant', null, 9, 'What are the risks?', 'Swelling, bruising, scabbing, numbness, shedding, folliculitis, infection, thin growth in some grafts, scarring in the donor area and a hairline that does not suit you. Ask about each in the consultation.', true),
  ('ht-meds', 'hair-transplant', null, 10, 'Will I still need medicines?', 'Many people do, because hair outside the transplant can keep thinning. A doctor may advise minoxidil, or for some men finasteride. They are prescription medicines, so ask the doctor.', true),
  ('ht-delhi-home', 'hair-transplant', 'delhi', 20, 'How do I travel home after the Day 1 wash?', 'Arrange a cab or a driver, and bring someone with you. Avoid a crowded metro car, and do not ride a two-wheeler. Ask the clinic when you can travel on your own.', true),
  ('ht-delhi-stay', 'hair-transplant', 'delhi', 21, 'Do I need to stay in Delhi?', 'Many people go home the same night, and some stay one night near the facility. If you live more than an hour away, ask whether a stay is available and what it costs.', true),
  ('ht-delhi-smog', 'hair-transplant', 'delhi', 22, 'What does the doctor say about smog and a fresh transplant?', 'We make no claim about what smog does to grafts. Ask the doctor whether to stay indoors and cover the head, and how the season changes the plan.', true),
  ('ht-delhi-attendant', 'hair-transplant', 'delhi', 23, 'What are the parking and attendant rules?', 'They differ between facilities. Ask whether an attendant can stay, where the driver can wait and what the visiting hours are on the day.', true),
  ('ht-ggn-night', 'hair-transplant', 'gurgaon', 20, 'Is it a same-day or one-night stay from Delhi?', 'From South Delhi a same-day return is possible. From Noida or Faridabad a night near the facility may be easier. Ask what a stay includes and what it costs.', true),
  ('ht-ggn-helmet', 'hair-transplant', 'gurgaon', 21, 'Can I wear a helmet or a cap on a two-wheeler commute?', 'A helmet presses on grafts, so ask the doctor when it is allowed. Arrange a cab for the ride home and the early weeks, and ask when a soft cap is fine.', true),
  ('ht-ggn-followup', 'hair-transplant', 'gurgaon', 22, 'Gurgaon or Delhi for the follow-up?', 'If you live in Delhi, ask whether the first wash and day 10 review can be done near home. A written plan and daylight photos help a doctor elsewhere.', true),
  ('ht-ggn-name', 'hair-transplant', 'gurgaon', 23, 'Gurgaon or Gurugram: is it the same place?', 'Yes. Both spellings are used for the same city in Haryana. This page uses Gurgaon because more people search for it.', true),
  ('ht-lko-small', 'hair-transplant', 'lucknow', 20, 'I live in a small town. Can I come for a day-care procedure?', 'Yes, many people do, and most plan one or two nights. A transplant is a long day, and the road home after dark is tiring. Ask the clinic for the full timeline.', true),
  ('ht-lko-night', 'hair-transplant', 'lucknow', 21, 'Is there a stay near the facility?', 'That is to be confirmed. No partner facility is confirmed in Lucknow yet. Ask what a stay costs and what it includes, and look for one close to the facility.', true),
  ('ht-lko-wash', 'hair-transplant', 'lucknow', 22, 'Where do I get my first wash done?', 'It is usually the next day. Ask the clinic who does it, and whether a local doctor can do it from a written plan if you return home.', true),
  ('ht-lko-summer', 'hair-transplant', 'lucknow', 23, 'What are the summer sweat rules?', 'Sweat and sun are usually limited for a period after a transplant. Ask the doctor what to do in May or June and how long to avoid heavy sweating.', true),
  ('ht-knp-where', 'hair-transplant', 'kanpur', 20, 'Which Kanpur or Lucknow facility does the procedure?', 'That is to be confirmed. No partner facility is confirmed in Kanpur yet, and Lucknow is the nearest other city we cover. If care is there, the page will say so, with the trip time.', true),
  ('ht-knp-followup', 'hair-transplant', 'kanpur', 21, 'What is the follow-up after I return to Kanpur?', 'The first wash is the next day and a review comes around day 10. Ask whether a Kanpur doctor can do a simple check from a written plan, and what the planning doctor needs.', true),
  ('ht-knp-helmet', 'hair-transplant', 'kanpur', 22, 'Can I wear a helmet after a transplant?', 'A helmet presses on grafts, so ask when it is allowed. Arrange a car or a cab for the ride home and the early reviews.', true),
  ('ht-knp-dust', 'hair-transplant', 'kanpur', 23, 'Does Kanpur''s dust matter for a healing scalp?', 'We make no claim. Ask the doctor how to wash, what to wear outdoors and how long to avoid dust and sweat.', true)
insert into public.blog_posts (slug, title, excerpt, minutes, thumb, treatment_slug, body, reviewer_id, published, date_published, date_modified, cover, next_cities) values
  ('questions-to-ask-your-plastic-surgeon', 'Questions to ask your plastic surgeon before you book', 'A checklist you can screenshot: registration, anaesthesia, what the quote includes.', 3, 2, null, '["This guide is being written and has not been reviewed by a surgeon yet. It is not published to search engines.","A checklist you can screenshot: registration, anaesthesia, what the quote includes."]'::jsonb, null, false, '2026-11-09', '2026-11-09', null, null),
  ('how-to-compare-surgery-quotes', 'How to compare two surgery quotes line by line', 'Why two quotes can look different and what to check in each line.', 4, 1, null, '["This guide is being written and has not been reviewed by a surgeon yet. It is not published to search engines.","Why two quotes can look different and what to check in each line."]'::jsonb, null, false, '2026-11-09', '2026-11-09', null, null),
  ('gynecomastia-grades', 'Gynecomastia grades 1 to 4: what each stage looks like', 'How doctors describe the size and spread of male chest tissue, what each grade usually needs, and when a check-up makes sense.', 5, 1, 'gynecomastia-surgery', '["[[reviewer]]","Gynecomastia is graded from 1 to 4. Grade 1 is a small button of tissue under the nipple. Grade 4 is a large chest with extra skin. The grade helps a doctor choose between watching, liposuction, gland removal or a mix, but the examination matters more than the number. This guide sits under our [[link: /gynecomastia-surgery | gynecomastia surgery overview]].","## What the four grades mean","Several grading systems exist and surgeons do not all use the same one. The version below is the simple one patients meet most often.","- Grade 1: a small, slightly puffy area right behind the nipple. The chest outline is otherwise flat.","- Grade 2: the enlargement spreads beyond the nipple area and the chest looks fuller. The skin still fits snugly.","- Grade 3: a clear breast shape with extra skin hanging below the chest crease.","- Grade 4: a large, rounded chest with obvious loose skin.","Notice that the grades describe shape and skin, not what the tissue is made of. Two men with the same grade can have different mixes of fat and gland, which is why [[link: /learn/gynecomastia-fat-or-gland | the fat-or-gland check]] comes first.","## How doctors decide the grade","The doctor looks at you standing and lying down, feels the tissue between finger and thumb, and checks both sides. They may ask when the change began, which medicines you take, and whether there is pain or discharge. Photographs for your own file are common. A scan or blood test is added only when the story or the exam suggests it.","## What each grade usually needs","This is a general pattern, not a rule for your chest.","- Grade 1 often needs only a review. If it began recently, a doctor may suggest waiting and treating any cause first.","- Grade 2 is where surgery is often discussed. Liposuction, gland removal or both are the usual choices. [[link: /learn/gynecomastia-liposuction-vs-gland-removal | This page explains how the plan is chosen]].","- Grades 3 and 4 often involve loose skin. The surgeon may remove some skin, tighten it, or plan a second stage. Be ready for a longer scar line and a longer recovery than a simple liposuction case.","## Does the grade change the price?","Usually yes, because a higher grade can mean more theatre time, a longer anaesthesia, and skin work. The grade is one of several factors; hospital type and anaesthesia matter too. Our [[link: /cost/gynecomastia-surgery | cost page]] lists what moves a quote and what to ask to have written down.","> A grade is a starting description. It is not a promise about what surgery will be needed or how the chest will look afterwards.","## Who should wait","If the enlargement started in the last few months, a doctor may want to look for a cause first. Teenagers are often asked to wait, because puberty changes can settle by themselves; see [[link: /learn/gynecomastia-in-teenagers | gynecomastia in teenagers]]. Anyone planning surgery should have a steady weight, because losing or gaining weight afterwards changes the chest.","## When to see a doctor","Book an appointment, without waiting for a grade to worsen, if you notice any of these:","- a hard lump on one side only, or a lump that feels fixed rather than rubbery","- nipple discharge, especially bloody discharge","- skin changes, dimpling or redness over the chest","- pain that is getting worse","- fast growth over weeks","These signs need a proper check. They are uncommon, but a doctor should rule them out, whatever the grade looks like.","## Questions worth asking","- Which grading system are you using, and what grade do you think I am?","- How much of what you feel is gland and how much is fat?","- Will I need skin removal, and what scar would that leave?","- What is included in the quote if the plan changes on the day?","[[faq: What are the 4 grades of gynecomastia? | Grade 1 is a small button of tissue under the nipple, grade 2 is wider enlargement with a snug skin fit, grade 3 adds extra skin below the chest crease, and grade 4 is a large chest with obvious loose skin. Systems differ between surgeons.]]","[[faq: Which grade needs surgery? | There is no grade that always needs surgery. Surgery is usually discussed from grade 2 upward when the tissue has stopped changing, a cause has been checked, and the person is bothered by it. The doctor decides after an examination.]]","Sending a short message on WhatsApp is a gentle way to ask what a written estimate would cover for your situation, or you can run a quote through the quote checker. Nothing needs deciding today.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia. Grading systems differ between papers; reviewer to confirm the version used here.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-fat-or-gland', 'Fat or gland? What a doctor checks before surgery', 'Chest fat and breast gland look alike from outside but are treated differently. Here is how a doctor tells them apart.', 5, 2, 'gynecomastia-surgery', '["[[reviewer]]","A fuller male chest can be fat, gland tissue, or both. Gland tissue feels firm and rubbery, sits behind the nipple, and does not shrink with diet. Fat is soft and spread over the chest. A doctor tells them apart by examination, sometimes with a scan. The answer decides whether the plan is liposuction, gland removal or both.","See also the [[link: /gynecomastia-surgery | gynecomastia surgery guide]].","## Gland and fat side by side","- Feel: gland is firm or rubbery, like a small disc. Fat is soft and moves easily.","- Place: gland sits right behind the nipple. Fat spreads wider, often towards the armpit and sides.","- Tenderness: gland can ache or feel sore to touch, particularly while it is growing. Fat usually does not hurt.","- Diet and weight: gland changes little with weight loss. Fat usually shrinks when overall weight comes down.","Most men have a mix, so do not be surprised if a doctor says \"a bit of both\".","## The pinch test, and why it is not enough","Doctors often lie the patient flat and pinch the tissue around the nipple. A firm, button-like disc suggests gland. You can try something similar at home, but a home check can mislead you, especially if you are heavy, if the tissue is tender, or if only one side is affected. Treat it as a reason to book an exam, not as a diagnosis.","## What the exam adds","A doctor will usually do more than feel the chest:","- Ask when it started and whether it came on suddenly or slowly.","- Review your medicines, supplements, alcohol and any drug use.","- Examine both sides, the armpits, and often the testicles, because some hormone problems show up there.","- Look at the skin and the nipple for changes.","## When a scan or blood tests are used","An ultrasound shows whether there is true gland tissue and how much. Blood tests look at hormones and at liver, kidney or thyroid function. Neither is needed for every patient. They are more likely if the swelling is new, one-sided, painful or very hard, or if the story points to a hormone cause. If a doctor orders a test, ask what question it answers.","## When it is not only fat or gland","Rarely, a firm lump is something else and needs its own work-up. Do not wait for it to become obvious. See a doctor soon if you have:","- a hard, fixed lump on one side","- bloody nipple discharge","- skin dimpling or a change in nipple shape","- swelling that is rapid or painful","> Most chest enlargement in men is not cancer. A doctor still checks, because the rare cases are better found early.","## Why the answer changes the plan","Fat can be removed by liposuction through tiny cuts. Gland tissue does not respond to suction as well, so it is usually cut out through a small opening at the edge of the areola or the side of the chest. When both are present, surgeons often combine the two. [[link: /learn/gynecomastia-liposuction-vs-gland-removal | Here is how that choice is made]]. If the chest is soft with little gland, the label may be [[link: /learn/pseudogynecomastia | pseudogynecomastia]], which is handled differently.","## Who should wait","If the enlargement is recent, a doctor may prefer to look for a cause before any surgery. If your weight is still moving, the chest may change as it settles, so a plan made now may need changing later. Teenagers can read [[link: /learn/gynecomastia-in-teenagers | this guide for young patients]].","## What to ask at the consultation","- Do you think this is mostly fat, mostly gland, or a mix?","- Would a scan change your advice?","- Who will examine me: the surgeon or an assistant?","- If you find more gland than expected on the day, how is the quote affected?","You can read about what a doctor looks at in the [[link: /learn/gynecomastia-grades | grades guide]] and find the right kind of specialist in [[link: /learn/doctor-for-gynecomastia | which doctor to see]].","[[faq: How do I know if it is fat or gland? | A firm, rubbery disc behind the nipple, sometimes tender, usually means gland. A soft, spread-out fullness that shrinks with weight loss usually means fat. Only an examination, and sometimes an ultrasound, can confirm which you have.]]","[[faq: Can fat from the chest be removed without surgery? | Weight loss can reduce chest fat for some men. Creams and tablets sold for this have no good evidence behind them. Where fat stays despite a steady weight, liposuction is the usual procedure that a surgeon discusses.]]","If you would like a plain explanation of what your own examination might involve, message us on WhatsApp. Or try the quote checker if you already hold a written estimate and want to compare lines.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('pseudogynecomastia', 'Pseudogynecomastia: chest fat with no gland', 'Pseudogynecomastia is a fuller chest made of fat, not gland. How it is told apart and what people usually consider.', 4, 3, 'gynecomastia-surgery', '["[[reviewer]]","Pseudogynecomastia means a fuller-looking male chest caused by fat rather than by breast gland. The chest feels soft, not firm, and it often goes with extra weight elsewhere. Losing weight can shrink it. If fat stays on despite a steady weight, liposuction is the option a surgeon may raise.","A doctor confirms which you have; the [[link: /gynecomastia-surgery | gynecomastia surgery page]] covers the wider topic.","## What the word means","\"Pseudo\" means false. A man with pseudogynecomastia has a chest that looks like gynecomastia, but there is no true growth of gland tissue behind the nipple. The shape is made by fat. Many men have a mix of both, so the pure form is less common than the label suggests.","## How it is told apart from true gynecomastia","Your doctor will look at three things.","- Texture. Fat is soft and moves under the fingers. There is no firm disc behind the nipple.","- Spread. The fullness is wide and may blend into the sides and upper abdomen.","- Pattern. It often tracks with weight gain and sometimes comes with fat around the waist too.","Sometimes an ultrasound is used if the exam leaves a doubt. The longer comparison is in [[link: /learn/gynecomastia-fat-or-gland | fat or gland]].","## What weight loss can and cannot do","For many men with this kind of chest, losing weight in a steady, medically sensible way reduces chest fat along with fat elsewhere. You cannot choose where the body takes fat from first, so the chest may be one of the last areas to shrink. It also depends on genetics and age. Quick crash dieting is not recommended, and it can leave loose skin.","Exercise helps with weight and muscle tone, but it does not target chest fat on its own; see [[link: /learn/male-chest-exercise-and-fat | what chest exercise can change]].","## When liposuction is discussed","Some men reach a stable, healthy weight and the chest is still full. In that case surgeons may talk about liposuction to remove a measured amount of fat. It is not a weight loss method. Skin that has stretched may not tighten fully, so a doctor will check how elastic your skin is. You can read about the procedure on our [[link: /liposuction | liposuction page]], and about men''s cases in [[link: /learn/liposuction-for-men | liposuction for men]].","## Risks to be honest about","Any surgery carries risk, including bleeding, infection, fluid collection, uneven contour and loose skin. Fat can return in treated and untreated areas if weight goes up. There are always small scars. The surgeon should say all this before you sign anything.","> If weight is still changing, wait. Surgery on a chest that is still shrinking or growing may need a second look later.","## Who should wait","- People who are in the middle of losing or gaining weight.","- Anyone who has not had a proper exam; the diagnosis is not certain from a mirror.","- Teenagers, unless a doctor has a specific reason otherwise.","## When to see a doctor","Book a visit if there is a firm lump, tenderness, discharge, or growth on only one side. These are not typical of simple chest fat and need a check. Also see a doctor if you are worried about your weight, or if the chest has changed quickly without a reason.","## Questions for the consultation","- Is this fat, gland, or both?","- What would a stable weight look like for me?","- If I only have liposuction, could gland tissue be left behind?","- What is the surgeon''s plan if my skin does not tighten?","## A short example","Picture two men of the same height who both say their chest looks \"full\". One is lean, plays sport, and has a firm, tender button under each nipple. The other has gained weight over several years and has a soft, wide chest that moves when he walks. The first is likely to have gland tissue. The second is more likely to have chest fat. They need different advice, even though a photograph might look similar.","## What to bring to a visit","A note of your weight over the last year, a list of medicines and supplements, and when you first noticed the change. If you have old photographs, they can help the doctor see how fast it developed.","[[faq: What is pseudogynecomastia? | It is a fuller male chest caused by fat, without true growth of breast gland tissue. It feels soft rather than firm and often follows weight gain.]]","[[faq: Is chest fat the same as gynecomastia? | Not exactly. Gynecomastia involves gland tissue behind the nipple. Chest fat alone is called pseudogynecomastia. Many men have some of each.]]","If you want to talk it through, WhatsApp us and ask how the two cases are usually quoted. You can also paste a quote into the quote checker to see which lines to compare. There is no pressure either way.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('male-chest-exercise-and-fat', 'Can chest exercise change gynecomastia?', 'What push-ups and bench press do to a male chest, why gland tissue does not respond, and when to stop trying.', 4, 2, 'gynecomastia-surgery', '["[[reviewer]]","Exercise can build the muscle under the chest and help you lose overall body fat. It does not shrink gland tissue. If your enlargement is mostly fat, steady weight loss may help. If it is gland, no amount of push-ups will remove it, and heavy chest work can make the chest look bigger.","More background is on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","## What exercise actually does","Training the chest makes the pectoral muscle thicker. That changes the shape under the skin. Exercise also burns energy, which can lower total body fat over time. What it cannot do is pick fat from one place. Doing a hundred push-ups a day does not melt fat from the chest in particular.","## Why gland tissue does not respond","Breast gland tissue is not muscle and not ordinary fat. It is a firm tissue that grows because of hormone signals. Diet and workouts do not remove it. This is why some lean, fit men still have a rounded area behind the nipple. If that describes you, see [[link: /learn/gynecomastia-fat-or-gland | how a doctor tells fat from gland]].","## Bench press and how it looks","A bigger pectoral muscle can push a firm gland disc forward and make it more visible, especially in a fitted shirt. Some men notice the area looks worse after months of heavy bench work. It is not that the muscle caused gland growth. Look for causes in [[link: /learn/gynecomastia-gym-steroids | the gym and steroid guide]], because some gym products can feed the problem.","## Diet and weight","If the chest is mostly fat, a sensible plan usually means eating a bit less than you burn, building muscle with resistance work, and being patient. Months, not weeks. Cutting too fast can strip muscle and leave loose skin. Skip tablets and drinks that promise chest fat loss. They have no good evidence behind them.","## A fair way to test it","- Pick a stable routine that you can keep up.","- Weigh yourself and note the chest area once every two weeks, not daily.","- After three to four months, check whether the soft, wide fullness has reduced.","- Notice what has not changed. A firm disc under each nipple that stays the same is likely gland.","This is a self-check, not a diagnosis. See a doctor to confirm it.","> If you have done everything and the chest is the same size, the exercise did not fail. The tissue was not the kind that exercise reaches.","## When to stop trying and see a doctor","- A lump, soreness or discharge appears.","- One side is much larger or growing faster.","- You have worked on weight and routine for several months with no change in the firm area.","- The chest is affecting your mood, relationships or confidence.","Then it is time to ask what else could be going on, including [[link: /learn/gynecomastia-causes | causes a doctor checks first]]. If the chest is soft and your weight is high, [[link: /learn/pseudogynecomastia | pseudogynecomastia]] may fit better.","## Who should wait","Anyone considering surgery should hold a steady weight for a few months first, because changes after surgery can alter the result. That means finishing a diet or bulk phase before booking. Doctors also like to know your usual training so they can plan when you return to it. The week-by-week plan is in [[link: /learn/gynecomastia-recovery-timeline | the recovery timeline]].","## If surgery is the answer","Some men decide that surgery is the better route once they understand the tissue. The choice between liposuction and gland removal depends on your case; read [[link: /learn/gynecomastia-liposuction-vs-gland-removal | how the plan is chosen]].","## What to do instead of guessing","Many men spend months on chest routines before asking anyone. A faster route is a short examination. A doctor can tell in one visit whether you are dealing with fat, gland or both, and that changes how you spend the next six months.","## Training around the problem","If you are training with a firm gland disc and you want to keep going, there is no harm in doing so unless you have pain or a lump. Some men prefer lighter chest work and more back, shoulders and legs while they decide what to do. That is a personal choice, not a medical rule. Wear a snug layer if the chest bothers you in the gym, and do not tape or bind it tightly for long hours, because that can irritate the skin.","[[faq: Can exercise cure gynecomastia? | Exercise cannot remove gland tissue. It can help reduce overall fat and improve muscle tone, which may lessen a soft, fatty chest. A doctor can tell you how much of your chest is gland.]]","[[faq: Do push-ups reduce man boobs? | Push-ups strengthen the chest muscle but do not burn fat from the chest alone. If the fullness is gland, push-ups will not shrink it and may make it more noticeable.]]","When you are ready to ask a real person, message us on WhatsApp. If you already have a quote from a clinic, the quote checker shows the lines worth comparing. No rush.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-causes', 'Causes of gynecomastia: puberty, medicines, hormones', 'The common reasons a man''s chest grows: puberty, some medicines, alcohol, health conditions and weight.', 5, 1, 'gynecomastia-surgery', '["[[reviewer]]","Gynecomastia usually comes from a shift in the balance between the hormones oestrogen and testosterone. Common triggers are puberty, some medicines, alcohol or drug use, weight gain and certain health conditions. In many cases no single cause is found. A doctor looks for treatable causes before surgery is discussed. This page links to our [[link: /gynecomastia-surgery | main gynecomastia guide]].","## Puberty","Many boys develop some chest tissue during puberty as hormones change. In most, it settles over time without treatment. Parents often worry; [[link: /learn/gynecomastia-in-teenagers | this guide for teenagers and parents]] explains what usually happens and when to get advice.","## Medicines","Some medicines can lead to chest growth as a side effect. Classes that doctors commonly mention include some antibiotics, some anxiety and mood medicines, some treatments for prostate problems, and some medicines for stomach ulcers or heartburn. The list is long and changes with new drugs.","> Do not stop a prescribed medicine on your own. Take the name to your doctor and ask whether it could be linked and whether there are alternatives.","## Alcohol and drugs","Heavy alcohol use can affect the liver, which handles hormones, and may change the balance. Anabolic steroids and some recreational drugs are also linked with breast tissue growth. If this applies to you, say so at the consultation. A doctor has heard it all before and needs the facts to help. The gym angle is in [[link: /learn/gynecomastia-gym-steroids | steroids, supplements and lifting]].","## Health conditions","Some conditions can raise oestrogen or lower testosterone, or both. Examples include kidney disease, liver disease, an overactive thyroid and problems with the testicles. Treating the condition sometimes reduces the chest tissue. That is one reason a first visit often includes blood tests.","## Weight","Body fat makes some oestrogen. More fat can mean more oestrogen, and fat also adds to chest size on its own. If the fullness is mostly fat, it is [[link: /learn/pseudogynecomastia | pseudogynecomastia]], and the plan is different.","## Age","Hormone levels shift again in older men, and gynecomastia becomes more common in middle and later life. New enlargement in an older man deserves a proper check, as it can be linked to a medicine or a health condition.","## Which causes a doctor treats first","Doctors usually begin with what can be changed:","- reviewing and adjusting medicines","- advising on alcohol and drugs","- treating a medical condition found on tests","- agreeing a plan for weight","If the chest tissue has been there for a long time, it can become firm and scar-like, and it often does not shrink even after the cause is fixed. Then surgery may be discussed.","## Who should wait","If the enlargement began in the last few months and a cause is still being investigated or treated, wait. Operating before the cause is dealt with risks the tissue coming back. Teenagers should also usually wait; see the [[link: /learn/gynecomastia-grades | grades guide]] for how size is described.","## When to see a doctor","- the enlargement is new and growing","- there is pain, a hard lump, or discharge from the nipple","- only one side is affected","- you are on long-term medicines and have noticed a change","Choosing who to see is covered in [[link: /learn/doctor-for-gynecomastia | which doctor treats gynecomastia]]. For claims about tablets and creams, read [[link: /learn/gynecomastia-tablets-creams-evidence | what the evidence says]].","## What a first visit may cover","A first appointment about a new chest change often includes a list of questions, a physical exam, and sometimes blood tests. The questions can feel personal: medicines, alcohol, drug use, sleep, weight changes, any problems with the testicles or with sexual function. You do not need to prepare answers, but it helps to write down medicine names beforehand.","## When no cause is found","In a good share of men, tests come back normal and no clear trigger is found. That does not mean the doctor missed something or that you did anything wrong. It usually means a small hormone imbalance or a sensitivity of the chest tissue that cannot be traced. In that situation, the discussion turns to how much the chest bothers you and whether surgery is appropriate.","[[faq: What causes gynecomastia? | Usually a change in the balance of oestrogen and testosterone. Triggers include puberty, certain medicines, alcohol or drug use, weight gain, some health conditions, and age. Often no single cause is found.]]","[[faq: Can gynecomastia be caused by medicines? | Yes. Several classes of medicine are linked with it. Do not stop a prescribed medicine yourself; ask your doctor to review it.]]","If you want help organising your questions before a consultation, message us on WhatsApp, or paste a quote into the quote checker. We will not push you to book.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-liposuction-vs-gland-removal', 'Liposuction only, or gland removal? How the plan is chosen', 'Surgeons may use liposuction, gland removal or both. What decides the plan, skin removal, and questions to ask.', 5, 3, 'gynecomastia-surgery', '["[[reviewer]]","Liposuction removes fat. Gland excision cuts out firm breast tissue. Many men need both, some need only one, and larger cases may also need skin removed. The surgeon decides after examining you, mainly by how much of the chest is fat and how much is gland. The overview is on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","## The three approaches","Liposuction only. A thin tube is passed through a tiny cut and fat is suctioned out. It suits a chest made mostly of fat, which is the case discussed in [[link: /learn/pseudogynecomastia | pseudogynecomastia]].","Gland excision. The firm disc behind the nipple is removed through a small opening at the edge of the areola or the side of the chest. It is used when gland tissue is the problem.","Both together. This is common because most enlarged chests contain some fat and some gland. Liposuction smooths the surrounding contour and the gland is taken out directly.","## What decides between them","- The exam and, if needed, a scan showing how much gland there is.","- Chest size and grade; see [[link: /learn/gynecomastia-grades | the four grades]].","- Skin: tight skin shrinks back better than stretched skin.","- Your goals and how much scar you will accept.","- Anaesthesia: local with sedation or general, depending on the plan and your health.","Some surgeons also plan for the unexpected. If gland is found in a larger amount on the day, the plan may change, and the quote should say how.","## Loose skin","When the chest is large or the skin has stretched, fat or gland removal alone can leave extra skin. The surgeon may suggest removing some, or tightening it with radiofrequency heat, or leaving it and reviewing later. Removing skin means a longer scar. Ask where it would sit and see an example on a real patient who has agreed to show one.","## What each costs, in plain terms","Liposuction alone usually takes less theatre time than gland removal with skin work. Anaesthesia type, hospital, and the number of follow-up visits matter too. The cost page has the factors: [[link: /cost/gynecomastia-surgery | gynecomastia cost factors]]. No quote should be final until a surgeon has examined you.","## Recovery differences","Both start with a compression vest, swelling and bruising. Cases with gland excision or skin removal can need more careful wound care, and sometimes a drain for a short while. The week-by-week plan is in [[link: /learn/gynecomastia-recovery-timeline | the recovery timeline]].","## Risks","Both approaches carry risks: bleeding, infection, fluid collection, uneven contour, delayed healing and changes in nipple sensation. Fat can return if weight goes up, so a stable weight matters. Liposuction on its own can leave gland behind. Gland excision can leave a dip if too much is removed. Your surgeon should explain which risk is bigger for your plan.","> If a clinic says one method suits every chest, ask them to explain why.","## Who should wait","- Anyone whose weight is still changing.","- Anyone whose cause has not been looked for; see [[link: /learn/gynecomastia-causes | causes of gynecomastia]].","- Teenagers, unless there is a specific medical reason.","## Questions to ask","- Based on my exam, do you plan liposuction, gland excision or both, and why?","- Where will each cut be?","- What happens if you find more gland than expected?","- Will I need skin removal now or later?","- Does the quote cover a second small procedure, if one is needed?","More on questions to bring is in [[link: /learn/questions-to-ask-your-plastic-surgeon | this checklist]]. If you also have fat on the abdomen or sides, see our [[link: /liposuction | liposuction page]].","## A worked comparison in words","Imagine a man with a soft chest, a small firm disc behind each nipple and good skin. The surgeon may plan gentle liposuction across the chest, plus removal of each disc through a small cut at the edge of the areola. Now imagine a man with a very soft chest and no disc at all. Liposuction alone may be enough. A third man has a large chest with hanging skin: here the surgeon may discuss skin removal, and a second small operation later if needed. Three men, three plans.","## Why the cut location matters","Cuts for gland removal sit at the edge of the areola or in the crease at the side of the chest. Your surgeon should show you the exact line on your own chest and explain how it will look when healed. A cut in the wrong place can leave a visible mark, so this is a fair thing to ask about in detail.","[[faq: Is liposuction enough for gynecomastia? | It can be, if the chest is mostly fat. If there is a firm gland, liposuction alone may leave part of it behind. A surgeon decides after examining you.]]","You can message us on WhatsApp for a written estimate, or put your quote through the quote checker. Take as long as you need.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-recovery-timeline', 'Gynecomastia surgery recovery time, week by week', 'What to expect in the first days, weeks and months, and when work, driving, the gym and travel usually restart.', 5, 2, 'gynecomastia-surgery', '["[[reviewer]]","Most men go home the same day, rest for a few days, and return to desk work in about a week. Driving, brisk walking and a compression vest follow within two weeks. Lifting and chest work usually wait four to six weeks or more. Your surgeon sets the dates for you.","Details of the operation are on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","> These timings are general. Your surgeon''s instructions override this page, and they depend on the method used and how your body heals.","## Day 0 to 2","You will feel drowsy, sore and tight across the chest. A compression vest is put on, and some men have a small drain for a short time. Rest, take the medicines you were given, walk around the house every few hours, and sleep with your head slightly raised. Have someone with you at home the first night.","## Week 1","Swelling and bruising peak around days 2 to 4 and then slowly ease. Short walks are good. Most men with desk jobs feel ready to return by the end of the week, though energy dips by afternoon are common. Many surgeons want to see you for a first review within the first week to check the wounds and any fluid. Do not drive while you are taking sedating pain medicines.","## Week 2","Bruises turn yellow-green and fade. You may still feel firm lumps under the skin, which are normal as swelling settles. Brisk walking and gentle cycling are often allowed now. Keep wearing the vest as instructed. If the surgeon has removed stitches, wounds are usually checked then.","## Weeks 4 to 6","Many surgeons clear light weights and swimming at about this time. Heavy lifting, chest presses and contact sports usually wait longer, so ask directly for your own date. Going back too soon is the most common way to cause fluid build-up or a bulge.","## Months 2 to 3","The chest keeps softening and the shape continues to settle. Numbness around the nipple or incisions can linger and slowly improve. Final shape may take several months; do not judge it in week 3.","## Work, driving, gym and flying","- Work: desk work in about a week for many; physical jobs often need two to four weeks or more.","- Driving: only when you are off sedating medicines and can turn and brake without pain.","- Gym: walking early, legs and core later, chest and heavy upper-body work last.","- Travel: short trips are usually fine after the first review. Long flights deserve a conversation, because sitting still raises clot risk.","## The compression vest","The vest controls swelling and helps skin settle. It should be snug and not painful. Ask how many hours a day, for how many weeks, how many vests are included in the quote, and how to wash it.","## Who should wait to book","If you have a big event, exam or a trip in the next few weeks, move the date. Rushed recovery causes problems. Men who smoke should stop before surgery, as nicotine slows healing.","## When to call your doctor","Call the same day for any of these. See [[link: /learn/gynecomastia-surgery-risks | the risks guide]] for the full list.","- fever or chills","- swelling that is growing fast or is much bigger on one side","- redness, heat or pus from a wound","- chest pain, breathlessness, or a painful swollen calf (go to emergency care)","- bleeding that soaks the dressing","## Fitting recovery into your plan","Ask the clinic for a written recovery plan for your job, and see how quote lines like garments and review visits are handled on our [[link: /cost/gynecomastia-surgery | cost page]]. The two cities where we are building local information first are [[link: /gynecomastia-surgery-in-gurgaon | Gurgaon]] and [[link: /gynecomastia-surgery-in-delhi | Delhi]].","[[faq: How long is recovery after gynecomastia surgery? | Many men return to desk work in about a week and feel mostly normal by four to six weeks. Full settling of the shape takes a few months. Your surgeon sets your own dates.]]","[[faq: When can I go to the gym? | Walking soon after surgery. Heavier chest and upper-body work is usually held back for at least four to six weeks. Your surgeon will give a date.]]","[[faq: Can I fly after surgery? | Short flights are often fine once you have had your first review. Long flights raise clot risk, so ask the surgeon.]]","If it helps to plan around your work leave, send us your dates on WhatsApp and we will help you ask the right questions. The quote checker is there if you already hold a quote.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia. Timings are drafts pending surgeon review.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-surgery-risks', 'Gynecomastia surgery risks and when to call your doctor', 'An honest list of what can go wrong after gynecomastia surgery, what is common, and which signs need a call.', 5, 1, 'gynecomastia-surgery', '["[[reviewer]]","Gynecomastia surgery is a common operation, but it carries risks like any surgery: bruising and swelling are expected, while infection, bleeding, fluid collection, uneven contour, scars and numbness are possible. Fat can return if weight rises. Knowing the signs that need a same-day call matters more than any list. Start with our [[link: /gynecomastia-surgery | gynecomastia surgery guide]].","## Common and expected","These happen to many people and usually settle:","- bruising and swelling for several weeks","- tightness and soreness","- temporary numbness or odd sensations around the nipple","- small lumps and firmness as tissue heals","## Less common but real","- Infection. Redness, warmth, pus or fever. It is treated with antibiotics and sometimes drainage.","- Bleeding or a blood collection under the skin. It may need a small procedure to drain.","- Seroma, a pocket of fluid. It can need draining with a needle.","- Uneven shape. One side can look different from the other, and some small difference is normal.","- Contour irregularity. A dip, bump or ridge can form where too much or too little was removed.","- Delayed healing, more likely in smokers.","- Loose skin when the skin does not tighten.","- Changes in nipple sensation, shape or colour.","## Rare","- Loss of skin or nipple tissue from poor blood supply.","- Blood clots in the legs or lungs.","- An allergic reaction or problems related to anaesthesia.","Your anaesthetist will assess your health beforehand. Ask which type is planned and why.","## Scars","Every operation that cuts the skin leaves a mark. Cuts for liposuction are tiny. Gland excision usually leaves a small line at the edge of the areola or on the side of the chest. Skin removal leaves a longer scar. Most fade over many months, but they do not vanish, and healing varies with skin type and care. Ask your surgeon to show you where each scar will sit on your own chest.","## Can it come back?","Treated gland and fat cells are removed, but the body can lay down new fat if weight rises. Gland can regrow if the cause, such as a medicine or a steroid, continues. Be cautious about any claim that it never returns.","## Reducing risk","- Share your full medical history, medicines, supplements and alcohol or drug use.","- Stop smoking before surgery, if you smoke.","- Follow the instructions about the vest, rest and review visits.","- Choose a surgeon registered with the NMC or a State Medical Council and check the registration. See [[link: /how-we-verify-surgeons | how we check registration]].","## When to call the same day","> If you have chest pain, trouble breathing, or a swollen painful calf, go to an emergency department. Do not wait for office hours.","Call your surgeon at once for:","- fever or chills","- redness, heat or pus","- fast swelling on one side","- bleeding that does not stop with gentle pressure","- pain getting worse after day three instead of better","Recovery steps are in [[link: /learn/gynecomastia-recovery-timeline | the timeline]].","## Who should wait","People with uncontrolled health conditions, those still gaining or losing weight, and anyone who has not been checked for a cause should wait. Teenagers are generally advised to wait.","## What to ask before surgery","- Which of these risks apply most to my case?","- What is your policy if I need a second procedure?","- Who do I call out of hours?","- What is the follow-up plan, and is it in the quote?","Use [[link: /learn/questions-to-ask-your-plastic-surgeon | this checklist]] to be thorough, and see the chosen doctor''s role in [[link: /learn/doctor-for-gynecomastia | choosing who to see]].","## Putting the risks in proportion","Reading a long list of risks can make anything sound frightening. Most people who have this operation heal without a serious problem, but we cannot give you a number because the figures we can verify differ between studies and between hospitals. What helps is knowing which risk applies to your plan and what the surgeon would do if it happened. Ask for that in plain words.","## Mental and emotional side","Some men feel low in the first weeks, when swelling hides the shape they hoped for. Some feel anxious about scars. This is common and usually passes. Tell your doctor if it does not, or if it feels heavy.","[[faq: What are the risks of gynecomastia surgery? | Bruising and swelling are expected. Infection, bleeding, fluid collection, uneven contour, delayed healing, loose skin and changes in sensation are possible. Clots and tissue loss are rare.]]","[[faq: Are there scars? | Yes. Cuts are small and placed at the edge of the areola or the side of the chest, and they usually fade, but they do not disappear.]]","[[faq: Can gynecomastia come back? | It can if weight rises or the cause continues, such as a medicine or steroid use.]]","If you would like a coordinator to walk through the risks, message us on WhatsApp. We will not rush you.","[[sources: NHS patient information on gynaecomastia and on surgery risks; Mayo Clinic patient information on gynecomastia. Reviewer to confirm.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('doctor-for-gynecomastia', 'Which doctor to see for gynecomastia', 'GP, endocrinologist or plastic surgeon? What each one checks, how to confirm registration, and how to read a quote.', 4, 3, 'gynecomastia-surgery', '["[[reviewer]]","Start with a general doctor or an endocrinologist if the swelling is new, painful or one-sided. See a plastic surgeon when the tissue has settled and you want to know about surgery. Each looks at a different part of the problem. You can read the surgical side on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","## Three kinds of doctor","A general physician or family doctor is the usual first stop. They take the history, examine you, check your medicines and order basic tests. They can refer you on.","An endocrinologist deals with hormones. They look for causes like thyroid trouble, a testosterone problem, or a medicine effect, and may treat them.","A plastic surgeon deals with the shape. They assess the grade, the mix of fat and gland, the skin, and plan the operation if surgery is right.","Some men go straight to a surgeon and that is fine, but ask whether the cause has been looked at. [[link: /learn/gynecomastia-causes | The causes guide]] explains why.","## What each visit should include","- A conversation about when it began and what has changed.","- A review of every medicine, supplement, alcohol and drug use.","- A physical examination, including both sides of the chest.","- A clear explanation, in plain words, of what is gland and what is fat; see [[link: /learn/gynecomastia-fat-or-gland | fat or gland]].","A visit that is only a sales talk is a warning sign.","## Checking a surgeon''s registration","In India a doctor must be registered with the National Medical Commission or a State Medical Council. The registration number can be looked up on the public register. A plastic surgeon should also hold a recognised postgraduate qualification in plastic surgery. Ask for the registration number and check it yourself. We explain our own checks on [[link: /how-we-verify-surgeons | how we verify surgeons]]. We do not rank doctors against each other, and we do not list one as better than another.","## Questions to ask","- How often do you perform this operation?","- Will you operate, or will someone else?","- Where is it done, and what happens if something goes wrong?","- Who will I see for follow-up?","- Which risks matter most in my case?","There is a longer list in [[link: /learn/questions-to-ask-your-plastic-surgeon | the checklist guide]].","## How to read a quote","A quote should say what it covers: surgeon fee, facility, anaesthesia, garment, medicines, tests, review visits, and what happens if a second procedure is needed. Two quotes can differ only because one leaves lines out. Use the comparison guide, [[link: /learn/how-to-compare-surgery-quotes | how to compare two quotes]], and the factors on our [[link: /cost/gynecomastia-surgery | cost page]].","## Who should wait","If you are a teenager, a parent should go with you. If your enlargement is recent, see a physician first. If a clinic pushes you to pay on the first visit, step back.","## When to see a doctor soon","- a hard lump, nipple discharge or skin change","- enlargement in just one breast","- pain, or fast growth","- chest changes with weakness, fatigue or other symptoms","## Where local information lives","We are building city pages with real travel and facility details, starting with [[link: /gynecomastia-surgery-in-gurgaon | Gurgaon]] and [[link: /gynecomastia-surgery-in-delhi | Delhi]]. They appear as each one is checked.","## What a good first consultation feels like","You are asked questions before you are shown prices. You are examined in private, with a chaperone if you want one. The doctor explains what they see and what they do not know yet. You leave with a written plan or a written list of tests. You are told that you can think it over and come back, and that you can ask someone else.","## Red flags in a clinic","- A price is quoted on the phone with no examination.","- You are told to pay a deposit before you have seen the surgeon.","- The surgeon''s name or registration number is hard to get.","- Photographs of other patients are shown without consent, or with no detail about what was done.","- You are told there are no risks, or that results are the same for everyone.","If you notice any of these, pause. You are allowed to leave and take your time. Nothing about this operation is urgent unless a doctor has said so for a medical reason.","[[faq: Which doctor treats gynecomastia? | A general doctor or endocrinologist looks for causes. A plastic surgeon assesses and operates if surgery is needed. Many people see more than one.]]","If you want to work through who to see, message us on WhatsApp and tell us what you have noticed. The quote checker can also help if you are holding a written estimate. No obligation.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia; National Medical Commission (nmc.org.in) registration information.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-in-teenagers', 'Gynecomastia in teenagers: does it go away on its own?', 'Chest enlargement is common in puberty and often settles. A guide for teenagers and parents on waiting and when to see a doctor.', 4, 2, 'gynecomastia-surgery', '["[[reviewer]]","Many boys develop some chest enlargement during puberty, and in most it settles by itself over months to a couple of years. A doctor can check for other causes. Surgery in a teenager is considered only in particular situations, after growth has settled, and with the family involved. This page is written for both parents and teens.","The wider topic is on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","## Why it happens in puberty","During puberty, hormone levels change quickly and not always evenly. For a time, the balance can tip towards oestrogen, and chest tissue grows. It can affect one side or both and can be tender. It is not the boy''s fault, and it is not caused by anything he ate or did. More causes are listed in [[link: /learn/gynecomastia-causes | causes of gynecomastia]].","## How long is it reasonable to wait?","Doctors often suggest watching for a period, because many cases settle. How long depends on the boy, on how bothered he is, and on what the doctor finds. We do not give a fixed number here, because the surgeon or paediatrician reviewing your case sets it. Ask the doctor what a sensible review point would be and write it down.","## When to see a doctor","Do not wait for puberty to pass if any of these apply:","- a hard lump, or a lump on one side only","- nipple discharge","- pain that is getting worse","- fast growth","- a medicine that was started recently, or any steroid or supplement use","- distress, low mood, avoiding school activities or swimming because of the chest","A family doctor or paediatrician is a good first stop. They can examine, ask about medicines, and decide if blood tests or a referral are needed. Reading [[link: /learn/gynecomastia-grades | the grades guide]] helps you follow what the doctor says.","## What parents can do","Stay calm and listen. Teens may feel embarrassed and say little. Ask simple questions, avoid jokes, and make clear that this is common and medical. Do not buy creams, tablets or supplements online. They have no good evidence behind them and some can do harm; see [[link: /learn/gynecomastia-tablets-creams-evidence | what the evidence says]]. Look at your son''s medicines with the doctor, and do not stop any without advice.","## Fat or gland?","Many teenagers who are overweight have chest fat rather than gland tissue. The doctor can tell the difference; read [[link: /learn/gynecomastia-fat-or-gland | how that check works]]. A healthy routine of eating, sleep and activity is reasonable advice for any teenager, but it will not shrink gland tissue.","## Surgery in a minor, plainly","Surgery is not a first step in a teenager. It may be considered if the tissue has stayed for a long time, a cause has been checked, growth has settled and the enlargement is causing real distress. The decision involves the teenager, parents or guardians, and a surgeon. The teenager should be able to say in his own words what he wants. Consent from a parent or guardian is needed, and a good doctor will make sure the teenager is heard.","> If a clinic gives a quick surgery date without a full exam and a long conversation with the family, ask for a second opinion.","## Who should wait","- Boys in the middle of puberty, unless a doctor sees a specific reason.","- Anyone using steroids, supplements or new medicines; the cause should be addressed first.","- Anyone who is not sure and is being pushed by someone else.","## Support","Teasing and embarrassment can be harder than the chest itself. If your child is withdrawn or low, talk to the school counsellor or doctor. That counts as medical care too.","## Talking to the doctor as a teenager","If you are the teenager reading this, you are allowed to ask questions. You can ask the doctor to explain things again, to speak to you and not only to your parents, and to see you alone for part of the visit. It is normal to feel awkward. Doctors see this often, and they care more about your health than about what your chest looks like.","## School, sport and swimming","Boys sometimes skip sport or swimming to avoid being seen. A snug, plain undershirt can help while you wait. If teasing is happening, tell a teacher or counsellor, because that is a separate problem that needs attention.","[[faq: Does gynecomastia go away on its own? | In many teenagers it settles over months to a couple of years. It may not, particularly if it has been there for a long time, and a doctor should check for other causes.]]","[[faq: At what age is surgery considered? | There is no single age. Surgery is considered when growth has settled, causes have been checked, and the chest is causing real distress. The decision is shared between the teenager, his parents and a surgeon.]]","Parents who would like a plain-language call before any appointment can message us on WhatsApp. We explain, we do not pressure.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia. Reviewed by two reviewers before publication (pending).]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-gym-steroids', 'Gynecomastia and the gym: steroids, supplements, lifting', 'How anabolic steroids and some gym products can lead to chest tissue growth, what lifting does, and what to tell your doctor.', 4, 1, 'gynecomastia-surgery', '["[[reviewer]]","Anabolic steroids can cause gynecomastia by upsetting the body''s hormone balance, and some supplements may too. Lifting itself does not create gland tissue, but a bigger chest muscle can make existing tissue more visible. If you use any of these, tell your doctor. They have heard it before, and the plan depends on the truth.","See the main [[link: /gynecomastia-surgery | gynecomastia surgery guide]].","## Anabolic steroids","Anabolic steroids raise testosterone-like activity in the body. Some of the extra hormone can be converted into oestrogen, and the body may also lower its own testosterone. The result can be breast tissue growth, often tender. This can happen during a cycle or after it. Stopping the steroid may help in the early stage, but once gland tissue has become firm, it often stays.","Steroid use also affects the liver, heart, fertility and mood. A doctor can talk about these without judgment, and your confidentiality applies.","## Supplements","Many gym supplements are not well tested. Some contain ingredients that are not on the label, including hormone-like compounds. Products sold as \"testosterone boosters\" or \"muscle builders\" can alter hormones in ways that are hard to predict. We do not name products. If you have used any supplement in the past year, bring the container or a photograph of its ingredient list to the consultation.","## Lifting and how the chest looks","Lifting builds muscle and burns energy. It does not turn muscle into gland. However:","- A thicker chest muscle sits behind the gland and pushes it forward.","- In a lean man, any firm disc under the nipple stands out more.","- Heavy bench pressing may make you press on a tender area and notice it more.","Read [[link: /learn/male-chest-exercise-and-fat | what chest exercise can and cannot change]] for more.","## What to tell the doctor","- Which substances you take or have taken, how long, and when you stopped.","- Any other medicines, including for hair or prostate.","- Alcohol and recreational drugs.","- When you first noticed the chest change.","This helps the doctor look at the causes properly; see [[link: /learn/gynecomastia-causes | causes of gynecomastia]]. It also lets the anaesthetist plan with the full picture. Hiding a steroid cycle from a surgeon raises the risk of problems during and after surgery.","## What to stop","Do not stop a prescribed medicine on your own. For non-prescribed steroids and supplements, talk to your doctor about stopping, especially before surgery. A doctor may want you to be off them for a period before an operation, because operating while the cause is still active risks the tissue regrowing.","## After surgery","Return to training is gradual and set by your surgeon. Lifting too early can cause fluid collection or uneven healing; see [[link: /learn/gynecomastia-surgery-risks | risks and warning signs]]. If you go back on steroids, the chest tissue can return.","> Surgery removes tissue that is already there. It does not make the body immune to whatever caused it.","## Who should wait","Wait if you are still on a steroid cycle, if you are cutting or bulking heavily and your weight is moving, or if you have not been checked for causes. Bodybuilders often want a quick date before a competition; surgery and a competition do not mix, because swelling and recovery take weeks.","## When to see a doctor","- tender swelling during or after a cycle","- a hard lump, nipple discharge or swelling on one side only","- mood changes, testicular shrinkage or low desire","Early review gives you the most options. Read [[link: /learn/gynecomastia-grades | the grades guide]] to follow what you are told.","## A note on privacy","Many men worry that admitting to steroid use will be recorded and shared. A doctor keeps your information confidential in the same way as any other medical history. You can ask the clinic how your records are stored and who can see them. A surgeon cannot plan properly without this information, because anaesthesia, wound healing and the risk of regrowth all depend on it.","## Planning a gym break","If you decide on surgery, expect a pause from heavy upper-body training around the operation. Some men use this time for leg work, walking and mobility. Plan it around your goals, and avoid booking a date just before a trip, a shoot or a competition.","[[faq: Can steroids cause gynecomastia? | Yes. Anabolic steroids can disturb the hormone balance and lead to breast tissue growth. Early on it may ease when the steroid is stopped, but firm tissue often stays.]]","[[faq: Will it stay once I have it? | Early tissue may settle if the cause is removed. Longstanding firm tissue often stays and may need surgery. It can come back if the cause returns.]]","If you want to discuss this privately, message us on WhatsApp. We keep your details to the enquiry only.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('gynecomastia-tablets-creams-evidence', 'Gynecomastia tablets, creams, homeopathy: what evidence says', 'What doctors may prescribe and when, and why creams, oils, herbal and homeopathic products have no good evidence for gland tissue.', 4, 3, 'gynecomastia-surgery', '["[[reviewer]]","There is no tablet, cream or oil proven to remove breast gland tissue. A doctor may prescribe medicine in selected cases, usually when the problem is new, painful and causes are being treated. Homeopathy and herbal products have no good evidence for this. Delaying a check-up can cost time. The surgical option is on our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","## Which tablets are discussed","Online lists are long, and the names change. In clinic practice, doctors may consider certain hormone-related medicines in selected people, usually when the enlargement is recent and painful. These medicines are prescribed by a doctor after an exam, and some have side effects. We give no names, doses or brands here. Do not buy them off a website or from a friend.","For most men with long-standing enlargement, medicine does little, because the tissue has turned firm. In that situation the conversation moves to surgery.","## Creams, oils and gels","Creams and oils sold for \"chest reduction\" are applied to the skin. There is no good evidence that skin products can remove gland tissue lying beneath. Some contain hormone-like or steroid ingredients that can cause skin harm or raise the very problem you want to fix. Check ingredients, and ask a doctor first.","## Homeopathy, herbal and Ayurvedic products","Studies of good quality showing that these remove gland tissue do not exist, as far as widely available medical guidance goes. Some products are tested poorly, and some herbal mixes are contaminated or contain undeclared ingredients. If you choose to try something, tell your doctor, so they can watch for interactions. Do not use it in place of a medical check.","## Fat burners and \"gynecomastia pills\"","Supplements that claim to burn chest fat or shrink gland do not do what the label says. They can raise heart rate and blood pressure, and some contain hormone-like ingredients. See [[link: /learn/gynecomastia-gym-steroids | the gym and supplement guide]].","## What can be treated without surgery","Several things help more than a product:","- reviewing any medicine that may be the cause","- stopping steroids or other drugs","- treating a thyroid, liver, kidney or testicular problem","- weight management, if fat is part of it","Details are in [[link: /learn/gynecomastia-causes | causes of gynecomastia]].","## The cost of delay","When tissue is recent, treating the cause may let it settle. As months pass, gland tissue can become firm and scar-like, and it then responds less to anything except surgery. Spending a year on products can mean the window for non-surgical help has gone. It also costs money. Compare any \"course\" price with the surgical factors on our [[link: /cost/gynecomastia-surgery | cost page]] only after you have had an exam.","> A product that promises to remove gland tissue without a doctor is making a claim it cannot back up.","## Who should wait","If the enlargement is new and your doctor is investigating a cause, a short wait is reasonable. Teenagers should see a doctor, not a shop. Do not wait if there is a hard lump or discharge.","## When to see a doctor","- Pain, tenderness or fast growth.","- A lump on one side.","- Discharge from the nipple.","- You have been using a product for months with no change.","Learn how a doctor tells the tissue types apart in [[link: /learn/gynecomastia-fat-or-gland | fat or gland]], and how exercise fits in at [[link: /learn/male-chest-exercise-and-fat | chest exercise]]. For who to consult, read [[link: /learn/doctor-for-gynecomastia | which doctor to see]].","## How to judge an online claim","When you see a product that promises to shrink a male chest, run it through four questions. Who made it, and can you find them? Is there a study, and is it about this exact product in men like you? Does the claim include a time period and a percentage? Is the seller also a clinic that benefits from you spending money? If you cannot answer, treat it as advertising. A doctor can tell you what is known and what is not, and will not mind you asking.","[[faq: Which tablet is used for gynecomastia? | Only a doctor can decide. Certain hormone-related medicines are sometimes prescribed in selected, recent cases. There is no tablet proven to remove firm, long-standing gland tissue.]]","[[faq: Does homeopathy work for gynecomastia? | There is no good evidence that it does. If you use it, tell your doctor, and do not delay a medical check.]]","If you have been using something and are not sure what to do next, message us on WhatsApp. We will tell you what to ask a doctor, nothing more.","[[sources: NHS patient information on gynaecomastia; Mayo Clinic patient information on gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-vs-weight-loss', 'Liposuction is not weight loss: what it can change', 'Liposuction reshapes stubborn pockets of fat. It is not a way to lose weight or treat obesity. What it can and cannot do.', 4, 1, 'liposuction', '["[[reviewer]]","No, liposuction is not weight loss. It removes fat from chosen areas to change shape, and the amount removed is small compared with a diet or a weight-loss programme. It does not treat obesity and does not improve health markers by itself. It suits people near a steady weight with stubborn pockets. Our [[link: /liposuction | liposuction guide]] gives the full picture.","## What liposuction takes out","Fat cells in the treated area are removed through thin tubes passed under the skin. The shape of that area changes because fewer fat cells remain there. The surgeon limits the volume taken in one session, because removing too much at once raises risk. So the scale will move a little, if at all, and the difference shows in how clothes fit.","## What it does not do","- It does not remove fat inside the abdomen around the organs, which is called visceral fat.","- It does not tighten loose skin on its own.","- It does not cure high blood sugar, blood pressure or cholesterol.","- It does not stop fat from being stored elsewhere if you gain weight.","Doctors treat obesity with lifestyle changes, medicines and, in some cases, other kinds of surgery. Liposuction is not one of them.","## Where it fits","Think of three layers. Diet and activity change your overall weight. Medical care deals with health problems. Liposuction, if suitable, refines contour in places that have not shifted despite the first two. Many surgeons ask you to reach a steady weight first, and to hold it for some months.","## Do diet and exercise first","Give a sensible plan a fair try. If the pocket remains the same while the rest of the body has slimmed, that pocket may be a candidate. Fat distribution is partly inherited, so some people store fat around the flanks or lower abdomen no matter what they do.","> If your main aim is to see a lower number on the scale, liposuction is the wrong tool. Ask your doctor about weight management.","## Who it suits","- Adults close to a stable, healthy weight.","- People with firm, elastic skin that can shrink back.","- Those with a specific, localised pocket.","- People in good general health, who do not smoke or are willing to stop.","Read more about the checks in [[link: /learn/liposuction-candidate | who is a candidate for liposuction]].","## What happens after","The garment and swelling matter in the first weeks, and the final shape settles over months. If you gain weight afterwards, fat can return in treated and untreated areas, and often less evenly. See [[link: /learn/liposuction-fat-return | whether fat comes back]].","## Who should wait","- Anyone whose weight is still changing.","- Anyone planning pregnancy in the near future.","- People with health conditions that are not under control.","- Anyone expecting weight loss as the main benefit.","## Questions for your doctor","- Based on my body, how much fat could be removed in one session without raising the risk?","- Will my skin tighten, or should I think about other options?","- What happens if I gain weight afterwards?","- Is my goal better served by something else?","Also see how it compares with surgery for loose skin in [[link: /learn/liposuction-vs-tummy-tuck | liposuction vs tummy tuck]] and what a quote covers on our [[link: /cost/liposuction | liposuction cost page]].","## A fair expectation","If you are 5 kilos above your usual weight and have a pocket of fat on the flanks, liposuction may make the flank slimmer, while the scale hardly changes. If you are 25 kilos above a healthy weight, liposuction will not make you healthy, and a surgeon may refuse to operate until you have worked on weight with a doctor. Both answers are medical, not personal.","## Check your reasons","Ask yourself what you want to feel or do differently in six months. If the answer is \"wear fitted clothes comfortably\", surgery may help. If the answer is \"feel better about my body in general\", it may not, and talking to a counsellor or doctor can give you more than any procedure.","[[faq: Is liposuction weight loss? | No. It removes fat from chosen areas to reshape them. It is not a treatment for obesity and does not replace diet, activity or medical care.]]","[[faq: How much fat can be removed? | The surgeon sets a limit for each person and each session, based on health and the areas treated. We do not give a single figure because it varies.]]","If this fits what you are asking, message us on WhatsApp and we will explain what a written estimate covers, or use the quote checker. No pressure.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('types-of-liposuction', 'Types of liposuction: tumescent, ultrasound, power, laser', 'The main liposuction techniques in plain words, how a surgeon chooses between them, and whether the method changes the price.', 5, 2, 'liposuction', '["[[reviewer]]","Liposuction methods differ in how fat is loosened before it is suctioned out: salt-water solution, sound waves, a vibrating tube or laser heat. Most operations use a salt-water solution with local anaesthetic in all cases. The choice depends on the area, the amount of fat, your skin and the surgeon''s training, not on a single method being better.","See our [[link: /liposuction | liposuction overview]].","## The tumescent step","In most modern liposuction, the area is first filled with a fluid containing salt water, a local anaesthetic and a drug that narrows blood vessels. This swells the tissue, eases fat removal and reduces bleeding and bruising. It is the base for the techniques below, so you will hear the word \"tumescent\" often. Some clinics treat it as a technique on its own, when it is used with local anaesthetic alone.","## Traditional suction","A thin hollow tube, called a cannula, is moved back and forth under the skin while suction removes the fat. The surgeon does the work with arm movement. It is the original method and still widely used, especially for larger volumes.","## Power-assisted","The cannula vibrates quickly, which helps break up fat with less effort. Some surgeons find it useful in tougher areas or when treating several places. It is not a different outcome, just a different tool.","## Ultrasound-assisted","Sound energy softens the fat before it is removed. It is often discussed for firmer fat, such as the upper back, the male chest or the abdomen when more definition is wanted. Heat is generated, so training and care matter to protect skin. Brand names exist, but the method is the point.","## Laser-assisted","A thin fibre delivers laser energy to loosen fat and, some say, warm the skin. Evidence on how much extra skin tightening it gives is mixed, and this page makes no claim that it works better. Ask the surgeon what they have seen in their own patients.","## How the choice is made","- The area. Firmer areas may suit energy-based tools.","- The amount of fat to be removed.","- How elastic your skin is.","- Earlier surgery in the same area.","- The surgeon''s experience with that device.","- Your goals, for example smoothing versus defining muscle lines.","Ask the surgeon why they have picked their method for you. A good answer refers to your body, not to the machine''s name. If a clinic only tells you its device is the \"latest\", ask for the reason.","## Does the technique change the price?","It can. Energy-based devices need equipment and trained staff, which adds to theatre costs. Other factors include the number of areas, the volume removed, the anaesthesia, and what the hospital charges. See the factor list on our [[link: /cost/liposuction | liposuction cost page]].","## Risks that apply to all methods","Bruising, swelling, numbness, uneven contour, fluid collection, infection, bleeding, loose skin and scars are possible with every method. Heat-based methods add a small risk of skin burns. See [[link: /learn/liposuction-risks | the risks guide]].","> A newer or more expensive technique is not automatically a better one. The surgeon''s judgement and the fit with your body matter more.","## Who should wait","Wait if your weight is not stable, if you are expecting a method to remove loose skin, or if you cannot get a clear answer on why a method was chosen. Choice of area matters too; see [[link: /learn/liposuction-body-areas | which body areas can be treated]].","## Questions to ask","- Which method do you recommend for me, and why?","- How many times have you used it on this area?","- What skin changes should I expect?","- Does the quote change if you switch methods on the day?","## Reading a quote with a technique name in it","Quotes often include a technique name in brackets or a brand. Do not let that name end the conversation. Ask three plain questions: what does the device do, what is the reason for using it on my body, and what is the price difference compared with the standard method? If the answer is vague, ask the surgeon directly. You can also compare lines using [[link: /learn/how-to-compare-surgery-quotes | how to compare two surgery quotes]].","## The surgeon matters more than the device","The same tool in different hands gives different results. A surgeon who is comfortable with a simple method will often do better than one who is new to a fancy device. Ask how many of these they do each year, whether they treat your area often, and what they do when things do not go to plan.","[[faq: What are the types of liposuction? | Tumescent, traditional, power-assisted, ultrasound-assisted and laser-assisted are the main ones. Most use a tumescent solution as the base.]]","[[faq: Which type is better? | No type is better for everyone. The surgeon chooses based on the area, the fat, your skin and their own experience.]]","Message us on WhatsApp if you would like a plain explanation of a method named in a quote, or run the quote through the quote checker.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction. Technique descriptions to be confirmed by the reviewer.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-recovery-timeline', 'Liposuction recovery time, week by week', 'What most people notice in the first days, weeks and months after liposuction, and when to restart work, driving and exercise.', 5, 3, 'liposuction', '["[[reviewer]]","Most people go home the same day or the next morning and rest for about three days. Many return to desk work within one to two weeks, and gradual exercise starts around four to six weeks. The shape keeps changing for months. Your surgeon sets your dates. Procedure basics are on our [[link: /liposuction | liposuction page]].","> The pace below is a general guide. Your surgeon''s advice for your areas and method comes first.","## Days 0 to 3","Expect soreness, tightness, bruising and swelling. Fluid may leak from the small cuts, and that is common. A compression garment is put on in or just after theatre. Rest, take the medicines you were given, drink enough fluids and take short walks around the house. Ask someone to stay with you the first night.","## Week 1","Swelling and bruising are usually at their peak in the first few days, then slowly ease. A first review is often around day 3 to 5, when the surgeon checks the cuts and the garment. Light walking is encouraged. Do not drive while taking sedating pain medicine.","## Weeks 2 to 4","Soreness fades and you can slowly return to normal routines. Bruises turn yellow and clear. The skin can feel hard or lumpy, and numbness is common. These are part of healing. Your surgeon may suggest light massage, but only if they advise it. Wear the garment as instructed; read [[link: /learn/liposuction-compression-garment | the compression garment guide]].","## Weeks 4 to 6","Many people progress to stronger exercise at this time, depending on the area treated. Surgeons often like a gradual build-up rather than a sudden return to a full gym session. Ask for a specific date for each activity.","## Months 2 to 3","Swelling continues to fall and the contour becomes clearer. You may still notice firmness in places. Do not judge the outcome yet.","## Months 6 to 12","The final shape settles and scars mature. Some swelling can linger in the lower body longer. If something looks uneven after the swelling has gone, talk to your surgeon. Revision is sometimes discussed, and you should know in advance how it is handled and charged.","## Work, driving, exercise and travel","- Work: desk work in about one to two weeks for many; physical jobs often longer.","- Driving: when you are off sedating medicines and can move without pain.","- Exercise: walking early, gradual build-up from about weeks 4 to 6, advised by the surgeon.","- Flying: short flights may be fine after the first review; long flights raise clot risk, so ask first.","## Who should wait to book","Wait if you have a wedding, exam, trip or sports event within the next month or two. If you have a job with heavy lifting, plan extra leave. Smokers should stop well before surgery, because nicotine slows healing.","## When to call your doctor","Contact the surgeon the same day for:","- fever or chills","- redness, heat, pus or a bad smell from a cut","- swelling that is very uneven or growing fast","- pain that is getting worse after the first days","- bleeding that soaks the dressing","> Chest pain, breathlessness, or a painful swollen calf need emergency care.","For the longer list of possible problems, read [[link: /learn/liposuction-risks | liposuction risks]]. To see how recovery items such as garments and review visits appear in quotes, see [[link: /cost/liposuction | the cost page]]. Our local pages for [[link: /liposuction-in-gurgaon | Gurgaon]] and [[link: /liposuction-in-delhi | Delhi]] will carry travel details when they are checked.","## What helps in the first week","- Set up a place to rest with water, medicines and a charger within reach.","- Keep loose, dark clothes for the first days, because some fluid may leak onto them.","- Plan simple meals, since standing for long is tiring.","- Walk a little every few hours; lying flat all day raises clot risk.","- Write down questions for the first review so you do not forget them.","## Mood and patience","It is normal to feel low or impatient when swelling hides the shape you wanted. Photographs taken at week 3 can be discouraging. Wait and look again at months 3 and 6.","[[faq: How long is recovery after liposuction? | Many people rest for about three days, return to desk work within one to two weeks, and restart exercise gradually from around four to six weeks. Final shape takes months.]]","[[faq: When can I exercise? | Walking soon after surgery. Stronger exercise is usually added from around four to six weeks, but your surgeon sets the date for your areas.]]","[[faq: When is the swelling gone? | Most swelling falls over the first few weeks to months. Some can linger up to a year, especially in the lower body.]]","If you want help planning leave, send us your dates on WhatsApp and we will go through the questions to ask. You can also use the quote checker.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction. Timings are drafts pending surgeon review.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-risks', 'Liposuction risks and when to call your doctor', 'Bruising and swelling are expected. A plain list of other possible problems, how rare they are said to be, and warning signs.', 5, 1, 'liposuction', '["[[reviewer]]","Liposuction is a common operation, but it is surgery and it carries risk. Bruising, swelling, soreness and numbness are expected. Infection, bleeding, fluid collection, uneven contour, loose skin and scars are possible. Blood clots and serious problems are rare. Warning signs deserve a same-day call. Start with our [[link: /liposuction | liposuction guide]].","## Expected effects","- Bruising that may spread and change colour.","- Swelling that lasts weeks and softens over months.","- Soreness, tightness and temporary numbness.","- Fluid leaking from the small cuts in the first days.","- Temporary lumps or unevenness while swelling settles.","These ease with time. If they do not, or if they worsen, tell your surgeon.","## Possible complications","- Infection. Redness, heat, pus, fever. It can need antibiotics or drainage.","- Bleeding or a blood collection (haematoma). It can need draining.","- Seroma, a pocket of fluid under the skin. It may need needle drainage.","- Contour irregularity. Dents, ridges or waves, from uneven removal or healing.","- Asymmetry. Small differences are common, and bigger ones may need a touch-up.","- Loose skin, if the skin does not shrink back.","- Changes in skin sensation, sometimes slow to return.","- Scars. The cuts are small, and they still leave marks that fade over months.","- Skin discolouration or, with heat-based methods, a skin burn.","## Rare but serious","- Blood clots in the legs or lungs.","- Fat entering the blood stream.","- Damage to deeper structures, with the risk higher in larger or multiple-area treatments.","- Reactions to anaesthesia or to the large volumes of fluid used.","Your anaesthetist will review your health and medicines before surgery. Ask what type of anaesthesia is planned and where you will recover.","## What raises the risk","Treating many areas at once, removing a large amount of fat, smoking, long flights soon after surgery, and underlying health conditions can all raise risk. Surgeons often set limits for a single session. If a clinic proposes a very large volume or several areas in one day, ask why.","## Contour problems and loose skin","Uneven results are one of the most common reasons for dissatisfaction. Skin quality matters: younger, firmer skin shrinks back better. When skin is loose, surgery for skin, such as a tummy tuck, may be a better fit; see [[link: /learn/liposuction-vs-tummy-tuck | liposuction vs tummy tuck]].","## Revision","Some people need a second procedure. Ask in advance whether it is included in the quote, for how long, and what is not covered. A good answer is specific and in writing.","## Reducing risk","- Be honest about your health, medicines, supplements and smoking.","- Check that the surgeon is registered; see [[link: /how-we-verify-surgeons | how we check registration]].","- Follow instructions for garments, movement and review visits. See [[link: /learn/liposuction-recovery-timeline | the recovery timeline]].","- Ask who to call at night.","## Who should wait","People with uncontrolled medical conditions, those with unstable weight, anyone planning pregnancy soon, and anyone who has been told to stop a blood-thinning medicine but has not yet discussed it with their doctor. Also read [[link: /learn/liposuction-candidate | who is a candidate]].","## When to call","> Chest pain, trouble breathing or a swollen, painful calf: go to emergency care.","Call your surgeon the same day for fever, spreading redness, pus, fast one-sided swelling, bleeding that will not stop, or pain that worsens after the first days.","## Questions before you book","Use [[link: /learn/questions-to-ask-your-plastic-surgeon | this checklist]]. See our local pages for [[link: /liposuction-in-gurgaon | Gurgaon]] and [[link: /liposuction-in-delhi | Delhi]] as they go live.","## How common are these problems?","Readers often want a number. We do not give one, because the figures vary between studies, between techniques and between patient groups, and we have not verified a single figure that applies to every case. A good surgeon will describe which problems they see in their own practice and how they handle them. Be wary of anyone who says there are no risks, and of anyone who frightens you without telling you what they would do.","## Smoking and nicotine","If you smoke or use nicotine in any form, including patches and chewing products, tell your surgeon. Nicotine narrows blood vessels and slows healing, and surgeons commonly ask patients to stop for a period around surgery.","[[faq: What are the risks of liposuction? | Bruising, swelling and numbness are expected. Infection, bleeding, fluid collection, uneven contour, loose skin and scars are possible. Clots and other serious problems are rare.]]","[[faq: Is liposuction dangerous? | Any surgery carries risk. Risk depends on your health, the amount of fat removed, the number of areas, the anaesthesia and the surgeon. Ask for the risks that apply to you.]]","If you would like to go through your own questions with a coordinator, message us on WhatsApp. We will not push for a decision.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction. Reviewer to confirm each risk statement.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-vs-tummy-tuck', 'Liposuction vs tummy tuck: which one fits your case', 'Liposuction removes fat. A tummy tuck removes loose skin and tightens muscle. How they differ and when both are combined.', 5, 2, 'liposuction', '["[[reviewer]]","Liposuction removes fat through small cuts. A tummy tuck removes loose skin and can tighten the abdominal muscles, through a longer cut. If your problem is a pocket of fat with firm skin, liposuction is often discussed. If you have loose skin or separated muscles, a tummy tuck is. Some people need both. See our [[link: /liposuction | liposuction page]].","## Side by side","- What is removed: liposuction takes fat. A tummy tuck takes extra skin and sometimes fat, and tightens the muscle layer.","- Cuts: liposuction uses small cuts. A tummy tuck uses a longer cut low on the abdomen, often hidden in underwear lines, and sometimes around the navel.","- Recovery: liposuction recovery is usually shorter. A tummy tuck usually means a longer recovery, more restricted movement and sometimes a drain.","- Scar: tiny scars versus a longer scar line.","- Skin: liposuction does not remove loose skin. A tummy tuck does.","## How to tell which problem you have","Stand relaxed and pinch the belly. If you can pinch a thick fold, and the skin looks firm, fat is the main issue. If the skin hangs or folds even at a steady weight, or the belly bulges forward from weak muscles, a tummy tuck may be the better fit. Muscle separation after pregnancy or major weight loss is a common reason. Only an exam tells you for certain.","## Skin and muscle","Fat removal alone can leave loose skin more visible. Surgeons judge how well skin will shrink. If it likely will not, they may advise a skin operation instead or in addition. Muscle tightening is done only in a tummy tuck, not with liposuction.","## When both are done","Surgeons sometimes combine them: tummy tuck for skin and muscle, and liposuction to contour the flanks or upper abdomen. This lengthens the operation and recovery and adds risk, so the surgeon decides if it is suitable. Ask about limits. We will link to a dedicated page on [[link: /tummy-tuck | tummy tuck]] when it is ready.","## Non-surgical options","Fat freezing, heat devices and similar methods exist. They usually change less per session and do not remove loose skin. See [[link: /learn/liposuction-vs-non-surgical-fat-reduction | how to compare these options]].","## Price and recovery in plain terms","A tummy tuck is generally a larger operation, with more theatre time and a longer stay, so the quote is usually higher than for one area of liposuction. The exact figure depends on the hospital, anaesthesia and what is included. Our [[link: /cost/liposuction | liposuction cost page]] lists the factors, and any quote should be in writing.","## Risks","Both carry the usual surgical risks: bleeding, infection, fluid collection, scars and clots. A tummy tuck adds risks linked to the longer cut and the muscle repair, such as wound healing problems. Liposuction adds contour irregularity. Read [[link: /learn/liposuction-risks | liposuction risks]].","> Do not pick on scar length alone. A smaller scar with the wrong operation can leave you unhappy.","## Who should wait","- Anyone planning pregnancy in the future, as it can change the abdomen again.","- Anyone still losing weight.","- Smokers, until they have stopped.","- Anyone who has not had a proper exam.","Check [[link: /learn/liposuction-candidate | who is a candidate]].","## Questions to ask","- Is my problem fat, skin, muscle or all three?","- Which operation do you recommend, and what would you do if I disagree?","- What scar will I have and where will it sit?","- What if I choose liposuction and the skin does not tighten?","## Two people, two plans","A man in his thirties with a firm belly and a pocket of fat above the belt may do well with liposuction alone. A woman who has had two children, has a loose lower belly and a separation of the muscles may find liposuction does little, and a tummy tuck fits better. A third person lost a lot of weight and has hanging skin everywhere: they may need a different kind of body contouring altogether. The labels \"liposuction\" and \"tummy tuck\" are tools, and the plan comes from the exam.","## Time off work","Plan more leave for a tummy tuck than for liposuction. Many people need around two weeks or more away from a desk job after a tummy tuck, and longer for physical work, but your surgeon sets the real figure. For liposuction the usual range is shorter, as in the [[link: /learn/liposuction-recovery-timeline | recovery timeline]].","[[faq: Liposuction or tummy tuck? | Liposuction suits firm skin with a fat pocket. A tummy tuck suits loose skin or weak muscles. Surgeons sometimes combine them.]]","[[faq: Can I have both together? | Sometimes. The surgeon decides based on your health, how much is planned, and risk.]]","You can message us on WhatsApp to understand how the two are usually quoted, or compare lines in the quote checker.","[[sources: NHS patient information on liposuction and abdominoplasty; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-body-areas', 'Which body areas can liposuction treat?', 'Abdomen, flanks, thighs, hips, back, arms, chest and chin: what each area involves and what changes the price by area.', 4, 3, 'liposuction', '["[[reviewer]]","Liposuction can treat many areas: abdomen, waist and flanks, thighs, hips, buttocks, back, upper arms, chest and the chin and neck. Each behaves differently in how much fat there is, how the skin responds and how recovery feels. The surgeon decides which areas are suitable for you. Our [[link: /liposuction | liposuction page]] has the overview.","## Abdomen","The most requested area. Liposuction helps with a pocket of fat in the lower or upper belly. It does not remove fat around the organs, and it cannot fix loose skin or separated muscles; see [[link: /learn/liposuction-vs-tummy-tuck | liposuction vs tummy tuck]]. The extent of the area treated drives the price.","## Waist and flanks","Often called love handles. This area is often treated along with the abdomen. The number of areas combined is what moves the quote.","## Thighs and hips","Inner thigh, outer thigh and hips. Fat in this region tends to be firmer and can need more time. Volume removed is a main factor. Skin elasticity matters especially on the inner thigh.","## Buttocks","Liposuction can help refine the area around the buttocks, though some people want fat for shaping, and that is a different procedure. Ask the surgeon to explain what is being planned.","## Back","The bra-strap area and upper back. These fat pockets may be fibrous, and surgeons may use certain energy-based tools. Several zones can mean a higher quote.","## Upper arms","The upper arm is a common request. Skin elasticity decides the result. If the skin is loose, liposuction can leave it hanging, and a skin operation may be discussed.","## Chest","In men, chest fat or a mix of fat and gland can be treated. See [[link: /learn/liposuction-for-men | liposuction for men]] for how it relates to gynecomastia.","## Chin and neck","Liposuction under the chin is a smaller procedure, often done with local anaesthetic. [[link: /learn/double-chin-liposuction | The double chin guide]] explains who it suits and what recovery involves.","## What changes the price by area","- How many areas are treated at once.","- The amount of fat to be removed.","- The method used, for example ultrasound-assisted.","- Type of anaesthesia and where it is done.","- Garments, medicines and follow-ups.","Our [[link: /cost/liposuction | cost page]] has sample ranges, marked as such, and a list of what to get in writing.","## How areas are chosen","The surgeon looks at where fat sits, how your skin is, your proportions and your goals. They may recommend treating fewer areas, or treating areas in stages. A good plan is about balance, not just removing from the area you point at.","## Who should wait","People whose weight is changing, those who expect liposuction to tighten loose skin, and anyone with health conditions not yet under control. Wait too if you have a large number of areas in mind and your surgeon has not discussed the limits.","## When to see a doctor","See a doctor for a lump that has appeared recently or that is painful, fat pockets that appear suddenly, or swelling that does not go. Not all lumps are fat.","## Questions to ask","- Which of my areas would respond well and which would not?","- Is it better to treat everything now or in stages?","- Which method for each area, and why?","- How does the quote change if I add or remove an area?","Look at [[link: /learn/types-of-liposuction | the types of liposuction]] to follow the answers.","## Combining areas","Surgeons sometimes treat the abdomen, flanks and back in one session to keep proportions even. The more areas, the longer the operation and the larger the volume of fluid and fat involved, which affects risk and recovery. Many surgeons set a limit per session and may suggest staging.","## Areas that are harder","Inner thighs, upper arms and the lower belly after pregnancy can be harder because of skin and fibrous fat. That does not mean they cannot be treated. It means the surgeon will talk more about skin, and about a plan B if the skin does not tighten. Ask what that plan B would be and what it adds to the quote.","[[faq: Which areas can be treated? | Abdomen, flanks, thighs, hips, buttocks, back, upper arms, chest, and chin and neck, among others. The surgeon decides which suit you.]]","[[faq: Can stomach fat be removed? | Fat under the skin of the belly can be treated. Fat around the organs cannot, and loose skin needs a different approach.]]","If you would like to map out which areas fit your goals, message us on WhatsApp, or put your quote through the quote checker. No pressure at all.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-candidate', 'Who is a candidate for liposuction? What surgeons check', 'Good general health, steady weight, elastic skin and realistic goals. What a surgeon reviews before saying yes or no.', 4, 1, 'liposuction', '["[[reviewer]]","There is no single rule. A surgeon decides after a consultation, looking at your health, medicines, weight, skin and goals. People near a steady, healthy weight with a localised pocket of fat and firm skin are the usual match for the procedure. A number on a chart, such as BMI, is only one input. See our [[link: /liposuction | liposuction guide]].","## What the surgeon is checking","- Health history. Heart, lung, blood pressure, diabetes, clotting problems, previous surgeries.","- Medicines and supplements. Some, such as blood thinners, may need to be paused only on the advice of your own doctor.","- Smoking and alcohol. Both slow healing.","- Weight history. Is your weight steady, and is the fat in a pocket rather than all over?","- Skin quality. Can it shrink back after fat is removed?","- Goals. What exactly do you want to change?","## A typical profile","- An adult in good general health.","- Weight stable for some months.","- Firm, elastic skin.","- One or a few localised pockets.","- Clear and realistic expectations.","- Willing to follow aftercare.","This is a typical picture, not a requirement. People outside it may still be treated, and some people who fit may be told to wait.","## What about BMI?","You may see a number quoted online. A surgeon uses it as a guide to health risk, not a pass or fail mark. We do not give a number here because it varies between surgeons and hospitals, and a widely agreed single cut-off is not something we can verify. Ask your surgeon what they use and why.","## Tests before surgery","Blood tests, sometimes an ECG, and an assessment by the anaesthetist are common. If you have a medical condition, your own doctor may be asked to confirm you are fit. These are not obstacles; they protect you.","## Who should wait","- Weight is still changing.","- You are pregnant, breastfeeding or planning pregnancy soon.","- A health condition is not under control.","- You smoke and have not stopped.","- You want weight loss; see [[link: /learn/liposuction-vs-weight-loss | liposuction is not weight loss]].","- You have a big event soon.","- You feel pressure from someone else, not from yourself.","## When the answer is no","A good surgeon will sometimes say no, or suggest another operation, or advise waiting. If your problem is loose skin, they may point you to [[link: /learn/liposuction-vs-tummy-tuck | a tummy tuck]]. If they say yes to everything without questions, ask for another opinion.","## The consultation","Bring a list of your medicines, past surgeries and questions. Expect an examination, discussion of the plan, a written estimate and time to ask. You should leave knowing the method, the areas, the anaesthesia, the risks that apply to you and what the quote includes. See [[link: /learn/liposuction-risks | the risks guide]].","> You can say no after a consultation. A good clinic expects it.","## Questions for the surgeon","- Am I a candidate today, or should I wait?","- What risks matter most for me?","- What would make you say no?","- What happens if I do not like the result?","Read the list in [[link: /learn/questions-to-ask-your-plastic-surgeon | questions to ask your plastic surgeon]]. See our local pages for [[link: /liposuction-in-lucknow | Lucknow]] and [[link: /liposuction-in-kanpur | Kanpur]] once they are live.","## What to bring to the first visit","- A list of all medicines, vitamins and herbal products, with doses.","- Details of any past operations and reactions to anaesthesia.","- Recent blood test or ECG reports if you have them.","- Photos of your weight history, if you want to show how it has changed.","- A written list of what you want to change and what worries you.","## Family and privacy","Many people bring a relative to the consultation, and that is fine. If you prefer to go alone, that is your right. Ask who will see your photographs and records, and how long they are kept. A clinic should be able to answer this plainly.","[[faq: Who is not a candidate for liposuction? | People with unstable weight, uncontrolled health conditions, those who smoke without plans to stop, those expecting weight loss, and others the surgeon judges unfit. The surgeon decides.]]","[[faq: What BMI is needed? | There is no single figure we can give. The surgeon sets limits for you based on health and the plan.]]","If you want to check whether your situation is likely to need extra tests, message us on WhatsApp. The quote checker can also help you read a written estimate.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-fat-return', 'Can fat come back after liposuction?', 'Treated fat cells are removed, but the body can store fat again. What happens if you gain weight and how to protect the shape.', 4, 2, 'liposuction', '["[[reviewer]]","Fat cells removed by liposuction do not grow back in the same place. But the cells that remain, in treated and untreated areas, can get larger if you gain weight, and the shape can change. So fat can reappear, often unevenly. A steady weight protects the result. More basics are on our [[link: /liposuction | liposuction page]].","## What happens to the fat cells","Liposuction takes out a share of fat cells in the treated area. With fewer cells, that area can hold less fat than before. It is not zero, though. The cells left behind can store more fat if you take in more energy than you burn.","## What happens if you gain weight","Weight gain after surgery tends to show up in a different pattern. Some people notice fat in the treated area, but often it appears more in places that were not treated, such as the upper abdomen, back or arms. The proportions can change, and not in the way you planned. Scars and swelling do not control this; your habits do.","## The visceral fat point","Fat around the organs inside the abdomen is not removed by liposuction. If you gain weight, some goes there, and it matters for health. This is why surgeons discuss lifestyle and not just shape. See also [[link: /learn/liposuction-vs-weight-loss | liposuction is not weight loss]].","## What helps keep the result","- Reach a steady weight before surgery, and stay near it.","- Keep a routine of regular movement you enjoy.","- Eat in a way you can keep for years, not weeks.","- Go to follow-up visits, even when you feel well.","- Avoid crash diets, which can change skin and muscle tone.","There is no trick. The surgeon cannot control what happens after you leave, and it is better to hear that honestly.","## Untreated areas","Areas you did not treat stay as they were. After surgery they may look more noticeable by contrast. Some people choose to treat more areas later; others learn to like the balance. Talk about this during planning; see [[link: /learn/liposuction-body-areas | which areas can be treated]].","## Revision","If a pocket remains or the shape is uneven once swelling has settled, which can take months, a second procedure is sometimes discussed. Ask your surgeon before the first operation how a revision works, when it can be done, and who pays for what.","> Be cautious of any promise that results never change. Bodies change with weight, age and pregnancy.","## Men and chest fat","Men who have liposuction on the chest also need to watch weight and, where relevant, causes of chest tissue; see [[link: /learn/liposuction-for-men | liposuction for men]].","## Who should wait","- Anyone whose weight is moving up or down.","- Anyone who plans to gain weight, for example in a bulking phase or soon after a pregnancy.","- Anyone expecting the surgery to \"fix\" eating habits.","## When to see a doctor","If you see a quick change in shape soon after surgery, such as one-sided swelling, or a firm area that grows, tell your surgeon. Not everything is fat. Rapid weight gain without a clear reason also deserves a check-up with a physician.","## Questions to ask your surgeon","- What weight range would you want me to stay in?","- Which areas are most likely to change if I gain weight?","- How is revision handled, and what does it cost?","- What follow-up is included?","The price of a touch-up varies; see the factors on our [[link: /cost/liposuction | liposuction cost page]].","## Weight, age and hormones","Fat patterns shift over a lifetime. Pregnancy, menopause, long-term stress, sleep loss and some medicines can all change where the body stores fat. None of these means the operation failed. They are reasons to expect that the body will keep changing, and to treat any result as a snapshot that needs maintenance.","## A sensible check-in","Many people find it useful to weigh themselves once a week and measure the treated area once a month for the first year. If weight creeps up by a few kilos, adjust early. Waiting until clothes feel tight makes it harder to correct.","[[faq: Does fat come back after liposuction? | The removed cells do not return, but remaining fat cells can enlarge with weight gain, in treated and untreated areas.]]","[[faq: Will I regain weight? | Not because of the operation. Weight depends on what you eat and how active you are. Large gains can change your shape.]]","If you want to talk about what keeps results steady, message us on WhatsApp. Or compare a quote in the quote checker. We will not rush you.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-compression-garment', 'Compression garment after liposuction: how long to wear it', 'Why surgeons ask you to wear a compression garment, how long it is usually worn, fit, washing, comfort and what to ask about it.', 4, 3, 'liposuction', '["[[reviewer]]","A compression garment is a tight, elastic piece of clothing worn after liposuction to control swelling and support the skin. It is usually put on right after surgery and worn day and night for the first weeks. How long exactly is the surgeon''s decision. Ask what is in your quote. The wider recovery picture is in [[link: /learn/liposuction-recovery-timeline | the recovery timeline]].","## What it does","After liposuction, fluid collects in the treated area. A garment applies even pressure, which can reduce swelling and bruising, support the skin as it settles and lower the chance of a fluid pocket. It also helps you feel held together in the first days. Doctors differ on how much it improves the final shape, so ask why your surgeon wants it.","## When it starts","Usually in theatre or straight after, over the dressings. In the first few days you may wear it almost all the time, taking it off only when the surgeon allows, for example for a short wash.","## How long to wear it","This varies by surgeon, area and how you heal. Many surgeons say a few weeks of near-constant wear, then a period of part-time wear. We do not give a fixed number of weeks because only your surgeon can do so. Write down the instruction you were given, and ask for it in writing.","## Fit","It should be snug and even, not painful. Signs it is too tight: numb or tingling skin, a feeling of being short of breath, deep marks or skin bulging at the edges. Signs it is too loose: it slides, rolls or bunches. A garment that rolls into a band can cause its own marks. Ask for a fitting before surgery, and request a second size if swelling changes.","## Washing and skin care","- Own at least two garments so one can be washed while you wear the other.","- Wash as instructed, usually by hand with mild soap, and dry flat away from direct heat.","- Keep the skin underneath clean and dry, and use a thin cotton layer if the surgeon allows it.","- Watch for rashes or blisters and tell your clinic.","## Heat and comfort","In hot cities such as Delhi or Lucknow, a tight garment in summer can be sweaty and itchy. Choose breathable fabric, change the garment when damp, and plan your surgery date around the weather if possible. Do not loosen it on your own to feel cooler.","## Is it mandatory?","Most surgeons recommend one, but it is the surgeon''s call. If you do not wear it, you may have more swelling or a higher chance of a fluid pocket. Do not skip it because it is uncomfortable. Tell the clinic about problems, and they can help.","> A garment is not a substitute for rest. Wearing it does not mean you can go back to the gym early.","## What to ask for in the quote","- How many garments are included, and which type?","- Is a fitting included?","- Who pays if I need a second size?","- Are medicines and dressings included?","See the quote lines to compare on our [[link: /cost/liposuction | liposuction cost page]].","## Who should wait","If you cannot wear a tight garment for the planned weeks, because of work uniforms, a skin condition or heat, discuss it with the surgeon before booking. Do not buy a garment online without advice.","## When to call the doctor","- numbness, tingling or colour change under the garment","- a rash, blister or open skin","- swelling at the edge that is growing","- breathlessness or pain that is getting worse","For the longer list, read [[link: /learn/liposuction-risks | liposuction risks]].","## Practical tips from the first week","Put on a clean garment after each wash, and have a spare ready in advance. If skin under the edge itches, ask the clinic about a soft liner instead of scratching. Take care in the toilet: a tight garment can be awkward, so choose a design with a gusset or opening if the clinic stocks one. Keep the area clean and dry after showers, and do not use heat pads on treated skin.","## Related reading","Early movement affects swelling too. Read the [[link: /learn/liposuction-recovery-timeline | recovery timeline]] for what to do each week, and [[link: /learn/liposuction-body-areas | the guide to body areas]] to see how garments differ by area.","[[faq: How long to wear a compression garment? | Usually for several weeks, with near-constant wear at first. Your surgeon sets the time for your areas.]]","[[faq: Is it mandatory? | Most surgeons advise it. Ask your surgeon what happens if you do not wear it.]]","If you want to check how garments are counted in a quote, message us on WhatsApp, or use the quote checker. Take your time.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction. Garment duration to be confirmed by the reviewer.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('double-chin-liposuction', 'Double chin liposuction: who it suits and recovery', 'Liposuction under the chin removes fat below the jawline. Who it suits, what recovery involves, and other causes of a double chin.', 4, 1, 'liposuction', '["[[reviewer]]","Yes, a double chin made of fat can be treated with liposuction. A small cut under the chin lets the surgeon remove fat below the jawline, and recovery is usually shorter than for body areas. It works well with good skin tone. If the problem is loose skin, muscle bands or the jaw shape, other options fit better.","See our [[link: /liposuction | liposuction page]].","## What is treated","The fat sits between the skin and the neck muscle under the chin. A thin tube is passed through one or two tiny cuts, and the fat is suctioned out. Sometimes the surgeon works under local anaesthetic with or without sedation; others use general anaesthesia. It is among the smaller liposuction procedures; see [[link: /learn/liposuction-body-areas | all treatable areas]].","## Who it suits","- Adults with a localised fat pad under the chin.","- People whose skin is still firm and elastic.","- Those at a steady weight.","- Those in good general health.","The jaw and neck shape also matter. A recessed chin, a low hyoid bone or heavy neck muscles can create a similar look that fat removal will not fix.","## What else can cause it","A double chin is not always fat. Common causes:","- loose skin with age","- muscle bands in the neck","- the shape of the jaw and chin","- weight gain","- an enlarged thyroid or lymph glands, which need a doctor","If you notice a lump, swelling that is new, or difficulty swallowing, see a doctor first.","## Technique","Most of the technique is similar to other liposuction: solution, then thin tubes. Some surgeons use energy-based tools to help the skin; see [[link: /learn/types-of-liposuction | types of liposuction]]. In some people, skin tightening or a neck-lift procedure is discussed alongside or instead.","## Recovery","- Day 0 to 3: swelling and a tight feeling, bruising under the chin. You may wear a chin strap or garment.","- Week 1: swelling peaks and then eases. Many people return to desk work in a few days to a week, depending on bruising and how comfortable they are with it showing.","- Weeks 2 to 4: bruises fade, and the neck may feel firm or numb.","- Months: the contour keeps refining.","Your surgeon will tell you how long to wear a garment and when to restart exercise. See [[link: /learn/liposuction-compression-garment | the garment guide]].","## Risks","Bruising, swelling, numbness and uneven contour are the usual concerns. Rare problems include injury to a small nerve that controls part of the lower lip, skin damage, infection and bleeding. Choose a surgeon who does this regularly and ask how they handle complications. More in [[link: /learn/liposuction-risks | liposuction risks]].","> The skin under the chin is thin. Too much removal can leave a hollow, so a careful surgeon takes less rather than more.","## Price drivers","The main ones are the technique, whether skin work is added, anaesthesia, hospital type and follow-up. Sample figures, marked as such, appear on our [[link: /cost/liposuction | liposuction cost page]].","## Who should wait","People with a changing weight, those with mostly loose skin, and anyone with an unexplained neck lump. Also wait if you have a big event in the next few weeks, because bruising can last.","## Questions to ask","- Is my double chin mostly fat, skin or structure?","- Is liposuction enough or will I need something more?","- Which anaesthesia do you plan?","- What does the quote cover?","Compare with other approaches in [[link: /learn/liposuction-vs-non-surgical-fat-reduction | non-surgical fat reduction]].","## Planning around a visible recovery","A bruised neck is hard to hide. If you work in front of customers or on camera, consider a collared shirt or scarf in the first week, and avoid booking surgery just before an important meeting. Sleeping with your head raised for the first nights can reduce swelling.","## Staying realistic","A surgeon can change the fat pad but not the bones. If you want a sharper jawline, tell the surgeon exactly what you have in mind and ask them to show on your own face what is possible and what is not. A frank answer is worth more than a promise.","[[faq: Can a double chin be removed by liposuction? | If it is mostly fat, yes. If it comes from loose skin, muscle bands or the jaw shape, liposuction alone may not give the change you want.]]","If you are not sure which type you have, message us on WhatsApp and we will tell you what to ask a surgeon, or use the quote checker.","[[sources: NHS patient information on liposuction; Mayo Clinic patient information on liposuction.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-vs-non-surgical-fat-reduction', 'Fat freezing, laser, RF or liposuction: how to compare', 'Non-surgical fat reduction and liposuction work in different ways. A plain way to compare them, with no made-up claims.', 5, 2, 'liposuction', '["[[reviewer]]","Non-surgical methods such as fat freezing, laser, radiofrequency, injections and muscle stimulation usually change less per session than liposuction and are not meant for large amounts of fat. Liposuction removes fat directly in one operation. We do not claim one is better. We give you the questions to compare them. See our [[link: /liposuction | liposuction page]].","## What each method does, in plain words","- Fat freezing: a device cools the fat in a pinched fold until the cells are damaged, and the body clears them over weeks.","- Laser: heat from a laser applied through the skin aims to damage fat cells.","- Radiofrequency: radio waves heat the tissue, and are often used for skin tightening and fat reduction.","- Injections: a substance injected into small pockets, such as under the chin, aims to break down fat.","- Muscle stimulation: electrical pulses make the muscle contract, aiming to build muscle and reduce fat.","- Liposuction: fat is removed with a thin tube. See [[link: /learn/types-of-liposuction | the types of liposuction]].","Each has different devices, brands and rules. We do not compare them with numbers here, because we cannot verify a single set of figures that applies to all of them.","## What surgery does differently","Liposuction takes a measured amount of fat out in one sitting under anaesthesia. That is why recovery involves swelling, garments and rest. Non-surgical methods usually involve no cuts and little downtime, but often need several sessions and can give a smaller change.","## How to compare","Ask the same questions of every option:","- How much change is typical for someone like me? Ask to see how the clinic measures it.","- How many sessions, and what is the total price for the course?","- What are the risks, including less common ones?","- Who performs it, and what are their qualifications?","- What if I am not happy at the end?","- Does it suit my skin? Do I have loose skin that none of these will tighten?","## Risks are not zero","Non-surgical does not mean risk-free. Burns, pain, skin changes, uneven results and, with some methods, hardened tissue are reported. Surgery has its own set; see [[link: /learn/liposuction-risks | liposuction risks]]. Be cautious about any clinic that says there is no downside.","## Price","Many sessions can add up to a sum similar to surgery, and the change can be smaller. Others cost less for small pockets. Always ask for the total course price in writing, and compare with the factors on our [[link: /cost/liposuction | liposuction cost page]].","## Where each fits","A small pocket in someone near a steady weight, who does not want surgery, may try a non-surgical method first. A bigger pocket, or a wish for a clear change in one go, is usually discussed with liposuction. Loose skin may need neither; see [[link: /learn/liposuction-vs-tummy-tuck | liposuction vs tummy tuck]]. Under the chin, see [[link: /learn/double-chin-liposuction | the double chin guide]].","> Pay attention to how a clinic talks about results. Specific, measured language is a good sign. Vague promises are not.","## Who should wait","If your weight is changing, wait. If you are pregnant or breastfeeding, wait. If you have a medical condition, a skin condition or an implanted device, ask your doctor before any heat-based or electrical method.","## When to see a doctor","See a doctor for a lump that is new, painful or growing, since not every fullness is fat. Also seek advice if a treated area becomes red, blistered or very painful.","## Fair question to ask any clinic","\"If I came to you for a second opinion with a quote from another clinic, how would you read it?\" Good clinics will answer honestly.","## A note on marketing language","Phrases like \"no downtime\", \"melts fat\" or \"tightens skin\" are advertising words, not medical measurements. Ask what the clinic means in days, weeks or centimetres, and how they measure it. If the answer is a photo, ask whether the lighting, posture and time between pictures were the same. A fair clinic will explain, and will tell you if your body is not a good match for the method.","[[faq: Is fat freezing better than liposuction? | They work differently. Fat freezing is non-surgical and usually changes less per session. Liposuction removes more in one operation but involves surgery. The right choice depends on your body and goals.]]","If you would like help weighing two quotes, message us on WhatsApp or use the quote checker. It is your decision.","[[sources: NHS patient information on cosmetic procedures; Mayo Clinic patient information on liposuction. No comparative data is cited here.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('liposuction-for-men', 'Liposuction for men: chest, abdomen and love handles', 'Men use liposuction too. What it treats on the chest, belly and sides, how it differs from gynecomastia surgery, and what to expect.', 5, 3, 'liposuction', '["[[reviewer]]","Liposuction is not only for women. Men commonly have it for the chest, abdomen and flanks. Fat in these areas can persist despite diet and training. If a firm gland sits behind the nipple, it is gynecomastia and may need gland removal as well. A doctor tells which you have. See our [[link: /liposuction | liposuction page]].","## Where men store fat","Men tend to carry fat around the abdomen, the sides of the waist and the chest. Some of it is visceral fat inside the abdomen, which liposuction cannot reach. The soft layer under the skin is what the operation treats.","## Chest fat","A soft, wide fullness of the chest can be fat alone, called [[link: /learn/pseudogynecomastia | pseudogynecomastia]]. Liposuction through small cuts at the side of the chest is a common plan. The surgeon may use an energy-based tool for firmer fat in men; see [[link: /learn/types-of-liposuction | the types]].","## When it is gynecomastia and not only fat","If there is a firm, rubbery disc behind the nipple, or tenderness, the tissue is gland. Liposuction alone may leave part of it behind. The plan then often combines liposuction with gland removal. Read [[link: /learn/gynecomastia-liposuction-vs-gland-removal | how that plan is chosen]] and our [[link: /gynecomastia-surgery | gynecomastia surgery page]].","Can liposuction fix \"man boobs\"? Only if they are fat. Many men have a mix, so a clinical exam matters. See [[link: /learn/gynecomastia-fat-or-gland | fat or gland]].","## Abdomen and flanks","Men often ask about a rounded belly and \"love handles\". If the skin is firm and the fat sits under it, liposuction may help. If the abdomen is large because of fat around the organs, liposuction will not shrink it, and the doctor may advise weight management first. Loose skin after big weight loss needs another approach; see [[link: /learn/liposuction-vs-tummy-tuck | liposuction vs tummy tuck]].","## Recovery","Similar to other liposuction: soreness, swelling and bruising, a compression garment, and gradual return to routine. Men who train hard often want to know when they can lift. Your surgeon gives dates for each area, and chest or abdominal work usually comes back later than walking. See [[link: /learn/liposuction-recovery-timeline | the recovery timeline]] and the [[link: /learn/liposuction-compression-garment | garment guide]].","## Risks","Bruising, swelling, numbness, uneven contour, fluid collection, infection and loose skin are possible. Steroid and supplement use matter, because they affect hormones and the chest. Say so honestly. See [[link: /learn/gynecomastia-gym-steroids | the gym and steroid guide]] and [[link: /learn/liposuction-risks | liposuction risks]].","> Surgery on the chest does not stop the cause. If a medicine or steroid is behind it, the tissue can return.","## Price","The area, amount of fat, method and anaesthesia change the quote. Our [[link: /cost/liposuction | liposuction cost page]] lists the factors, and any figure there is a labelled sample.","## Who should wait","- Anyone whose weight is changing.","- Men in a bulking or cutting phase.","- Those with a recent chest change that has not been checked.","- Men planning a competition within weeks.","## When to see a doctor first","A hard lump on one side, nipple discharge, skin dimpling or a fast change in the chest should be checked before any surgery planning.","## Questions to ask","- Is my chest fat, gland, or both?","- Which method will you use and why?","- Will liposuction leave gland tissue behind?","- What is in the quote, and what is not?","## Common questions men ask","Will people be able to tell? Garments are worn under clothes, and the first week is the most visible, with swelling and bruising. How soon can I train? That depends on the area, and chest or abdominal work usually waits the longest. Will it affect my fitness? A short break is normal, and your surgeon will give a plan for returning. Can I eat normally? Usually yes, in moderation, once the anaesthesia has worn off.","## Privacy and comfort","Many men feel awkward discussing their chest or belly. A good clinic will examine you in private, explain each step, and let you bring someone if you wish. You can ask to speak to a male or female doctor if that matters to you, though availability varies.","[[faq: Can liposuction fix man boobs? | If the fullness is fat, liposuction can reduce it. If there is gland tissue, gland removal is usually needed too. A doctor checks which you have.]]","[[faq: Is liposuction only for women? | No. Men have liposuction for the chest, abdomen and flanks.]]","To talk through your own chest or belly, message us on WhatsApp, or use the quote checker if you already have an estimate. No pressure.","[[sources: NHS patient information on liposuction and gynaecomastia; Mayo Clinic patient information on liposuction and gynecomastia.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-10', '2026-11-10', null, null),
  ('acne-grades-when-to-see-doctor', 'Acne grades: when pimples need a dermatologist', 'How doctors describe mild, moderate and severe acne, which signs need a visit this week, and what a first appointment covers.', 5, 1, 'acne-treatment', '["[[reviewer]]","Doctors usually describe acne as mild, moderate or severe, based on the kind of spots and how many there are. Blackheads and a few small pimples are mild. Many red, swollen spots, or deep painful lumps, are moderate to severe and should be seen by a doctor. This guide supports our [[link: /acne-treatment | acne treatment overview]].","## The usual grades","Systems differ between doctors, so treat the list below as a plain-language guide and not as a diagnosis.","- Mild: mostly blackheads and whiteheads, with a few small red pimples.","- Moderate: more red spots, many with pus, spread over the face and sometimes the chest or back.","- Moderately severe: many inflamed spots and some deep lumps.","- Severe: large, painful lumps (nodules or cysts) that can leave marks. These often appear on the jaw, back and chest too.","The number of spots is only part of the picture. A doctor also asks how long the acne has lasted, whether it comes back after treatment, and whether it leaves marks.","## Blackheads, pimples and cysts","A blackhead is a blocked pore that stays open at the surface. A whitehead stays closed. A pimple with pus is a red spot with a white or yellow tip. A cyst or nodule sits deeper, feels hard or tender, and may last weeks. Deep lumps are the type most likely to scar, so they are the ones not to squeeze or leave alone for months.","## Signs that need a doctor this week","- Painful, deep lumps that keep returning in the same place.","- Acne that began suddenly in adulthood, or after a new medicine or supplement.","- Fever, spreading redness or pus that looks like an infection.","- Acne together with irregular periods or excess facial or body hair in women.","- Dark marks or pits that are appearing after the pimples heal.","Pharmacy creams for a few small spots are common. If there is no change after several weeks, or the acne is getting worse, an examination gives you a plan that fits your skin.","## What a first visit covers","The doctor looks at your face, back and chest, asks how long this has been going on, and asks about medicines, supplements, skin products and family history. Women may be asked about periods and pregnancy plans, because some acne medicines cannot be used in pregnancy. You may leave with creams, a tablet, or a plan to review in a few weeks. Ask what each item is for and how long you should use it before judging it.","> A grade describes how acne looks today. It does not predict how long treatment will take or how your skin will respond.","## Who should wait","Do not start a new tablet, peel or light session until a doctor has seen you if you are pregnant or planning pregnancy, or if you have an infected, very sore area. A doctor may also ask you to pause some skin products before a procedure.","## Questions worth asking","- Which grade or type of acne do you think I have?","- Do I need tests before any tablet?","- How many visits should I plan for, and how often?","- What will treatment cost for the first three months? Our [[link: /cost/acne-treatment | cost page]] lists the lines to ask about.","[[faq: How many grades of acne are there? | Different doctors use different scales. Most patients hear mild, moderate or severe, sometimes with a fourth step between moderate and severe. Ask which scale your doctor uses.]]","[[faq: Can I treat cystic acne with a pharmacy cream? | Deep lumps often need a prescription plan and a review. Creams alone may not be enough, and squeezing can leave marks. A dermatologist can advise.]]","[[faq: Should I see a dermatologist or a general physician? | Both can see acne. A dermatologist has more training in skin conditions, which helps when acne is moderate or severe, keeps returning or leaves marks.]]","Related reading: [[link: /learn/acne-medicines-doctors-prescribe | acne medicines explained]] and [[link: /learn/acne-peels-light-laser | peels and light for acne]]. If you are planning visits, see how a course is organised in [[link: /acne-treatment-in-delhi | Delhi]] and [[link: /acne-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor. We do not diagnose or prescribe.","[[sources: NHS patient information on acne; American Academy of Dermatology patient information on acne. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('acne-medicines-doctors-prescribe', 'Acne medicines doctors prescribe, explained', 'The main groups of acne medicines, why some are time-limited, what needs a prescription, and the mistakes that slow progress.', 6, 2, 'acne-treatment', '["[[reviewer]]","Doctors usually prescribe acne medicine in groups: creams or gels used on the skin, antibiotics for a limited time, hormone-related tablets for some women, and isotretinoin for severe or stubborn acne. Which group suits you depends on the type of acne and your health. This guide names classes only. Our [[link: /acne-treatment | acne treatment overview]] explains the wider plan.","## Creams and gels","Most plans start here. Doctors use several types, each with a different job.","- Retinoid creams help unblock pores and are usually used at night. They can cause dryness and peeling in the first weeks.","- Benzoyl peroxide reduces the bacteria that feed inflamed spots. It can bleach fabric and dry the skin.","- Topical antibiotics are often combined with another ingredient so bacteria are less likely to adapt.","- Azelaic acid is sometimes used when marks or sensitive skin are a concern.","Some creams are sold without a prescription and some are not. A doctor can say which ones to combine, since stacking several strong products can burn the skin.","## Antibiotic tablets and why they are time-limited","Doctors sometimes add an antibiotic tablet for moderate or inflamed acne. The course is usually kept as short as the plan allows, because long use can make bacteria resistant and can cause side effects. Ask how long you should take it and what to expect when it ends. Many doctors pair a tablet with a cream that continues after the tablet stops.","## Hormone-related options for some women","When acne follows a pattern, such as a monthly flare along the jaw, a doctor may talk about hormone-related medicines. They are decided case by case and need questions about periods, pregnancy plans and medical history. They are not suitable for everyone. If you have irregular cycles, tell the doctor, who may ask for tests.","## Isotretinoin","Isotretinoin is a strong prescription tablet used for severe acne or acne that has not responded to other plans. It needs pregnancy prevention, regular follow-up and sometimes blood tests. We cover the questions to ask in [[link: /learn/isotretinoin-acne-questions | our isotretinoin guide]].","## What needs a prescription","Antibiotic tablets, hormone-related medicines and isotretinoin are prescription medicines. Do not buy them without one, and do not share a friend''s strip. A prescription also gives a doctor the chance to check allergies and other medicines you take.","> Medicines in this guide are described by group only. Names, doses and timing are decided by a registered doctor who has examined you.","## Common mistakes","- Stopping early when the skin looks better, then seeing acne return.","- Switching creams every week. Most products need weeks before you can judge them.","- Using many strong products at once.","- Skipping sunscreen while using drying creams or tablets.","- Picking at spots, which can leave marks.","## Who should wait","Tell the doctor first if you are pregnant, planning pregnancy or breastfeeding. Some acne medicines can harm an unborn baby. Also mention liver or kidney conditions, other medicines and any past reaction to antibiotics.","## Questions worth asking","- What is each product for, and when do I apply it?","- How many weeks before we judge whether it helps?","- What side effects should make me call you?","- How much will the first three months of medicines cost? Use our [[link: /cost/acne-treatment | acne cost page]] as a checklist.","[[faq: Which tablet is used for acne? | There is no single choice. The right medicine depends on the acne type, your health, pregnancy plans and what you tried before. A doctor decides after an examination.]]","[[faq: How long do acne medicines take to work? | Many people wait several weeks before a clear change, and some skin gets worse briefly at first. Your doctor sets a review date. TODO-VERIFY: reviewer range.]]","[[faq: Can I stop once the pimples are gone? | Not without asking. Stopping early is a common reason acne returns. Doctors often plan a gradual change to a maintenance routine.]]","Related reading: [[link: /learn/how-long-acne-treatment-takes | how long acne treatment takes]], [[link: /learn/adult-hormonal-acne-women | adult acne in women]] and [[link: /learn/fungal-acne-vs-bacterial-acne | fungal and bacterial acne]]. City guides: [[link: /acne-treatment-in-lucknow | Lucknow]] and [[link: /acne-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor. We do not prescribe.","[[sources: NHS patient information on acne treatments; British Association of Dermatologists patient information leaflets on acne. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('isotretinoin-acne-questions', 'Isotretinoin for acne: questions to ask your doctor', 'What isotretinoin is, who doctors consider it for, the pregnancy rules, the checks during treatment, and why you need a prescription.', 6, 3, 'acne-treatment', '["[[reviewer]]","Isotretinoin is a strong prescription tablet that doctors consider for severe acne, or for acne that returns after other plans. It carries serious risks, including harm to an unborn baby, so it needs pregnancy prevention, check-ups and sometimes blood tests. Only a registered doctor can decide if it suits you. See our wider [[link: /acne-treatment | acne treatment guide]].","## What it is","Isotretinoin is a vitamin A related medicine. It reduces oil production in the skin and affects how pores clog. Doctors usually consider it for severe nodular acne, acne that leaves marks, or acne that has not improved with other plans.","## Who doctors consider it for","A doctor may raise the option when acne is deep and painful, scarring, or returning after other treatments. Age, weight, pregnancy plans, liver health, mood history and other medicines all enter the decision. A teenager and a parent usually make the decision with the doctor together.","## Pregnancy rules","This is the most important point. Isotretinoin can cause serious birth defects. Women who could become pregnant are usually asked for a negative pregnancy test before starting, regular tests during treatment, and reliable contraception for a period set by the doctor. Tell the doctor straight away if you think you may be pregnant. Men are usually told to ask about the rules that apply to them.","## Checks during treatment","Doctors often ask for blood tests, for example liver and blood fat levels, before and during treatment. Your visits are not optional extras. They are how the doctor spots a problem early. TODO-VERIFY: reviewer confirms which tests and how often.","## Common effects","- Dry lips and skin, sometimes dry eyes or a dry nose.","- Sun sensitivity, so sunscreen and shade matter.","- Muscle or joint aches in some people.","- A flare of acne in the first weeks for some.","Report severe headache, vision changes, stomach pain, yellowing of the skin or eyes, or any thoughts of self-harm to the doctor or emergency services without delay.","## Mood","Some people report low mood while taking it. Evidence on the link is debated, and doctors still ask about mood before and during treatment. Tell family or friends what you are taking so they can notice changes. If you feel very low or have thoughts of harming yourself, seek urgent help.","## Why you need a prescription","Do not buy isotretinoin from an online seller or a friend. A product with no prescription has no check on pregnancy, liver health or your other medicines, and you cannot be sure what is inside. A doctor can also plan what to avoid, such as waxing or some peels, during treatment.","> This page gives questions to ask. It does not give a dose or a reason to start or stop any medicine.","## Who should wait","Wait and talk to a doctor if you are pregnant, planning pregnancy or breastfeeding, or have liver disease, high blood fat levels or a history of depression. Also tell the doctor about vitamin A supplements and other medicines.","## Questions to ask your doctor","- Why is this the right option for my acne?","- What pregnancy test and contraception rules apply to me?","- Which blood tests do I need, and when?","- What side effects should I report, and who do I call after hours?","- Can I have a peel, laser or waxing during treatment? See [[link: /learn/acne-peels-light-laser | peels and light for acne]].","- What will visits and tests add to the cost? Our [[link: /cost/acne-treatment | cost page]] lists items to ask about.","[[faq: Is isotretinoin the same as a normal antibiotic? | No. It is a different type of medicine with different risks and checks. Antibiotics are described in our guide to acne medicines.]]","[[faq: Will acne come back after isotretinoin? | It can. Some people need another plan later. Ask your doctor what maintenance routine to use afterwards.]]","[[faq: Can I take it without a prescription if I use a low amount? | No. Using it without a doctor skips the pregnancy and blood checks and is not advised.]]","Related reading: [[link: /learn/how-long-acne-treatment-takes | how long acne treatment takes]]. Visit planning: [[link: /acne-treatment-in-delhi | Delhi]], [[link: /acne-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor. We do not prescribe.","[[sources: British Association of Dermatologists patient information leaflet on isotretinoin; NHS patient information on isotretinoin. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('fungal-acne-vs-bacterial-acne', 'Fungal acne vs bacterial acne: how doctors tell', 'Why itchy, uniform bumps can be a yeast related condition and not ordinary acne, how doctors check, and why the wrong cream can make it worse.', 5, 2, 'acne-treatment', '["[[reviewer]]","Some small, itchy, same-size bumps on the forehead, chest or back are caused by yeast living in hair follicles, and are often called fungal acne. Doctors call it Malassezia folliculitis. Ordinary acne is driven by oil, clogged pores and bacteria. A doctor can tell them apart by examination, which matters because they need different treatment. See the main [[link: /acne-treatment | acne treatment guide]].","## Why the difference matters","Ordinary acne medicines target oil, blocked pores and bacteria. Antibiotics can reduce yeast competitors on the skin, so a long antibiotic course may leave yeast-related bumps worse. A cream that suits one type can do little for the other. That is why a guess from a photo is risky.","## Clues doctors look for","- Bumps that are all about the same size.","- Itching, which is less common in ordinary acne.","- Spots on the forehead, upper back, chest or shoulders.","- Bumps that flare with sweat, humid weather or tight clothes.","- Acne that gets worse during an antibiotic course.","- No blackheads, which are usual in ordinary acne.","These clues point towards a possibility. They do not confirm it, and both conditions can occur together.","## How a doctor checks","The doctor looks closely and asks about itching, sweating, medicines and how the spots reacted to earlier treatment. A skin scraping or swab may be used to look for yeast under a microscope. Sometimes the doctor starts a trial of treatment and reviews the response. You may be asked to bring the creams you have used.","## Why the wrong plan backfires","Using ordinary acne creams repeatedly on yeast-related bumps may do nothing, and thick moisturisers or oily products can feed the yeast. Skipping a diagnosis can mean months of treatment that does not match the cause. Strong steroid creams can also thin the skin and make the problem worse. Do not apply a steroid cream to your face without advice.","> If bumps are itchy, uniform and not responding to acne creams after a few weeks, ask a doctor whether another cause is possible.","## Treatment in outline","Plans for yeast-related folliculitis often use medicated washes or antifungal medicines chosen by the doctor, with attention to sweat and tight clothing. TODO-VERIFY: reviewer confirms wording. Do not start antifungal tablets without a prescription.","## What to bring to the visit","Bring a list of every cream, wash and tablet you have used, with rough dates. Note when the bumps started, whether they itch, and whether they change with sweating or after workouts. Photos taken in daylight every week or two help the doctor see how the spots have behaved.","## Who should wait","Do not begin a peel, laser or strong acid on bumps you have not had examined. See a doctor soon if there is fever, spreading redness, pus or pain. Anyone with diabetes or a weak immune system should have new rashes checked early.","## Questions worth asking","- Do you think this is ordinary acne, a yeast-related problem, or both?","- Do I need a scraping or swab?","- Which of my current products should I stop?","- How many weeks before we review?","[[faq: Is fungal acne really acne? | The name is used by many people, but it is a different condition from ordinary acne. It involves yeast in hair follicles, which is why doctors use a different term.]]","[[faq: Can I diagnose fungal acne at home? | No. The signs overlap with ordinary acne and other rashes. A doctor can check and decide whether tests are needed.]]","[[faq: Will it come back? | Yeast-related bumps can return, especially with sweat and heat. Ask your doctor how to lower the chance of a repeat.]]","Related reading: [[link: /learn/acne-grades-when-to-see-doctor | acne grades and when to see a doctor]] and [[link: /learn/acne-medicines-doctors-prescribe | acne medicines explained]]. Cost lines for visits are on the [[link: /cost/acne-treatment | acne cost page]]; city pages for [[link: /acne-treatment-in-lucknow | Lucknow]] and [[link: /acne-treatment-in-kanpur | Kanpur]] cover follow-up planning.","Message us on WhatsApp if you want help preparing questions for a registered doctor. We do not diagnose.","[[sources: American Academy of Dermatology patient information on folliculitis; NHS patient information on acne. TODO-VERIFY: open each page and confirm that Malassezia folliculitis is covered.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('adult-hormonal-acne-women', 'Adult and hormonal acne in women: what to check', 'Why acne can appear after 25, the jawline pattern doctors mention, when tests are asked for, and what to tell the doctor about pregnancy plans.', 5, 3, 'acne-treatment', '["[[reviewer]]","Acne after 25 is common in women. It often sits along the jaw and chin and may flare around periods. A doctor checks your skin, asks about periods and pregnancy plans, and decides whether any tests are needed before choosing treatment. Many plans use creams first. See our [[link: /acne-treatment | acne treatment guide]] for the full picture.","## Why acne appears or continues in adulthood","Acne is linked to oil production, clogged pores, bacteria and inflammation. Hormone changes can add to the oil, which is one reason many women see flares before periods. Other contributors a doctor may discuss include certain medicines, some skin and hair products, and family history. Stress and poor sleep are often mentioned, and the evidence that they directly cause acne is limited. TODO-VERIFY: reviewer sets evidence level.","## The pattern doctors notice","Deep, tender spots on the jawline, chin and lower cheeks that come and go with the cycle are a typical description. A doctor still examines the face, because other conditions such as rosacea or folliculitis look similar. If you have only occasional pimples, no tests may be needed.","## When tests are asked for","A doctor may suggest tests if acne comes with irregular periods, excess facial or body hair, hair thinning, or sudden onset. These signs can point to a hormone condition such as polycystic ovary syndrome (PCOS), which has its own plan. Tests are advised by a doctor, based on your symptoms. Do not order hormone panels on your own without a doctor reviewing the results, since normal ranges depend on age and timing in the cycle.","## Pregnancy and medicines","If you are pregnant or planning to be, tell the doctor first. Some acne medicines, including strong tablets, are not used in pregnancy. Your doctor may choose a different plan, and may advise on contraception while treatment runs. Breastfeeding also changes the choices. Our [[link: /learn/acne-medicines-doctors-prescribe | guide to acne medicines]] lists the groups in plain terms, and the [[link: /learn/isotretinoin-acne-questions | isotretinoin guide]] covers the pregnancy rules in more detail.","## What daily routine helps","- A gentle wash twice a day, without scrubbing.","- A light moisturiser and sunscreen.","- Not squeezing deep spots.","- Checking cosmetics and hair oils that sit on the forehead and jawline.","- Sleeping and eating at regular times, which may help overall health even if the direct effect on acne is unclear.","> Hormone-related acne is common, and a doctor may look at the pattern before choosing a plan.","## Planning visits","Most plans need a review after several weeks, so ask how often you will be seen and whether some reviews can be done by video. Keep the list of products you use, because some cosmetics and hair oils can add to breakouts along the hairline and jaw.","## Who should wait","Do not start any tablet, peel or light session without telling the doctor about pregnancy plans. Anyone with a sudden severe flare, fever or spreading redness should be seen promptly.","## Questions worth asking","- Do my periods or other symptoms suggest tests?","- Which options fit if I plan a pregnancy in the next year?","- How many months should I follow this plan before we review?","- What will visits and any tests cost? See the [[link: /cost/acne-treatment | acne cost page]].","[[faq: Is adult acne different from teenage acne? | The spots look similar, but adult acne often sits lower on the face and may flare with the cycle. The treatment plan depends on skin type, pregnancy plans and other health factors.]]","[[faq: Do I need a hormone test for acne? | Not always. A doctor usually asks when there are other signs such as irregular periods or excess hair.]]","[[faq: Can I use acne medicines if I might get pregnant? | Some cannot be used. Tell your doctor about pregnancy plans before any prescription.]]","Related reading: [[link: /learn/how-long-acne-treatment-takes | how long acne treatment takes]]. Local planning: [[link: /acne-treatment-in-gurgaon | Gurgaon]] and [[link: /acne-treatment-in-delhi | Delhi]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: NHS patient information on acne; NHS patient information on polycystic ovary syndrome. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('acne-peels-light-laser', 'Chemical peels and light for acne: what they can do', 'Where peels, light sessions and lasers may help acne, where they do not, the pigment risk in darker skin, and how they fit with tablets.', 6, 1, 'acne-treatment', '["[[reviewer]]","Chemical peels and light-based sessions are sometimes added to an acne plan to help with clogged pores, marks or inflammation. They do not replace the creams or tablets a doctor prescribes, and results vary. Risks include redness, flaking and dark marks, which are more of a concern in darker skin. See our [[link: /acne-treatment | acne treatment guide]].","## Where a procedure may help","Doctors sometimes use a superficial peel for blackheads, whiteheads and mild marks. Light-based devices, including blue light, are used for some inflamed acne. Lasers are used by some doctors for marks and scars, and are covered with scars in [[link: /learn/acne-scar-types-treatment | our scar guide]]. Evidence differs by method and by person, and a reviewer will set the final wording. TODO-VERIFY.","## Where they do not help","A procedure does not remove the cause of acne, and acne can return. Deep cysts usually need a medical plan first. A peel on actively infected or very sore skin can make things worse. Do not expect one session to change your skin.","## Sessions and spacing","Doctors commonly plan a series of sessions some weeks apart. The number depends on your skin, the method and your response. TODO-VERIFY: reviewer sets any range. Ask for the number of sessions, the gap between them and the review point in writing.","## What a visit looks like","The doctor examines the skin, asks about medicines and recent sun, and may do a small patch test. The skin is cleaned, the peel or device is applied for a set time, and the skin is cooled or neutralised as needed. Redness and a tight feeling are common. Flaking can follow for several days, depending on the strength.","## Darker skin and pigment risk","Indian skin tones can develop dark patches after irritation, called post-inflammatory hyperpigmentation. Strong peels and some devices raise this risk. Many doctors choose gentler settings or different methods. Ask how the doctor adjusts the plan for your skin tone and what they would do if marks appear.","## Timing with tablets","Some acne tablets make the skin more fragile. Doctors often ask people to wait a set time after certain tablets before a peel or laser. Do not decide the interval yourself. If you are taking isotretinoin, see [[link: /learn/isotretinoin-acne-questions | our isotretinoin guide]] and ask the prescribing doctor before any procedure.","> Never have a peel or laser on skin that is sunburnt, infected or newly irritated.","## What the cost lines look like","Quotes usually list the consultation, each session, any numbing or cooling, products for aftercare and follow-up visits. Our [[link: /cost/acne-treatment | cost page]] shows the lines to ask about in writing. Packs with many sessions need a clear refund and exit policy before you pay.","## Who should wait","Pregnancy, active infection, cold sores, recent sun exposure or tanning, a tendency to form thick scars, and recent strong tablets are all reasons to ask a doctor before starting.","## Questions worth asking","- Why this method for my skin, and what else could I use?","- What are the risks for my skin tone?","- Who performs the session, and with what training?","- What do I do if my skin reacts?","[[faq: Can a chemical peel treat acne? | A peel may help some people as part of a plan, but it is not a stand-alone answer. Acne can return, and a doctor decides what suits your skin.]]","[[faq: Is laser better than a peel for acne? | They do different jobs. Peels and light sessions are used for different problems, and one is not better in general. Ask which fits your goal.]]","[[faq: How soon can I wear makeup after a peel? | It depends on the peel. Your doctor gives instructions on timing and products.]]","Related reading: [[link: /hydrafacial | hydrafacial, a skin-care session that does not treat acne]], [[link: /learn/hydrafacial-vs-peel-vs-microdermabrasion | hydrafacial, peel and microdermabrasion compared]]. City pages: [[link: /acne-treatment-in-lucknow | Lucknow]], [[link: /acne-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on acne treatment; NHS patient information on acne. TODO-VERIFY: confirm device and peel statements with the reviewer.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('acne-scar-types-treatment', 'Acne scars: types and when treatment makes sense', 'The difference between dark marks and true scars, the main scar shapes, why active acne comes first, and how doctors describe options.', 6, 2, 'acne-treatment', '["[[reviewer]]","Acne can leave two different problems. Flat dark or red marks usually fade over months. True scars are dents or raised areas in the skin and are slower to change. Doctors treat active acne first, then look at scars, and results vary with the scar type and skin. See our [[link: /acne-treatment | acne treatment guide]].","## Marks and scars are different","A flat brown or red mark is a pigment or blood-vessel change left after a pimple heals. It is not a dent. Many fade slowly, and sunscreen helps stop them getting darker. A scar involves the skin''s structure. It can be pitted or raised, and it does not fade on its own in the same way.","## Scar types doctors describe","- Rolling scars: shallow, wide dips with sloping edges.","- Boxcar scars: round or oval dents with sharp edges.","- Ice pick scars: narrow, deep, pit-like marks.","- Raised scars: thick lumps, more common on the jawline, chest and back. Keloid tendency runs in some families.","Many people have more than one type, which is why a doctor examines the skin under light and by touch before suggesting a plan.","## Treat active acne first","New pimples create new marks, so most doctors start by controlling acne. Treating scars while acne is active can waste money and may irritate the skin. See [[link: /learn/how-long-acne-treatment-takes | how long acne treatment takes]] for a realistic timeline.","## Options in plain terms","Doctors describe several options, and a plan often combines them. TODO-VERIFY: reviewer confirms each description.","- Chemical peels for surface texture and marks.","- Microneedling, using tiny needles to prompt skin changes.","- Laser or light-based devices, with settings adjusted for skin tone.","- Small procedures such as subcision, which releases the tissue under a dented scar.","- Fillers for some soft dents, temporary and used by selected doctors.","- Injections or other methods for raised scars, decided by a doctor.","Each has risks, including redness, dark marks, infection and uneven results. In darker skin, some devices raise the chance of pigment change. A doctor can explain how the method is adjusted.","## What results depend on","Scar type, depth, age of scars, skin tone, how many sessions you can attend and how well aftercare is followed all matter. Many scars improve in look without disappearing. Ask what level of change is realistic for your scars and how it will be judged. Before-and-after photos from one clinic cannot predict your result.","> A scar plan is a set of options over months. It is not a single procedure with a fixed outcome.","## What it costs","Scar plans usually run as courses. Quotes differ because of the method, the number of sessions, the device and who performs them. Our [[link: /cost/acne-treatment | cost page]] shows the lines to compare, and the city pages for [[link: /acne-treatment-in-delhi | Delhi]] and [[link: /acne-treatment-in-gurgaon | Gurgaon]] cover follow-up planning.","## Who should wait","Wait if acne is active, if your skin is sunburnt or infected, if you took isotretinoin recently, or if you are pregnant. Anyone with a history of thick scarring should tell the doctor before any needle or laser.","## Questions worth asking","- Which of my scars are dents and which are marks?","- What would you try first, and what is the plan if my skin reacts?","- How many sessions, and what does each cost?","[[faq: Can acne scars be removed? | Treatment can change how scars look, often partly. Doctors rarely promise that a scar will disappear. Ask what is realistic for your type.]]","[[faq: Do dark marks need treatment? | Many fade with time and sun protection. A doctor can suggest options if they stay or worry you.]]","[[faq: Can I squeeze pimples to avoid marks? | Squeezing raises the chance of marks and infection. Leave deep spots to a doctor.]]","Related reading: [[link: /learn/acne-peels-light-laser | peels and light for acne]], [[link: /learn/acne-grades-when-to-see-doctor | acne grades]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on acne scars; NHS patient information on scars. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('how-long-acne-treatment-takes', 'How long acne treatment takes and why acne returns', 'A realistic week-by-week picture of acne treatment, why a flare can come first, why acne returns, and when to ask a doctor to change the plan.', 6, 3, 'acne-treatment', '["[[reviewer]]","Acne treatment is usually a course of months, not weeks. Many plans show a first change after several weeks, and some skin gets worse briefly at the start. Acne can return when treatment stops, so doctors often plan a maintenance routine. Results vary. See our [[link: /acne-treatment | acne treatment guide]] for the options. TODO-VERIFY: reviewer sets the ranges below.","## A rough timeline","- Weeks 1 to 2: creams can cause dryness, stinging or peeling. Some people see a flare. Doctors often ask you to keep going unless it is severe.","- Weeks 4 to 6: a review visit. The doctor checks whether spots are fewer and decides whether to continue or change.","- Around month 3: many plans reach a clearer picture of what is working. Marks may still be visible even where new spots slow down.","- After that: some people move to a lighter maintenance routine, others need a longer plan.","The pattern differs by acne type and medicine. Deep cystic acne often takes longer than mild acne, and doctors may adjust the plan more than once.","## Why the first weeks can feel worse","Retinoid creams and some other medicines clear blocked pores that were already forming under the skin. That can bring a short flare. It does not always mean the treatment is wrong, and it should not be ignored if the skin is very sore. Call your doctor if irritation is severe or spreading.","## Why acne returns","Treatment controls the factors behind acne. It does not change your skin for good, so spots can come back when treatment stops. Triggers doctors discuss include hormone changes, some medicines, heavy products on the skin, and stopping creams too early. Seasonal sweat and heat can also play a part. If acne returns, tell the doctor early, since a short plan change may be enough.","## Food and face wash myths","Evidence that food directly causes acne is mixed, and some studies link high-sugar diets and some dairy to flares in some people. TODO-VERIFY: reviewer sets evidence wording. Scrubbing and frequent face-washing can irritate the skin and make acne worse. A gentle wash twice a day is enough for most people. Home pastes and lemon on the skin can burn, and they are not advised.","## When to ask for a change","- No improvement after the period your doctor set.","- Side effects you cannot manage.","- New marks forming faster than old ones fade.","- You are pregnant, or planning to be.","Doctors may change the medicine, adjust the strength or add a procedure. See [[link: /learn/acne-medicines-doctors-prescribe | acne medicines explained]] and [[link: /learn/acne-peels-light-laser | peels and light for acne]].","> A plan that is reviewed on a schedule is easier to judge than one that is changed whenever the skin has a bad week.","## Planning the visits and the cost","Count the consultation, follow-up visits, medicines per month and any procedures. Our [[link: /cost/acne-treatment | cost page]] has a simple way to add these up. If you live outside a big city, ask how follow-ups can be arranged, for example by video, and which visits must be in person. Our pages for [[link: /acne-treatment-in-lucknow | Lucknow]] and [[link: /acne-treatment-in-kanpur | Kanpur]] cover travel planning.","## Who should wait","Pregnant women and those planning pregnancy should talk to a doctor before any acne medicine. Anyone with a very sore, infected or rapidly spreading flare should be seen quickly.","[[faq: How many months does acne treatment take? | Many plans last several months and some last longer. Your doctor sets a review date and changes the plan if needed.]]","[[faq: Why did my acne come back after I stopped? | The causes behind acne can continue after treatment ends. Ask your doctor about a maintenance plan.]]","[[faq: Is it normal for acne to get worse at first? | Some people see a short flare with certain medicines. Tell your doctor if it is severe or lasts longer than expected.]]","Related reading: [[link: /learn/adult-hormonal-acne-women | adult acne in women]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: NHS patient information on acne; American Academy of Dermatology patient information on acne. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-vs-regular-facial', 'Hydrafacial vs a regular facial: the real differences', 'How a hydrafacial session differs from a standard facial in steps, time and cost drivers, and who might prefer which. No claim that one is better.', 5, 1, 'hydrafacial', '["[[reviewer]]","A hydrafacial uses a handheld device to cleanse, exfoliate and loosen blocked pores, then applies a serum. A regular facial is done mostly by hand with creams, steam and massage. Both are skin-care sessions, and neither treats acne or scars. The choice depends on your skin, time and budget. See our [[link: /hydrafacial | hydrafacial overview]].","## The steps side by side","A hydrafacial session usually runs in a fixed order, often cleansing, a mild acid exfoliation, suction to clear pores, and a serum. A regular facial often includes cleansing, steam, manual extractions, a mask and massage. Clinics vary, so ask for the exact steps in writing. TODO-VERIFY: reviewer confirms the standard step order.","- Cleansing: both start with it.","- Exfoliation: a hydrafacial uses a device and a solution. A regular facial may use a scrub or acid, depending on the clinic.","- Pore clearing: a hydrafacial uses suction. A regular facial usually uses hands or tools.","- Serums and masks: both may include them, and quality and ingredients differ between places.","- Massage: more common in a regular facial.","## What each is meant to do","Both aim to leave the skin feeling cleaner and look fresher for a short time. A hydrafacial is often chosen by people who want a shorter session with a device. A regular facial suits those who want a longer, relaxing session. Neither changes skin structure, and neither replaces a doctor''s plan for acne or pigment.","## Time and cost drivers","Sessions often run from about 30 to 60 minutes. TODO-VERIFY: reviewer confirms. Price depends on the device, the serum or booster, who performs the session, add-ons such as LED or lymphatic steps, and the city. Our [[link: /cost/hydrafacial | hydrafacial cost page]] lists the lines to ask for. Compare quotes line by line. Our [[link: /learn/read-hydrafacial-quote | guide to reading a quote]] shows how.","## Who might prefer which","- People with sensitive or reactive skin may prefer a gentler, shorter facial. Ask a doctor first if skin is very reactive.","- People who want a quick session before an event may like a device-based session, with a trial well before the date. See [[link: /learn/hydrafacial-before-wedding-timing | timing before a wedding]].","- People who enjoy longer sessions with massage may prefer a regular facial.","Neither is better in general. If a salon or clinic tells you one is, ask what that claim is based on.","## Risks that apply to both","Redness, stinging, breakouts after the session and allergic reactions to products can occur. Unclean tools raise the risk of infection. Pink skin can last a few hours. See [[link: /learn/hydrafacial-side-effects-who-should-skip | side effects and who should skip it]].","> If you have active acne, a skin disease or you are unsure about a product, see a dermatologist before any facial.","## Who should wait","Wait if you have sunburn, open sores, a cold sore, an active skin infection, or irritated skin from new acids. Pregnant women should ask their doctor first. If you took isotretinoin recently, ask the prescribing doctor how long to wait.","## Questions worth asking","- Who will perform my session and with what training?","- Which products touch my face, and are tips and tools single use or cleaned between clients?","- What add-ons are included, and which cost extra?","- What happens if my skin reacts?","[[faq: Is a hydrafacial the same as a regular facial? | No. Both clean the skin, but a hydrafacial uses a handheld device for exfoliation and pore clearing, while a regular facial is mostly manual. Steps differ between places.]]","[[faq: Which is better for oily skin? | Neither is better in general. Ask a skin doctor, since oily and acne-prone skin can react to some products.]]","[[faq: Which costs more? | A hydrafacial often costs more because of the device and consumables, but quotes vary a lot. Ask for a written list of what is included.]]","Related reading: [[link: /learn/hydrafacial-vs-peel-vs-microdermabrasion | hydrafacial, peel and microdermabrasion compared]]. City guides: [[link: /hydrafacial-in-delhi | Delhi]] and [[link: /hydrafacial-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin care and facials; NHS patient information on skin care. TODO-VERIFY: open each page and confirm that facials are covered.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-acne-prone-skin', 'Hydrafacial for acne-prone skin: what to expect', 'What a hydrafacial can and cannot do when you get pimples, why breakouts can follow a session, and when to see a dermatologist first.', 5, 2, 'hydrafacial', '["[[reviewer]]","A hydrafacial does not treat acne. It is a skin-care session that cleans pores and exfoliates the surface, and some clinics provide it for oily or acne-prone skin. If you have active, inflamed or painful acne, see a dermatologist first. Breakouts can follow a session. See our [[link: /hydrafacial | hydrafacial overview]] and the [[link: /acne-treatment | acne treatment guide]].","## Active acne and old marks","Inflamed spots, pus and painful lumps need a medical plan. Facial devices can irritate them. Old marks and blocked pores on otherwise calm skin are what a hydrafacial can touch at the surface, and the change is mostly in how the skin looks and feels for a short time. Dark marks and scars need other approaches, covered in [[link: /learn/acne-scar-types-treatment | our scar guide]].","## Extractions have limits","Many sessions include suction or manual extraction of blocked pores. Deep cysts cannot be extracted this way, and squeezing them can make marks worse. A trained person should decide what to extract and what to leave.","## Why a breakout can follow","Some people see new spots a few days after a session. Possible reasons include irritation, a product that blocks pores for that person, or a coincidence with their own acne cycle. TODO-VERIFY: reviewer confirms wording. If it happens, stop new products and tell the clinic. A doctor can advise if it keeps happening.","## When to see a dermatologist first","- Painful, deep or spreading spots.","- Acne that is getting worse or leaving marks.","- You are using prescription acne medicines.","- You are pregnant or planning pregnancy.","- The skin is very dry, sore or peeling from acne creams.","A dermatologist can decide whether a session is sensible, delay it, or advise another method. See [[link: /learn/acne-peels-light-laser | peels and light for acne]] for procedures doctors discuss for acne.","## Isotretinoin and timing","If you have taken isotretinoin, ask the prescribing doctor when facial procedures can restart. Doctors set the interval, and it can be many weeks or longer. TODO-VERIFY: reviewer sets the wording. Do not rely on a clinic''s general answer.","## What a sensible visit looks like","The person checks your skin before starting, asks about medicines and recent products, and tells you which steps they will skip. They use clean or single-use tips and explain what to avoid afterwards, such as the sun and strong acids for a few days. They do not promise any particular skin outcome.","> A hydrafacial is not an acne treatment. Do not use it in place of a doctor''s plan.","## Aftercare for oily and acne-prone skin","Use a gentle cleanser and a plain moisturiser, and wear sunscreen. Avoid scrubs and strong acids for the days the clinic advises. Do not pick at spots, and do not apply new products on the same day.","## Cost","A session is usually priced per visit, with extra charges for boosters. Do not buy a large pack until you have seen how your skin reacts to one session. Our [[link: /cost/hydrafacial | cost page]] lists the lines to ask about.","## Who should wait","Wait if there is an infection, a cold sore, sunburn or very sore acne. Anyone pregnant should check with a doctor first.","[[faq: Can I get a hydrafacial with active pimples? | Some clinics do it on mild breakouts, and many advise waiting if spots are inflamed or painful. A dermatologist can decide for your skin.]]","[[faq: Will a hydrafacial clear my acne? | No. It is a skin-care session and not an acne treatment.]]","[[faq: Can I have one while taking acne tablets? | Ask your prescribing doctor first. Some medicines make skin fragile.]]","Related reading: [[link: /learn/hydrafacial-side-effects-who-should-skip | hydrafacial side effects]] and [[link: /learn/acne-grades-when-to-see-doctor | acne grades]]. City guides: [[link: /hydrafacial-in-lucknow | Lucknow]], [[link: /hydrafacial-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on acne; NHS patient information on acne. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-side-effects-who-should-skip', 'Hydrafacial side effects and who should skip it', 'Common effects such as pink skin and stinging, less common problems such as breakouts and allergy, who should skip it, aftercare and red flags.', 5, 3, 'hydrafacial', '["[[reviewer]]","The most common effects of a hydrafacial are pink skin and mild stinging that settle within hours to a day or two. Less often, people see breakouts, allergic reactions or a cold sore flare. People with sunburn, infection or sore acne should skip it. This is a general guide, and your doctor''s advice overrides it. See our [[link: /hydrafacial | hydrafacial overview]].","## Common effects","- Pink or red skin for a few hours.","- Stinging or warmth during or just after the session.","- A tight or dry feeling for a day or two.","- Mild sensitivity to the sun.","TODO-VERIFY: reviewer confirms the time window. Many people return to normal routines the same day, though redness can be visible. It is wise not to plan an important event for the same evening on the first visit.","## Less common problems","- A breakout after the session.","- An allergic reaction to a serum, such as itching, swelling or rash.","- A cold sore flare in people who get them.","- Pigment change on skin that was irritated.","- Infection, if tools are not cleaned or single use.","- Burns or bruising from poor device handling, which are rare.","## Who should skip it","- Sunburnt or very irritated skin.","- Open sores, cold sores or any skin infection in the area.","- Recent use of strong acids or retinoids, unless your doctor says it is fine.","- Recent laser or peel.","- Isotretinoin in the last months. The prescribing doctor sets the interval.","- Pregnancy, unless a doctor says it is fine.","- Skin conditions such as eczema or rosacea in a flare, without a doctor''s advice.","- Known allergy to an ingredient in the serum.","Ask for a patch test if your skin reacts easily. See [[link: /learn/hydrafacial-acne-prone-skin | hydrafacial and acne-prone skin]].","## Aftercare","Use a gentle cleanser and plain moisturiser, wear sunscreen and avoid sun exposure. Skip strong acids and scrubs for the days the clinic names. Keep your hands off your face. Avoid heat, steam rooms and heavy exercise for the period your clinic advises. TODO-VERIFY: reviewer confirms the list.","## Red flags to act on","- Swelling of the lips, face or throat, or trouble breathing. This needs emergency care.","- Blisters, severe pain or skin that turns dark or grey.","- Pus, spreading redness or fever.","- A reaction that gets worse after the first day.","Contact the clinic and a doctor without delay if any of these occur.","> A session should never be rushed. If a person pushes you to skip a skin check, you can say no.","## Who performs it","Ask whether the session is done by a doctor, nurse or trained technician, and how they handle tips and tools. Do not assume a technician is a doctor. Our [[link: /hydrafacial | hub]] has a checklist for choosing a clinic.","## Cost of a reaction","Ask what happens if your skin reacts. Does the clinic include a review visit, and is it free or charged? Add this to your written quote. See [[link: /cost/hydrafacial | the cost page]].","## Who should wait","Anyone with an active infection, sunburn or pregnancy question should hold off, and so should those who have taken isotretinoin recently, until a doctor says it is fine.","[[faq: Is there downtime after a hydrafacial? | Most people go about their day, but pink skin and sensitivity can last for hours or longer. Plan for some redness.]]","[[faq: Does it hurt? | Many describe a mild tingling or suction feeling, and sensitive skin may sting. Sensations vary.]]","[[faq: Can I wear makeup afterwards? | Many clinics suggest waiting some hours. Follow the instructions you are given.]]","Related reading: [[link: /learn/how-often-hydrafacial | how often to have a hydrafacial]], [[link: /learn/hydrafacial-indian-skin-pigmentation | hydrafacial on Indian skin]]. City guides: [[link: /hydrafacial-in-delhi | Delhi]] and [[link: /hydrafacial-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin care and cosmetic procedures; NHS patient information on skin reactions. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('how-often-hydrafacial', 'How often can you get a hydrafacial?', 'Why clinics suggest different gaps between sessions, what skin type and active products change, and how to avoid pack pressure.', 5, 1, 'hydrafacial', '["[[reviewer]]","There is no single schedule for a hydrafacial. Clinics suggest gaps that range from a few weeks to a few months, and the right gap depends on your skin, your other products and how your skin reacted last time. A dermatologist can advise. Treat any fixed monthly plan with care. See our [[link: /hydrafacial | hydrafacial overview]]. TODO-VERIFY: reviewer sets any interval and labels it as opinion.","## Why advice differs","There is little agreed guidance on how often a hydrafacial should be repeated, so the interval often reflects the clinic''s habit. Skin that is oily and tolerant may handle more frequent sessions than skin that is dry or sensitive. If a clinic quotes an interval, ask what it is based on.","## What changes the gap","- Skin type and how it reacted to the last session.","- Use of retinoids, acids or peels at home. These already exfoliate, and extra exfoliation can irritate.","- Sun exposure and tanning.","- Season and humidity, which affect dryness.","- Your goal. A one-off session before an event is different from a regular routine.","## Retinoids and acids","If you use a retinoid or a strong acid, tell the person before the session. Some doctors ask you to pause these for a few days before and after. Do not stop prescribed medicine on your own. Ask the prescribing doctor.","## What a review visit checks","After a first session, ask for a quick review of how your skin responded. Redness that lasted longer than expected, breakouts or dryness all mean the gap should be longer, or the plan should change. A good clinic adjusts the plan, and does not push the same schedule.","## Pack pressure","Packs of three or six sessions are common, and they can lower the price per session. They can also lock you into sessions you do not need. Ask these questions before you pay:","- Can I use the sessions over a longer period?","- What happens if my skin reacts and I should stop?","- Is there a written refund or exit policy?","- Is the booster or serum the same in every session?","Our [[link: /learn/read-hydrafacial-quote | guide to reading a quote]] explains packs line by line. If you feel pressed to decide on the spot, you can leave and come back.","## Cost over a year","Multiply the price per session by the number of sessions you actually plan to have in a year. Add products and any add-ons. Our [[link: /cost/hydrafacial | cost page]] shows the lines to ask about, and the city pages for [[link: /hydrafacial-in-lucknow | Lucknow]] and [[link: /hydrafacial-in-kanpur | Kanpur]] show local sample ranges once confirmed.","> A hydrafacial does not need to be repeated to keep the skin healthy. Sun protection and a gentle routine matter more day to day.","## Who should wait","Do not book repeat sessions if your skin is irritated, sunburnt or infected, or if you have started new strong products. Ask a doctor first if you are pregnant or took isotretinoin recently.","## Questions worth asking","- What gap do you suggest for my skin, and why?","- What would make you advise a longer gap?","- Do I need a booster each time, and what does it cost?","[[faq: Can I have a hydrafacial every week? | Most clinics do not suggest this. Frequent exfoliation can irritate the skin. Ask your skin doctor.]]","[[faq: Is monthly the standard? | Some clinics suggest it, but there is no single standard. The right gap varies by person.]]","[[faq: Do I need a doctor to decide? | For sensitive skin, active acne or medicines, a dermatologist can advise. For routine sessions, a trained professional should check your skin before every visit.]]","Related reading: [[link: /learn/hydrafacial-side-effects-who-should-skip | side effects and who should skip it]], [[link: /learn/hydrafacial-vs-regular-facial | hydrafacial vs a regular facial]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin care; NHS patient information on skin care. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-vs-peel-vs-microdermabrasion', 'Hydrafacial vs chemical peel vs microdermabrasion', 'A plain comparison of what each procedure does, downtime, risks and who it suits, so you can pick by goal and ask better questions.', 5, 2, 'hydrafacial', '["[[reviewer]]","A hydrafacial, a chemical peel and microdermabrasion all exfoliate the skin, but they work differently and carry different downtime and risks. A hydrafacial is the gentlest of the three for most people, and a peel can go deeper. Which suits you depends on your goal and your skin. This guide compares them in plain terms. See our [[link: /hydrafacial | hydrafacial overview]].","## What each one does","- Hydrafacial: a device exfoliates and clears pores with suction and a serum is applied. It is a surface skin-care session.","- Chemical peel: an acid solution is applied to loosen the top layers of skin. Strength ranges from light to deep, and a doctor chooses it. TODO-VERIFY: reviewer confirms wording.","- Microdermabrasion: a device removes the outer layer by abrasion, using fine particles or a diamond-tipped head, along with suction.","## Downtime","A hydrafacial often leaves pink skin for hours. A light peel can cause redness and flaking for several days, and stronger peels take longer. Microdermabrasion can leave the skin pink or tender for a day or so. TODO-VERIFY: the reviewer sets the ranges. Plan any big event with a gap, and do a trial first.","## Risks","All three can cause redness, stinging, dryness and sun sensitivity. Peels carry a higher chance of burns and dark marks, especially in darker skin, if the strength is wrong. Abrasive methods can irritate the skin if used too hard. See [[link: /learn/hydrafacial-indian-skin-pigmentation | hydrafacial on Indian skin]] for pigment concerns.","## Who each suits","- Hydrafacial: people who want a gentle, short skin-care session and have no active skin disease.","- Chemical peel: people whose doctor suggests it for a specific concern such as surface texture or marks. A doctor should assess the skin first, and may advise a gentler method. See [[link: /learn/acne-peels-light-laser | peels for acne]].","- Microdermabrasion: people with tolerant skin who want surface smoothing. It is less suited to active acne, very sensitive skin or darker skin with a tendency to pigment change, unless a doctor agrees.","## Picking by goal","- A routine skin-care session: a hydrafacial or a regular facial.","- Surface texture or marks that bother you: ask a dermatologist what a peel or other method might do.","- Active acne: a doctor''s plan first. See our [[link: /acne-treatment | acne treatment guide]].","- Pigment such as melasma: a dermatologist, since irritation can make it worse.","None of these methods stops ageing or removes scars. Results vary, and one session usually makes a small change.","## What to ask about cost","Ask what the price includes, how many sessions are needed, and what the product is. Peels are often priced per session by strength, and devices by session plus add-ons. Our [[link: /cost/hydrafacial | cost page]] has a line-by-line checklist.","> Do not choose by the machine name. Choose by what a doctor thinks your skin needs.","## Who should wait","Do not have any of these on sunburnt, infected or newly irritated skin. Pregnant women should ask a doctor first, and people who took isotretinoin recently should wait for the interval their doctor sets.","## Questions worth asking","- Why this method for my skin and my goal?","- What are the risks for my skin tone?","- How many sessions, and how far apart?","- What do I do if my skin reacts?","[[faq: Which is stronger, a peel or a hydrafacial? | A peel can reach deeper layers and carries a higher chance of flaking and pigment change. A hydrafacial is milder for most people.]]","[[faq: Can I combine them in one visit? | Some clinics do. Doing more at once raises the chance of irritation, so ask the doctor if this is wise for your skin.]]","[[faq: Is microdermabrasion the same as a hydrafacial? | No. Microdermabrasion uses abrasion to remove surface skin, and a hydrafacial uses a different device with suction and serums.]]","Related reading: [[link: /learn/hydrafacial-vs-regular-facial | hydrafacial vs a regular facial]]. City guides: [[link: /hydrafacial-in-delhi | Delhi]], [[link: /hydrafacial-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on chemical peels and microdermabrasion; NHS patient information on skin care. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-before-wedding-timing', 'Hydrafacial before a wedding: how many days to plan', 'How far ahead to try a session, how long redness can last, what to avoid before and after, and why a trial visit comes first.', 5, 3, 'hydrafacial', '["[[reviewer]]","Plan the first hydrafacial well before a wedding, at least a few weeks ahead, so you can see how your skin reacts. A session close to the event is a risk if your skin turns out to be sensitive. Redness is common for hours, and some people react for longer. Your dermatologist can set the timing. See our [[link: /hydrafacial | hydrafacial overview]]. TODO-VERIFY: reviewer sets the timing wording.","## Why a trial matters","Skin responds differently from person to person. A trial session tells you how long redness lasts, whether you get a breakout, and whether a serum irritates your skin. Do not try a new device session in the week before an event. If you already know your skin tolerates it, a short gap may be reasonable, but ask the person doing it.","## A simple timeline","- Several weeks before: book a skin check and a first session if you have never had one.","- About two weeks before: if the first session went well, a second can be planned. Ask how long to leave between sessions.","- The week before: avoid new products, scrubs, waxing on the face, threading in new areas and strong acids unless your doctor advises.","- Day of the event: keep skin care simple.","TODO-VERIFY: the reviewer confirms the gaps and sets any day count.","## What to avoid before","- Sunburn and tanning. Sun makes skin more reactive and harder to treat.","- New products, especially acids and retinoids.","- Other procedures such as peels or lasers near the same date.","- Squeezing spots, which can leave marks that show in photos.","## What to avoid after","Skip strong acids, scrubs, saunas and heavy exercise for the days your clinic names. Use sunscreen and plain moisturiser. Avoid trying new makeup the same day if your skin looks sensitive. If a product stings, wash it off.","## Makeup and photos","Pink skin can show through makeup. Bring your own tested products to your trial visit, and ask how soon you can use them. If you are using a makeup artist, tell them what you had done and when. Do not have a session on the day before photographs unless you know how your skin behaves.","## What not to expect","A single session is not going to change skin tone, scars or pigment. It can leave skin looking cleaner for a short time. Do not pay for a large bridal pack on the promise of a particular look. See [[link: /learn/how-often-hydrafacial | how often to have a hydrafacial]].","> The week before a wedding is the wrong time to find out your skin reacts to something new.","## Cost planning","Add the trial session, the pre-event session and any boosters. Ask for a written total before you pay. Our [[link: /cost/hydrafacial | cost page]] lists the lines to compare and [[link: /learn/read-hydrafacial-quote | our quote guide]] shows red flags.","## Who should wait","Skip a session if you have sunburn, a cold sore, an infection, or you are pregnant and not sure. People with acne or pigment concerns should see a dermatologist first. See [[link: /learn/hydrafacial-side-effects-who-should-skip | who should skip it]].","[[faq: How many days before an event should I have a hydrafacial? | There is no single number. Many people plan a trial weeks ahead and any later session with a gap that suits their skin. Ask your doctor.]]","[[faq: Can I have one the day before? | It is not advised for a first time. Redness or sensitivity can still be there.]]","[[faq: Will it make my skin look better in photos? | It can make skin look cleaner for a short time. Results vary.]]","Related reading: [[link: /learn/hydrafacial-vs-regular-facial | hydrafacial vs a regular facial]]. City guides: [[link: /hydrafacial-in-lucknow | Lucknow]] and [[link: /hydrafacial-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin care; NHS patient information on sun protection. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hydrafacial-indian-skin-pigmentation', 'Hydrafacial on Indian skin: tan, pigment and melasma', 'What a surface skin-care session can touch, why melasma needs a dermatologist, the sun rules that matter, and how irritation can darken skin.', 5, 1, 'hydrafacial', '["[[reviewer]]","A hydrafacial works on the surface of the skin. It can make skin look cleaner and may lift some surface tan for a short time, but it does not treat melasma or deep pigment. Irritation can make dark patches worse in some Indian skin tones, so ask a dermatologist first if you have pigment concerns. See our [[link: /hydrafacial | hydrafacial overview]].","## What it can touch","Surface dullness and light tan sit in the outer layer of skin. Exfoliation can remove some dead cells, which may improve how the skin looks for a short time. TODO-VERIFY: reviewer confirms wording. The change is usually small and does not last without sun protection.","## What needs a dermatologist","Melasma, which appears as brown patches on the cheeks, forehead and upper lip, is driven by factors including hormones and sun, and tends to return. It needs a doctor''s assessment. Post-acne marks, freckles, and dark patches from other causes can look similar, and a doctor can tell them apart. Do not rely on a facial for these.","## How irritation darkens skin","Skin that is irritated, burned or inflamed can produce extra pigment as it heals, called post-inflammatory hyperpigmentation. This happens more easily in medium to dark skin tones. A harsh scrub, a strong acid, or a session on sunburnt skin can set it off. If a session leaves lasting redness, avoid further exfoliation until a doctor has seen it.","## Sun rules that matter","- Use a broad-spectrum sunscreen every day, and reapply when outdoors.","- Cover up in strong sun and avoid peak hours when you can.","- Avoid sunbeds and tanning.","- Do not have a session on skin that is sunburnt or freshly tanned.","Sun protection often matters more than any single session for how pigment behaves.","## Products to be careful with","Some skin-lightening creams sold without a prescription contain strong steroids or other ingredients that can harm the skin. Ask a doctor before using one. Do not apply home remedies such as lemon on the face, since they can burn. Tell the person doing your hydrafacial about every product you use.","## What a good visit includes","A skin check, a question about melasma or pigment history, a patch test if your skin reacts easily, and a clear plan for sun protection afterwards. If the person promises to lighten skin or remove pigment, take it as a warning.","> A facial can make skin look cleaner. It is not a treatment for pigment disorders.","## Cost","Sessions are priced per visit, and doctor-led plans for pigment have their own costs. Our [[link: /cost/hydrafacial | hydrafacial cost page]] lists what to ask, and the [[link: /acne-treatment | acne treatment guide]] covers marks after pimples.","## Who should wait","Wait if you are sunburnt, if the skin is irritated, or if you have an active melasma flare that is under treatment, until your dermatologist agrees. Pregnant women should ask their doctor first, since melasma is common in pregnancy and many products are not advised.","## Questions worth asking","- Is this skin patch melasma or something else?","- How will you adjust the session for my skin tone?","- What do I do if my skin darkens afterwards?","[[faq: Can a hydrafacial remove tan? | It can remove some surface tan for a short time. Sun exposure brings it back, so sun protection matters.]]","[[faq: Is it suitable for melasma? | A dermatologist should decide. Irritation can make melasma worse.]]","[[faq: Can a hydrafacial make my skin darker? | Irritation, burns or sun exposure after a session can lead to dark marks in some people. Tell the clinic if you see changes.]]","Related reading: [[link: /learn/hydrafacial-side-effects-who-should-skip | hydrafacial side effects]], [[link: /learn/hydrafacial-acne-prone-skin | hydrafacial and acne-prone skin]]. City guides: [[link: /hydrafacial-in-delhi | Delhi]], [[link: /hydrafacial-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on melasma and sun protection; NHS patient information on sun protection. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('read-hydrafacial-quote', 'How to read a hydrafacial quote: serums, add-ons, packs', 'What a base session covers, how boosters and add-ons change the total, how to work out the per-session price of a pack, and red flags to watch.', 5, 2, 'hydrafacial', '["[[reviewer]]","A hydrafacial quote should list the base session, any booster serum, add-on steps, consumables and follow-up in separate lines, with a total in writing. Two quotes can look far apart because one includes more steps than the other. Divide any pack price by the number of sessions to compare. See our [[link: /cost/hydrafacial | hydrafacial cost page]] and [[link: /hydrafacial | overview]].","## Base session and boosters","The base session is the standard cleansing, exfoliation and serum. A booster is an extra serum applied for a specific purpose. Ask what the booster is meant to do, what it contains, and whether you need it at all. A booster is optional for most people, and the price can add a lot.","## Add-ons","Some clinics add steps such as LED light, lymphatic massage or extra masks. Each should have its own price. Ask which add-ons are included in the base price, and which are extra.","## Packs","A pack of several sessions often lowers the price per session. To compare, divide the pack total by the number of sessions and add any boosters you will want each time. Then check:","- How long the sessions are valid.","- What happens if your skin reacts and you have to stop.","- Whether you can transfer sessions or get a refund.","- Whether the same booster is used in each session.","Do not pay for a large pack before you have tried one session. See [[link: /learn/how-often-hydrafacial | how often to have a hydrafacial]].","## Consumables and tips","Disposable tips and serums are a cost to the clinic. Ask whether tips are single use or cleaned between clients, and whether the quote includes them. Aftercare products sold at the clinic should have separate prices and be optional.","## What else to ask in writing","- Who performs the session, and with what qualification.","- Whether a skin check comes first, and if it costs extra.","- What the review visit costs if your skin reacts.","- What the cancellation and refund policy is.","- What taxes are added to the quote.","## Red flags","- A price that is only given over the phone and not in writing.","- A quote that changes on the day.","- Pressure to buy a pack or leave a deposit the same day.","- A promise of a particular skin result.","- No skin check before the session.","- Refusal to say who performs the session.","> A clear written quote is a reasonable thing to ask for, and a clinic that cannot provide one is giving you information.","## What changes the price","Common factors include the city, the type of clinic, the person performing the session, the device and serum, and the add-ons. Our [[link: /cost/hydrafacial | cost page]] shows each line. City pages for [[link: /hydrafacial-in-delhi | Delhi]] and [[link: /hydrafacial-in-gurgaon | Gurgaon]] show sample ranges once real quotes are confirmed. Until then, treat any figure you see online as unverified, including ours.","## Insurance","Cosmetic skin care is usually not covered by health insurance. Ask your insurer in writing if you want to be sure. TODO-VERIFY: reviewer or lawyer confirms wording.","## Who should wait","Do not pay for a session if you have sunburn, infection, or a question about pregnancy or recent isotretinoin use. Get advice first.","[[faq: Why do hydrafacial prices differ between clinics? | Differences come from the device, the serum, add-ons, the person performing it, and the city. A clinic with higher prices may include more steps. Compare line by line.]]","[[faq: Is a pack worth it? | It depends on whether you will use every session and whether your skin tolerates it. Try one session first.]]","[[faq: Should I pay a deposit? | Be careful with large deposits. Ask for the refund terms in writing.]]","Related reading: [[link: /learn/hydrafacial-vs-regular-facial | hydrafacial vs a regular facial]], [[link: /learn/hydrafacial-before-wedding-timing | timing before a wedding]]. More city pages: [[link: /hydrafacial-in-lucknow | Lucknow]], [[link: /hydrafacial-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: Sources to be added after reviewer sign-off. TODO-VERIFY: a named consumer protection or regulator page, opened and checked.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('how-long-wrinkle-injections-last', 'How long do wrinkle injections last?', 'How soon botulinum toxin starts to show, how long the effect usually lasts, what changes it, and why repeat visits are normal.', 5, 1, 'botulinum-toxin-injections', '["[[reviewer]]","Botulinum toxin (often called Botox) injections for wrinkles take a few days to show and the effect wears off over a few months. Exact timing varies by person, area and plan, so your doctor gives the range for you. Repeat visits are normal. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]]. TODO-VERIFY: reviewer sets the ranges.","## When it starts to show","The injection relaxes the small muscles that make frown lines and other movement lines. The change builds gradually. Many people notice it within several days, and the full effect often takes about two weeks. TODO-VERIFY: reviewer confirms. Doctors often schedule a review visit around two weeks to check the result.","## How long it lasts","The effect fades over a few months as the muscle recovers. Then the lines usually return to how they were before. Your doctor can tell you what range to expect for your face. Do not accept a fixed promise from a person who has not examined you.","## What changes the duration","- The area treated. Muscles differ in strength and in how much they move.","- Your own muscle strength and how expressive your face is.","- The product prescribed and the plan your doctor chose.","- How you metabolise it, which varies from person to person.","- How often you have it done. Some doctors say repeat treatment is needed to keep the look, and the plan should be discussed at the start.","Heavy exercise, heat and sun are often mentioned online as shortening the effect. The evidence is limited, so ask your doctor what matters for you.","## Why repeat visits happen","Because the effect is temporary, keeping the look means going back. Repeat treatment has a cost each time, and the cost over a year is worth working out before you start. See [[link: /cost/botulinum-toxin-injections | our cost page]] for the lines to ask about.","## What happens as it wears off","Movement returns slowly. Lines that were relaxed can look the same as before. Some people see no change over time and others find they need less frequent visits. Do not repeat the injection sooner than your doctor advises, because more is not better.","> Repeat treatment is a recurring cost. Ask your doctor to put the visit gap and expected yearly cost in writing.","## Touch-up visits","If the result looks uneven at the review visit, a doctor may adjust. Ask whether a touch-up is included in the price, and what the policy is. Do not assume it is free.","## Planning around events","If you have a wedding, interview or trip coming up, do not schedule the injection in the last days before it. The review visit, the first bruise and any uneven result all need time. Many people book the first treatment well ahead, then plan repeats around their calendar.","## Who should wait","Wait if you are pregnant, planning pregnancy or breastfeeding, if you have an infection at the injection site, or if you have a nerve or muscle condition. A doctor should check your medicines too. See the full list in [[link: /learn/botulinum-toxin-side-effects | the side effects guide]].","## Questions worth asking","- How long should I expect this plan to last for my face?","- When is the review visit, and is a touch-up included?","- What will I spend over a year if I repeat it?","[[faq: Does botulinum toxin last for good? | No. The effect fades over months and the lines return. Your doctor can explain what to expect for your plan.]]","[[faq: Can I have it done more often to make it last? | More frequent treatment does not make it last longer and can raise risks. Follow your doctor''s gap.]]","[[faq: Does the effect stop suddenly? | It usually fades gradually over weeks.]]","Related reading: [[link: /learn/aftercare-after-wrinkle-injections | aftercare in the first 24 hours]] and [[link: /learn/botulinum-toxin-vs-fillers | botulinum toxin vs fillers]]. City pages: [[link: /botulinum-toxin-injections-in-lucknow | Lucknow]], [[link: /botulinum-toxin-injections-in-kanpur | Kanpur]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; American Academy of Dermatology patient information on botulinum toxin. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('botulinum-toxin-vs-fillers', 'Botulinum toxin vs fillers: what each is for', 'Movement lines versus volume loss, the areas each is used for, how long each lasts, their risks, and the questions to ask before choosing.', 5, 2, 'botulinum-toxin-injections', '["[[reviewer]]","Botulinum toxin relaxes the muscles that cause movement lines, such as frown lines. Fillers add volume or fill creases where the skin has lost support. They do different jobs, and many people need only one. A doctor decides after looking at your face. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]].","## What each is for","Botulinum toxin is used where lines appear when you frown, squint or raise your brows. Fillers are used where the face has lost volume or where folds have formed, such as around the mouth or in the cheeks. Neither changes skin quality much, and neither stops ageing. See [[link: /anti-aging-treatment | the anti-aging overview]] for other options.","## Areas","- Botulinum toxin: forehead, between the brows, and around the eyes, in the usual wrinkle uses.","- Fillers: cheeks, lines from the nose to the mouth, lips and the chin, as decided by the doctor.","Both can also be used in other places for other reasons. Those uses are not covered here.","## How long each lasts","Both are temporary. Toxin fades over a few months. Fillers last for a period that depends on the material and area, and a doctor can tell you what to expect. TODO-VERIFY: reviewer confirms ranges. Neither should be described to you as lasting for good.","## Risks of each","- Botulinum toxin: bruising, headache, uneven results, and a drooping eyelid or brow in some people. See [[link: /learn/botulinum-toxin-side-effects | side effects]].","- Fillers: swelling, lumps, bruising and uneven contour. A rare and serious risk is a filler entering a blood vessel, which can damage skin or vision, and needs urgent care. TODO-VERIFY: reviewer confirms wording.","Doctors choose their products and technique to lower these risks, and not every person is a good candidate.","## Combined plans","Some doctors use both in one plan, for example toxin for the forehead and filler for volume. Combining raises the number of injections and the cost. Ask what each part is for and what you would lose by skipping one.","## Regulation","Fillers may be regulated differently from toxin, and the rules for advertising and sale vary. Use a registered doctor and ask them to show you the product pack and batch label. See [[link: /learn/check-wrinkle-injection-product | how to check a product]].","## Cost","Prices differ by area, product and doctor. Toxin is often priced per area, and filler per syringe or amount used, so totals are not easy to compare. Ask for a written plan with a total. See [[link: /cost/botulinum-toxin-injections | our cost page]] for toxin lines.","> A plan is only as good as the question it answers. Ask what each injection is meant to change.","## Who should wait","Wait if you are pregnant or breastfeeding, if you have an infection near the site, or if you are expecting a result that no injection can deliver. Nerve and muscle conditions affect toxin choices, and bleeding disorders and some medicines affect both.","## Questions worth asking","- Which of my lines are movement lines and which are volume loss?","- What would you do first, and why?","- What are the risks for my face and what do I do if something goes wrong?","[[faq: Which is better, botulinum toxin or fillers? | Neither is better in general. They do different jobs. A doctor can match the option to your face.]]","[[faq: Can I have both on the same day? | Some doctors do this. Ask whether it suits your plan and what it adds to the cost.]]","[[faq: Are fillers reversible? | Some types can be dissolved. Ask your doctor which type is being used and whether it can be reversed.]]","Related reading: [[link: /learn/skin-boosters-vs-fillers-vs-toxin | skin boosters, fillers and toxin compared]], [[link: /learn/wrinkle-injections-for-men | wrinkle injections for men]]. City pages: [[link: /botulinum-toxin-injections-in-delhi | Delhi]], [[link: /botulinum-toxin-injections-in-gurgaon | Gurgaon]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on injectable fillers and botulinum toxin; American Academy of Dermatology patient information on fillers. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('botulinum-toxin-side-effects', 'Botulinum toxin side effects and what to do', 'Common, uncommon and rare effects of botulinum toxin injections, how they unfold over days, who is at higher risk, and when to call a doctor.', 6, 3, 'botulinum-toxin-injections', '["[[reviewer]]","Common effects of botulinum toxin injections are small bumps, redness, bruising and headache, which settle within days. Less often, a brow or eyelid can droop or the result can look uneven. Rare problems such as trouble swallowing or breathing need urgent care. Your doctor and the product leaflet give the full list. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]].","## Common effects","- Small bumps where the needle went in, which settle within hours.","- Redness or tenderness at the sites.","- Bruising, more likely if you take blood-thinning medicines.","- A mild headache, usually brief.","## Less common effects","- A drooping eyelid or brow, caused by the toxin spreading to nearby muscle. It can last weeks and settles as the effect wears off. A doctor can sometimes suggest eye drops for droopy eyelids.","- An uneven result, such as one brow higher than the other. A touch-up may help.","- A frozen or heavy look when too much is used. A conservative plan lowers this risk.","- Dry eyes or watery eyes, in treatment around the eyes.","- Flu-like symptoms in some people.","## Rare and urgent effects","Rarely, the effect can spread beyond the area treated. Warning signs include trouble swallowing, trouble breathing, weakness in distant muscles, hoarse voice or drooping that is widespread. Seek urgent medical help for these. Allergic reactions such as rash, swelling of the lips or face, or difficulty breathing also need emergency care. TODO-VERIFY: reviewer confirms wording against the leaflet.","## How effects unfold over days","Bumps and redness appear within minutes to hours. Bruising may show in a day or two. Headache may come the same day. A drooping eyelid or brow tends to appear days to a couple of weeks later. Review visits at about two weeks let your doctor see the full result.","## Who is at higher risk","- People with nerve or muscle conditions.","- People taking some antibiotics or medicines that affect nerves and muscles. Tell the doctor about all medicines.","- People with infection or skin problems at the injection site.","- Pregnant and breastfeeding women, because information is limited.","- People with thin or weak muscle in the area being treated.","## What to do","Note the time, the symptom and the area. Take photos if it helps. Call the doctor who treated you for anything that worries you. If you cannot reach them, go to a doctor or emergency service. Do not rub the area, and do not try to correct an uneven result yourself.","> Ask before treatment who you should call, and on what number, if something goes wrong after hours.","## Reducing the chance of problems","Choose a registered doctor with relevant training. Ask what product is being used and see the sealed vial. Follow aftercare instructions, described in [[link: /learn/aftercare-after-wrinkle-injections | our aftercare guide]]. Report your medicines and health conditions honestly. Our [[link: /learn/check-wrinkle-injection-product | guide to checking the product]] covers what to ask about.","## Cost of complications","Ask in writing whether review visits and touch-ups are included, and who pays for treatment of a complication. See [[link: /cost/botulinum-toxin-injections | our cost page]].","## Who should wait","Wait if you are pregnant, breastfeeding, unwell, or have an infection near the site. Postpone until a doctor agrees if you have a neuromuscular condition.","[[faq: Is botulinum toxin dangerous? | Serious problems are rare, but they can happen, and any injection has risks. Treatment should be done by a trained doctor who explains the risks first.]]","[[faq: How long does a drooping eyelid last? | It can last weeks and usually settles as the effect wears off. A doctor can advise on options. TODO-VERIFY: reviewer confirms.]]","[[faq: Can I take painkillers for the headache? | Ask your doctor which are suitable, since some increase bruising.]]","Related reading: [[link: /learn/how-long-wrinkle-injections-last | how long wrinkle injections last]]. City pages: [[link: /botulinum-toxin-injections-in-lucknow | Lucknow]], [[link: /botulinum-toxin-injections-in-kanpur | Kanpur]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; American Academy of Dermatology patient information on botulinum toxin; the product leaflet for the medicine prescribed. TODO-VERIFY: open each source and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('aftercare-after-wrinkle-injections', 'What to do after wrinkle injections: first 24 hours', 'The usual advice for the first day after botulinum toxin injections, what is normal, what to avoid, and which signs need a call to the doctor.', 5, 1, 'botulinum-toxin-injections', '["[[reviewer]]","After botulinum toxin injections, doctors commonly ask you to keep the skin clean, avoid rubbing the treated area, stay upright for some hours and skip hard exercise that day. Small bumps and redness are normal. Your doctor''s own instructions come first. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]]. TODO-VERIFY: reviewer confirms the list.","## The first few hours","- Do not rub, press or massage the treated area unless your doctor says to.","- Stay upright for several hours. Avoid lying flat or bending forward for long.","- Keep makeup off the sites until the clinic says it is fine.","- Move your face as normal. Some doctors ask you to frown or raise your brows gently in the first hours. Follow your own doctor''s advice.","## The first day","- Skip heavy exercise and heat such as saunas or steam. Heat and strong activity raise blood flow to the face.","- Avoid alcohol for the period your doctor advises, since it can increase bruising.","- Avoid facials, peels or devices on the area.","- Wash your face gently and use sunscreen outside.","Some doctors give extra advice about pillows and sleeping position. Ask what applies to you.","## What is normal","Small bumps that fade within hours, mild redness, tenderness and a little bruising are common. A mild headache can occur. The effect on the lines builds over several days, so do not judge the result on day one.","## Myths to ignore","Many online lists include rules with no good evidence, such as strict bans on washing your face or on all talking and chewing. Follow your doctor''s instructions, and ask for the reason if a rule seems odd. A short written aftercare sheet from the clinic is reasonable to expect.","## Travel and events","Avoid long flights, intense sport or an important event on the day. If you must travel, tell the doctor beforehand and ask what to do about pressure and activity. Keep your clinic''s contact number with you for the first few days.","## Medicines","Tell the doctor about blood thinners and supplements before treatment, since they can increase bruising. Ask before taking painkillers afterwards. Do not stop prescribed medicine on your own.","## Red flags","- Trouble swallowing, breathing or speaking.","- Swelling of the lips, face or throat, or widespread rash.","- Severe pain, blistering, or signs of infection such as pus or spreading redness.","- Drooping of the eyelid or brow, which can appear in the days after.","- Vision changes.","Call your doctor, or go to an emergency service for the serious signs. See [[link: /learn/botulinum-toxin-side-effects | the side effects guide]].","> Ask the doctor to give the aftercare rules in writing and to tell you who to contact after hours.","## Review visit","A review at about two weeks lets the doctor check the result and adjust. Ask whether it is included in the price. See [[link: /cost/botulinum-toxin-injections | the cost page]] for lines to compare.","## Who should wait","If you have an infection, a cold sore near the area or fever on the day, ask to reschedule. Pregnant women should check with a doctor first.","## Questions worth asking","- Which of these rules apply to me and for how long?","- Who do I call if I am worried?","- When is the review?","[[faq: Can I wash my face after botulinum toxin? | Most doctors say yes, gently. Avoid rubbing. Follow your own doctor''s advice.]]","[[faq: Can I exercise the same day? | Doctors often advise skipping hard exercise on the day. Ask for your own instructions.]]","[[faq: When can I wear makeup? | Ask your clinic. Some suggest waiting for some hours.]]","Related reading: [[link: /learn/how-long-wrinkle-injections-last | how long wrinkle injections last]]. City pages: [[link: /botulinum-toxin-injections-in-delhi | Delhi]], [[link: /botulinum-toxin-injections-in-gurgaon | Gurgaon]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; the aftercare sheet from the treating doctor. TODO-VERIFY: open each source and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('age-for-wrinkle-injections', 'What age do doctors consider wrinkle injections?', 'There is no set age for botulinum toxin. Doctors decide after an examination, and skin care and sun protection usually come first.', 5, 2, 'botulinum-toxin-injections', '["[[reviewer]]","There is no set age for wrinkle injections. A doctor decides after examining your face, and the decision depends on the lines you have, how they look at rest, your health and what you want. Many doctors suggest skin care and sun protection first. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]].","## What the doctor looks at","Doctors look at lines at rest and in motion. Lines that only show when you frown may respond to treatment of the muscle. Lines that are visible at rest may involve skin changes too, and a different plan can be needed. The doctor also checks the position of your brows and eyelids, muscle strength and any medical condition.","## Questions about your face and mood","Doctors also ask why you want treatment. Frown lines that make you look tired or cross when you are not can be a reason. A wish to look like someone else is not. Be honest about your goals and any past treatments, since this helps the doctor choose a plan that is conservative at first and easy to adjust.","## Age is a poor guide","Skin ageing depends on sun exposure, smoking, genetics and skin type. Two people of the same age can have very different faces. People of any adult age may be told they do not need treatment. Adults under 18 are not the target of this guide, and treatment for young people is a medical decision made with a guardian.","## Starting early to prevent lines","Some people ask whether starting young stops lines forming. Evidence on this is limited, and doctors differ. TODO-VERIFY: reviewer confirms wording. Starting a repeat treatment commits you to repeat visits and a recurring cost. If you are unsure, ask your doctor what they would advise if cost and fashion were not a factor.","## Skin care first","- Use sunscreen every day.","- Do not smoke.","- Keep skin moisturised.","- Ask a doctor about a retinoid for the skin surface, if suitable. See [[link: /learn/sunscreen-retinoids-skin-ageing | sunscreen and retinoid basics]].","These steps cost less and cut down on several causes of lines. They do not replace injections, and they are not a reason to avoid seeing a doctor.","## Expectations","Treatment can soften movement lines. It does not remove sun damage, lift sagging skin or add volume. Results vary. If you are hoping for something different, ask what else exists. See [[link: /anti-aging-treatment | the anti-aging overview]].","## Cost over time","The cost is recurring. Over several years the total can be large, so decide how long you are willing to continue. Ask your doctor to estimate the yearly cost. See [[link: /cost/botulinum-toxin-injections | the cost page]].","> The right moment to start is when you have a reason to, and not when an age or an advertisement says so.","## Who should wait","Wait if you are pregnant, breastfeeding, unwell or have an infection. Do not start if the main driver is pressure from other people or social media. Talk to a doctor if you feel distressed about your looks, since this can be a health concern in its own right.","## Questions worth asking","- Do my lines need injections, or would skin care do?","- What happens if I stop after one or two visits?","- How would you plan this over a year?","[[faq: Is 25 too young for botulinum toxin? | There is no fixed age. A doctor decides from your face and goals. Many people at that age do not need it.]]","[[faq: Is there an upper age limit? | No fixed limit. Health and expectations matter more.]]","[[faq: Does it prevent wrinkles? | Evidence is limited and doctors differ. Ask your own doctor.]]","Related reading: [[link: /learn/anti-aging-care-by-decade | anti-aging care by decade]], [[link: /learn/botulinum-toxin-vs-fillers | botulinum toxin vs fillers]]. City pages: [[link: /botulinum-toxin-injections-in-lucknow | Lucknow]], [[link: /botulinum-toxin-injections-in-kanpur | Kanpur]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; American Academy of Dermatology patient information on skin ageing. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('botulinum-toxin-units-explained', 'Units explained: why per-unit prices can mislead', 'What a unit measures, why units are not comparable between products, how a doctor sets the dose, and why a written total for your plan is clearer.', 5, 3, 'botulinum-toxin-injections', '["[[reviewer]]","A unit is a measure of how much biological activity a dose of botulinum toxin has. Units are not comparable between products, and the dose is set by your doctor for your face. So a price quoted per unit tells you little about the total cost. Ask for a written total for your whole plan. See our [[link: /cost/botulinum-toxin-injections | cost page]] and [[link: /botulinum-toxin-injections | overview]].","## What a unit measures","A unit describes how strong a dose is in lab terms. It does not tell you how much of a visible effect you will get. Manufacturers measure strength in their own ways, so one product''s unit does not equal another''s. Do not compare numbers across products.","## Who sets the dose","Your doctor decides the dose, based on your muscles, the lines, your health and the product used. A friend''s dose tells you nothing about yours. A conservative plan may use less at first, and the doctor adds at a review if needed.","## Why per-unit quotes mislead","- A low per-unit figure can come with a large number of units, so the total is not low.","- Different products use different units, so the figures cannot be compared.","- A per-unit quote does not tell you the doctor''s fee, the consultation or the review.","- It can hide a plan that treats more areas than you need.","- It may push you to compare on price instead of on the doctor and the plan.","Cost guides that list numbers of units for each area can be wrong for your face. This guide does not list any.","## What to ask in writing","- The areas to be treated and why.","- The total price for the plan, including the doctor''s fee and the product.","- Whether a review visit is included.","- What a touch-up costs, if needed.","- The name of the product, which you can ask to see on the vial or pack.","A clear written plan lets you compare two doctors fairly. See [[link: /learn/check-wrinkle-injection-product | how to check the product]].","## How to compare two quotes","Ask both doctors to write the same plan: same areas, same visit schedule, and the same review. Then compare the totals and what each includes, such as the consultation, the product and a touch-up. A quote that leaves out the review or the touch-up may look low and cost more later.","## Why price should not decide","Choosing on price alone can lead to dilute, counterfeit or poorly handled product. A very low quote is a reason to ask more questions. See the same guide for warning signs. This does not mean a higher price means better care, either. The training of the doctor and what the plan includes matter more.","## Insurance","Cosmetic use is usually not covered. Ask your insurer in writing. TODO-VERIFY: reviewer or lawyer confirms wording.","> If someone quotes you a number of units before they have looked at your face, ask them how they chose it.","## Who should wait","Wait if you are pregnant, breastfeeding, unwell, or have a nerve or muscle condition. Do not agree to a plan under time pressure.","## Questions worth asking","- Why this dose for my face?","- What will the total be if I need a touch-up?","- Which parts of the quote are the doctor''s fee and which are the product?","[[faq: How many units do I need? | Only a doctor who has examined you can say. It depends on the muscles and the plan.]]","[[faq: Is a price per unit a fair way to compare? | Not usually. Units differ between products and a unit price does not show the total. Compare written totals for the same plan.]]","[[faq: Why do two doctors quote different totals? | They may plan different areas, use different products and include different follow-up. Ask each to list what is included.]]","Related reading: [[link: /learn/botulinum-toxin-vs-fillers | botulinum toxin vs fillers]]. City pages: [[link: /botulinum-toxin-injections-in-delhi | Delhi]] and [[link: /botulinum-toxin-injections-in-gurgaon | Gurgaon]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; the product leaflet for the medicine prescribed. TODO-VERIFY: open each source and confirm wording on units.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('check-wrinkle-injection-product', 'Genuine or diluted? Questions to ask before injections', 'General steps to check a botulinum toxin product before treatment: sealed vial, batch label, licensed supplier, a written plan and red flags.', 5, 1, 'botulinum-toxin-injections', '["[[reviewer]]","Fake or poorly handled injectable products exist, and you can lower your risk by asking questions. Ask to see the sealed vial and its batch label, ask who supplied it, and get a written plan. Treatment should be done by a registered doctor. These checks are general, and no single check proves a product is genuine. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]].","## Why it matters","Botulinum toxin is a prescription medicine. Counterfeit, diluted or wrongly stored product can fail to work or cause harm. A low price can be a sign of a problem, though a high price does not prove quality either.","## What to ask to see","- The sealed vial or pack opened in front of you.","- The label with the product name, batch number and expiry date.","- The packaging, which should look intact and unaltered.","Note the batch number in your records. Ask the doctor to record it in your file too. TODO-VERIFY: reviewer confirms the checks.","## Where it came from","Ask how the clinic buys its product. A doctor should be able to say it comes from a licensed supplier and show an invoice if asked. Be wary of an answer that is vague or defensive. Product sold through social media or sent by courier for use at home is a red flag.","## Storage and handling","These products need cold storage. Ask how it is stored and how long a vial is kept after it is opened. Reuse or sharing of vials across patients should concern you. TODO-VERIFY: reviewer confirms the wording on reuse.","## Who is injecting","Ask for the name and registration of the doctor performing the injection, and check it on the state medical council register. A beauty salon or an unregistered person should not be injecting a prescription medicine. See the choose-a-doctor checklist in the [[link: /botulinum-toxin-injections | overview]].","## A written plan and consent","You should get a consultation, a written plan with areas and the total, and a consent form that lists risks. If a clinic refuses to provide any of these, think twice.","## Red flags","- A very low price for the whole plan.","- A deal that expires today.","- Vials already opened or prepared before you arrive.","- Treatment at a home, party or pop-up setting.","- A doctor who will not give a name or a registration number.","- No questions about your health or medicines.","- A promise of a particular outcome.","> If you feel pressed to decide quickly, walk out. You can come back after you have checked.","## If you suspect a problem","Contact the treating doctor and a doctor of your own. Keep the packaging, the batch number and photos. The correct official channel for reporting a suspected fake or a complication should be listed here after it has been checked. TODO-VERIFY: add the official reporting channel from a verified source.","## What it costs","Ask what the price includes. See [[link: /cost/botulinum-toxin-injections | our cost page]] and [[link: /learn/botulinum-toxin-units-explained | the guide to units]].","## Who should wait","Wait if you are pregnant, breastfeeding or unwell. Postpone if you cannot confirm the product and the doctor, since a delay costs less than a complication.","## Questions worth asking","- Can I see the sealed vial and the batch label?","- Where do you buy your product?","- What is your registration number?","[[faq: How can I tell if botulinum toxin is genuine? | You cannot tell from looking at the result. Ask to see the sealed vial, label and batch number, and ask where it was bought. Choose a registered doctor.]]","[[faq: Is a very low quote a problem? | It can be a reason to ask more questions. Compare written plans, not single numbers.]]","[[faq: Can I bring my own product? | No. A doctor should supply and store the product they inject.]]","Related reading: [[link: /learn/botulinum-toxin-side-effects | botulinum toxin side effects]]. City pages: [[link: /botulinum-toxin-injections-in-lucknow | Lucknow]] and [[link: /botulinum-toxin-injections-in-kanpur | Kanpur]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: Product leaflet for the medicine prescribed; the state medical council register for checking doctor registration. TODO-VERIFY: open each source and add the official channel for complaints.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('wrinkle-injections-for-men', 'Wrinkle injections for men: what differs', 'How male facial muscles, brow shape and expectations change the plan for botulinum toxin, with risks, aftercare and questions to ask.', 5, 2, 'botulinum-toxin-injections', '["[[reviewer]]","Men can have botulinum toxin injections for wrinkles. A doctor adjusts the plan because male facial muscles are often stronger and brows sit differently. The aim is usually a natural expression, and results vary. A doctor decides after an examination. See our [[link: /botulinum-toxin-injections | botulinum toxin injections overview]].","## What differs","- Muscle strength: many men have stronger forehead and frown muscles, which can mean a different plan from the one a woman would get. The doctor decides.","- Brow shape: male brows are often lower and flatter. A plan that lifts or arches the brow can look out of place, so doctors take care with the forehead.","- Skin and hair: thicker skin and facial hair affect how injections are placed and how bruises show.","- Expectations: many men want to look rested and keep their expression. Say that clearly.","Do not expect any plan to give a particular look. Ask the doctor what a conservative plan would change and what it would not.","## Common areas","Forehead lines, frown lines between the brows and lines around the eyes are the usual areas. Doctors treat these with attention to balance, since a heavy forehead with a mobile frown can look odd. See [[link: /learn/botulinum-toxin-vs-fillers | botulinum toxin vs fillers]] for other options.","## Risks","The risks are the same as for anyone: bruising, headache, uneven results, and a drooping brow or eyelid in some people. A forehead treated without enough care can leave a heavy brow. See [[link: /learn/botulinum-toxin-side-effects | the side effects guide]].","## Aftercare","Follow your doctor''s instructions on the first day. Avoid rubbing the area and skip hard exercise that day. If you shave, ask when you can shave near the injection sites. See [[link: /learn/aftercare-after-wrinkle-injections | the aftercare guide]].","## Cost and visits","The effect is temporary, and repeat visits are a recurring cost. Ask for a written plan and yearly estimate. See [[link: /cost/botulinum-toxin-injections | our cost page]]. Men sometimes prefer fewer visits and a shorter plan, which the doctor can plan around.","## Skin and hair care","Men who shave daily may notice more irritation at the sites. Ask about moisturiser and sunscreen after treatment, and avoid new products on the treated skin for the first day. A plain routine is easier to judge if a reaction occurs.","## Privacy","Many men worry about others noticing. A conservative plan and a review visit help. A doctor should keep your treatment private, and you should be able to ask about how your records are handled.","> The aim of a plan is a result that fits your face. Say what you want to keep as well as what you want to soften.","## Who should wait","Wait if you have an infection near the area, if you take medicines that thin the blood and your doctor has not reviewed them, or if you have a nerve or muscle condition. Do not start if you expect a change in how others see you that injections cannot deliver. Men who feel distress about their looks can talk to a doctor about it.","## Questions worth asking","- What would a conservative plan for my face change?","- How will my brows look after treatment?","- What is the review plan, and what does a touch-up cost?","[[faq: Is botulinum toxin only for women? | No. Men are treated too. The plan is adjusted for muscle strength and brow shape.]]","[[faq: Will I look frozen? | It depends on the plan. Ask for a conservative plan and a review.]]","[[faq: Do men need more? | Often the muscles are stronger, which may change the plan. Only a doctor who has examined you can say.]]","Related reading: [[link: /learn/age-for-wrinkle-injections | what age doctors consider wrinkle injections]], [[link: /learn/how-long-wrinkle-injections-last | how long they last]]. City pages: [[link: /botulinum-toxin-injections-in-delhi | Delhi]], [[link: /botulinum-toxin-injections-in-gurgaon | Gurgaon]].","Talk to a doctor about your options. Message us on WhatsApp if you want help preparing questions.","[[sources: American Society of Plastic Surgeons patient information on botulinum toxin; American Academy of Dermatology patient information on botulinum toxin. TODO-VERIFY: open each page and confirm wording on male patients.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('skin-boosters-vs-fillers-vs-toxin', 'Skin boosters, fillers and toxin: what each does', 'What botulinum toxin, fillers and skin boosters target, how long each lasts, the risks, and how doctors combine them. Evidence for boosters is mixed.', 6, 1, 'anti-aging-treatment', '["[[reviewer]]","Botulinum toxin softens movement lines, fillers add volume or fill folds, and skin boosters are injections meant to add hydration to the skin. Each targets a different problem, and the evidence for boosters is more limited. A doctor chooses after looking at your skin. See our [[link: /anti-aging-treatment | anti-aging treatment overview]].","## What each one targets","- Botulinum toxin: lines caused by muscle movement, such as frown lines. It relaxes the muscle for a few months. See [[link: /botulinum-toxin-injections | the botulinum toxin overview]].","- Fillers: lost volume or deep folds. A gel-like material is placed under the skin to add support.","- Skin boosters: a thin, hydrating product placed in many tiny points, meant to improve how the skin feels and looks. Evidence on how much they change skin is limited and mixed. TODO-VERIFY: reviewer sets wording.","## How long each lasts","Toxin effect fades over months. Filler duration depends on the material and area. Boosters are often repeated as a series. Ask the doctor for ranges for your plan and treat any single figure from an advertisement with caution. None of them is a one-time fix.","## Sessions","Toxin often takes one visit and a review. Fillers may need one visit with a touch-up. Boosters are often planned as a set of sessions several weeks apart. TODO-VERIFY: reviewer confirms. Each visit adds cost.","## Risks","- Toxin: bruising, headache, uneven result and a drooping brow or eyelid in some people. See [[link: /learn/botulinum-toxin-side-effects | side effects]].","- Fillers: swelling, lumps, bruising and uneven contour. A rare, serious risk is blockage of a blood vessel, which needs urgent care.","- Boosters: bumps, bruising, redness and lumps at the sites, and infection if technique is poor.","All injectables carry a risk of allergy and infection. A doctor can say who is a better candidate.","## Combinations","Doctors sometimes use more than one in a plan. This adds visits and cost, and raises the chance of side effects. Ask what each part does and what you would lose by leaving one out. For an expanded comparison of toxin and fillers, see [[link: /learn/botulinum-toxin-vs-fillers | botulinum toxin vs fillers]].","## Who to ask","A registered dermatologist or a trained physician should do injectables. Ask about their training and to see the product pack. See [[link: /learn/check-wrinkle-injection-product | how to check a product]]. Do not choose from a menu of names. Ask what the plan is for your face.","## What injectables cannot do","They do not stop ageing, and they do not replace sun protection. They do not tighten loose skin much, and they cannot do what surgery does. See [[link: /learn/home-remedies-skin-ageing | what home care can and cannot do]].","> A named product or a fashionable technique is not a plan. A plan begins with what bothers you and what a doctor finds on examination.","## Cost","Prices differ by product, area and doctor. Our [[link: /cost/anti-aging-treatment | cost page]] shows the lines to compare, and the [[link: /cost/botulinum-toxin-injections | toxin cost page]] covers wrinkle injections.","## Who should wait","Wait if you are pregnant or breastfeeding, if you have an infection or a cold sore near the site, or if you are unwell. Tell the doctor about blood thinners, allergies and past reactions.","## Questions worth asking","- What is this injection meant to change?","- What happens if I stop after one visit?","- What do I do if I notice a problem, and who do I call?","[[faq: What is the difference between a skin booster and a filler? | A filler adds volume or fills folds. A skin booster is meant to add hydration across the skin. Evidence for boosters is more limited.]]","[[faq: Can I have toxin and filler together? | Some doctors combine them. Ask whether you need both and what each adds to cost and risk.]]","[[faq: Which lasts longest? | It depends on the material and the person. Ask your doctor for a range.]]","Related reading: [[link: /learn/prp-face-evidence | PRP for the face: what evidence exists]], [[link: /learn/hifu-radiofrequency-skin-tightening | HIFU and radiofrequency tightening]]. City pages: [[link: /anti-aging-treatment-in-lucknow | Lucknow]], [[link: /anti-aging-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Society of Plastic Surgeons patient information on injectable fillers and botulinum toxin; American Academy of Dermatology patient information on cosmetic procedures. TODO-VERIFY: open each page and confirm wording on boosters.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('chemical-peels-for-ageing-skin', 'Chemical peels for ageing skin: types and risks', 'Superficial, medium and deep peels in plain terms, how long skin takes to settle, pigment risk in Indian skin, and who should wait.', 6, 2, 'anti-aging-treatment', '["[[reviewer]]","A chemical peel applies an acid solution to loosen the outer layers of skin, and the skin then flakes and renews. Peels are used for uneven texture, tone and fine lines. Light peels settle in days, and deeper ones take longer and carry higher risks. Results vary. See our [[link: /anti-aging-treatment | anti-aging treatment overview]].","## The three depths","- Superficial peels act on the outer layer. Redness and light flaking last for a few days. TODO-VERIFY: reviewer confirms ranges.","- Medium peels reach deeper. Skin can be red, swollen and peeling for a week or more, and sun avoidance is strict.","- Deep peels are done by experienced doctors, often with sedation, and recovery is long. They carry the highest risk.","Depth depends on the acid, its strength and how long it stays on. A doctor chooses these for your skin.","## What a peel may help","Superficial peels may improve rough texture and dullness for a short time. Deeper peels may soften fine lines and uneven tone. They do not remove deep wrinkles or sagging, and they do not stop ageing. Ask what change is realistic for your skin, and how it will be judged.","## Downtime","Expect redness, tightness and flaking. A deeper peel can mean days at home. You cannot pick the flakes. Plan around events, and do a trial before an important date.","## Risks","Redness, burning, infection, scarring and changes in skin colour are possible. A cold sore flare can occur in people who get them. Peels can leave lighter or darker patches. See the next section for skin tone.","## Pigment risk in Indian skin","Medium to dark skin tones are more likely to develop post-inflammatory hyperpigmentation, which means dark patches after irritation. Stronger peels raise the chance. Doctors may pick gentler acids, pre-treat the skin and ask you to avoid sun strictly. Ask how they adjust the plan for your skin tone and what they would do if marks appear.","## Sun avoidance","Skin is more sensitive to the sun for weeks after a peel. Use broad-spectrum sunscreen daily and avoid peak sun. See [[link: /learn/sunscreen-retinoids-skin-ageing | sunscreen and retinoid basics]]. Do not have a peel just before a holiday in strong sun.","> A peel is a controlled injury to the skin. How you care for the skin afterwards changes how it heals.","## Retinoids and other products","Many doctors ask you to pause retinoids and strong acids before a peel. Do not stop prescribed medicine on your own. Ask which products to stop and for how long.","## Cost","Peels are priced per session, and a plan may need several sessions. Strength, acid and the doctor affect the total. See our [[link: /cost/anti-aging-treatment | cost page]] for lines to compare.","## Who should wait","Wait if you have sunburn or a tan, active infection, a cold sore, open skin or irritated skin. Pregnant women should ask a doctor first, and people who took isotretinoin recently should wait for the interval their doctor sets. A tendency to keloid or thick scars needs a doctor''s advice.","## Questions worth asking","- Which peel and strength do you suggest for me, and why?","- What are the risks for my skin tone?","- What will my skin look like in the first week?","[[faq: Does a chemical peel remove wrinkles? | It may soften fine lines and uneven texture. Deep wrinkles usually need other methods. Results vary.]]","[[faq: How many peels will I need? | It depends on the peel and your skin. A doctor sets the plan.]]","[[faq: Can I get a peel at a salon? | Stronger peels should be done by a doctor. Ask who performs it and with what training.]]","Related reading: [[link: /learn/laser-for-ageing-skin-indian-skin | laser for ageing skin on Indian skin tones]], [[link: /hydrafacial | hydrafacial overview]]. City pages: [[link: /anti-aging-treatment-in-delhi | Delhi]], [[link: /anti-aging-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on chemical peels; NHS patient information on skin care. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-face-evidence', 'PRP for the face: what it is and what evidence exists', 'How PRP is made, how it is used on the face, what studies suggest so far, the sessions and risks, and why you should ask for the evidence.', 6, 3, 'anti-aging-treatment', '["[[reviewer]]","Platelet-rich plasma (PRP) is made from your own blood and injected or applied to the skin. Doctors use it in several ways, including on the face. Evidence for facial use is limited and mixed, and results vary. Ask a doctor what they expect for your skin. See the full [[link: /prp-treatment | PRP treatment overview]] and our [[link: /anti-aging-treatment | anti-aging overview]].","## How PRP is made","A small amount of your blood is taken and spun in a machine so that the platelet-rich part separates. That portion is then used for the treatment. The details of the process differ between clinics. TODO-VERIFY: reviewer confirms. For a longer description, see [[link: /learn/prp-how-it-is-made | how PRP is made]].","## How it is used on the face","Doctors may inject PRP in small amounts or apply it after a skin-needling session. People ask about it for fine lines, skin texture and the area under the eyes. These uses are described by doctors, and the research behind them is still developing.","## What studies suggest","Small studies have looked at PRP for skin texture and fine lines, and some report improvement while others show limited change. Many studies use different methods, so they are hard to compare. TODO-VERIFY: reviewer cites studies that a person has opened. Do not accept claims about collagen or reversing ageing without a named study. PRP does not stop ageing.","## What to ask your doctor","- What outcome do you expect for my skin, and what is that based on?","- What would you do if I see no change?","- What is the total plan and cost?","## What a consultation should include","A proper visit covers your skin history, your medicines, a look at the face in good light and a discussion of what you hope to change. You should hear the limits of the treatment as well as its aims. If you leave with a plan but no mention of risks or alternatives, ask for them before agreeing.","## Sessions","Plans are often a series of sessions several weeks apart. TODO-VERIFY: reviewer sets any range. Ask how many sessions, how far apart, and how you will know whether it is working. If there is no change after a set point, ask whether to stop.","## Risks","Bruising, swelling, redness and tenderness are common after the injections. Infection and an uneven result are less common. PRP uses your own blood, so allergy to the product is unlikely, but a reaction to numbing cream or another product can occur. See [[link: /learn/prp-side-effects | PRP side effects]].","## Who should wait","- People with blood disorders or low platelet counts.","- People on blood thinners, unless the doctor has reviewed them.","- Anyone with infection or skin disease in the treatment area.","- Pregnant or breastfeeding women, because information is limited.","- Those with an active cancer, unless their treating doctor agrees.","See [[link: /learn/prp-who-should-wait | the PRP checklist]].","> If a clinic describes PRP as a certain fix for ageing, ask which study they are relying on.","## Cost","Prices vary by clinic, the kit used, the sessions planned and add-ons such as needling. Compare written totals. See [[link: /cost/anti-aging-treatment | the anti-aging cost page]] and the PRP cost page at [[link: /cost/prp-treatment | PRP treatment cost]].","## Other options","If your main concern is movement lines, see [[link: /botulinum-toxin-injections | botulinum toxin injections]]. For surface texture, doctors may suggest other methods, covered in [[link: /learn/chemical-peels-for-ageing-skin | the peel guide]].","[[faq: Does PRP work for wrinkles? | Evidence is limited and mixed. Some people see a change in texture, and results vary. Ask the doctor what they expect.]]","[[faq: Is PRP made from my own blood? | Yes. A sample of your blood is processed and the platelet-rich part is used.]]","[[faq: How many sessions are needed? | It depends on the plan. Ask your doctor and agree a review point.]]","Related reading: [[link: /learn/skin-boosters-vs-fillers-vs-toxin | skin boosters, fillers and toxin compared]]. City pages: [[link: /anti-aging-treatment-in-lucknow | Lucknow]], [[link: /anti-aging-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on cosmetic procedures; peer-reviewed studies on platelet-rich plasma in facial skin, to be named after a reviewer opens them. TODO-VERIFY: add at least two verified papers.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('laser-for-ageing-skin-indian-skin', 'Laser for ageing skin on Indian skin tones', 'Ablative and non-ablative lasers in plain terms, the downtime, the pigment risk that matters most for Indian skin, pre-care and sun rules.', 6, 1, 'anti-aging-treatment', '["[[reviewer]]","Lasers send energy into the skin to prompt renewal. Some remove the outer layer (ablative) and some heat the deeper layers while leaving the surface intact (non-ablative). Both are used for texture, tone and fine lines. For Indian skin tones, the main risk is dark patches after treatment, so settings and the doctor matter. See our [[link: /anti-aging-treatment | anti-aging overview]].","## Ablative and non-ablative","- Ablative lasers remove the top layer and heat the layers below. Recovery is longer, with redness, oozing and crusting in the first days. TODO-VERIFY: reviewer confirms ranges.","- Non-ablative lasers heat deeper layers while sparing the surface. Downtime is shorter, redness lasts hours to a few days, and several sessions are common.","- Fractional methods treat a pattern of tiny points to shorten healing.","Device names vary and do not tell you much. Ask what type the doctor is using and why.","## What they may help","Doctors use lasers for fine lines, uneven texture and some surface marks. Results vary and are usually gradual. They do not lift sagging skin much, and they do not stop ageing. For firmness, see [[link: /learn/hifu-radiofrequency-skin-tightening | HIFU and radiofrequency]].","## Pigment risk in medium to dark skin","Heat can trigger extra pigment in skin with more melanin, known as post-inflammatory hyperpigmentation, and in some cases lighter patches. Doctors lower the risk by choosing suitable settings, testing a small area, pre-treating the skin and requiring strict sun protection. Ask how many Indian skin tones the doctor treats and how they handle a reaction. Do not accept a general promise that the laser is suitable for all skin types.","## Choosing who does it","Lasers should be used by a trained doctor who treats many skin tones. Ask about the person''s training, whether the device is maintained, and who handles complications. Do not choose on the device name or a low price alone.","## Pre-care","- Avoid sun and tanning for weeks before.","- Pause retinoids and strong acids if your doctor advises.","- Tell the doctor about cold sores, since a laser can set one off. They may give a preventive medicine.","- Share your history of scarring or keloid.","## Downtime and care afterwards","Expect redness, a sunburnt feeling and flaking. Keep the skin clean, moisturised and out of the sun. Follow written instructions, and do not pick crusts. A review visit lets the doctor check healing.","## Sessions","Some plans need several sessions weeks apart. TODO-VERIFY: reviewer sets any range. Ask how many sessions, what the gap is, and what you would do if marks appear.","> Test spots and conservative settings cost time. They are part of a careful plan, and not a delay.","## Cost","Laser prices depend on the device, the area, the number of sessions and the doctor. See our [[link: /cost/anti-aging-treatment | cost page]] for lines to compare.","## Who should wait","Wait if you have a tan or sunburn, active infection or cold sore, open skin or a keloid tendency. Do not proceed if you took isotretinoin recently, until your doctor agrees. Pregnant women should ask first.","## Questions worth asking","- Why this laser for my skin and my concern?","- How do you adjust for my skin tone?","- What are the signs that I should call you?","[[faq: Is laser suitable for Indian skin? | Some lasers can be used with care. The doctor should adjust the plan for your skin tone and discuss the pigment risk.]]","[[faq: Is laser resurfacing painful? | Many people feel heat or stinging, and numbing is often used. Sensations vary.]]","[[faq: How long do results last? | Results vary, and ageing continues. Sun protection helps keep the gains.]]","Related reading: [[link: /learn/chemical-peels-for-ageing-skin | chemical peels for ageing skin]], [[link: /learn/sunscreen-retinoids-skin-ageing | sunscreen and retinoids]]. City pages: [[link: /anti-aging-treatment-in-delhi | Delhi]], [[link: /anti-aging-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on laser skin resurfacing; NHS patient information on skin care. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('anti-aging-care-by-decade', 'Anti-aging care in your 30s, 40s and 50s', 'What doctors usually talk about by decade, why daily skin care comes first, where procedures fit, and what you probably do not need.', 6, 2, 'anti-aging-treatment', '["[[reviewer]]","Doctors usually discuss the same basics at every age: daily sunscreen, a gentle routine and not smoking. Procedures come into the conversation when a specific concern bothers you. There is no fixed list of treatments for each decade. See our [[link: /anti-aging-treatment | anti-aging treatment overview]].","## In your 30s","Skin often looks much as it did, with early fine lines around the eyes and forehead for some people. Doctors tend to stress sun protection, a simple moisturiser and, if suitable, a retinoid. Procedures are optional. Many people do not need any in this decade. TODO-VERIFY: reviewer sets wording.","## In your 40s","Lines at rest, uneven tone and a drier feel are common concerns. Hormone changes around perimenopause can affect skin. Doctors may talk about retinoids, peels, and injectables for movement lines. See [[link: /botulinum-toxin-injections | botulinum toxin injections]] for the area-based options. Ask what each suggestion is meant to change.","## In your 50s","Skin tends to be thinner and drier, and loss of volume and firmness are more visible. Doctors often discuss moisturising, sun care and treatment of specific concerns such as pigment or loose skin. Options range from creams to peels, lasers, fillers and energy devices. For loose skin, results of non-surgical devices are limited, and surgery is a different decision. TODO-VERIFY: reviewer confirms wording.","## What matters at any age","- Daily sunscreen and sun avoidance.","- Not smoking.","- Moisturising.","- Enough sleep and regular exercise, which support health overall.","- Treating skin conditions such as acne or pigment problems when they arise.","These steps cost little. See [[link: /learn/sunscreen-retinoids-skin-ageing | the basics before any procedure]].","## Where procedures fit","Procedures can soften certain lines, improve texture or add volume. They do not stop ageing, and they require upkeep. A reasonable approach is to name your specific concern, ask a doctor what is realistic, and start with the least invasive option. Review at a set date.","## What you may not need","You may not need a package of treatments, a monthly programme or a product line sold at the clinic. If someone recommends many procedures at once, ask which one matters most.","## Keeping a record","Keep a short note of each product and treatment you try, with the date and what you noticed. It helps the doctor see what has been tried and avoids repeating something that did not suit your skin. Photographs taken in the same light every few months are more useful than memory.","## Avoiding age-based pressure","Advertisements often suggest you should start at a certain age. A doctor can tell you whether you have a concern worth treating. There is no age at which you have failed to start. If you notice anxiety about ageing, a doctor can help you talk through it. See [[link: /learn/age-for-wrinkle-injections | what age doctors consider wrinkle injections]].","> Skin care is a daily habit. Procedures are optional extras that fit a specific concern.","## Cost","Plan on a yearly total, since most treatments repeat. See our [[link: /cost/anti-aging-treatment | cost page]].","## Who should wait","Wait if you are pregnant or breastfeeding, if you have an infection or sunburn, or if you are unwell. Tell the doctor about all medicines, and ask about the interval after isotretinoin.","## Questions worth asking","- What is the one concern I should address first?","- What can I do at home before a procedure?","- What are the yearly costs of this plan?","[[faq: When should I start anti-aging treatment? | There is no set age. Start with sun protection and a simple routine, then ask a doctor if a specific concern needs more.]]","[[faq: Do I need a procedure in my 30s? | Many people do not. A doctor can look at your skin and advise.]]","[[faq: Which treatment is right for my age? | There is no list by age. A doctor chooses after looking at your skin and goals.]]","Related reading: [[link: /learn/home-remedies-skin-ageing | what home remedies can and cannot do]]. City pages: [[link: /anti-aging-treatment-in-lucknow | Lucknow]], [[link: /anti-aging-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin ageing and sun protection; NHS patient information on sun protection. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('sunscreen-retinoids-skin-ageing', 'Sunscreen and retinoids: the basics before any procedure', 'Why sun exposure matters most for skin ageing, how to use sunscreen, what retinoids do and how they irritate, and what to pause before a peel or laser.', 6, 3, 'anti-aging-treatment', '["[[reviewer]]","Sun exposure is a major driver of visible skin ageing, and daily sunscreen is one of the most useful habits. Retinoids are medicines related to vitamin A that doctors use for texture and fine lines, and they can irritate. Many doctors ask you to start with these basics before any procedure. See our [[link: /anti-aging-treatment | anti-aging treatment overview]].","## Sun and ageing","Ultraviolet light damages skin over years and contributes to lines, uneven tone and rough texture. It also raises the chance of skin cancer. Indian skin tones have more natural protection but still tan, pigment and age with sun exposure. Dark skin also gets sunburn and skin cancer, so protection matters for everyone.","## How to use sunscreen","- Choose a broad-spectrum product, which covers both UVA and UVB light. Ask your doctor about the SPF that suits you.","- Apply enough to cover the face and neck, and reapply every couple of hours outdoors.","- Use it on cloudy days, and when indoors near strong windows.","- Combine it with shade, a hat and sunglasses.","Some sunscreens leave a white cast on darker skin. Try different formulas to find one you will use. Do not rely on makeup with SPF alone.","## What retinoids do","Retinoids help skin renew itself and can improve texture and fine lines with regular use over months. They are available as creams and gels, and some strengths need a prescription. TODO-VERIFY: reviewer confirms wording. They do not stop ageing, and results vary.","## Irritation and how to reduce it","Redness, dryness, peeling and stinging are common in the first weeks. Doctors often suggest using a small amount a few nights a week and building up. Use a plain moisturiser and sunscreen by day. Avoid using several strong products together. Stop and call your doctor if skin is very sore or swollen.","## Pregnancy","Some retinoids are not advised in pregnancy or when planning pregnancy. Tell your doctor before starting. See [[link: /learn/acne-medicines-doctors-prescribe | acne medicines explained]] for related drug groups.","## What to stop before a peel or laser","Many doctors ask you to pause retinoids and strong acids for some days before a peel or laser. The exact time depends on the procedure and your skin. Do not stop a prescribed medicine on your own. Ask for a written list. See [[link: /learn/chemical-peels-for-ageing-skin | the peel guide]] and [[link: /learn/laser-for-ageing-skin-indian-skin | the laser guide]].","## Reading labels","Check the ingredient list for the active you are looking for, and be wary of products that do not give one. Fragrance and alcohol can irritate sensitive skin. If you react to a product, stop it and show the label to your doctor. Introduce one new product at a time so that you know which one caused any reaction.","## Products to avoid","Avoid skin-lightening creams that include strong steroids, and unproven products sold online with big promises. Do not use lemon, baking soda or other kitchen items on the face. Ask a doctor first about new actives.","> A simple routine used every day will do more than a complicated one used for a week.","## Cost","Sunscreen and a retinoid cost much less than procedures. Ask your doctor what to start with, and add procedures only for specific concerns. See [[link: /cost/anti-aging-treatment | our cost page]].","## Who should wait","Pregnant women and those planning pregnancy should check with a doctor before using a retinoid. Do not use a retinoid on broken, sunburnt or infected skin.","## Questions worth asking","- Which sunscreen type suits my skin?","- Should I start a retinoid, and at what pace?","- What should I stop before a procedure?","[[faq: Do I need sunscreen indoors? | If you sit near a bright window or go outside, yes. Ask your doctor what suits your day.]]","[[faq: Can I use a retinoid every night? | Many doctors start with a few nights a week. Follow your own doctor''s plan.]]","[[faq: Does sunscreen prevent all ageing? | No. It lowers one cause, and ageing continues.]]","Related reading: [[link: /learn/anti-aging-care-by-decade | anti-aging care by decade]]. City pages: [[link: /anti-aging-treatment-in-delhi | Delhi]], [[link: /anti-aging-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on sunscreen and on retinoids; NHS patient information on sun protection. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('home-remedies-skin-ageing', 'Can food, yoga or home remedies slow skin ageing?', 'What evidence supports for skin health (sleep, sun, smoking, diet pattern), what has none, and why big promises on products should worry you.', 6, 1, 'anti-aging-treatment', '["[[reviewer]]","Some habits are linked to better skin health, such as sun protection, not smoking, enough sleep and a balanced diet. Many foods, yoga poses and home remedies promoted online have little or no evidence. None of them stops ageing. See our [[link: /anti-aging-treatment | anti-aging treatment overview]]. TODO-VERIFY: reviewer sets evidence wording.","## What has reasonable support","- Sun protection. This has the strongest link to visible skin ageing.","- Not smoking. Smoking is linked to more wrinkles and dull skin.","- Sleep. Regular sleep supports health, and poor sleep is linked to tired-looking skin in some studies.","- A balanced diet with vegetables, fruit and protein. Studies link overall diet patterns to health, and the effect on skin lines is less clear.","- Moisturiser, which improves dryness and comfort.","- Regular exercise, which supports general health.","## What has limited evidence","- Single \"anti-aging foods\". Evidence that one food changes skin lines is weak.","- Collagen drinks and powders. Studies are mixed and often funded by makers. Ask a doctor.","- Vitamin and antioxidant supplements. Taking more than you need can be harmful. Check with a doctor.","- Face yoga. Small studies exist, but evidence that it changes lines is limited.","- Face massage tools. They may feel nice, and evidence of lasting change is lacking.","## Home remedies to avoid","Lemon, baking soda, raw egg, toothpaste or kitchen spices on the face can burn or irritate the skin and may leave dark marks. Homemade masks can cause allergic reactions. If you want to try something, test a small area first and tell your doctor. Do not use it on broken skin.","## Red flags on products","- Promises that a product undoes ageing, removes wrinkles or give a particular look.","- Claims of a secret ingredient.","- Testimonials in place of evidence.","- High prices with no ingredient list.","- Pressure to buy a bundle.","If a product claims it works like a drug, a regulator may treat it differently. Ask a doctor what is known.","> No cream, drink or exercise stops skin from ageing. Some habits slow the damage that adds to it.","## Sleep, stress and skin","Poor sleep and long periods of stress are linked in some studies to tired-looking skin and flares of skin conditions. Fixing them is not simple, and it does not need a product. A doctor can help if sleep problems or low mood are affecting your life, which matters beyond skin.","## What a doctor adds","A doctor can look at your skin, decide whether you have a specific concern, and suggest options such as a retinoid or a procedure. See [[link: /learn/sunscreen-retinoids-skin-ageing | the basics of sunscreen and retinoids]] and [[link: /learn/anti-aging-care-by-decade | care by decade]].","## Cost","Many supplements and devices cost more than a consultation. Ask how much you have spent already. If you are comparing a procedure with a regimen, see [[link: /cost/anti-aging-treatment | our cost page]].","## Who should wait","Do not start supplements if you are pregnant, breastfeeding or taking other medicines until you have asked a doctor. Anyone with a skin condition such as eczema should check new products first.","## Questions worth asking","- Which habits matter most for my skin?","- Is this supplement or remedy suitable with my medicines?","- What would you recommend before I spend on procedures?","[[faq: Which foods are good for skin? | A balanced diet supports general health. No single food is proven to change skin lines.]]","[[faq: Does face yoga work? | Evidence is limited. It is low risk for most people if done gently, and it is not a replacement for sun protection.]]","[[faq: Are collagen supplements useful? | Evidence is mixed. Ask your doctor before spending on them.]]","Related reading: [[link: /learn/skin-boosters-vs-fillers-vs-toxin | skin boosters, fillers and toxin compared]]. City pages: [[link: /anti-aging-treatment-in-lucknow | Lucknow]], [[link: /anti-aging-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on skin ageing; NHS patient information on healthy lifestyle and skin. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hifu-radiofrequency-skin-tightening', 'HIFU and radiofrequency skin tightening: how they work', 'How focused ultrasound and radiofrequency heat the deeper skin, the areas treated, what it feels like, sessions, risks and limits compared with surgery.', 6, 2, 'anti-aging-treatment', '["[[reviewer]]","HIFU (high-intensity focused ultrasound) and radiofrequency use heat delivered below the skin surface to prompt tightening over weeks to months. Doctors use them for mild to moderate looseness. They do not do what surgery does, and results vary. See our [[link: /anti-aging-treatment | anti-aging treatment overview]].","## How they work","Both aim heat at deeper layers without cutting the skin. HIFU focuses ultrasound energy at set depths. Radiofrequency uses electrical energy to heat tissue, and some devices combine it with tiny needles. The skin is meant to respond over time by firming. Evidence of benefit varies by device and area, and studies are often small. TODO-VERIFY: reviewer confirms wording.","## Areas treated","Doctors use these methods on the lower face, jawline, neck and sometimes the brow or the skin of the body. Choice depends on the area and on how much looseness you have.","## What it feels like","Many people describe heat, snapping or tingling, and some find parts of the session uncomfortable. Numbing cream or pain relief is sometimes used. Ask the doctor what to expect. Sensations vary, and nobody can promise the experience will be comfortable for you.","## Sessions","Some plans use one session and a review. Others use several sessions. Effects, if any, tend to appear gradually over weeks to months. TODO-VERIFY: reviewer sets the range. Ask what you should see and by when, and what happens if there is no change.","## Risks","- Redness, swelling and tenderness for days.","- Bruising and numbness that settles with time in many cases.","- Burns and blisters if energy is too high or poorly applied.","- Uneven results, and nerve effects such as weakness in a part of the face, which are uncommon and usually temporary.","- Fat loss or contour change in a treated area, which is rare.","Deep heat is not a gentle option just because there is no cut. A trained doctor matters.","## Who it may suit","People with mild to moderate looseness who want a non-surgical option and accept a modest, gradual result. It is less suited to people with a lot of loose skin, who may need surgery. A doctor can say which group you are in.","## Limits compared with surgery","Surgery removes or repositions tissue, and energy devices do not. A device cannot lift heavy folds. Results of heat-based methods are smaller and do not last as long as surgical change. Ask the doctor to describe the difference in plain terms. See [[link: /learn/skin-boosters-vs-fillers-vs-toxin | other injectable options]].","> If someone says a device does the same as a surgical lift, ask what study supports it.","## Body fat is a different issue","These devices are mostly used on skin looseness. Excess body fat is a different topic, covered in our [[link: /liposuction | liposuction guide]].","## Cost","Prices vary with the device, area and number of sessions. See our [[link: /cost/anti-aging-treatment | cost page]]. Ask for the total for the whole plan.","## Who should wait","Wait if you are pregnant, have a skin infection, open wounds or implants in the treated area, or a pacemaker or other implanted device, unless your doctor agrees. Tell the doctor about fillers and previous procedures.","## Questions worth asking","- Which method and why for my area?","- What are the risks for my face?","- How will we judge whether it worked?","[[faq: Is HIFU the same as radiofrequency? | No. HIFU uses focused ultrasound. Radiofrequency uses electrical energy. Both heat deeper tissue.]]","[[faq: Is it a replacement for a facelift? | No. Results are smaller. Surgery does things devices cannot.]]","[[faq: How long do results last? | Ageing continues, and results vary. Ask your doctor for a realistic range.]]","Related reading: [[link: /learn/laser-for-ageing-skin-indian-skin | laser for ageing skin on Indian skin tones]], [[link: /learn/chemical-peels-for-ageing-skin | chemical peels]]. City pages: [[link: /anti-aging-treatment-in-delhi | Delhi]], [[link: /anti-aging-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on cosmetic procedures; American Society of Plastic Surgeons patient information on non-surgical skin tightening. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-how-it-is-made', 'How PRP is made: blood draw to injection', 'The steps from a small blood sample to platelet-rich plasma, what platelet-rich means, why methods differ, and what to ask a clinic about its process.', 5, 1, 'prp-treatment', '["[[reviewer]]","Platelet-rich plasma (PRP) is made from a small sample of your own blood. The blood is spun in a centrifuge so the platelet-rich part separates, and that part is then injected or applied to the treatment area. Methods differ between clinics, so ask how yours works. See our [[link: /prp-treatment | PRP treatment overview]].","## What platelet-rich means","Blood contains red cells, white cells, platelets and plasma. Platelets help with clotting and also release signalling substances. PRP is plasma that has more platelets per millilitre than your normal blood. The exact concentration differs between kits and methods, and the ideal concentration is not settled. TODO-VERIFY: reviewer confirms wording.","## Step by step","- A nurse or doctor takes blood from a vein in your arm, usually a small amount in one or more tubes.","- The tubes go into a centrifuge, which spins them to separate the layers.","- The platelet-rich layer is drawn off. Some methods spin the blood twice.","- Some clinics add an activating agent just before use. Others use none.","- The PRP is injected into the treatment area or applied to the skin after needling.","The whole visit often lasts about an hour, including preparation. TODO-VERIFY: reviewer confirms the time.","## Single and double spin","A single-spin system uses one round, and a double-spin system uses two. Neither is proven better for every use. Ask the doctor which they use and why. Do not accept a claim that a particular machine is the only right one.","## Kits and devices","Several kits and machines are sold for PRP. Their regulatory status and quality differ. Ask whether the kit is single use, whether it is sealed, and where it came from. Do not choose a clinic because of a machine name.","## Hygiene and handling","Because PRP uses your own blood, allergy to the product is unlikely. Infection, bruising and pain at the draw and injection sites are possible. Tools and tubes must be clean or single use. Ask how the clinic prevents mix-ups of samples when several patients are treated in a day.","## What it is used for","Doctors use PRP in several areas, including hair thinning, skin and some joint problems. The evidence differs by use. Hair is covered in [[link: /learn/prp-for-hair-loss-evidence | our evidence guide]]. The skin uses are covered in [[link: /learn/prp-for-skin-face-under-eye | the skin guide]].","> PRP is a procedure whose steps vary. Ask for the steps in writing, and ask what each is for.","## Before your visit","Drink water, eat a light meal, and tell the doctor about blood thinners and supplements. Ask whether to avoid anti-inflammatory painkillers beforehand. Do not stop prescribed medicine on your own.","## Cost","The price depends on the kit, the doctor''s time, the area and any add-ons such as needling. Ask for the cost of each session and of the plan. See [[link: /cost/prp-treatment | our cost page]].","## Who should wait","Wait if you have a blood disorder, a low platelet count or an infection, if you take blood-thinning medicine that your doctor has not reviewed, or if you are pregnant or breastfeeding. See [[link: /learn/prp-who-should-wait | the full checklist]].","## Questions worth asking","- Which method and kit do you use, and how is it stored and discarded?","- How is my sample labelled?","- How many sessions do you suggest, and why?","[[faq: Is PRP made from my own blood? | Yes. A small sample of your blood is processed and the platelet-rich part is used.]]","[[faq: Does blood draw hurt? | It is a routine needle draw. Many people feel a brief sting. The injections can feel more uncomfortable.]]","[[faq: Is there one correct way to make PRP? | No. Methods differ, and the ideal concentration is not settled.]]","Related reading: [[link: /learn/prp-side-effects | PRP side effects]]. City pages: [[link: /prp-treatment-in-delhi | Delhi]], [[link: /prp-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss and treatments; peer-reviewed reviews on platelet-rich plasma preparation, to be named after a reviewer opens them. TODO-VERIFY: add verified papers.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-for-hair-loss-evidence', 'Does PRP work for hair loss? What the evidence says', 'What studies of PRP for pattern hair thinning tested, why results are mixed, who may see no change, and why a diagnosis comes before any plan.', 6, 2, 'prp-treatment', '["[[reviewer]]","Evidence on PRP for hair thinning is mixed. Some small studies report more hair in some people with pattern thinning, and others show little change, and the studies use different methods. PRP is not a proven fix and results vary. A doctor should find the cause of the thinning first. See our [[link: /prp-treatment | PRP treatment overview]].","## What studies tested","Most studies looked at men and women with pattern hair thinning, often called androgenetic alopecia. They injected PRP into the scalp in a series of sessions and counted hairs or measured density, usually compared with a placebo or with another treatment. Findings differ in the number of sessions, the PRP method and how outcomes were measured. TODO-VERIFY: reviewer names at least two papers that a person has opened, and sets the exact wording.","## Why results are mixed","- PRP is made in different ways, so one study''s PRP may not match another''s.","- The number of people studied is often small.","- Follow-up time is often short.","- Hair counts vary with the day and the method.","- People differ in the type and stage of thinning.","This is why a doctor cannot promise a result. If a clinic gives you a percentage, ask which study it comes from.","## Patterns where it has been tried","Doctors have used PRP in early to moderate pattern thinning, and for other types of hair loss in some cases. The evidence is weaker for other causes. Thinning can also come from thyroid problems, low iron, medicines, stress, scalp disease or hormone conditions. Those need their own care. Treating PRP as the answer without a diagnosis risks wasting money and time.","## Who may see no change","People with advanced baldness, where follicles are gone or very small, are less likely to benefit. Someone with a cause that is not addressed may also see little change. A doctor can examine your scalp, ask about family history and order tests if needed. TODO-VERIFY: reviewer confirms wording.","## The place of medical therapy","Doctors usually discuss established medicines first. See [[link: /learn/prp-vs-minoxidil-finasteride | PRP versus minoxidil and finasteride]]. PRP is sometimes suggested in addition to them. When thinning is advanced, a hair transplant may be discussed, which is covered in the [[link: /hair-transplant | hair transplant guide]].","## What a fair plan looks like","A scalp examination, a named diagnosis, a clear statement that evidence is mixed, a set number of sessions, a review point at which you and the doctor decide whether to continue, and a written total. If the doctor will not talk about the limits, ask someone else.","> Ask what happens if there is no change after the planned sessions.","## Cost","Prices vary with the kit, the doctor''s time, the sessions and add-ons. Plan for a series, and add a review. Do not pay for a large prepaid package before you know how you respond. See [[link: /cost/prp-treatment | our cost page]] and [[link: /learn/prp-cost-why-quotes-differ | why quotes differ]].","## Who should wait","Wait if you have a blood disorder or low platelets, active scalp infection, cancer under treatment, or if you are pregnant or breastfeeding. Take medicines for thinning as your doctor says, and ask before stopping any.","## Questions worth asking","- What do you think is causing my thinning?","- What does the evidence say for people like me?","- How will we judge whether it is working, and when do we stop?","[[faq: Does PRP stop hair fall? | Evidence is mixed. Some people see a change, others do not. A doctor should look for the cause of the thinning first.]]","[[faq: Is PRP better than minoxidil? | They are different options. Doctors often start with established medicines, and PRP may be added. Ask your doctor.]]","[[faq: How soon will I know if PRP is working? | It takes months to judge, since hair cycles are slow. Ask your doctor for a review date.]]","Related reading: [[link: /learn/prp-hair-sessions-and-spacing | PRP for hair: sessions and spacing]], [[link: /learn/prp-side-effects | side effects]]. City pages: [[link: /prp-treatment-in-lucknow | Lucknow]], [[link: /prp-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss; NHS patient information on hair loss; at least two peer-reviewed papers on PRP for pattern hair thinning, to be named after a reviewer opens them. TODO-VERIFY: add verified papers.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-hair-sessions-and-spacing', 'PRP for hair: sessions and spacing explained', 'How doctors describe a PRP plan for hair, why the number and gap of sessions vary, what a review checks, and when stopping is reasonable.', 5, 3, 'prp-treatment', '["[[reviewer]]","There is no fixed number of PRP sessions for hair. Doctors usually describe a series of sessions several weeks apart, followed by a review and possibly maintenance visits. The plan depends on your hair, your doctor and the evidence they rely on. Ask for the plan in writing. See our [[link: /prp-treatment | PRP treatment overview]]. TODO-VERIFY: reviewer sets any numbers.","## Why plans differ","Studies of PRP for hair used different schedules, and no single plan has been agreed. Clinics follow their own habits. A plan may differ for early thinning and for more advanced loss. Ask the doctor what their schedule is based on.","## A typical shape","Doctors often describe:","- A first series of sessions spaced weeks apart.","- A review after the series, to judge change.","- Possible maintenance sessions after that, at longer gaps.","The numbers are set by the doctor. Be wary of a package with a fixed large number of sessions that is paid in full at the start. TODO-VERIFY: reviewer confirms wording.","## Why it takes months to judge","Hair follows a slow cycle. Hairs shed and new ones grow over months, so a change in density is hard to see after one or two sessions. A review at the right time is more useful than weekly checking. Take photos in the same light and angle at each visit.","## What a review checks","The doctor compares photos and may use a close-up scalp exam. They ask about shedding, any new medicines or illness, and side effects. They decide whether to continue, change the plan, or stop. If you cannot see a difference at the review, you can ask to stop.","## When stopping is reasonable","- No change at the agreed review point.","- Side effects that bother you.","- A cause for the thinning has been found that needs another treatment.","- The cost no longer fits your plans.","A good plan has a stopping point from the start.","## Combining with medicines","Doctors often use PRP in addition to prescribed medicines, and the combination is chosen case by case. See [[link: /learn/prp-vs-minoxidil-finasteride | PRP versus minoxidil and finasteride]]. If you stop a medicine, thinning can resume, which is true of the medicines and not of PRP alone.","## Maintenance","Some doctors suggest repeat sessions to keep any gain. Evidence on how long benefit lasts is limited. Ask what the maintenance plan would cost for a year. See [[link: /cost/prp-treatment | the cost page]].","> The most useful question about a plan is what happens if it does not work.","## Practical points","Wear loose clothing and bring a cap if you want to cover the scalp afterwards. Plan sessions when you can avoid heavy exercise for the rest of the day. Ask about washing hair on the day, and about avoiding scalp products for some hours. Follow your doctor''s instructions.","## Who should wait","Wait if you have a scalp infection, a blood disorder, low platelets, or if you are pregnant or breastfeeding. Doctors may ask you to pause blood-thinning medicines only if it is appropriate. Do not stop them on your own.","## Questions worth asking","- How many sessions, how far apart, and why?","- When is the review, and what will you check?","- What will a year of this plan cost?","[[faq: How many PRP sessions do I need for hair? | The number is set by your doctor and varies. Ask for the plan and a review point.]]","[[faq: How far apart are the sessions? | Often several weeks. Your doctor decides.]]","[[faq: Do I need maintenance? | Some doctors suggest it. Evidence on how long a benefit lasts is limited.]]","Related reading: [[link: /learn/prp-for-hair-loss-evidence | what the evidence says]], [[link: /learn/prp-side-effects | side effects]]. City pages: [[link: /prp-treatment-in-delhi | Delhi]], [[link: /prp-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss; NHS patient information on hair loss. TODO-VERIFY: open each page and confirm wording on session plans.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-vs-minoxidil-finasteride', 'PRP vs minoxidil vs finasteride for thinning hair', 'What each option is, how it is used, who prescribes it, the main side effects, whether they can be combined, and why finding the cause comes first.', 6, 1, 'prp-treatment', '["[[reviewer]]","Minoxidil and finasteride are medicines doctors use for pattern hair thinning, and PRP is a procedure that some doctors add. They work in different ways, and a doctor decides which suit you after finding the cause. Minoxidil and finasteride need a doctor''s advice, and neither suits everyone. See our [[link: /prp-treatment | PRP treatment overview]].","## Find the cause first","Thinning can come from pattern hair loss, thyroid or iron problems, medicines, stress, scalp disease or hormone conditions. A doctor can examine your scalp and order tests if needed. A plan for the wrong cause wastes time.","## Minoxidil","Minoxidil is applied to the scalp as a liquid or foam, and some doctors prescribe it in other forms. It is used regularly over months. Common effects include scalp irritation and, in some people, increased shedding at first. Unwanted hair on the face can occur. Stopping it usually means thinning returns. Ask your doctor which form suits you. TODO-VERIFY: reviewer confirms wording.","## Finasteride","Finasteride is a prescription tablet used in men with pattern thinning. It affects a hormone involved in the process. Reported side effects include sexual problems and mood changes in some men, and the effect on a pregnancy matters, so women who are or may become pregnant should not handle crushed or broken tablets. It is not used in the same way for women. Your doctor will explain the risks and checks. Only a doctor can prescribe it.","## PRP","PRP is a procedure using your own blood, described in [[link: /learn/prp-how-it-is-made | how PRP is made]]. Evidence is mixed, as set out in [[link: /learn/prp-for-hair-loss-evidence | the evidence guide]]. It is sometimes added to medicines.","## Who prescribes and manages","A dermatologist or a trained physician should prescribe medicines for hair thinning and review progress. Do not buy prescription medicines without a prescription, and do not rely on an online seller. Ask about monitoring and follow-up.","## Can they be combined?","Doctors sometimes combine a medicine with PRP. The decision depends on your hair, your health, your budget and your goals. More treatments do not always mean a better outcome. Ask what each part is for.","## Differences in plain terms","- Minoxidil: applied to the scalp, used daily, and works only while you use it.","- Finasteride: a tablet for men, with specific side effects, taken regularly under a doctor''s care.","- PRP: a clinic procedure repeated over several visits, with mixed evidence.","## Side effects to discuss","Ask about scalp irritation, shedding, sexual effects, mood changes and how a pregnancy would change the plan. Report any new symptoms. See [[link: /learn/prp-side-effects | PRP side effects]] for the procedure.","> Medicine and procedure both need a review date. Ask for it at the first visit.","## Cost","Medicines cost money every month, and PRP costs money per session. Work out a yearly total for each option. See [[link: /cost/prp-treatment | the cost page]].","## Who should wait","Pregnant women and those planning pregnancy should talk to a doctor before any of these. Wait on PRP if you have a blood disorder or infection. Tell your doctor about all medicines and liver or heart conditions.","## Questions worth asking","- What is causing my thinning?","- What are the side effects of each option for me?","- How long should I try before we review?","[[faq: Is minoxidil better than PRP? | They are different. Doctors often start with medicines, and PRP may be added. Ask your doctor.]]","[[faq: Can women take finasteride? | It is not used the same way as in men, and it carries pregnancy risks. A doctor decides.]]","[[faq: Do I have to continue minoxidil forever? | Usually the effect lasts only while you use it. Ask your doctor.]]","Related reading: [[link: /learn/hair-transplant-for-women | hair transplant for women]], [[link: /learn/hair-transplant-shock-loss | shock loss after a transplant]]. City pages: [[link: /prp-treatment-in-lucknow | Lucknow]], [[link: /prp-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss treatments; NHS patient information on hair loss. TODO-VERIFY: open each page and confirm wording on both medicines.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-side-effects', 'PRP side effects: what is common and what is not', 'Common effects of PRP injections such as bruising and swelling, less common problems, red flags, who should wait and when to call the doctor.', 5, 2, 'prp-treatment', '["[[reviewer]]","Common effects of PRP are pain at the injection sites, swelling, redness and bruising, which settle over days. Less often, people get headache, infection or an uneven result. PRP uses your own blood, so allergy to it is unlikely, but any needle procedure carries risks. See our [[link: /prp-treatment | PRP treatment overview]].","## Common effects","- Soreness or a tight feeling at the blood draw site and where PRP was injected.","- Swelling and redness for a day or two.","- Small bruises, more likely if you take blood-thinning medicine.","- A mild headache after scalp injections.","- A feeling of numbness or sensitivity in the area for a short time.","TODO-VERIFY: reviewer confirms the durations. Most people go home the same day.","## Less common effects","- Infection at an injection site, with pain, warmth, pus or fever.","- Scarring or nerve injury, which are rare.","- Reactions to numbing cream, an activating agent or needling products.","- An uneven result or lumps in skin treated for texture.","- Fainting at the blood draw.","- Shedding of hairs in some people after scalp treatment, which a doctor can explain.","## Red flags","- Fever, spreading redness, pus or increasing pain.","- Severe swelling or headache that does not settle.","- Vision changes, if treatment was near the eyes.","- Numbness that is spreading.","Call the doctor who treated you or seek urgent care for these signs.","## Who should wait","Wait if you have a blood disorder, low platelets, an infection, cancer under treatment, or a condition that affects clotting. Pregnant and breastfeeding women should check with a doctor first. Tell the doctor about blood thinners and supplements such as fish oil and vitamin E. See [[link: /learn/prp-who-should-wait | who should not have PRP]].","## Lowering the risk","Choose a registered doctor. Ask about single-use kits and how the area is cleaned. Follow instructions on washing, sun and exercise. Do not pick scabs. Report anything that worries you early.","## When to expect the worst of it","Soreness is usually strongest on the day and the day after. If it is getting worse after the third day instead of easing, call the clinic. Keep a note of when symptoms started, since it helps the doctor judge whether the cause is the procedure or something else.","## What to ask before treatment","- What are the usual and rare risks for me?","- Whom do I call after hours?","- What happens if I get an infection or a reaction, and who bears the cost?","See [[link: /learn/prp-how-it-is-made | how PRP is made]] for the process.","> A procedure with a low risk of serious harm still needs informed consent. Ask for the risks in plain words.","## After the session","Keep the treated area clean, and do not apply makeup or scalp products until the clinic says you can. Avoid touching the area for the first hours. Many doctors ask you to skip heavy exercise and some skin products for a day or so. Follow your own instructions. A cold pack can help with swelling if your doctor agrees. TODO-VERIFY: reviewer confirms the list.","## Cost of problems","Some clinics include a review visit and treatment of minor problems in the price, and some charge for each. Ask whether review visits are included and what happens if you need extra care. See [[link: /cost/prp-treatment | our cost page]].","[[faq: Is PRP painful? | Many people find the injections uncomfortable. Numbing is often used. Sensations vary.]]","[[faq: Can PRP cause an allergic reaction? | Allergy to your own blood is unlikely, but reactions to other products used in the session can happen.]]","[[faq: How long do bruises last? | Often days, and longer in some people. Tell your doctor if they worry you.]]","Related reading: [[link: /learn/prp-for-hair-loss-evidence | what the evidence says]], [[link: /learn/prp-for-skin-face-under-eye | PRP for skin]]. City pages: [[link: /prp-treatment-in-delhi | Delhi]], [[link: /prp-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss treatments; NHS patient information on injections and aftercare. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-for-skin-face-under-eye', 'PRP for skin: face, under-eye and scars', 'How doctors describe PRP for facial skin, the area under the eyes and scars, how it pairs with needling, what it does not do, and who should wait.', 6, 3, 'prp-treatment', '["[[reviewer]]","Doctors use PRP on the face, around the eyes and on some scars. Evidence for these uses is limited and mixed, and results vary. PRP is often combined with micro-needling. It does not remove dark circles caused by pigment or deep scars. A doctor should examine your skin first. See our [[link: /prp-treatment | PRP treatment overview]].","## Facial skin","People ask about PRP for fine lines, texture and dullness. Doctors may inject small amounts in the skin or apply PRP after needling. Studies exist, with mixed findings and different methods. For the broader anti-ageing picture, see [[link: /learn/prp-face-evidence | PRP for the face: what evidence exists]] and the [[link: /anti-aging-treatment | anti-aging overview]].","## Under the eyes","The skin under the eyes is thin, so injections need care. Dark circles have many causes: pigment, shadows from the shape of the face, visible blood vessels, allergy, tiredness and thin skin. PRP may not help all of them, and evidence is limited. A doctor should identify the cause before suggesting any treatment. TODO-VERIFY: reviewer confirms wording on dark circles.","## Scars","Doctors sometimes use PRP with needling for acne scars, with the aim of improving texture. The evidence is limited, and other methods are used more widely. See [[link: /learn/acne-scar-types-treatment | acne scar types and options]]. PRP does not remove scars.","## PRP with micro-needling","Needling creates tiny channels in the skin. PRP is applied after, so it reaches the skin through those channels. Redness and flaking follow for a few days. Needling carries its own risks, including infection and pigment change, and it is a separate procedure with its own cost.","## What PRP does not do","- It does not remove dark circles caused by pigment.","- It does not lift sagging skin or fill deep folds.","- It does not replace sun protection.","- It does not stop ageing.","Ask a doctor what they expect and what that is based on. Be cautious about names such as \"vampire\" treatments, which are marketing and not medical terms.","## Sessions","Doctors may suggest a series of sessions weeks apart, followed by a review. Skin treated with needling needs time to settle between visits, and sun protection matters throughout. TODO-VERIFY: reviewer sets any range. Ask when you will judge the result and what you would do if there is none. Keep to a sun-protection routine between visits, because irritated skin that is exposed to sun can darken.","## Risks","Bruising, swelling and redness are common, and they can be more visible on thin skin around the eyes. Less often there are infection, pigment change or an uneven result. Risk of a cold sore flare is possible. See [[link: /learn/prp-side-effects | PRP side effects]].","> Name the problem first. A treatment makes sense only if it matches the cause.","## Cost","Prices vary with the kit, the area, whether needling is used and the number of sessions. See [[link: /cost/prp-treatment | the cost page]].","## Who should wait","Wait if you have a blood disorder, an infection, a cold sore, active acne in the area or sunburn, and if you are pregnant or breastfeeding. A tendency to thick scars needs a doctor''s advice before needling. See [[link: /learn/prp-who-should-wait | the checklist]].","## Questions worth asking","- What is causing my concern, and is PRP suited to that cause?","- What would you expect and why?","- What is the plan if there is no change?","[[faq: Does PRP help dark circles? | Evidence is limited, and dark circles have many causes. A doctor should identify the cause first.]]","[[faq: Is PRP facial the same as a vampire facial? | The name is a marketing term for PRP with needling. Ask what is actually done.]]","[[faq: Can PRP remove acne scars? | It may help texture a little in some people. It does not remove scars.]]","Related reading: [[link: /learn/prp-how-it-is-made | how PRP is made]]. City pages: [[link: /prp-treatment-in-lucknow | Lucknow]], [[link: /prp-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on cosmetic procedures; peer-reviewed studies on PRP in facial skin and scars, to be named after a reviewer opens them. TODO-VERIFY: add verified papers.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-who-should-wait', 'Who should not have PRP: a checklist', 'Conditions and medicines that may mean waiting or avoiding PRP, the questions a doctor asks, tests that may be needed, and what to tell the clinic.', 5, 1, 'prp-treatment', '["[[reviewer]]","PRP may not suit people with blood disorders, low platelets, some infections, certain cancers, or those taking blood-thinning medicines. Pregnant and breastfeeding women are usually advised to wait. A doctor must check your history before treatment. This list is general, and the reviewer will confirm each item. See our [[link: /prp-treatment | PRP treatment overview]].","## Conditions that call for care","- Blood disorders and low platelet counts, since PRP depends on your platelets.","- Conditions that affect clotting.","- Active skin infection or an open wound at the treatment site.","- Current cancer or a recent diagnosis, unless your treating doctor agrees.","- Fever or a general infection.","- Uncontrolled diabetes, or conditions that slow healing.","- Liver disease, which can affect platelets and clotting.","- A weak immune system.","TODO-VERIFY: reviewer signs off every item.","## Medicines that matter","- Blood thinners, such as tablets or injections that stop clots.","- Anti-inflammatory painkillers, which some doctors ask you to avoid around the time of treatment.","- Steroids, in the area or by mouth.","- Supplements that can affect bleeding, for example fish oil and vitamin E.","Do not stop prescribed medicine on your own. Ask the prescribing doctor first.","## Pregnancy and breastfeeding","Information on PRP in pregnancy is limited. Many doctors advise waiting. Tell the clinic if you may be pregnant. If you are breastfeeding, ask the doctor.","## Habits and recent events","Heavy alcohol use, smoking and a recent illness can affect platelets and healing. Sun exposure or sunburn in the treatment area, and recent procedures such as peels, lasers or other injections, may mean waiting. Ask what gap to leave.","## What a doctor should ask","Your history of bleeding and clotting, your medicines and supplements, allergies, infections, previous procedures, any cancer history and your goals. A clinic that skips these questions gives you a reason to look elsewhere.","## Why the list is long","Each item on this list links to one of two concerns: whether PRP will work as intended when platelets or clotting are affected, and whether the procedure could harm you. A long history form is routine, and your answers help the doctor decide whether to proceed, change the plan or refer you to a specialist first.","## Tests that may be needed","Doctors may advise a blood count or other tests if your history suggests a problem. Do not order tests without a doctor reviewing them. TODO-VERIFY: reviewer confirms wording.","## What to tell the clinic","Bring a list of all medicines, dates of recent procedures and any hospital stays. Mention if you faint at needles. Say if you have had a bad reaction to numbing cream.","> A thorough history takes a few minutes, and it protects you. Ask the clinic to explain why a question matters.","## Cost","A consultation may be charged separately. Ask whether tests are included. See [[link: /cost/prp-treatment | our cost page]].","## Other options","If PRP does not suit you, a doctor can suggest other plans. For hair, see [[link: /learn/prp-vs-minoxidil-finasteride | the medicine comparison]]. For skin, see [[link: /learn/prp-for-skin-face-under-eye | PRP for skin]].","## Questions worth asking","- Is there any reason PRP might not suit me?","- Which of my medicines would you want me to review first?","- What tests, if any, do I need before treatment?","[[faq: Can I have PRP while taking blood thinners? | Only if your doctor has reviewed it. Do not stop the medicine on your own.]]","[[faq: Can PRP be done if I have diabetes? | It depends on how well it is controlled and on the treatment area. A doctor decides.]]","[[faq: Is PRP suitable in pregnancy? | Doctors usually advise waiting, since information is limited.]]","Related reading: [[link: /learn/prp-side-effects | PRP side effects]], [[link: /learn/prp-how-it-is-made | how PRP is made]]. City pages: [[link: /prp-treatment-in-delhi | Delhi]], [[link: /prp-treatment-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss treatments; NHS patient information on blood tests and medicines that affect bleeding. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('prp-cost-why-quotes-differ', 'PRP cost: why one clinic quotes more than another', 'What makes PRP quotes differ, from the kit and doctor time to add-ons and number of sessions, how to compare quotes line by line, and red flags.', 5, 2, 'prp-treatment', '["[[reviewer]]","Two PRP quotes can differ because they include different things: the kit used, the doctor''s time, add-ons such as needling, the number of sessions and follow-up. Ask for each quote in writing and compare line by line. All figures on our pages are sample data pending confirmed quotes. See our [[link: /cost/prp-treatment | PRP cost page]] and [[link: /prp-treatment | overview]].","## What goes into a quote","- Consultation, and whether it is credited if you proceed.","- The kit and consumables used to make the PRP.","- The doctor''s time and who performs the session.","- Numbing cream or other comfort steps.","- Add-ons such as needling or other products.","- The number of sessions in the plan.","- A review visit, and any maintenance sessions.","## Why quotes differ","Kits differ in cost, and clinics differ in how much they spend on equipment and staff. The doctor''s training and the city also matter. A quote that looks low may leave out the review or the add-ons. One that looks high may include them.","## A simple formula","Total plan cost = consultation + (price per session x number of sessions) + add-ons + review visits + any maintenance. Ask the clinic to fill in each part. This is a formula only, and we do not state an average. TODO-VERIFY: figures come only from confirmed quotes.","## Prepaid packages","A package of many sessions paid at the start can lower the price per session and lock you in. Ask:","- Can I stop if I see no change or have side effects, and what happens to the unused sessions?","- What is the refund policy, in writing?","- Is the same kit used in each session?","- Is there an expiry on the package?","Be cautious of pressure to pay on the first visit. See [[link: /learn/prp-hair-sessions-and-spacing | sessions and spacing]].","## Questions about the plan itself","Ask how many sessions the doctor suggests and why, when you will review, and what the evidence says for your concern. For hair, see [[link: /learn/prp-for-hair-loss-evidence | the evidence guide]]. A cheaper plan with no review may cost more in the end than a priced plan that stops when it should.","## Red flags","- A price given only by phone.","- A quote that changes on the day.","- A promise of a particular result.","- Refusal to say who performs the session.","- No questions about your health.","- Pressure to buy a large package right away.","## Checking the doctor","Ask who will perform the session, and check the registration on the state medical council register. Doctor time is one of the lines that changes the quote, so ask whether the price depends on who does it.","## Insurance","PRP for cosmetic reasons is usually not covered. Ask your insurer in writing. TODO-VERIFY: reviewer or lawyer confirms wording.","> The clearest quote is one that lists every line and the total.","## Where to find local sample ranges","City pages show sample ranges only when real quotes exist. See [[link: /prp-treatment-in-delhi | Delhi]] and [[link: /prp-treatment-in-gurgaon | Gurgaon]]. Until then, treat any number as unverified, including ours.","## Who should wait","Do not pay for PRP before a doctor has checked whether it suits you. Wait if you have a blood disorder, infection or pregnancy question. See [[link: /learn/prp-who-should-wait | the checklist]].","## Questions worth asking","- What does the total include and leave out?","- What is the exit policy for a package?","- What is the review plan?","[[faq: Why is PRP so expensive in some clinics? | Costs come from the kit, the doctor''s time, the setting and add-ons. A higher price does not prove better results.]]","[[faq: Is a package cheaper? | The price per session may be lower, but you commit upfront. Ask about exit and refund terms.]]","[[faq: Is the consultation free? | Policies differ. Ask in writing.]]","Related reading: [[link: /learn/prp-side-effects | PRP side effects]]. More city pages: [[link: /prp-treatment-in-lucknow | Lucknow]], [[link: /prp-treatment-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: Sources to be added after reviewer sign-off. TODO-VERIFY: a named consumer protection or regulator page, opened and checked.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-fue-fut-dhi', 'FUE, FUT and DHI: how they differ and what to ask', 'How follicles are taken in FUE and FUT, what DHI means, the scar and shaving differences, who each usually fits, and questions to ask the surgeon.', 6, 1, 'hair-transplant', '["[[reviewer]]","FUE takes follicles one at a time with a small punch, and FUT removes a thin strip of scalp from the back and splits it into grafts. DHI is a name some clinics use for a version of FUE in which a pen-like tool places the hairs. Which fits you depends on your donor area, your goals and the surgeon. See our [[link: /hair-transplant | hair transplant overview]].","## How follicles are taken","- FUE (follicular unit extraction): the surgeon removes individual follicular units from the donor area with a tiny punch. The donor area is usually trimmed short, and some clinics shave it.","- FUT (follicular unit transplantation, strip method): the surgeon removes a thin strip of scalp from the back or sides, closes the wound with stitches or staples, and technicians split the strip under magnification.","- DHI (direct hair implantation): the term used by some clinics for FUE with a pen-like implanter that places each graft directly. TODO-VERIFY: reviewer confirms wording. Others use the term as a brand or marketing name, so ask what exactly is done.","## Scars","FUE leaves many tiny dot-like marks that are usually hard to see under short hair. FUT leaves a thin line across the back of the scalp, which can be visible if hair is cut very short. Both can scar in an unusual way in some people. Ask to see the surgeon''s technique for closing and how scars are handled. Photos from one clinic cannot predict your own scarring.","## Shaving and downtime","FUE often needs the donor area to be trimmed, and some people need a larger shaved patch. FUT avoids shaving a wide area, though a strip must be taken. Recovery details appear in [[link: /learn/hair-transplant-recovery-calendar | the recovery calendar]]. Both involve swelling, scabbing and a period without strenuous exercise.","## Who each usually fits","- FUE: people who want to wear their hair very short, who prefer no linear scar, or who need grafts from more than one area, as decided by the surgeon.","- FUT: people with a lax scalp and a larger donor requirement, who accept a linear scar.","- DHI: people for whom the surgeon thinks the implanter method fits. Ask for the reasons.","No method fits everyone, and a good surgeon explains what fits your pattern. See [[link: /learn/hair-transplant-donor-area-limits | donor area limits]].","## Questions to ask","- Which method do you recommend for me, and why?","- Who removes the grafts and who places them? What is their training?","- How many grafts are planned, and what is the plan if the donor falls short?","- How is the donor area protected from over-harvesting?","- What does the quote include? See [[link: /learn/hair-transplant-cost-per-graft | how the bill is built]].","## Questions a clinic should not dodge","Ask who performs each step. In some places, unqualified staff perform parts of the surgery, and that is a recognised problem. Ask for the surgeon''s name and check their registration on the state medical council register. TODO-VERIFY: reviewer cites an official source on qualification concerns.","## Risks","Bleeding, infection, swelling, numbness, scarring, uneven density and a result that looks different from what you expected can occur. Shedding after surgery is common and described in [[link: /learn/hair-transplant-shock-loss | our shock loss guide]].","> A method name is a label. The surgeon''s skill and the plan matter more than the label.","## Cost","Prices depend on the method, the number of grafts, the surgeon, the clinic and the city. See [[link: /cost/hair-transplant | our cost page]].","## Who should wait","Wait if your hair loss is still changing quickly, if the cause is not known, or if you are unwell. A doctor may ask you to try medical treatment first. See [[link: /learn/hair-transplant-norwood-grade-candidate | candidacy by Norwood grade]].","[[faq: Which is better, FUE or FUT? | Neither is better for everyone. The right method depends on your donor area, hair length, scar tolerance and the surgeon''s skill.]]","[[faq: Is DHI different from FUE? | Some clinics use DHI for a form of FUE with a pen-like implanter. Ask what exactly is done and by whom.]]","[[faq: Does FUE leave scars? | Every method leaves some mark. Ask what scars to expect and see how they are handled.]]","Related reading: [[link: /learn/hair-transplant-grafts-needed | how many grafts you need]]. City pages: [[link: /hair-transplant-in-delhi | Delhi]], [[link: /hair-transplant-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: International Society of Hair Restoration Surgery patient information on hair transplantation; American Academy of Dermatology patient information on hair transplants. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-norwood-grade-candidate', 'Am I a candidate? Hair transplant by Norwood grade', 'How the Norwood scale describes male pattern baldness, what a surgeon checks about the donor area, and why some people should wait or try medicines.', 6, 2, 'hair-transplant', '["[[reviewer]]","Whether you are a candidate depends on your pattern of loss, the donor hair available, your age and your goals. The Norwood scale helps describe the pattern, and a surgeon examines your scalp before saying anything about a plan. Some people are advised to wait or start medicines first. See our [[link: /hair-transplant | hair transplant overview]].","## The Norwood scale","The Norwood scale describes male pattern hair loss in stages, from a normal hairline to loss across the front, crown and sides. Stages are numbered, and some have variants. It is a descriptive tool, and surgeons use it to talk about the pattern, not to promise a result. The scale is from a medical paper published in 1975. TODO-VERIFY: reviewer confirms citation.","## What each broad stage often means","These are general statements for the reviewer to confirm. TODO-VERIFY: [R] for each.","- Early stages: a receding hairline or small crown loss. Many doctors suggest medical treatment and watching progress, and surgery may be discussed later.","- Middle stages: clear loss at the front and crown. Surgery may be considered if donor hair is good and the pattern has stabilised.","- Advanced stages: large areas of loss. The donor area may not be enough to cover everything, and the surgeon will set priorities.","No stage decides on its own whether surgery is possible. See [[link: /learn/hair-transplant-grafts-needed | how many grafts you need]].","## The donor check","The surgeon looks at the density and quality of hair on the back and sides, the thickness of each hair, scalp laxity and any signs of thinning there. A thin donor area limits what can be moved. See [[link: /learn/hair-transplant-donor-area-limits | donor area limits]].","## Why some should wait","- Young people whose loss is still progressing, since a transplanted hairline can look odd as the surrounding hair thins.","- People whose cause of thinning is not known or has not been treated.","- Anyone with unrealistic expectations of density or hairline.","- People with scalp disease, active infection or uncontrolled medical conditions.","A surgeon may ask you to wait a year or more and review. That is good advice, not an obstacle.","## Medical therapy first","Doctors often start with medicines for pattern thinning, which is covered in [[link: /learn/prp-vs-minoxidil-finasteride | the medicine comparison]]. Medicines may slow loss and keep existing hair while a transplant adds hair where it is gone. They are often continued after surgery.","## Other causes of hair loss","Thinning can come from thyroid problems, low iron, hormone conditions, medicines, scalp disease or stress. These need their own care, and a transplant does not treat them. A dermatologist can examine you and arrange tests.","## Questions to ask","- What stage do you think I am, and is the pattern stable?","- What is the donor area like, and how many grafts could be used?","- What would you do if my loss continues?","> A realistic plan describes a hairline that suits your face for years to come.","## Cost","The cost relates to the number of grafts and the plan. See [[link: /cost/hair-transplant | our cost page]].","## Who should wait","Wait if you are under 25 with fast loss, if the cause is unknown, or if your scalp has an infection or skin disease. Talk to a doctor if you are anxious about hair loss, since it can affect mood.","[[faq: At what age can I have a hair transplant? | There is no fixed age. Surgeons often prefer a stable pattern, which is why younger people with fast loss may be asked to wait.]]","[[faq: Can anyone with baldness have a transplant? | No. It depends on the donor area, the pattern and your health. A surgeon decides.]]","[[faq: Do I need medicines as well? | Often a doctor recommends them to protect existing hair. Ask what suits you.]]","Related reading: [[link: /learn/hair-transplant-for-women | hair transplant for women]]. City pages: [[link: /hair-transplant-in-lucknow | Lucknow]], [[link: /hair-transplant-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: Norwood OT. Male pattern baldness: classification and incidence. Southern Medical Journal, 1975; American Academy of Dermatology patient information on hair loss. TODO-VERIFY: open each source and confirm the citation details.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-grafts-needed', 'How many grafts do you need? How grafts are counted', 'What a graft is, how the area and density are measured, why the donor limits the number, and why the figure changes after the examination.', 5, 3, 'hair-transplant', '["[[reviewer]]","A graft is a small unit of tissue holding one or more hairs, usually between one and a few. The number of grafts you need depends on the size of the area, the density wanted, your hair type and what the donor area can supply. No online figure applies to you. The surgeon sets an estimate after examining your scalp. See our [[link: /hair-transplant | hair transplant overview]]. TODO-VERIFY: reviewer confirms the hairs-per-graft range.","## What a graft is","Hair grows in natural groups called follicular units, usually with one to four hairs each. Surgeons move these units as grafts. Single-hair grafts are often used at the front of the hairline for a softer edge, and multi-hair grafts behind for fullness. TODO-VERIFY: [R].","## How the number is worked out","- The surgeon measures the area to be covered.","- They decide on a target density that fits your hair and the donor supply.","- They check how many grafts the donor area can give without leaving it thin.","- They split the work between the hairline, the middle and the crown, in order of priority.","The result is an estimate. The actual number depends on what is extracted and how many are usable. Ask how the clinic counts and whether the number is the one planned or the one extracted.","## Why numbers differ between clinics","A clinic may count single units, or count hairs, or quote a larger figure by including multi-hair grafts. Comparing two quotes requires the same definition. Ask for a written definition of a graft.","## Limits of the donor","Every person has a limited supply of donor hair. Taking too much can leave the donor area thin. A plan that tries to cover a large area at high density may not be possible in one session. See [[link: /learn/hair-transplant-donor-area-limits | donor area limits]].","## Hairline and crown priorities","Many surgeons protect the hairline and the front third first, because they frame the face. The crown can take many grafts and show a modest result. Discuss which area matters to you and the order of work.","## Density","Density means hairs per square centimetre. Surgeons describe what is realistic for your donor and your hair. Do not accept a promise of a number. A plan with moderate density that blends with existing hair often looks more natural than an aim for the maximum.","## Why the number changes after the exam","Online calculators and phone quotes are guesses. The surgeon may change the number when they see the scalp, the donor and the pattern. If a clinic quotes a firm number without an examination, ask how they arrived at it.","> The question to ask is how many grafts your plan needs and why, and how many grafts you can afford is a separate question.","## Cost","Many clinics quote by graft count, and the bill is made of the rate, the number and extras. See [[link: /learn/hair-transplant-cost-per-graft | how the bill is built]] and [[link: /cost/hair-transplant | the cost page]].","## Who should wait","Wait if the pattern is still progressing, if the donor is thin or if the cause of thinning is unknown. See [[link: /learn/hair-transplant-norwood-grade-candidate | candidacy by Norwood grade]].","## Questions to ask","- How do you define and count a graft?","- How many do you plan, and how many might the donor supply?","- What if I need a second session?","[[faq: How many grafts for a receding hairline? | It depends on the area, density and donor. Only a surgeon who has examined you can say.]]","[[faq: Are more grafts always better? | No. The donor is limited, and a plan that is too large can leave the donor thin.]]","[[faq: Why do clinics give different numbers? | They may count differently or plan different density. Ask for the definition and the area covered.]]","Related reading: [[link: /learn/hair-transplant-fue-fut-dhi | FUE, FUT and DHI]]. City pages: [[link: /hair-transplant-in-delhi | Delhi]], [[link: /hair-transplant-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: International Society of Hair Restoration Surgery patient information on hair transplantation; American Academy of Dermatology patient information on hair transplants. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-recovery-calendar', 'Hair transplant recovery: a day by day and month calendar', 'A general timeline from the day of surgery to about 18 months, covering washing, sleeping, work, sport, sun and the signs that mean you should call.', 6, 1, 'hair-transplant', '["[[reviewer]]","Early recovery from a hair transplant takes about one to two weeks, when scabs form and fall, and the visible result builds over many months. The timeline below is general, and your surgeon''s instructions come first. See our [[link: /hair-transplant | hair transplant overview]]. TODO-VERIFY: reviewer confirms every day and month below.","## The calendar","- Day 0 to 1: a dressing or band may be used. Mild bleeding, soreness and swelling are common. Sleep with your head raised.","- Days 2 to 5: swelling often moves toward the forehead and around the eyes. Take medicines as prescribed.","- Days 5 to 10: scabs form on the recipient area and start to loosen. Your surgeon will show you how to wash.","- Weeks 2 to 3: most scabs fall. Redness fades. Some people return to desk work earlier.","- Weeks 2 to 8: transplanted hairs often shed, which is expected and not a failure. See [[link: /learn/hair-transplant-shock-loss | shock loss]].","- Months 3 to 4: new hairs start to appear in many people, thin at first.","- Months 6 to 9: hairs thicken and the pattern becomes clearer.","- Months 12 to 18: many people see the final look, though timing varies.","## Washing and sleeping","Follow the washing method you are given, and do not scrub. Avoid hot water pressure directly on the area at first. Sleep with your head raised for the period your surgeon names, and avoid pressing the area against a pillow.","## Work and sport","Many people return to desk work within days to a couple of weeks, depending on swelling and how visible the area is. Hard exercise, heavy lifting, swimming and contact sport are usually avoided for a period set by the surgeon. Do not return early because you feel well.","## Sun and heat","Protect the scalp from sun, and avoid saunas and hot rooms for the time advised. A hat that does not rub the grafts may be allowed. Ask which kind.","## How long transplanted hairs last","Transplanted hairs are taken from an area that is usually less affected by pattern loss, and they often keep that quality in their new place. Hair that was already there can continue to thin over time, and the surgeon may suggest medicines to protect it. Results are not static for life, and further procedures are sometimes needed. TODO-VERIFY: reviewer sets wording.","## Medicines","Surgeons often prescribe medicines for pain, swelling or infection and, sometimes, medicines to support existing hair. Take them as directed, and ask what to do if you miss a dose.","## Signs to call about","- Fever, increasing pain or pus.","- Heavy bleeding that will not stop with gentle pressure.","- Spreading redness or hot, hard areas.","- Severe swelling that affects your vision.","- Numbness that is spreading.","Contact the surgeon or seek urgent care.","> The calendar is a guide. If your recovery looks different, ask. Do not guess.","## Cost","Ask whether review visits and medicines are in the quote. See [[link: /cost/hair-transplant | the cost page]].","## Who should wait","Do not schedule surgery before a big event within weeks. Wait if you cannot arrange recovery time, if you have an infection, or if you cannot follow the aftercare plan.","## Questions to ask","- When are my review visits?","- What do I do if something looks wrong at night?","- When can I return to exercise and swimming?","[[faq: When can I go back to work after a hair transplant? | Many people with desk jobs return within days to a couple of weeks. Your surgeon sets the timing.]]","[[faq: When will I see the result? | New hairs often appear around months three to four, and the look continues to develop for many months. Timing varies.]]","[[faq: Is shedding after a transplant normal? | Yes, transplanted hairs often shed in the first weeks and months. Ask your surgeon what to expect.]]","Related reading: [[link: /learn/hair-transplant-fue-fut-dhi | FUE, FUT and DHI]], [[link: /learn/hair-transplant-donor-area-limits | donor area limits]]. City pages: [[link: /hair-transplant-in-lucknow | Lucknow]], [[link: /hair-transplant-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: International Society of Hair Restoration Surgery patient information on recovery after hair transplantation; American Academy of Dermatology patient information on hair transplants. TODO-VERIFY: open each page and confirm the calendar.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-shock-loss', 'Shock loss after a hair transplant: why it happens', 'What shock loss is, when it shows up, how it differs from graft failure, which hairs are affected, and when to see the doctor.', 5, 2, 'hair-transplant', '["[[reviewer]]","Shock loss is the shedding of hairs after surgery, often in the weeks after a hair transplant. Transplanted hairs commonly shed and then return, and some existing hairs nearby can shed too. It often settles over months, though not always. Contact your surgeon if you are worried. See our [[link: /hair-transplant | hair transplant overview]].","## What it is","Hairs follow a cycle of growth, rest and shedding. Surgery stresses the skin and follicles, and many hairs enter a resting phase and shed. Transplanted hairs often shed their visible shaft in the first weeks while the roots remain under the skin. New hairs form after months. TODO-VERIFY: reviewer confirms wording.","## When it appears","Many people notice shedding in the transplanted area from about two weeks to two months after surgery. Shedding in nearby native hair can occur as well. The timing varies. TODO-VERIFY: [R].","## Which hairs are affected","- Transplanted hairs, which shed and then return in most cases.","- Native hairs in or near the recipient area, which may shed and may or may not return, especially if they were already thin.","- Rarely, hairs in the donor area.","Native hairs that were already weakened by pattern loss are the ones most likely not to return, and a surgeon may discuss medicines to protect them.","## How it differs from graft failure","Shedding is common and expected. Failure means grafts did not take, which shows as areas where no new hairs appear after the usual time for return, often several months. The two can look alike in the first weeks. A surgeon can examine your scalp and compare photographs. Do not decide on your own at week three.","## When to see the doctor","- Shedding that continues beyond the period your surgeon described.","- Patchy loss that is increasing.","- Signs of infection such as pus, pain or fever.","- No new hairs by the time your surgeon told you to expect them.","Take dated photos in the same light to help the review. See [[link: /learn/hair-transplant-recovery-calendar | the recovery calendar]].","## Medicines","Doctors sometimes suggest medicines to support existing hair after surgery. See [[link: /learn/prp-vs-minoxidil-finasteride | the medicine comparison]]. Use only what a doctor prescribes.","## Reassurance with limits","Doctors often say that shedding is common and that hairs return. They cannot promise it for every person. Beware of a clinic that promises full return for everyone, and of one that never mentions shedding before surgery. Ask at the consultation what is likely and what could go differently.","## Mood","Waiting for results can be stressful. Talk to your surgeon if you feel low or anxious. Support from family and a plan for review visits help.","> Shedding after surgery is common. It is not a sign that you did something wrong.","## Cost","Ask whether review visits and any corrective treatment are included. See [[link: /cost/hair-transplant | the cost page]].","## Who should wait","Do not plan surgery before an event soon after. If you have a skin disease of the scalp, shedding conditions or an unknown cause of thinning, see a doctor before surgery.","## Questions to ask","- When should I expect shedding, and how long might it last?","- What would make you worried about graft failure?","- What does a review visit include?","[[faq: Will my transplanted hair fall out? | Many transplanted hairs shed in the first weeks and then return. Ask your surgeon what to expect.]]","[[faq: Is shock loss the same as graft failure? | No. Shedding is common. Failure means grafts did not take, and a surgeon can tell by examination.]]","[[faq: Does shock loss happen in the donor area? | It can, rarely. Tell your surgeon if you see it.]]","Related reading: [[link: /learn/hair-transplant-donor-area-limits | donor area limits]]. City pages: [[link: /hair-transplant-in-delhi | Delhi]], [[link: /hair-transplant-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: International Society of Hair Restoration Surgery patient information on hair transplantation; American Academy of Dermatology patient information on hair loss. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-cost-per-graft', 'Hair transplant cost per graft: how the bill is built', 'How a quote is made from the number of grafts, the rate, the method and extras, how sessions change the total, and how to read a written quote.', 5, 3, 'hair-transplant', '["[[reviewer]]","Most hair transplant quotes are built as a rate per graft times the number of grafts, plus extras. The technique, the surgeon, the clinic and the city change the rate. The number of grafts changes after examination. Ask for a written total that lists every line. All figures on our pages are sample data pending confirmed quotes. See our [[link: /cost/hair-transplant | hair transplant cost page]].","## The formula","Total = (rate per graft x number of grafts) + consultation + medicines and dressings + review visits + any extras. A clinic that quotes only the rate is giving you one part. Ask them to fill in each part. This is a formula only, and we do not state an average. TODO-VERIFY: figures come only from confirmed quotes.","## What changes the rate","- The method, for example FUE or FUT, and what each involves. See [[link: /learn/hair-transplant-fue-fut-dhi | FUE, FUT and DHI]].","- The surgeon''s training and experience.","- The clinic type and setting.","- The number of grafts, since some clinics change the rate for large cases.","- The city.","## How the graft count changes the bill","The number is an estimate until the exam and until surgery. Ask what happens to the price if the actual count is lower or higher than the quote. See [[link: /learn/hair-transplant-grafts-needed | how grafts are counted]]. If the quote is a flat package instead of a rate, ask how many grafts it covers.","## Sessions","A large area may need more than one session, and each session costs money. Ask if the quote covers a second session and at what price. The donor area limits what one session can do.","## What is often left out","- The consultation.","- Medicines and dressings.","- Review visits.","- Tests before surgery.","- Travel and stay, if you come from another town.","- Treatment of complications.","- A second session, if needed.","Ask for each of these in writing as included or excluded.","## How to read a written quote","Check the date, the surgeon''s name, the method, the number of grafts and the definition of a graft, the rate, the total, the included items, the payment schedule and the refund policy. Our [[link: /hair-transplant | hair transplant overview]] has a checklist for choosing a surgeon and a clinic.","## Red flags","- A price only over the phone.","- A quote that changes on arrival.","- Pressure to pay a deposit the same day.","- A promise of a particular density or timing.","- Refusal to name the surgeon or to describe who does each step.","- A rate that is far below others without explanation.","Low cost should lead to more questions, such as who does the work and how many grafts are placed per hour.","> The question that matters is what you will pay in total for the plan, including the parts that are easy to forget.","## Insurance and payment","Hair transplant for cosmetic reasons is usually not covered by insurance. Ask in writing. EMI and payment plans carry their own costs and terms. TODO-VERIFY: reviewer or lawyer confirms wording.","## Who should wait","Do not pay until a surgeon has examined you and given a written plan. Wait if the pattern is changing or the cause is unknown. See [[link: /learn/hair-transplant-norwood-grade-candidate | candidacy by Norwood grade]].","## Questions to ask","- What does the total include and leave out?","- How is the price affected if the count changes?","- What is the refund policy?","[[faq: How is hair transplant cost calculated? | Most quotes multiply a rate per graft by the number of grafts, then add extras. Ask for each line in writing.]]","[[faq: Why do clinics quote very different prices? | The method, the surgeon, the setting, the graft definition and the included items differ. Compare line by line.]]","[[faq: Is a lower price a problem? | It can be a reason to ask more questions, such as who performs the surgery.]]","Related reading: [[link: /learn/hair-transplant-recovery-calendar | recovery calendar]]. City pages: [[link: /hair-transplant-in-lucknow | Lucknow]], [[link: /hair-transplant-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: Sources to be added after reviewer sign-off. TODO-VERIFY: a named consumer protection or regulator page, opened and checked.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-donor-area-limits', 'Donor area limits: how much hair can be moved', 'What the donor area is, why the supply is limited, the risk of over-harvesting, body hair as an option, and why a long-term plan matters.', 5, 1, 'hair-transplant', '["[[reviewer]]","The donor area is the part of the scalp, usually the back and sides, from which hair is taken for transplanting. The supply is limited, and taking too much can leave the donor thin. A surgeon plans how much to move now and what to keep for later. See our [[link: /hair-transplant | hair transplant overview]].","## What the donor area is","In pattern hair loss, the hair on the back and sides tends to be less affected. Surgeons use it because those hairs often keep their character after being moved. The size of the donor zone depends on your scalp and your pattern. TODO-VERIFY: [R].","## Why supply is limited","A person has a fixed number of hairs in the donor area, and each graft taken is gone from there. The donor can only give so many grafts before it looks thin. Over a lifetime, a person may want more than one procedure, so the plan has to leave grafts for later.","## Over-harvesting","Taking too many grafts, or taking them too close together, can leave a moth-eaten look in the donor area or visible scars. The donor zone can also continue to change over the years. A responsible surgeon sets a limit and says no when a request goes beyond it. Be cautious of a clinic that promises to cover a large area in one session at high density.","## Reading your own donor","Ask the surgeon to show you the donor area, explain its density and describe what it can supply. Do not rely on a figure given without examination. See [[link: /learn/hair-transplant-grafts-needed | how grafts are counted]].","## Body hair as an option","In some people with a limited scalp donor, surgeons discuss using hair from the beard or chest. Body hair differs in cycle and texture, and its place in a plan is for the surgeon to decide. TODO-VERIFY: reviewer confirms wording. Ask about the experience of the surgeon with this approach and what to expect.","## Why a plan matters","A plan covers the pattern you have now and the pattern you may have in ten years. A hairline that is too low or too bold can look wrong if surrounding hair thins. Surgeons often choose a conservative hairline and keep grafts in reserve. Medical therapy may slow further loss and protect the result. See [[link: /learn/prp-vs-minoxidil-finasteride | the medicine comparison]].","## Who it affects most","Younger people with quickly progressing loss, those with a thin donor and people who want a very dense result are most affected by limits. Women with diffuse thinning may have a weaker donor. See [[link: /learn/hair-transplant-for-women | hair transplant for women]].","## Questions to ask","- How large is my donor, and how many grafts could it supply over my lifetime?","- What would you leave in reserve?","- What would you do if I need a second procedure?","> A donor limit protects you. A plan that ignores it uses up something you cannot replace.","## Cost","A plan for staged work has more than one cost. Ask how a second session would be priced. See [[link: /cost/hair-transplant | the cost page]].","## Who should wait","Wait if your donor is thin, if the loss is changing, or if the cause is unknown. Seek another opinion if you are advised to proceed without an examination.","[[faq: How much hair can be taken from the donor area? | It depends on your scalp. A surgeon decides after examining it. Taking too much can leave the donor thin.]]","[[faq: Can I use body hair? | Sometimes, if the scalp donor is limited. Ask the surgeon about experience and expected differences.]]","[[faq: What happens if I run out of donor hair? | Options become limited, and a doctor may discuss other approaches. This is why planning matters.]]","Related reading: [[link: /learn/hair-transplant-norwood-grade-candidate | candidacy by Norwood grade]], [[link: /learn/hair-transplant-fue-fut-dhi | FUE, FUT and DHI]]. City pages: [[link: /hair-transplant-in-delhi | Delhi]], [[link: /hair-transplant-in-gurgaon | Gurgaon]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: International Society of Hair Restoration Surgery patient information on hair transplantation; American Academy of Dermatology patient information on hair transplants. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null),
  ('hair-transplant-for-women', 'Hair transplant for women: who may be a candidate', 'Patterns of female hair loss, why diffuse thinning needs a medical work-up first, hairline lowering, who may wait, and the place of PRP and medicines.', 6, 2, 'hair-transplant', '["[[reviewer]]","Fewer women than men are candidates for a hair transplant, because many women lose hair in a diffuse pattern and the donor hair may also be thin. A doctor first looks for causes such as thyroid problems, low iron or hormone conditions. Transplant is considered only for selected patterns. See our [[link: /hair-transplant | hair transplant overview]].","## Patterns of hair loss in women","Female pattern hair loss often shows as widening of the parting and thinning across the top of the scalp, with the front hairline kept. Other patterns include loss after illness or childbirth, loss from medicines and loss from traction caused by tight hairstyles. A doctor identifies the pattern by examination and history. TODO-VERIFY: [R].","## Why a medical work-up comes first","Diffuse thinning can come from iron deficiency, thyroid disorders, hormone conditions such as polycystic ovary syndrome, nutrition, stress or medicines. A doctor may arrange tests, and treating the cause can change the picture. A transplant does not treat these causes. See [[link: /learn/adult-hormonal-acne-women | adult acne and hormones in women]] for related questions about tests.","## When a transplant may be considered","- Loss in a localised area, such as from scarring, injury or surgery.","- Traction loss that has stopped, after the cause is removed.","- A selected pattern with a good donor area.","- Hairline lowering for some women who want a lower forehead, which the surgeon assesses carefully.","Many women with diffuse loss are not candidates. A surgeon will explain why.","## Donor area","In diffuse loss, the donor area may also be thin, which limits how many grafts can be moved. A donor that is stable and dense is better. See [[link: /learn/hair-transplant-donor-area-limits | donor area limits]].","## Hairline lowering","Some women request a lower hairline. The surgeon assesses the existing hairline, the forehead, the donor and the likelihood of future loss. The plan should be conservative. The result takes months to show, and a second session is sometimes needed. TODO-VERIFY: reviewer confirms wording.","## Medical options","Doctors may suggest medicines suitable for women, treatment of any underlying cause, and in some cases PRP. See [[link: /learn/prp-for-hair-loss-evidence | what the evidence says about PRP]] and [[link: /learn/prp-vs-minoxidil-finasteride | the medicine comparison]]. Some medicines are not suitable in pregnancy, so tell the doctor about pregnancy plans.","## What to bring to the first visit","Bring a list of your medicines, any recent blood test reports, and photographs of your hair from a year or two ago. Note when thinning began, whether it followed an illness, childbirth or a change in medicine, and whether other women in your family have thin hair. This helps the doctor decide quickly whether a work-up is needed.","## Who may need to wait","Women with active hair loss, an unknown cause, a recent illness or childbirth, or a scalp condition should wait for a medical assessment. Those planning pregnancy should discuss timing, since hormone changes affect hair.","## Risks","Bleeding, infection, swelling, scarring, uneven density and shedding after surgery, as in men. See [[link: /learn/hair-transplant-shock-loss | shock loss]]. Results vary, and some women see less improvement than expected.","> A diagnosis first is cheaper than a procedure that does not match the cause.","## Cost","The cost relates to the number of grafts, the method and the surgeon. See [[link: /cost/hair-transplant | our cost page]] and [[link: /learn/hair-transplant-cost-per-graft | how the bill is built]].","## Questions to ask","- What do you think is causing my thinning?","- Am I a candidate, and why or why not?","- What are the other options for me?","[[faq: Can women have a hair transplant? | Some can, in selected patterns. Many women with diffuse thinning are not candidates. A doctor decides after a work-up.]]","[[faq: Is hair loss in women always hormonal? | No. Causes include iron, thyroid, medicines, stress and others. A doctor can investigate.]]","[[faq: Can a hair transplant lower my hairline? | Some surgeons do this in selected cases. Ask about risks, the donor and future loss.]]","Related reading: [[link: /learn/hair-transplant-norwood-grade-candidate | candidacy by Norwood grade]]. City pages: [[link: /hair-transplant-in-lucknow | Lucknow]], [[link: /hair-transplant-in-kanpur | Kanpur]].","Message us on WhatsApp if you want help preparing questions for a registered doctor.","[[sources: American Academy of Dermatology patient information on hair loss in women; NHS patient information on hair loss. TODO-VERIFY: open each page and confirm wording.]]"]'::jsonb, 'sample-reviewer', false, '2026-11-21', '2026-11-21', null, null)
insert into public.videos (slug, title, duration, iso_duration, description, transcript, poster, poster_alt, youtube_id, upload_date, is_sample, published) values
  ('gynecomastia-explained', 'Gynecomastia explained: grades, causes and when to see a doctor', '4:30', 'PT4M30S', 'A short sample video on how doctors describe the grades of gynecomastia, common causes, and when to see a doctor.', 'Gynecomastia is growth of breast gland tissue in boys and men. Doctors describe the size on a four-point scale. Some cases settle on their own, especially in teenagers. Others are linked to medicines or weight change. Only an examination can tell gland from fat. See a doctor early if there is a hard lump, one-sided change, pain or discharge.', 'grades', 'Animated chest diagram showing the four grades', null, '2026-11-09', true, true),
  ('gynecomastia-recovery-weeks', 'Recovery week by week: what to expect after chest surgery', '5:10', 'PT5M10S', 'A short sample video on what most people notice and do in each week after chest surgery, from day one to week twelve.', 'Day one is for rest at home with a compression garment on. Swelling and bruising peak in the first week and ease in the second. Many people return to desk work after about a week. Driving usually follows at about two weeks, and chest training after six weeks or more, if the surgeon agrees. Swelling takes months to settle.', 'recovery', 'Calendar graphic with weeks 1 to 12 marked', null, '2026-11-09', true, true)
